__modules['Theme'] = function(...)
--!strict
-- Theme.lua — design tokens (colors, metrics, fonts).
-- Offset pixels map directly to Roblox offsets.
--
-- Palette: **Uranium (Uranium Glass)**. Flat fills only — no gradients, no
-- glows — and at most one accent element per row. Anything sitting *on* a solid
-- accent fill (button text, the toggle-on knob) uses `knockout`, not white.
--
-- Two rules keep the green from taking the UI over:
--
-- 1. **The surfaces are near-neutral.** They carry only a whisper of green
--    (~10% saturation). The old ramp was a flat olive (#18220F) which, sat
--    under a screaming yellow-green accent, read muddy — two greens
--    fighting instead of one green on grey. Neutral ground is also what makes
--    the accent look bright; tinting the ground just spends the contrast.
--    The ramp is a real elevation ladder — chrome < bg < card < control <
--    control_hi — so a field reads as a field even sitting inside a card.
-- 2. **The accent has three weights, by area.** A colour that looks right as a
--    6px slider fill is a searing slab at button size, so bigger area = lower
--    value:
--      `accent`      small marks — slider fill, toggle track, icons, focus
--                    strokes, text. Bright, because it's tiny.
--      `accent_fill` large solid fills (primary buttons). Deeper; hovers *up*
--                    to `accent`, so the interaction reads as lighting up.
--      `accent_soft` accent laid into a surface (~13%) for tinted tiles — the
--                    active nav, avatar placeholders, badges. Reads as "this is
--                    accent-coloured" without putting neon on the screen.
--    util/Context.lua derives the last two from the live accent, so a caller's
--    `SetAccent` keeps all three in step.

local Theme = {}

-- ── Brand ─────────────────────────────────────────────────────────────────
-- `assets` is the **uranium-public** repo — the author's asset host, a separate
-- thing from this UI library (which lives in the `coreui` repo and is only
-- public so the loadstring works). `coreui` keeps its old name on purpose: the
-- loadstring URL is pinned to that path and renaming it breaks every shipped
-- loader. The art host is NOT pinned that way — nothing but this line points at
-- it — so it moved off the old `Krypton` name, and that path now 404s. Art the
-- UI ships with goes in that repo, not here; drop a file in its `Assets/` folder
-- and reference it as `Theme.Brand.assets .. "name.png"` (or
-- `Uranium.Asset.url("name.png")`).
--
-- If the mark ever comes up as the `atom` fallback glyph, check this URL first:
-- that fallback is what a 404 looks like, and it looks identical to "no file
-- access", so it reads as an executor problem when it's really a dead link.
--
-- The logo is a fallback chain — util/Asset.lua walks it in order, so
-- `Window{ Logo = ... }` can be a single source or a chain of its own.
--
-- The PNG comes FIRST on purpose — that's the Infinite Yield approach. It's
-- downloaded once, cached on disk, and handed to the engine via getcustomasset,
-- so it sidesteps every Roblox asset rule: no moderation wait, no Asset Privacy
-- restriction, no decal-vs-image id confusion. An uploaded asset id would be the
-- fallback for executors with no file access — there isn't one for the Uranium
-- mark yet, so those fall through to the tinted tile + Lucide `atom` glyph the
-- titlebar draws underneath the art (components/Window.lua, components/Screen.lua)
-- — a spritesheet slice, so it needs neither network nor file access. Add the id
-- here once it's uploaded and every client gets the real art unconditionally.
local ASSETS = "https://raw.githubusercontent.com/funjimmywantstodie/uranium-public/main/Assets/"

Theme.Brand = {
	name   = "Uranium",
	assets = ASSETS,
	logo = {
		ASSETS .. "uranium-orbitals-512-square.png", -- 512×512 square mark
	},
	radius = 8, -- rounded off with a UICorner
	-- The mark is a full-bleed tile, not a transparent glyph: the orbitals only
	-- span the middle ~58% and the rest is flat #0B0F0A margin baked into the
	-- PNG. Drawn 1:1 that reads as a tiny logo floating in a box. So the holder
	-- clips and the art is drawn `zoom`× oversized inside it — the dead margin
	-- is cropped away and the glyph fills ~82% of the holder instead of 58%.
	-- The tile's background is exactly `Colors.chrome` (#0B0F0A), so its edges
	-- vanish into the titlebar and the crop is invisible — which is why `chrome`
	-- is pinned to that value and the rest of the ramp moved around it.
	-- 1 = draw the source untouched (the default for a caller-supplied Logo,
	-- which we can't assume has margin).
	zoom = 1.42,
}

-- ── Colors ────────────────────────────────────────────────────────────────
Theme.Colors = {
	-- Elevation ladder, darkest → lightest. Each step is a real, visible lift,
	-- so depth comes from the fills themselves and the hairlines only have to
	-- draw the edge (they used to carry the whole separation on their own).
	chrome      = Color3.fromHex("0B0F0A"), -- titlebar / sidebar / status bar (the frame)
	bg          = Color3.fromHex("10150E"), -- window body — lifts off the chrome
	card        = Color3.fromHex("171D15"), -- group card fill
	pop         = Color3.fromHex("1A2118"), -- dropdown / colorpicker / toast (floats above cards)
	control     = Color3.fromHex("1D241B"), -- input / dropdown / button fill, on a card
	control_hi  = Color3.fromHex("262E23"), -- hovered control — one step lighter, nothing else
	-- Toggle / slider track: one step above `control` again, so an unfilled
	-- track still reads against the field it sits in.
	toggle_off  = Color3.fromHex("2B3428"),
	knob        = Color3.fromHex("6E7C69"), -- toggle knob (off)
	border      = Color3.fromHex("2B3427"), -- every 1px line
	border_soft = Color3.fromHex("1F271D"), -- between-field dividers (quieter than an edge)
	text        = Color3.fromHex("E9F2E5"), -- primary text / headings
	text_muted  = Color3.fromHex("98A394"), -- descriptions, placeholders, readouts
	text_dim    = Color3.fromHex("616D5D"), -- small caps headers, hints, idle icons
	-- Accent, by area — see the header. Small marks / large fills / tinted tiles.
	accent      = Color3.fromHex("7BE04A"), -- slider fill, toggle-on, focus stroke, icons
	accent_2    = Color3.fromHex("96EC69"), -- accent hover
	accent_fill = Color3.fromHex("5EB832"), -- large solid fills (primary buttons)
	accent_soft = Color3.fromHex("22331A"), -- accent tinted into a surface (~13%)
	accent_dim  = Color3.fromHex("4E9B2B"), -- pressed / disabled accent
	knockout    = Color3.fromHex("08140A"), -- text + icons ON a solid accent fill
	scroll      = Color3.fromHex("2B3427"), -- scrollbar thumb
	white       = Color3.fromHex("FFFFFF"),
	danger      = Color3.fromHex("FF6B6B"), -- destructive buttons + notify "error"
	success     = Color3.fromHex("7BE04A"), -- notify "success"
	warning     = Color3.fromHex("FFC53D"), -- risky toggles + notify "warning"
	info        = Color3.fromHex("98A394"), -- notify "info" (neutral, off-accent)
}

-- ── Metrics (offset px) ───────────────────────────────────────────────────
Theme.Metrics = {
	windowWidth   = 780,
	windowHeight  = 560,
	windowRadius  = 12,
	titlebar      = 50,
	logo          = 30, -- titlebar brand mark (square)
	statusbar     = 34,
	sidebar       = 64,
	navButton     = 40,
	navRadius     = 11,
	navIcon       = 20,
	cardRadius    = 9,
	controlRadius = 7,
	columnGap     = 24,
	groupGap      = 18,
}

-- ── Fonts ─────────────────────────────────────────────────────────────────
-- UI font "Inter" → Gotham family. Mono (keybind/hex) → Roboto Mono.
--
-- These are FontFace objects (set via the `FontFace` property, NOT `Font`).
-- The legacy `Enum.Font.*` values render from fixed-size bitmap atlases —
-- Roblox scales the nearest baked size to your TextSize, which is what made
-- the text look soft / rough / "pixelated". FontFace uses the SDF text
-- renderer, so glyphs stay crisp at any size.
local GOTHAM = "rbxasset://fonts/families/GothamSSm.json"
Theme.Font = {
	Bold    = Font.new(GOTHAM, Enum.FontWeight.Bold),                          -- titles
	Medium  = Font.new(GOTHAM, Enum.FontWeight.Medium),                        -- labels / weighted text
	Regular = Font.new(GOTHAM, Enum.FontWeight.Regular),                       -- body
	Mono    = Font.new("rbxasset://fonts/families/RobotoMono.json", Enum.FontWeight.Regular), -- keybind / hex
}

return Theme

end

__modules['components.BindChip'] = function(...)
--!strict
-- components/BindChip.lua — the little mono key chip, shared by the Keybind
-- control and by any control that takes a `Keybind` option (Toggle today).
--
-- The chip is TWO click targets in one pill:
--
--     ┌──────┬──────┐
--     │ MB2  │ hold │
--     └──────┴──────┘
--        ^       ^
--        |       └─ mode segment — click cycles Toggle → Hold → Always. Only
--        |          drawn when there's more than one mode to pick, so a pure
--        |          key picker still reads as a single plain chip.
--        └─ key segment — click to arm, then press the key to bind.
--
-- Mode cycling used to live on *right-clicking the chip*, which was both
-- invisible (nothing on screen said so) and a trap: right-click is the mouse
-- button people most want to bind, and pressing it just flipped the mode
-- instead. So the two jobs are now split by position rather than by button:
-- every click on the key half is about the key, and the mode has a label you
-- can see and press.
--
-- That frees the mouse buttons for binding. While armed, a right/middle click
-- **on the chip** binds MB2/MB3; a click anywhere **else** abandons the bind,
-- which is the same escape hatch as before. Left click is deliberately not
-- bindable from the UI — it's how you operate the menu (and the chip) — but
-- `handle:Set(Enum.UserInputType.MouseButton1)` still works for a caller that
-- really wants it.

local Services = __require("util.Services")

local UserInputService = Services.UserInputService

local Create = __require("util.Create")
local Theme = __require("Theme")
local Bind = __require("util.Bind")

-- Mouse buttons the click-to-bind UI will capture. MB1 is left out on purpose
-- (see the header) — it stays the "operate the UI" button.
local BINDABLE_MOUSE: { [Enum.UserInputType]: boolean } = {
	[Enum.UserInputType.MouseButton2] = true,
	[Enum.UserInputType.MouseButton3] = true,
}

-- Modes with nothing useful to cycle to (a pure picker, a one-shot command)
-- keep their chip single-segment.
local function cycleList(mode: string, modes: { string }?): { string }
	if mode == "None" then
		return { "None" }
	end
	local list = modes or Bind.DefaultModes
	for _, m in list do
		if m == mode then
			return list
		end
	end
	-- The starting mode isn't in the cycle list (e.g. Mode = "Press" with the
	-- default list) — keep it reachable by putting it first.
	local merged = { mode }
	for _, m in list do
		table.insert(merged, m)
	end
	return merged
end

return function(ctx: any, opts: any): (Frame, any)
	local colors = Theme.Colors
	local compact = opts.Compact == true
	local where = opts.Where or "Keybind"

	local mode = Bind.mode(opts.Mode, where, "Toggle")
	local modes = cycleList(mode, opts.Modes)
	local switchable = #modes > 1
	local listening = false

	local height = compact and 24 or 32
	local padX = compact and 9 or 13
	local textSize = compact and 11 or 12
	-- The key half keeps the old minimum so a chip doesn't jump around as the
	-- bound key changes; the mode half sizes to its word.
	local keyMin = compact and 46 or 70

	local chip = Create("Frame", {
		Name = "BindChip",
		AutomaticSize = Enum.AutomaticSize.X,
		Size = UDim2.fromOffset(0, height),
		BackgroundColor3 = colors.control,
		LayoutOrder = opts.LayoutOrder or 2,
	}, {
		Create.corner(Theme.Metrics.controlRadius),
		Create.stroke(colors.border),
		Create.listLayout({
			FillDirection = Enum.FillDirection.Horizontal,
			VerticalAlignment = Enum.VerticalAlignment.Center,
		}),
	})
	local stroke = chip:FindFirstChildOfClass("UIStroke") :: UIStroke

	-- Hover is tracked per segment: the segments tile the whole chip, so "the
	-- pointer is over one of them" is also "the pointer is over the chip", which
	-- is what decides whether a click while armed binds or abandons. (The parent
	-- Frame's own MouseEnter/Leave can't be used — a child button takes the
	-- mouse target away from it.)
	local hovered: { [Instance]: boolean } = {}

	local keyBtn: TextButton
	local modeBtn: TextButton? = nil
	local paint: () -> ()

	local function segment(name: string, order: number, minWidth: number): TextButton
		local btn = Create("TextButton", {
			Name = name,
			AutoButtonColor = false,
			AutomaticSize = Enum.AutomaticSize.X,
			Size = UDim2.fromOffset(0, height),
			BackgroundTransparency = 1,
			Text = "",
			TextColor3 = colors.text,
			TextSize = textSize,
			FontFace = Theme.Font.Mono,
			LayoutOrder = order,
			Parent = chip,
		}, {
			Create.padding(0, padX),
			Create("UISizeConstraint", { MinSize = Vector2.new(minWidth, height) }),
		})
		btn.MouseEnter:Connect(function()
			hovered[btn] = true
			paint()
		end)
		btn.MouseLeave:Connect(function()
			hovered[btn] = false
			paint()
		end)
		return btn
	end

	keyBtn = segment("Key", 1, keyMin)

	if switchable then
		modeBtn = segment("Mode", 2, compact and 34 or 44)
		-- Hairline between the halves, pulled back out of the mode segment's left
		-- padding so it lands on the actual boundary. A Frame doesn't sink input,
		-- so it can't punch a dead spot in either segment's hover.
		Create("Frame", {
			Name = "Divider",
			BackgroundColor3 = colors.border,
			BorderSizePixel = 0,
			Position = UDim2.fromOffset(-padX, 0),
			Size = UDim2.new(0, 1, 1, 0),
			Parent = modeBtn,
		})
	end

	local function overChip(): boolean
		return hovered[keyBtn] == true or (modeBtn ~= nil and hovered[modeBtn] == true)
	end

	local binding = Bind.get(ctx):Register({
		Key = opts.Key,
		Mode = mode,
		Modes = modes,
		Default = opts.Default,
		Where = where,
		-- What the bind HUD calls this bind (components/Hud.lua). The consumers
		-- pass their control's own `Name`, so nothing is declared twice.
		Label = opts.Label,
		-- ...and their own `Flag` as the id other controls point `Parent` at, for
		-- the same reason: the name a sub-option refers to its feature by is one
		-- the call site already wrote down.
		Id = opts.Id,
		Parent = opts.Parent,
		Hud = opts.Hud,
		GetState = opts.GetState,
		Callback = opts.OnActivate,
		OnChanged = opts.OnChanged,
	})

	-- ── paint ────────────────────────────────────────────────────────────────
	function paint()
		local over = overChip()
		-- The whole pill lifts on hover (it's one control), and the half under the
		-- pointer brightens its label — that's what tells you the two halves do
		-- different things before you click either of them.
		chip.BackgroundColor3 = over and colors.control_hi or colors.control

		if listening then
			keyBtn.Text = "..."
			keyBtn.TextColor3 = ctx.Accent
			stroke.Color = ctx.Accent
		else
			keyBtn.Text = Bind.name(binding:GetKey())
			-- An active bind (held, or toggled on) lights up, so a Hold key reads as
			-- live while it's down without anything else on the row moving.
			local active = binding:GetState()
			keyBtn.TextColor3 = active and ctx.Accent or colors.text
			stroke.Color = active and ctx.Accent or colors.border
		end

		if modeBtn then
			modeBtn.Text = binding:GetMode():lower()
			-- Muted, not dim: the mode half is the only thing on screen advertising
			-- that the mode is switchable at all, so it has to be readable at rest.
			modeBtn.TextColor3 = (hovered[modeBtn] and not listening) and colors.text or colors.text_muted
		end
	end

	binding.onState = function()
		paint()
	end
	-- Kept so handle:Destroy can drop it. Unlike most controls a chip really can
	-- outlive nothing — `Keybind`/`Toggle` handles expose :Destroy — and the
	-- registry has no idea the instances are gone, so a dropped chip's closure
	-- would keep painting a destroyed pill on every SetAccent for the life of the
	-- window (see the note on Context:RegisterAccent).
	local unsubscribeAccent = ctx:RegisterAccent(function()
		paint()
	end)

	-- ── rebind ───────────────────────────────────────────────────────────────
	-- The arming listener lives on UserInputService, so it outlives the chip's
	-- instances: a window torn down while a chip sat armed (a loader re-run,
	-- Uranium:Unload from a script) left it connected against a dead tree, holding
	-- the capture claim with nothing left that could release it. Kept at chip scope
	-- so `Destroying` and handle:Destroy can both cancel it.
	local armConn: RBXScriptConnection? = nil
	local function disarm(repaint: boolean?)
		if armConn then
			armConn:Disconnect()
			armConn = nil
		end
		if not listening then
			return
		end
		listening = false
		ctx:EndCapture()
		if repaint then
			paint()
		end
	end
	chip.Destroying:Connect(function()
		disarm(false)
		-- Also the path a chip taken down by an ancestor goes out on (a tab or
		-- group rebuilt under it), where handle:Destroy is never called.
		-- Unsubscribing twice is a no-op.
		unsubscribeAccent()
	end)

	keyBtn.Activated:Connect(function()
		if listening then
			return -- already armed; a left click on the chip is a no-op, not a bind
		end
		listening = true
		-- Claim key capture so the window's toggle-key listener (and every other
		-- binding) ignores input until the bind completes — otherwise binding e.g.
		-- RightShift also hid the window on that same keystroke.
		ctx:BeginCapture()
		paint()

		local function finish()
			disarm(true)
		end

		-- Every rebind below is tagged as user-driven, so a host watching flag
		-- changes (Context:OnFlagChanged) sees a chip the user re-keyed as
		-- exactly that, and not as the config load or the `:Set` that takes the
		-- same path through `binding:SetKey`.
		armConn = UserInputService.InputBegan:Connect(function(input)
			local kind = input.UserInputType
			if kind == Enum.UserInputType.Keyboard then
				finish()
				-- Escape cancels (keep the current bind); Backspace/Delete clears it.
				if input.KeyCode == Enum.KeyCode.Escape then
					-- leave the bind untouched
				elseif input.KeyCode == Enum.KeyCode.Backspace or input.KeyCode == Enum.KeyCode.Delete then
					ctx:User(function()
						binding:SetKey(Enum.KeyCode.Unknown)
					end)
				else
					ctx:User(function()
						binding:SetKey(input.KeyCode)
					end)
				end
				paint()
				return
			end

			local isMouse = kind == Enum.UserInputType.MouseButton1
				or kind == Enum.UserInputType.MouseButton2
				or kind == Enum.UserInputType.MouseButton3
			if not isMouse and kind ~= Enum.UserInputType.Touch then
				return
			end

			if overChip() then
				-- A click on the chip is aimed AT the chip: bind the mouse button if
				-- it's one we capture, and otherwise (left click, touch) just stay
				-- armed rather than eating the click as a cancel.
				if BINDABLE_MOUSE[kind] then
					finish()
					ctx:User(function()
						binding:SetKey(kind)
					end)
					paint()
				end
				return
			end
			-- A click anywhere else abandons the bind. Without this the chip sat in
			-- "..." forever holding key capture, which silently killed the window's
			-- toggle key until some key was eventually pressed.
			finish()
		end)
	end)

	-- ── mode cycle ───────────────────────────────────────────────────────────
	-- Left click only, and only on the mode half. Nothing about the mode is
	-- reachable from a mouse button any more, which is what lets the key half
	-- claim right/middle click for binding.
	if modeBtn then
		modeBtn.Activated:Connect(function()
			if listening then
				return
			end
			local current = binding:GetMode()
			-- 0 = the current mode isn't in the cycle list at all (a config restored
			-- a mode this chip doesn't offer), which cycles to modes[1] rather than
			-- silently skipping it.
			local index = 0
			for i, m in modes do
				if m == current then
					index = i
					break
				end
			end
			ctx:User(function()
				binding:SetMode(modes[(index % #modes) + 1])
			end)
			paint()
		end)
	end

	-- ── handle ───────────────────────────────────────────────────────────────
	local handle = {}
	handle.Binding = binding

	function handle:Get(): any
		return binding:GetKey()
	end
	function handle:Set(key: any)
		binding:SetKey(key)
		paint()
	end
	function handle:GetMode(): string
		return binding:GetMode()
	end
	function handle:SetMode(m: string)
		binding:SetMode(m)
		paint()
	end
	function handle:GetState(): boolean
		return binding:GetState()
	end
	-- `fire` = also run the activation callback (default: just sync + repaint).
	function handle:SetState(active: boolean, fire: boolean?)
		binding:SetState(active, fire)
		paint()
	end
	function handle:SetEnabled(enabled: boolean)
		binding:SetEnabled(enabled)
	end
	-- Config save/load: a bind is a key AND a mode, so it persists as both rather
	-- than through the plain :Get()/:Set() pair (util/Context.lua `bind` codec).
	function handle:GetFlag(): any
		return { Key = binding:GetKey(), Mode = binding:GetMode() }
	end
	function handle:SetFlag(value: any)
		if typeof(value) == "EnumItem" then
			binding:SetKey(value)
		elseif type(value) == "table" then
			-- Both halves land silently and ONE notification covers the record. Left
			-- to themselves, SetKey reports the pre-load mode and SetMode reports
			-- again — and SetMode no-ops (so reports nothing) when the saved mode
			-- already matches, which is the common case. The Settings tab's picker
			-- runs window:SetToggleKey off this callback, so it has to fire exactly
			-- once either way.
			local changed = false
			if value.Key ~= nil then
				binding:SetKey(value.Key, true)
				changed = true
			end
			if value.Mode ~= nil then
				binding:SetMode(value.Mode, true)
				changed = true
			end
			if changed and binding.onChanged then
				binding.onChanged(binding:GetKey(), binding:GetMode())
			end
		end
		paint()
	end
	function handle:Destroy()
		disarm(false)
		unsubscribeAccent()
		binding:Destroy()
	end

	paint()
	return chip, handle
end

end

__modules['components.Button'] = function(...)
--!strict
-- components/Button.lua — single button (bare or titled) + side-by-side ButtonRow.

local Create = __require("util.Create")
local Theme = __require("Theme")
local Tween = __require("util.Tween")
local Field = __require("components.Field")

local function newButton(ctx: any, label: string, accent: boolean, callback: (() -> ())?): TextButton
	local colors = Theme.Colors
	local btn = Create("TextButton", {
		Name = "Button",
		AutoButtonColor = false,
		Size = UDim2.new(1, 0, 0, 36),
		-- Accent buttons take the *deepened* accent, not the accent itself: a
		-- full-width slab of the raw accent is the single loudest thing the UI
		-- can draw. It hovers up to the real accent (see below).
		BackgroundColor3 = accent and ctx.AccentFill or colors.control,
		Text = label or "Button",
		TextColor3 = accent and colors.knockout or colors.text,
		TextSize = 13,
		FontFace = Theme.Font.Medium,
	}, {
		Create.corner(Theme.Metrics.controlRadius),
		Create.stroke(accent and colors.accent or colors.border, 1),
		Create("UIScale", {}),
	})
	local stroke = btn:FindFirstChildOfClass("UIStroke") :: UIStroke
	if accent then
		stroke.Transparency = 1
	end
	local scale = btn:FindFirstChildOfClass("UIScale") :: UIScale

	local function base(): Color3
		return accent and ctx.AccentFill or colors.control
	end
	-- Hovering an accent button brightens it to the full accent — the fill
	-- "lights up" rather than shifting to yet another shade.
	local function over(): Color3
		return accent and ctx.Accent or colors.control_hi
	end
	-- The `hovering` boolean this used to keep is Create.hover's now: its setter
	-- repaints to whichever end applies, so a SetAccent landing while the pointer
	-- is on the button doesn't snap it back to the resting fill.
	local _, setHover = Create.hover(btn, "BackgroundColor3", base(), over())
	btn.Activated:Connect(function()
		-- quick squash-and-release so the tap feels physical
		scale.Scale = 0.96
		Tween.play(scale, Tween.Spring, { Scale = 1 })
		if callback then
			task.spawn(callback)
		end
	end)

	if accent then
		ctx:RegisterAccent(function()
			setHover(base(), over())
		end)
	end
	return btn
end

local Button = {}

function Button.single(ctx: any, opts: any)
	-- titled → stacked field; bare → standalone padded row
	if opts.Name or opts.Desc then
		local f = Field.new(ctx, opts, true)
		local btn = newButton(ctx, opts.Label, opts.Accent == true, opts.Callback)
		btn.LayoutOrder = 2
		btn.Parent = f.field
		return f.field, { element = btn }, true
	end

	local wrap = Create("Frame", {
		Name = "ButtonRow",
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
	}, {
		Create.padding(8, 2),
	})
	local btn = newButton(ctx, opts.Label, opts.Accent == true, opts.Callback)
	btn.Parent = wrap
	return wrap, { element = btn }, true
end

function Button.row(ctx: any, list: { any })
	local wrap = Create("Frame", {
		Name = "ButtonRow",
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
	}, {
		Create.padding(8, 2),
		Create.listLayout({
			FillDirection = Enum.FillDirection.Horizontal,
			Padding = UDim.new(0, 10),
		}),
	})
	local GAP = 10
	local n = #list
	if n == 0 then
		return wrap, {}, true -- empty row: nothing to size (1/n would be a div by zero)
	end
	for i, item in list do
		local btn = newButton(ctx, item.Label, item.Accent == true, item.Callback)
		btn.LayoutOrder = i
		-- Even split without flexbox: each button takes 1/n of the row, minus
		-- its share of the inter-button gaps.
		btn.Size = UDim2.new(1 / n, -(GAP * (n - 1)) / n, 0, 36)
		btn.Parent = wrap
	end
	return wrap, {}, true
end

return Button

end

__modules['components.Code'] = function(...)
--!strict
-- components/Code.lua — multi-line monospace editor for pasting / editing raw
-- config blobs (Lua tables, JSON, scripts) that don't fit a structured control.
--
-- Stacked field: label/desc on top, a fixed-height scrolling TextBox below.
-- Wraps by default (clean for prose-ish config). `LineNumbers = true` adds a
-- left gutter — that mode disables wrap so each logical line is exactly one row
-- (so the numbers stay aligned) and scrolls horizontally instead.
--
-- An optional `Parse` fn turns the editor into a validated input: it runs on
-- blur inside a pcall; success caches the parsed value (read via :GetValue()),
-- failure paints the stroke red and prints the error on a line beneath the box.
--
-- Flag-captured as a plain string (the raw text), so it saves / loads through
-- the config system exactly like :Input.

local Create = __require("util.Create")
local Theme = __require("Theme")
local Tween = __require("util.Tween")
local Field = __require("components.Field")

local GUTTER_W = 30

return function(ctx: any, opts: any)
	local colors = Theme.Colors
	local f = Field.new(ctx, opts, true)

	local numbered = opts.LineNumbers == true
	local wrap = not numbered
	local height = opts.Height or 168

	local scroller = Create("ScrollingFrame", {
		Name = "Editor",
		Size = UDim2.new(1, 0, 0, height),
		BackgroundColor3 = colors.control,
		BorderSizePixel = 0,
		ClipsDescendants = true,
		CanvasSize = UDim2.new(),
		AutomaticCanvasSize = wrap and Enum.AutomaticSize.Y or Enum.AutomaticSize.XY,
		ScrollingDirection = wrap and Enum.ScrollingDirection.Y or Enum.ScrollingDirection.XY,
		ScrollBarThickness = 4,
		ScrollBarImageColor3 = colors.text_dim,
		ScrollBarImageTransparency = 0.35,
		LayoutOrder = 2,
		Parent = f.field,
	}, {
		Create.corner(Theme.Metrics.controlRadius),
		Create.stroke(colors.border),
		Create.padding(9, 11),
	})
	local stroke = scroller:FindFirstChildOfClass("UIStroke") :: UIStroke

	local gutter: TextLabel? = nil
	if numbered then
		gutter = Create("TextLabel", {
			Name = "Gutter",
			BackgroundTransparency = 1,
			Position = UDim2.fromOffset(0, 0),
			Size = UDim2.fromOffset(GUTTER_W, 0),
			AutomaticSize = Enum.AutomaticSize.Y,
			Text = "1",
			TextColor3 = colors.text_dim,
			TextSize = 13,
			FontFace = Theme.Font.Mono,
			TextXAlignment = Enum.TextXAlignment.Right,
			TextYAlignment = Enum.TextYAlignment.Top,
			Parent = scroller,
		}, { Create.padding(0, 8, 0, 0) })
	end

	local boxX = numbered and GUTTER_W or 0
	local box = Create("TextBox", {
		Name = "Box",
		Position = UDim2.fromOffset(boxX, 0),
		Size = wrap and UDim2.new(1, -boxX, 0, 0) or UDim2.fromOffset(0, 0),
		AutomaticSize = wrap and Enum.AutomaticSize.Y or Enum.AutomaticSize.XY,
		BackgroundTransparency = 1,
		Text = opts.Default or "",
		PlaceholderText = opts.Placeholder or "",
		PlaceholderColor3 = colors.text_dim,
		TextColor3 = colors.text,
		TextSize = 13,
		FontFace = Theme.Font.Mono,
		MultiLine = true,
		ClearTextOnFocus = false,
		TextWrapped = wrap,
		TextXAlignment = Enum.TextXAlignment.Left,
		TextYAlignment = Enum.TextYAlignment.Top,
		Parent = scroller,
	})

	-- Error line beneath the editor — hidden while the text parses (or no parser).
	local status = Create("TextLabel", {
		Name = "Status",
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		BackgroundTransparency = 1,
		Text = "",
		TextColor3 = colors.danger,
		TextSize = 12,
		FontFace = Theme.Font.Mono,
		TextXAlignment = Enum.TextXAlignment.Left,
		TextYAlignment = Enum.TextYAlignment.Top,
		TextWrapped = true,
		Visible = false,
		LayoutOrder = 3,
		Parent = f.field,
	})

	local lastValue: any = nil
	local valid = true

	local function syncGutter()
		if not gutter then
			return
		end
		local n = 1
		for _ in string.gmatch(box.Text, "\n") do
			n += 1
		end
		local lines = table.create(n)
		for i = 1, n do
			lines[i] = tostring(i)
		end
		gutter.Text = table.concat(lines, "\n")
	end

	-- Run the consumer parser; cache value on success, surface the error on fail.
	-- No parser → always "valid", value stays nil (Get() still yields raw text).
	local function validate(focused: boolean?)
		if not opts.Parse then
			return
		end
		local ok, res = pcall(opts.Parse, box.Text)
		valid = ok and res ~= nil
		lastValue = valid and res or nil

		if valid then
			status.Visible = false
			if not focused then
				Tween.play(stroke, Tween.Fast, { Color = colors.border })
			end
		else
			status.Text = ok and "Parse returned nil" or tostring(res)
			status.Visible = true
			Tween.play(stroke, Tween.Fast, { Color = colors.danger })
		end
		if opts.OnParse then
			opts.OnParse(valid, lastValue, (not valid) and status.Text or nil)
		end
	end

	box.Focused:Connect(function()
		Tween.play(stroke, Tween.Fast, { Color = ctx.Accent })
	end)
	box.FocusLost:Connect(function()
		validate(false)
		if valid then
			Tween.play(stroke, Tween.Fast, { Color = colors.border })
		end
	end)
	-- `handle:Set` writes `box.Text` and lets this signal do the work, so the two
	-- are indistinguishable from in here — the guard is only about *attribution*
	-- (Context:OnFlagChanged), and the callback fires exactly as it always did
	-- either way.
	local writing = false
	box:GetPropertyChangedSignal("Text"):Connect(function()
		syncGutter()
		if opts.Callback then
			if writing then
				task.spawn(opts.Callback, box.Text)
			else
				ctx:User(task.spawn, opts.Callback, box.Text)
			end
		end
	end)

	syncGutter()
	task.defer(function()
		validate(false)
	end)

	local handle = {}
	function handle:Get(): string
		return box.Text
	end
	function handle:Set(value: any)
		writing = true
		box.Text = tostring(value)
		writing = false
		syncGutter()
		validate(false)
	end
	-- The parsed value from the last successful Parse (nil if invalid / no parser).
	function handle:GetValue(): any
		return lastValue
	end
	-- Force a re-parse now; returns ok, value|errString.
	function handle:Validate(): (boolean, any)
		validate(false)
		-- Explicit branch, not `valid and lastValue or status.Text`: with no Parse
		-- (or a parser whose value is falsy) lastValue is nil and the idiom falls
		-- through to the status label, reporting the empty string as an error
		-- message on a control that is perfectly valid.
		if valid then
			return true, lastValue
		end
		return false, status.Text
	end

	return f.field, handle, true
end

end

__modules['components.Colorpicker'] = function(...)
--!strict
-- components/Colorpicker.lua — swatch button + preset grid popover with hex.

local Create = __require("util.Create")
local Theme = __require("Theme")
local Tween = __require("util.Tween")
local Log = __require("util.Log")
local Field = __require("components.Field")

-- Uranium accent ramp first, then the useful off-palette signals.
local DEFAULT_PRESETS = {
	"7be04a", "96ec69", "4e9b2b", "2dd4bf", "ffc53d", "ff6b6b",
	"3b82f6", "8b5cf6", "ec4899", "e9f2e5", "98a394", "171d15",
}

local function toHex(color: Color3): string
	return ("#%02X%02X%02X"):format(
		math.round(color.R * 255),
		math.round(color.G * 255),
		math.round(color.B * 255)
	)
end

local SCHEMA: Log.Schema = {
	{ "Default", "Color3" },
	{ "Presets", "table" },
}

return function(ctx: any, opts: any)
	local colors = Theme.Colors
	local where = Log.where("Colorpicker", opts.Name)
	Log.check(where, opts, SCHEMA)
	local f = Field.new(ctx, opts)
	-- ctx.Accent, not the static theme accent: a window built with a custom accent
	-- would otherwise hand an un-defaulted picker theme green as its swatch and as
	-- its :Get()/flag value.
	local value: Color3 = opts.Default or ctx.Accent

	local swatch = Create("TextButton", {
		Name = "Colorpicker",
		AutoButtonColor = false,
		Text = "",
		Size = UDim2.fromOffset(30, 30),
		BackgroundColor3 = value,
		LayoutOrder = 2,
		Parent = f.row,
	}, {
		Create.corner(8),
		Create.stroke(colors.border),
	})

	-- Frame, not CanvasGroup — the hex readout inside it would come out blurry
	-- (see util/Fade.lua); Context:OpenPopover fades it in without a buffer.
	local menu = Create("Frame", {
		Name = "ColorMenu",
		Visible = false,
		Size = UDim2.fromOffset(168, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		BackgroundColor3 = colors.pop,
	}, {
		Create.corner(10),
		Create.stroke(colors.border),
		Create.padding(10),
		Create.listLayout({ Padding = UDim.new(0, 9) }),
	})

	local grid = Create("Frame", {
		Name = "Grid",
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		LayoutOrder = 1,
		Parent = menu,
	}, {
		Create("UIGridLayout", {
			CellSize = UDim2.fromOffset(19, 19),
			CellPadding = UDim2.fromOffset(6, 6),
			SortOrder = Enum.SortOrder.LayoutOrder,
		}),
	})

	local hexLabel = Create("TextLabel", {
		Name = "Hex",
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 14),
		Text = toHex(value),
		TextColor3 = colors.text_muted,
		TextSize = 12,
		FontFace = Theme.Font.Mono,
		TextXAlignment = Enum.TextXAlignment.Left,
		LayoutOrder = 2,
		Parent = menu,
	})

	local function apply(color: Color3)
		value = color
		Tween.play(swatch, Tween.Normal, { BackgroundColor3 = color })
		hexLabel.Text = toHex(color)
		if opts.Callback then
			task.spawn(opts.Callback, color)
		end
	end

	for i, hex in (opts.Presets or DEFAULT_PRESETS) do
		-- Presets are caller-supplied, and Color3.fromHex throws on anything it
		-- can't parse — so one typo in a menu's palette used to kill the whole
		-- window build with a raw engine error rather than the offending swatch.
		local okHex, preset = pcall(Color3.fromHex, hex)
		if not okHex then
			Log.warn(where, ('Preset #%d ("%s") isn\'t a hex colour — skipped.')
				:format(i, tostring(hex)))
			continue
		end
		local chip = Create("TextButton", {
			Name = "Chip" .. i,
			AutoButtonColor = false,
			Text = "",
			BackgroundColor3 = preset,
			LayoutOrder = i,
			Parent = grid,
		}, {
			Create.corner(6),
			Create("UIStroke", { Color = colors.text, Transparency = 0.9 }),
			Create("UIScale", {}),
		})
		local chipScale = chip:FindFirstChildOfClass("UIScale") :: UIScale
		chip.MouseEnter:Connect(function()
			Tween.play(chipScale, Tween.Spring, { Scale = 1.18 })
		end)
		chip.MouseLeave:Connect(function()
			Tween.play(chipScale, Tween.Fast, { Scale = 1 })
		end)
		-- User-driven, so it's tagged for Context:OnFlagChanged — `handle:Set` and a
		-- config load reach `apply` too, and keep whatever tag they came in under.
		chip.Activated:Connect(function()
			ctx:User(apply, chip.BackgroundColor3)
			ctx:ClosePopover()
		end)
	end

	swatch.Activated:Connect(function()
		if ctx:IsOpen(menu) then
			ctx:ClosePopover()
		else
			ctx:OpenPopover(menu, swatch)
		end
	end)

	local handle = {}
	function handle:Get(): Color3
		return value
	end
	function handle:Set(color: Color3)
		apply(color)
	end

	return f.field, handle, true
end

end

__modules['components.Controls'] = function(...)
--!strict
-- components/Controls.lua — the control surface shared by Group cards and
-- Sections. Owns the container, dispatches to component builders, and manages
-- the 1px "between-field" separators (drawn after every bordered item except
-- the last, mirroring the CSS `:last-child` border rule).

local Create = __require("util.Create")
local Theme = __require("Theme")
local Log = __require("util.Log")

local Toggle = __require("components.Toggle")
local Slider = __require("components.Slider")
local Dropdown = __require("components.Dropdown")
local Input = __require("components.Input")
local Code = __require("components.Code")
local Keybind = __require("components.Keybind")
local Colorpicker = __require("components.Colorpicker")
local Button = __require("components.Button")
local Paragraph = __require("components.Paragraph")
local Label = __require("components.Label")
local Divider = __require("components.Divider")
local List = __require("components.List")
local Player = __require("components.Player")
local PlayerSelect = __require("components.PlayerSelect")
local Section = __require("components.Section")
local Custom = __require("components.Custom")
local Image = __require("components.Image")
local DataGrid = __require("components.DataGrid")
local MediaPlayer = __require("components.MediaPlayer")

-- The options EVERY control takes, checked here so each component only declares
-- what it adds on top (its own `SCHEMA`). `Desc` and `Default` are deliberately
-- absent: `Desc` is Field's, and `Default` is a different type per control.
local COMMON_SCHEMA: Log.Schema = {
	{ "Name", "string" },
	{ "Callback", "function" },
	{ "Flag", "string" },
}

local Controls = {}

-- `inheritParent` is the bind-HUD parent (util/Bind.lua's tree) a Group or
-- Section declared for everything inside it — see the note on `mount` below.
function Controls.new(ctx: any, frame: Frame, inheritParent: any?)
	local items: { { inst: Instance, sep: Frame?, bordered: boolean } } = {}
	local count = 0
	-- `Parent = true` on the container: the first bindable control in it is the
	-- feature, and everything bindable after it is a sub-option of that one. It's
	-- the "Aimbot / Sticky Aim / Wall Check / Auto Fire" card written the way it's
	-- always written, without having to repeat the feature's name — which is the
	-- shape that made the bind HUD unreadable in the first place. Resolved to a
	-- name here rather than a handle so it behaves exactly like the explicit form.
	local autoParent: any = nil

	-- The invariant every separator is kept at: visible iff its own item is
	-- bordered AND something still follows it (the CSS `:last-child` rule the
	-- reference draws). Only TWO of them can move when an item is appended — the
	-- new one (nothing follows it yet) and the previous one (something does now) —
	-- so that's all this touches. Re-deriving the whole list on every insert made
	-- building a card quadratic in its control count, for no answer that differed.
	local function place(inst: Instance, bordered: boolean)
		count += 1
		;(inst :: any).LayoutOrder = count * 2
		inst.Parent = frame

		local sep: Frame? = nil
		if bordered then
			sep = Create("Frame", {
				Name = "Separator",
				Size = UDim2.new(1, 0, 0, 1),
				BackgroundColor3 = Theme.Colors.border_soft,
				BorderSizePixel = 0,
				Visible = false, -- last item so far; the next `place` turns it on
				LayoutOrder = count * 2 + 1,
				Parent = frame,
			})
		end
		local previous = items[#items]
		if previous and previous.sep then
			previous.sep.Visible = previous.bordered
		end
		table.insert(items, { inst = inst, sep = sep, bordered = bordered })
	end

	-- Build via a component, drop it in, register it as a flag (if it carries one
	-- and a serializable `kind`), then hand back the control's handle.
	-- `label` is the human name used in diagnostics (defaults to the kind).
	local function mount(builder: (any, any) -> (Instance, any, boolean), opts: any, kind: string?, label: string?): any
		-- Generic option shape checks shared by every control, so a bad Callback
		-- or a table where a value was expected fails with a readable message
		-- instead of erroring deep inside the component builder.
		local control = label or (kind and (kind:gsub("^%l", string.upper))) or "Control"
		if opts ~= nil and type(opts) ~= "table" then
			Log.fail(control, ("options must be a table, got %s (write %s({ Name = ... }))")
				:format(typeof(opts), control))
		end
		if opts then
			Log.check(Log.where(control, opts.Name), opts, COMMON_SCHEMA)
		end

		-- A Group / Section built with `Parent = "<feature>"` hands that down to
		-- every bindable control inside it, so a card full of sub-options declares
		-- it once at the top instead of on every line — which is the shape the bind
		-- HUD's roll-up (util/Bind.lua `Binding:IsListed`) is worth having. An
		-- explicit `Parent` on the control itself still wins, and controls that
		-- aren't bindable ignore the field.
		-- `false` means "this container resolved to no feature" (see api:Section) and
		-- is skipped like nil — otherwise it was cloned onto every control's
		-- `Parent`, where util/Bind.lua's refKey discards it anyway.
		local bindable = kind == "toggle" or kind == "bind"
		-- ...and of those, the ones that can actually GO LIVE. A `Keybind` defaults
		-- to `Mode = "None"` — a pure key picker, which never activates and is never
		-- listed in the bind HUD (util/Bind.lua `Binding:IsListed`). Only a control
		-- that can be *running* is allowed to be the feature a `Parent = true` card
		-- is named after: letting a picker claim the slot pointed every toggle in
		-- the card at a parent that can never appear, and a keyless sub-option is
		-- only listed when it has no parent — so the whole card silently dropped out
		-- of the HUD. Inheriting a parent is still fine for a picker (it's invisible
		-- either way); it's claiming one that isn't.
		local activates = kind == "toggle"
			or (kind == "bind" and opts ~= nil and type(opts.Mode) == "string"
				and opts.Mode:lower() ~= "none")
		if bindable and inheritParent ~= nil and inheritParent ~= false
			and opts ~= nil and opts.Parent == nil then
			if inheritParent ~= true then
				opts = table.clone(opts)
				opts.Parent = inheritParent
			elseif autoParent == nil then
				-- `Parent = true`: the first bindable control here IS the feature, so
				-- it claims the slot rather than filling one. `false` = it had neither
				-- a Flag nor a Name, so there's nothing later controls could point at.
				-- A picker leaves the slot open for whatever comes next instead.
				if activates then
					autoParent = opts.Flag or opts.Name or false
				end
			elseif autoParent then
				opts = table.clone(opts)
				opts.Parent = autoParent
			end
		end

		-- Change notification (Context:OnFlagChanged) hangs off the control's own
		-- callbacks rather than off each component's internals: every stateful
		-- control already fires `Callback` on every value change — a click, a drag,
		-- a `:Set`, a config landing — and updates its state before it does, so one
		-- wrapper here covers every kind instead of a hook per component.
		--
		-- `OnChanged` is wrapped for the same reason: a Keybind in an activation
		-- mode spends `Callback` on activation, and re-keying it (which is what
		-- moves the flag) only reaches `OnChanged`.
		--
		-- The wrappers go on a COPY. `opts` is the caller's table and a loader that
		-- reuses one across two controls must not find our closure baked into it —
		-- same rule components/Settings.lua follows for its section options.
		local flag = opts and opts.Flag
		local watched = flag ~= nil and kind ~= nil
		local handle: any = nil
		if watched then
			local copy = table.clone(opts)
			local onCallback, onChanged = opts.Callback, opts.OnChanged
			local function notify()
				-- `handle` is nil only if a control fires a callback from inside its
				-- own constructor, before we've been handed it — nothing does today,
				-- and a value that early is the default anyway.
				if handle then
					ctx:NotifyFlag(flag)
				end
			end
			-- Notified BEFORE the caller's own callback: a callback that yields
			-- (or errors) shouldn't delay or swallow the notification, and the
			-- ambient source tag is still the one the change came in under.
			copy.Callback = function(...)
				notify()
				if onCallback then
					return onCallback(...)
				end
				return nil
			end
			copy.OnChanged = function(...)
				notify()
				if onChanged then
					return onChanged(...)
				end
				return nil
			end
			opts = copy
		end

		local inst, built, bordered = builder(ctx, opts)
		handle = built
		place(inst, bordered)
		if watched then
			ctx:RegisterFlag(flag, handle, kind)
		end
		return handle
	end

	local api = {}

	function api:Toggle(o) return mount(Toggle, o, "toggle") end
	function api:Slider(o) return mount(Slider, o, "slider") end
	function api:Input(o) return mount(Input, o, "input") end
	function api:Code(o) return mount(Code, o, "code") end
	-- "bind" (not "keybind") — the flag persists the key AND the mode.
	function api:Keybind(o) return mount(Keybind, o, "bind", "Keybind") end
	function api:Colorpicker(o) return mount(Colorpicker, o, "colorpicker") end
	function api:Paragraph(o) return mount(Paragraph, o, nil, "Paragraph") end
	function api:Label(o) return mount(Label, o, nil, "Label") end
	function api:Divider() return mount(Divider, {}, nil, "Divider") end
	function api:Player(o) return mount(Player, o, nil, "Player") end
	-- Source is caller-owned content (an id / path / url), not a settable value,
	-- so it gets no Flag codec — same call as Custom / DataGrid.
	function api:Image(o) return mount(Image, o, nil, "Image") end
	function api:List(o) return mount(List, o, nil, "List") end

	function api:Dropdown(o)
		return mount(function(c, opts)
			return Dropdown(c, opts, false)
		end, o, "dropdown")
	end
	function api:MultiDropdown(o)
		return mount(function(c, opts)
			return Dropdown(c, opts, true)
		end, o, "dropdown")
	end

	function api:PlayerSelect(o)
		return mount(function(c, opts)
			return PlayerSelect(c, opts, false)
		end, o, "playerselect")
	end
	function api:PlayerMultiSelect(o)
		return mount(function(c, opts)
			return PlayerSelect(c, opts, true)
		end, o, "playerselect")
	end

	function api:Button(o)
		Log.field(Log.where("Button", o and o.Name), "Callback", o and o.Callback, "function")
		local inst, handle, bordered = Button.single(ctx, o)
		place(inst, bordered)
		return handle
	end
	function api:ButtonRow(list)
		if type(list) ~= "table" then
			Log.fail("ButtonRow", ("expects an array of { Label = ..., Callback = ... } buttons, got %s")
				:format(typeof(list)))
		end
		local inst, handle, bordered = Button.row(ctx, list)
		place(inst, bordered)
		return handle
	end

	function api:Section(o)
		if o ~= nil and type(o) ~= "table" then
			Log.fail("Section", ("options must be a table like { Title = ... }, got %s"):format(typeof(o)))
		end
		Log.field(Log.where("Section", o and o.Title), "Parent", o and o.Parent, { "string", "boolean", "table" })
		local section, body = Section(ctx, o)
		place(section, true)
		-- A section is the natural place to say "everything under here belongs to
		-- that feature" — one line above eight sub-toggles. Falls through to the
		-- card's own declaration when the section doesn't make one; under a
		-- `Parent = true` card that means the feature the card already picked, so a
		-- section of sub-options doesn't start a second one of its own.
		--
		-- Spelled out rather than `(cond and autoParent) or inheritParent`: under a
		-- `Parent = true` card whose first bindable control had neither a Flag nor a
		-- Name, `autoParent` is the sentinel `false` — and the idiom fell straight
		-- through it to `inheritParent` (`true`), so the section started hunting for
		-- a feature of its own and every control in it became a sub-option of the
		-- section's first one. There is no feature to point at in that case; "no
		-- parent" is the honest answer.
		local inherit = o and o.Parent
		if inherit == nil then
			if inheritParent == true and autoParent ~= nil then
				inherit = autoParent -- the card's feature, or `false` for "there isn't one"
			else
				inherit = inheritParent
			end
		end
		return Controls.new(ctx, body, inherit)
	end

	-- Escape hatch: `builder(ctx, frame)` parents whatever it wants into `frame`.
	-- No Flag/kind — content is caller-owned, not a config-serializable value.
	function api:Custom(builder: ((any, Frame) -> ())?)
		if builder ~= nil and type(builder) ~= "function" then
			Log.fail("Custom", ("expects a builder function builder(ctx, frame), got %s"):format(typeof(builder)))
		end
		return mount(function(c, _opts)
			return Custom(c, builder)
		end, nil, nil, "Custom")
	end

	function api:DataGrid(o)
		return mount(DataGrid, o, nil, "DataGrid")
	end

	function api:MediaPlayer(o)
		return mount(MediaPlayer, o, nil, "MediaPlayer")
	end

	return api
end

return Controls

end

__modules['components.Custom'] = function(...)
--!strict
-- components/Custom.lua — escape hatch for parenting arbitrary Instances into
-- a Group/Section, for tools shaped nothing like the built-in controls (data
-- grids, custom previews, bespoke widgets).
--
-- `frame` is already (1,0)-wide + AutomaticSize.Y, matching the height-
-- reporting contract every control relies on (see CLAUDE.md "Adding a new
-- control") — nest your own content into it directly. If you need a fixed-
-- height scrollable viewport instead of unbounded growth, wrap a fixed-size
-- ScrollingFrame inside `frame`, the same way components/Code.lua does.

local Create = __require("util.Create")

return function(ctx: any, builder: ((any, Frame) -> ())?): (Frame, {}, boolean)
	local frame = Create("Frame", {
		Name = "Custom",
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
	}) :: Frame

	if builder then
		builder(ctx, frame)
	end

	return frame, {}, false
end

end

__modules['components.DataGrid'] = function(...)
--!strict
-- components/DataGrid.lua — dense, high-refresh-rate row grid (memory/value
-- scanner, traffic log, instance browser, leaderboard...). Built on the same
-- "fixed-height viewport inside an AutomaticSize.Y field" pattern as Code.lua,
-- so the card/Collapse machinery needs no changes to host it.
--
-- Row frames are pooled and reused across :SetRows calls — only cells whose
-- value actually changed get a property write — since the intended workload
-- is a few hundred live rows updating several times a second, not a one-shot
-- render.

local Create = __require("util.Create")
local Theme = __require("Theme")
local Tween = __require("util.Tween")
local Icons = __require("Icons")
local Log = __require("util.Log")
local Field = __require("components.Field")

export type ActionDef = { Name: string, Text: string?, Icon: string? }
export type ColumnDef = {
	Key: string,
	Title: string?,
	Width: number, -- fraction (0..1) of the grid's content width
	Editable: boolean?,
	Type: ("text" | "actions")?,
}

local PAD = 12
local CELL_GAP = 10

-- Inner offset-based inset so column math sits in an unambiguous coordinate
-- space — avoids relying on how UIPadding does or doesn't interact with
-- Scale-positioned siblings (untested combination elsewhere in this codebase).
local function makeContent(parent: Instance): Frame
	return Create("Frame", {
		Name = "Content",
		BackgroundTransparency = 1,
		Position = UDim2.fromOffset(PAD, 0),
		Size = UDim2.new(1, -PAD * 2, 1, 0),
		Parent = parent,
	}) :: Frame
end

return function(ctx: any, opts: any): (Frame, any, boolean)
	local colors = Theme.Colors
	local where = Log.where("DataGrid", opts.Name)
	local f = Field.new(ctx, opts, true)

	local columns: { ColumnDef } = opts.Columns or {}
	local rowHeight = opts.RowHeight or 27
	local bodyHeight = opts.Height or 200

	local offsets: { number } = {}
	do
		local x = 0
		for i, col in columns do
			offsets[i] = x
			x += col.Width
		end
	end

	-- ── header ────────────────────────────────────────────────────────────────
	local header = Create("Frame", {
		Name = "Header",
		BackgroundColor3 = colors.control,
		Size = UDim2.new(1, 0, 0, rowHeight),
		LayoutOrder = 2,
		Parent = f.field,
	}, {
		Create.corner(Theme.Metrics.controlRadius),
		Create.stroke(colors.border),
	})
	local headerContent = makeContent(header)
	for i, col in columns do
		Create("TextLabel", {
			Name = "Head_" .. col.Key,
			BackgroundTransparency = 1,
			Position = UDim2.new(offsets[i], 0, 0, 0),
			Size = UDim2.new(col.Width, -CELL_GAP, 1, 0),
			Text = col.Title or col.Key,
			TextColor3 = colors.text_muted,
			TextSize = 12,
			FontFace = Theme.Font.Medium,
			TextXAlignment = Enum.TextXAlignment.Left,
			TextTruncate = Enum.TextTruncate.AtEnd,
			Parent = headerContent,
		})
	end

	-- ── body (fixed-height scrolling viewport — the Code.lua pattern) ─────────
	local body = Create("ScrollingFrame", {
		Name = "Body",
		Size = UDim2.new(1, 0, 0, bodyHeight),
		BackgroundColor3 = colors.control,
		BorderSizePixel = 0,
		ClipsDescendants = true,
		CanvasSize = UDim2.new(),
		AutomaticCanvasSize = Enum.AutomaticSize.Y,
		ScrollingDirection = Enum.ScrollingDirection.Y,
		ScrollBarThickness = 4,
		ScrollBarImageColor3 = colors.text_dim,
		ScrollBarImageTransparency = 0.35,
		LayoutOrder = 3,
		Parent = f.field,
	}, {
		Create.corner(Theme.Metrics.controlRadius),
		Create.stroke(colors.border),
		Create.listLayout({}),
	})

	local rowEdited = Instance.new("BindableEvent")
	local rowAction = Instance.new("BindableEvent")

	type RowEntry = {
		frame: Frame,
		id: any,
		data: { [string]: any },
		lastValues: { [string]: any },
		cells: { [string]: TextLabel | TextBox },
		actionHolders: { [string]: Frame },
	}

	-- Paint a button's face. Separate from the build because renderActions reuses
	-- a button by Name across renders, so an action that swaps its Icon ("lock" →
	-- "unlock") or its Text has to actually repaint instead of keeping whatever
	-- it was first built with. The icon name is stashed as an attribute so the
	-- common case — same action re-sent every tick — costs one comparison rather
	-- than a rebuilt instance.
	local function paintActionButton(btn: TextButton, action: ActionDef)
		-- Icon takes priority when both are given — a fixed-size icon button,
		-- Text unused. Text alone renders as an auto-width label pill.
		local iconOnly = action.Icon ~= nil
		btn.Size = iconOnly and UDim2.fromOffset(22, 22) or UDim2.new(0, 0, 0, 22)
		btn.AutomaticSize = iconOnly and Enum.AutomaticSize.None or Enum.AutomaticSize.X
		btn.Text = iconOnly and "" or (action.Text or action.Name)

		if btn:GetAttribute("icon") == action.Icon then
			return
		end
		btn:SetAttribute("icon", action.Icon)
		local old = btn:FindFirstChild("Icon")
		if old then
			-- Rebuilt rather than Icons.apply'd: apply no-ops on an unknown name and
			-- can't cross between the ImageLabel and the glyph-TextLabel fallback.
			old:Destroy()
		end
		if action.Icon then
			local icon = Icons.new(action.Icon, 14, colors.text_dim)
			icon.AnchorPoint = Vector2.new(0.5, 0.5)
			icon.Position = UDim2.fromScale(0.5, 0.5)
			icon.Parent = btn
		end
	end

	local function buildActionButton(action: ActionDef): TextButton
		local btn = Create("TextButton", {
			Name = action.Name,
			AutoButtonColor = false,
			BackgroundColor3 = colors.control,
			Size = UDim2.fromOffset(22, 22),
			Text = "",
			TextColor3 = colors.text,
			TextSize = 12,
			FontFace = Theme.Font.Medium,
		}, {
			Create.corner(6),
			Create.padding(0, 8),
		}) :: TextButton

		Create.hover(btn, "BackgroundColor3", colors.control, colors.control_hi)
		return btn
	end

	-- Reuses buttons keyed by action Name across renders (repainting each for the
	-- action it now carries) and drops ones no longer present.
	local function renderActions(entry: RowEntry, key: string, actions: { ActionDef })
		local holder = entry.actionHolders[key]
		local seen: { [string]: boolean } = {}
		for i, action in actions do
			local child = holder:FindFirstChild(action.Name)
			local btn: TextButton
			if child and child:IsA("TextButton") then
				btn = child :: TextButton
			else
				btn = buildActionButton(action)
				btn.Parent = holder
				local name = action.Name
				btn.Activated:Connect(function()
					if entry.id ~= nil then
						rowAction:Fire(entry.id, name)
					end
				end)
			end
			paintActionButton(btn, action)
			btn.LayoutOrder = i
			seen[action.Name] = true
		end
		for _, child in holder:GetChildren() do
			if child:IsA("GuiObject") and not seen[child.Name] then
				child:Destroy()
			end
		end
	end

	local function buildRowFrame(): RowEntry
		local frame = Create("Frame", {
			Name = "Row",
			BackgroundTransparency = 1,
			Size = UDim2.new(1, 0, 0, rowHeight),
		}) :: Frame
		Create("Frame", {
			Name = "Sep",
			Size = UDim2.new(1, 0, 0, 1),
			Position = UDim2.new(0, 0, 1, -1),
			BackgroundColor3 = colors.border_soft,
			BorderSizePixel = 0,
			Parent = frame,
		})
		local content = makeContent(frame)

		local entry: RowEntry = {
			frame = frame,
			id = nil,
			data = {},
			lastValues = {},
			cells = {},
			actionHolders = {},
		}

		for i, col in columns do
			local pos = UDim2.new(offsets[i], 0, 0, 0)
			local size = UDim2.new(col.Width, -CELL_GAP, 1, 0)

			if col.Type == "actions" then
				local holder = Create("Frame", {
					Name = "Cell_" .. col.Key,
					BackgroundTransparency = 1,
					Position = pos,
					Size = size,
					Parent = content,
				}, {
					Create.listLayout({
						FillDirection = Enum.FillDirection.Horizontal,
						VerticalAlignment = Enum.VerticalAlignment.Center,
						Padding = UDim.new(0, 6),
					}),
				}) :: Frame
				entry.actionHolders[col.Key] = holder
			elseif col.Editable then
				local box = Create("TextBox", {
					Name = "Cell_" .. col.Key,
					Position = pos,
					Size = size,
					BackgroundColor3 = colors.control,
					ClearTextOnFocus = false,
					Text = "",
					TextColor3 = colors.text,
					TextSize = 12,
					FontFace = Theme.Font.Mono,
					TextXAlignment = Enum.TextXAlignment.Left,
					ClipsDescendants = true,
					Parent = content,
				}, {
					Create.corner(4),
					Create.stroke(colors.border),
					Create.padding(0, 6),
				}) :: TextBox
				local stroke = box:FindFirstChildOfClass("UIStroke") :: UIStroke
				-- The row this edit belongs to is captured when it starts, not read
				-- at blur: the frame is pooled, so an edit left open while :SetRows
				-- recycles it would otherwise commit the typed text against whichever
				-- id inherited the frame.
				local editingId: any = nil
				box.Focused:Connect(function()
					editingId = entry.id
					Tween.play(stroke, Tween.Fast, { Color = ctx.Accent })
				end)
				box.FocusLost:Connect(function()
					Tween.play(stroke, Tween.Fast, { Color = colors.border })
					local id = editingId
					editingId = nil
					if id ~= nil and id == entry.id then
						rowEdited:Fire(id, col.Key, box.Text)
					end
				end)
				entry.cells[col.Key] = box
			else
				local label = Create("TextLabel", {
					Name = "Cell_" .. col.Key,
					BackgroundTransparency = 1,
					Position = pos,
					Size = size,
					Text = "",
					TextColor3 = colors.text,
					TextSize = 12,
					FontFace = Theme.Font.Regular,
					TextXAlignment = Enum.TextXAlignment.Left,
					TextTruncate = Enum.TextTruncate.AtEnd,
					Parent = content,
				}) :: TextLabel
				entry.cells[col.Key] = label
			end
		end

		return entry
	end

	-- Writes `data` onto `entry`, touching only the cells whose value actually
	-- changed since the last render — the perf-critical path for fast tickers.
	local function applyRowData(entry: RowEntry, id: any, data: { [string]: any })
		entry.id = id
		entry.data = data
		for _, col in columns do
			local raw = data[col.Key]
			if entry.lastValues[col.Key] ~= raw then
				if col.Type == "actions" then
					entry.lastValues[col.Key] = raw
					renderActions(entry, col.Key, (raw :: { ActionDef }?) or {})
				else
					local cell = entry.cells[col.Key]
					local focused = col.Editable and (cell :: TextBox):IsFocused()
					if not focused then
						-- Only record the value once it's actually on screen. Marking
						-- it applied while the user was mid-edit made the skipped
						-- update permanent: the cell kept the stale text after blur.
						entry.lastValues[col.Key] = raw
						cell.Text = raw ~= nil and tostring(raw) or ""
					end
				end
			end
		end
	end

	local rowsById: { [any]: RowEntry } = {}
	local pool: { RowEntry } = {}

	local function acquireRow(): RowEntry
		local entry = table.remove(pool)
		if entry then
			return entry
		end
		return buildRowFrame()
	end

	local function releaseRow(entry: RowEntry)
		-- Cleared first, so the FocusLost below sees a row that no longer has an id
		-- and drops the half-finished edit instead of committing it.
		entry.id = nil
		entry.data = {}
		-- Drop the change-detection cache with the row: a pooled frame reused for a
		-- different id must repaint every cell, not diff against the old row's data.
		-- Blanking the cells is the other half of that — clearing the cache alone
		-- left the previous row's text and buttons on screen for any column the
		-- next row omits, because applyRowData compares `nil ~= nil` and skips.
		table.clear(entry.lastValues)
		for _, cell in entry.cells do
			if cell:IsA("TextBox") and cell:IsFocused() then
				cell:ReleaseFocus(false)
			end
			cell.Text = ""
		end
		for _, holder in entry.actionHolders do
			for _, child in holder:GetChildren() do
				if child:IsA("GuiObject") then
					child:Destroy()
				end
			end
		end
		entry.frame.Parent = nil
		table.insert(pool, entry)
	end

	local grid = {}
	grid.RowEdited = rowEdited.Event
	grid.RowAction = rowAction.Event

	function grid:SetRows(rows: { { [string]: any } })
		local newIds: { [any]: { [string]: any } } = {}
		local order: { any } = {}
		for i, data in rows do
			local id = data.id
			if id == nil then
				-- One malformed row used to take the whole call down with "table index
				-- is nil" — for a grid refilled several times a second, that's the
				-- entire view gone over one bad entry.
				Log.warn(where, ("row #%d has no `id` — skipped."):format(i))
			else
				newIds[id] = data
				table.insert(order, id)
			end
		end

		for id, entry in rowsById do
			if not newIds[id] then
				releaseRow(entry)
				rowsById[id] = nil
			end
		end

		for i, id in order do
			local entry = rowsById[id]
			if not entry then
				entry = acquireRow()
				rowsById[id] = entry
				entry.frame.Parent = body
			end
			entry.frame.LayoutOrder = i
			applyRowData(entry, id, newIds[id])
		end
	end

	function grid:UpdateRow(id: any, patch: { [string]: any })
		local entry = rowsById[id]
		if not entry then
			return
		end
		local data = entry.data
		for k, v in patch do
			data[k] = v
		end
		applyRowData(entry, id, data)
	end

	function grid:RemoveRow(id: any)
		local entry = rowsById[id]
		if not entry then
			return
		end
		releaseRow(entry)
		rowsById[id] = nil
	end

	return f.field, grid, false
end

end

__modules['components.Divider'] = function(...)
--!strict
-- components/Divider.lua — a hairline with 6px breathing room above/below.

local Create = __require("util.Create")
local Theme = __require("Theme")

return function(ctx: any, _opts: any)
	local holder = Create("Frame", {
		Name = "Divider",
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 13),
	}, {
		Create("Frame", {
			Name = "Line",
			AnchorPoint = Vector2.new(0.5, 0.5),
			Position = UDim2.fromScale(0.5, 0.5),
			Size = UDim2.new(1, 0, 0, 1),
			BackgroundColor3 = Theme.Colors.border_soft,
			BorderSizePixel = 0,
		}),
	})
	-- The divider is itself the separating line → no managed bottom border.
	return holder, {}, false
end

end

__modules['components.Dropdown'] = function(...)
--!strict
-- components/Dropdown.lua — single + multi select.
-- Box is a TextButton; the menu lives in the window overlay (high ZIndex) so it
-- escapes the scrolling content's clip. Single sets + closes; multi toggles a
-- check per option and stays open. Outside click closes (Context popover).

local Create = __require("util.Create")
local Theme = __require("Theme")
local Tween = __require("util.Tween")
local Icons = __require("Icons")
local Log = __require("util.Log")
local Field = __require("components.Field")

local MENU_MAX_H = 232 -- popover height cap; options scroll past it
local MENU_MIN_W = 150

local function build(ctx: any, opts: any, multi: boolean)
	local colors = Theme.Colors
	local where = Log.where(multi and "MultiDropdown" or "Dropdown", opts.Name)
	if opts.Options ~= nil and type(opts.Options) ~= "table" then
		Log.fail(where, ("Options must be an array of strings, got %s"):format(typeof(opts.Options)))
	end
	local options = opts.Options or {}
	local placeholder = opts.Placeholder or "None"
	local stack = opts.Stack == true

	local single: string? = opts.Default
	local selected: { [string]: boolean } = {}
	if multi and type(opts.Default) == "table" then
		for _, v in opts.Default do
			selected[v] = true
		end
	end

	local f = Field.new(ctx, opts, stack)

	-- box ────────────────────────────────────────────────────────────────────
	local box = Create("TextButton", {
		Name = "Dropdown",
		AutoButtonColor = false,
		Text = "",
		Size = stack and UDim2.new(1, 0, 0, 32) or UDim2.fromOffset(opts.Width or 130, 32),
		BackgroundColor3 = colors.control,
		LayoutOrder = 2,
		Parent = stack and f.field or f.row,
	}, {
		Create.corner(Theme.Metrics.controlRadius),
		Create.stroke(colors.border),
		Create.padding(0, 8, 0, 12),
		-- No UIListLayout: a layout-managed child won't render its Rotation, so
		-- the caret is positioned manually to keep it free to spin.
	})
	local boxStroke = box:FindFirstChildOfClass("UIStroke") :: UIStroke

	local valLabel = Create("TextLabel", {
		Name = "Value",
		BackgroundTransparency = 1,
		Size = UDim2.new(1, -24, 1, 0), -- fills, leaving 10px gap + 14px chevron
		AutomaticSize = Enum.AutomaticSize.None,
		Text = placeholder,
		TextColor3 = colors.text_muted,
		TextSize = 13,
		FontFace = Theme.Font.Regular,
		TextXAlignment = Enum.TextXAlignment.Left,
		TextTruncate = Enum.TextTruncate.AtEnd,
		Parent = box,
	})

	local chevron = Icons.new("caret", 14, colors.text_dim)
	chevron.AnchorPoint = Vector2.new(1, 0.5)
	chevron.Position = UDim2.new(1, 0, 0.5, 0);
	(chevron :: any).Parent = box

	-- menu ─────────────────────────────────────────────────────────────────── (parented to overlay on open)
	-- The option list lives in a ScrollingFrame capped at MENU_MAX_H: it used to be
	-- a plain auto-sized frame under a UISizeConstraint, which silently clipped
	-- every option past the sixth with no way to reach them.
	-- A Frame, not a CanvasGroup: a CanvasGroup would rasterize every option
	-- label into a buffer and blur it. Context:OpenPopover fades it in with
	-- util/Fade.lua instead, and ClipsDescendants does the clipping the group's
	-- canvas used to do for free.
	local menu = Create("Frame", {
		Name = "DropdownMenu",
		Visible = false,
		AutomaticSize = Enum.AutomaticSize.Y,
		Size = UDim2.fromOffset(MENU_MIN_W, 0),
		BackgroundColor3 = colors.pop,
		ClipsDescendants = true,
	}, {
		Create.corner(8),
		Create.stroke(colors.border),
		Create.padding(5),
	})

	local scroller = Create("ScrollingFrame", {
		Name = "Options",
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		Size = UDim2.new(1, 0, 0, 0),
		CanvasSize = UDim2.new(),
		AutomaticCanvasSize = Enum.AutomaticSize.Y,
		ScrollingDirection = Enum.ScrollingDirection.Y,
		ScrollBarThickness = 4,
		ScrollBarImageColor3 = colors.text_dim,
		ScrollBarImageTransparency = 0.35,
		Parent = menu,
	}, {
		Create.listLayout({ Padding = UDim.new(0, 2) }),
	})

	-- The viewport is driven off the layout's measured content height rather than
	-- AutomaticSize, so the menu is exactly as tall as its options up to
	-- MENU_MAX_H and scrolls beyond it. (The canvas keeps auto-sizing, which is
	-- what gives the overflow something to scroll through.)
	local optionLayout = scroller:FindFirstChildOfClass("UIListLayout") :: UIListLayout
	local function fitMenu()
		scroller.Size = UDim2.new(1, 0, 0, math.min(MENU_MAX_H, optionLayout.AbsoluteContentSize.Y))
	end
	optionLayout:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(fitMenu)

	local function valueLabelText(): (string, boolean)
		if multi then
			local list = {}
			for _, opt in options do
				if selected[opt] then
					table.insert(list, opt)
				end
			end
			if #list == 0 then
				return placeholder, false
			end
			return table.concat(list, ", "), true
		else
			if single == nil then
				return placeholder, false
			end
			return single, true
		end
	end

	local function relabel()
		local text, hasVal = valueLabelText()
		valLabel.Text = text
		valLabel.TextColor3 = hasVal and colors.text or colors.text_muted
	end

	local function isSelected(opt: string): boolean
		if multi then
			return selected[opt] == true
		end
		return single == opt
	end

	local function fireMulti(): { string }
		local list = {}
		for _, opt in options do
			if selected[opt] then
				table.insert(list, opt)
			end
		end
		return list
	end

	-- Live row handles so toggling a multi-select option repaints just that row.
	-- Rebuilding the whole menu on every click dropped hover states and re-ran the
	-- open animation mid-interaction.
	type Row = { tick: GuiObject, label: TextLabel }
	local rows: { [string]: Row } = {}

	local function paintRow(opt: string)
		local row = rows[opt]
		if not row then
			return
		end
		local sel = isSelected(opt)
		row.tick.Visible = sel
		row.label.TextColor3 = sel and colors.text or colors.text_muted
	end

	local function rebuild()
		table.clear(rows)
		for _, child in scroller:GetChildren() do
			if child:IsA("TextButton") then
				child:Destroy()
			end
		end
		for i, opt in options do
			local optBtn = Create("TextButton", {
				Name = opt,
				AutoButtonColor = false,
				Text = "",
				BackgroundColor3 = colors.control_hi,
				BackgroundTransparency = 1,
				AutomaticSize = Enum.AutomaticSize.Y,
				Size = UDim2.new(1, -4, 0, 0), -- -4 keeps rows clear of the scrollbar
				LayoutOrder = i,
				Parent = scroller,
			}, {
				Create.corner(6),
				Create.padding(7, 9),
				Create.listLayout({
					FillDirection = Enum.FillDirection.Horizontal,
					VerticalAlignment = Enum.VerticalAlignment.Center,
					Padding = UDim.new(0, 9),
				}),
			})

			local tickHolder = Create("Frame", {
				Name = "Tick",
				BackgroundTransparency = 1,
				Size = UDim2.fromOffset(15, 15),
				LayoutOrder = 1,
				Parent = optBtn,
			})
			local tick = Icons.new("check", 14, ctx.Accent)
			tick.Visible = false;
			(tick :: any).Parent = tickHolder

			-- Offset-sized + truncated: an option longer than the menu used to grow
			-- past its edge and get clipped by the menu instead of eliding.
			local label = Create("TextLabel", {
				Name = "Label",
				BackgroundTransparency = 1,
				Size = UDim2.new(1, -24, 0, 16),
				Text = opt,
				TextColor3 = colors.text_muted,
				TextSize = 13,
				FontFace = Theme.Font.Regular,
				TextXAlignment = Enum.TextXAlignment.Left,
				TextTruncate = Enum.TextTruncate.AtEnd,
				LayoutOrder = 2,
				Parent = optBtn,
			})

			rows[opt] = { tick = tick, label = label }
			paintRow(opt)

			Create.hover(optBtn, "BackgroundTransparency", 1, 0)
			-- Picking an option is user-driven, so it's tagged for
			-- Context:OnFlagChanged (a `:Set` and a config load take the same paths
			-- below but keep the ambient tag they came in under).
			optBtn.Activated:Connect(function()
				if multi then
					selected[opt] = not selected[opt] or nil
					paintRow(opt)
					relabel()
					if opts.Callback then
						ctx:User(task.spawn, opts.Callback, fireMulti())
					end
				else
					local previous = single
					single = opt
					if previous then
						paintRow(previous)
					end
					paintRow(opt)
					relabel()
					ctx:ClosePopover()
					if opts.Callback then
						ctx:User(task.spawn, opts.Callback, single)
					end
				end
			end)
		end
	end

	local function setOpenVisual(open: boolean)
		Tween.play(boxStroke, Tween.Fast, { Color = open and ctx.Accent or colors.border })
		Tween.play(chevron, Tween.Spin, { Rotation = open and 180 or 0 })
	end

	box.Activated:Connect(function()
		if ctx:IsOpen(menu) then
			ctx:ClosePopover()
			return
		end
		rebuild()
		fitMenu()
		scroller.CanvasPosition = Vector2.new(0, 0)
		menu.Size = UDim2.fromOffset(math.max(box.AbsoluteSize.X, MENU_MIN_W), 0)
		setOpenVisual(true)
		ctx:OpenPopover(menu, box, function()
			setOpenVisual(false)
		end)
	end)
	Create.hover(box, "BackgroundColor3", colors.control, colors.control_hi)

	-- No accent subscription on purpose, and this is why: everything accent-tinted
	-- here is created or written at OPEN time — the option ticks are built by
	-- `rebuild()`, the box stroke by `setOpenVisual` — so both already read the
	-- live `ctx.Accent`. (There used to be a `RegisterAccent(function() end)` here
	-- with this comment attached; an empty consumer isn't documentation, it's a
	-- dead closure the accent broadcast walks past on every SetAccent, once per
	-- dropdown in the menu.)
	relabel()

	local handle = {}
	function handle:Get(): any
		if multi then
			return fireMulti()
		end
		return single
	end
	function handle:Set(value: any)
		if multi then
			selected = {}
			if type(value) == "table" then
				for _, v in value do
					selected[v] = true
				end
			end
		else
			single = value
		end
		relabel()
		for opt in rows do
			paintRow(opt)
		end
		if opts.Callback then
			task.spawn(opts.Callback, multi and fireMulti() or single)
		end
	end
	-- Replace the option list at runtime (e.g. a refreshed saved-config list).
	-- Drops any selection that's no longer present so the label stays honest.
	function handle:SetOptions(list: { string })
		options = list or {}
		local function present(v: string): boolean
			for _, o in options do
				if o == v then
					return true
				end
			end
			return false
		end
		local changed = false
		if multi then
			for key in selected do
				if not present(key) then
					selected[key] = nil
					changed = true
				end
			end
		elseif single ~= nil and not present(single) then
			single = nil
			changed = true
		end
		relabel()
		if ctx:IsOpen(menu) then
			rebuild()
		end
		-- A prune is a real change of value, so it has to reach the consumer: the
		-- settings tab refreshes its saved-config list through here, and dropping
		-- the config that autoload points at silently left autoload.txt naming a
		-- file that no longer exists. Fired last, and only when something was
		-- actually dropped — a plain refresh stays a no-op, and a callback that
		-- calls SetOptions again finds nothing left to prune, so it can't recurse.
		if changed and opts.Callback then
			task.spawn(opts.Callback, multi and fireMulti() or single)
		end
	end

	return f.field, handle, true
end

return build

end

__modules['components.Field'] = function(...)
--!strict
-- components/Field.lua — the row scaffold every control sits on.
--
-- Layout mirrors `.coreui-field` from the CSS: 10px vertical padding, a flex
-- row with a name/description block on the left and the control on the right.
-- "Stacked" fields (slider, input, full-width dropdown/button) drop the control
-- to its own full-width line below the row.

local Create = __require("util.Create")
local Theme = __require("Theme")

local Field = {}

export type Field = {
	field: Frame, -- the whole field (parent for stacked controls)
	row: Frame,   -- the name | control row (parent for inline controls)
	main: Frame?, -- the name/description block, if a Name was given
}

function Field.new(ctx: any, opts: { Name: string?, Desc: string? }, stack: boolean?): Field
	local colors = Theme.Colors

	local field = Create("Frame", {
		Name = "Field",
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
	}, {
		Create.padding(10, 2),
		Create.listLayout({ Padding = UDim.new(0, 9) }),
	})

	local ROW_GAP = 14
	local row = Create("Frame", {
		Name = "Row",
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		LayoutOrder = 1,
		Parent = field,
	}, {
		Create.listLayout({
			FillDirection = Enum.FillDirection.Horizontal,
			VerticalAlignment = Enum.VerticalAlignment.Center,
			Padding = UDim.new(0, ROW_GAP),
		}),
	})

	local main: Frame? = nil
	if opts.Name then
		local block = Create("Frame", {
			Name = "Main",
			BackgroundTransparency = 1,
			Size = UDim2.new(0, 0, 0, 0),
			AutomaticSize = Enum.AutomaticSize.Y,
			LayoutOrder = 1,
			Parent = row,
		}, {
			Create.listLayout({ Padding = UDim.new(0, 3) }),
		})

		Create("TextLabel", {
			Name = "Title",
			BackgroundTransparency = 1,
			Size = UDim2.new(1, 0, 0, 0),
			AutomaticSize = Enum.AutomaticSize.Y,
			Text = opts.Name,
			TextColor3 = colors.text,
			TextSize = 13,
			FontFace = Theme.Font.Regular,
			TextXAlignment = Enum.TextXAlignment.Left,
			TextYAlignment = Enum.TextYAlignment.Top,
			TextWrapped = true,
			LayoutOrder = 1,
			Parent = block,
		})

		if opts.Desc then
			Create("TextLabel", {
				Name = "Desc",
				BackgroundTransparency = 1,
				Size = UDim2.new(1, 0, 0, 0),
				AutomaticSize = Enum.AutomaticSize.Y,
				Text = opts.Desc,
				TextColor3 = colors.text_muted,
				TextSize = 12,
				FontFace = Theme.Font.Regular,
				TextXAlignment = Enum.TextXAlignment.Left,
				TextYAlignment = Enum.TextYAlignment.Top,
				TextWrapped = true,
				LineHeight = 1.1,
				LayoutOrder = 2,
				Parent = block,
			})
		end
		main = block

		-- No flexbox: the label block consumes the row's leftover width so the
		-- control (added by the caller into `row`) lands flush right. Width is
		-- the row minus every sibling's measured width and the gap to each.
		local function syncMain()
			local used, others = 0, 0
			for _, child in row:GetChildren() do
				if child:IsA("GuiObject") and child ~= block then
					used += child.AbsoluteSize.X
					others += 1
				end
			end
			local avail = row.AbsoluteSize.X - used - others * ROW_GAP
			block.Size = UDim2.new(0, math.max(0, avail), 0, 0)
		end
		row:GetPropertyChangedSignal("AbsoluteSize"):Connect(syncMain)
		row.ChildAdded:Connect(function(child)
			if child:IsA("GuiObject") then
				child:GetPropertyChangedSignal("AbsoluteSize"):Connect(syncMain)
			end
			task.defer(syncMain)
		end)
		task.defer(syncMain)
	end

	return { field = field, row = row, main = main }
end

return Field

end

__modules['components.Group'] = function(...)
--!strict
-- components/Group.lua — titled card with a collapsible body.
-- Header toggles the card's visibility; the card hosts the control surface.

local Create = __require("util.Create")
local Theme = __require("Theme")
local Tween = __require("util.Tween")
local Icons = __require("Icons")
local Collapse = __require("util.Collapse")
local Controls = __require("components.Controls")

-- `scope` is the tab's identity, threaded down from components/Tab.lua: a group
-- is only unique *within* a tab, and the pair is what the window's persisted
-- collapse map is keyed on (see Context:RegisterGroup).
return function(ctx: any, column: Frame, opts: any, scope: string?)
	local colors = Theme.Colors
	local collapsed = opts.Collapsed == true

	local group = Create("Frame", {
		Name = "Group",
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		Parent = column,
	}, {
		Create.listLayout({}),
	})

	-- NOTE: the header does NOT use a UIListLayout. A UIListLayout manages its
	-- children's transforms and suppresses their Rotation, so a chevron laid out
	-- by one never visually spins. Title + chevron are positioned manually so the
	-- chevron is free to rotate (matches a bare ImageLabel, which rotates fine).
	local head = Create("TextButton", {
		Name = "Head",
		AutoButtonColor = false,
		Text = "",
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		LayoutOrder = 1,
		Parent = group,
	}, {
		Create.padding(2, 4, 8, 4),
	})

	Create("TextLabel", {
		Name = "Title",
		BackgroundTransparency = 1,
		AutomaticSize = Enum.AutomaticSize.Y,
		Size = UDim2.new(1, -18, 0, 0), -- leaves room for the chevron flush right
		Text = opts.Title or "Group",
		TextColor3 = colors.text_muted,
		TextSize = 13,
		FontFace = Theme.Font.Medium,
		TextXAlignment = Enum.TextXAlignment.Left,
		Parent = head,
	})

	local chevron = Icons.new("chev", 14, colors.text_dim)
	chevron.AnchorPoint = Vector2.new(1, 0.5)
	chevron.Position = UDim2.new(1, 0, 0.5, 0)
	chevron.Rotation = collapsed and 180 or 0;
	(chevron :: any).Parent = head

	local card = Create("Frame", {
		Name = "Card",
		BackgroundColor3 = colors.card,
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
	}, {
		Create.corner(Theme.Metrics.cardRadius),
		Create.stroke(colors.border),
		Create.padding(2, 14),
		Create.listLayout({}),
	})

	-- A clipping holder owns the card's height so collapse/expand slides the panel
	-- open/closed instead of snapping its visibility.
	local holder, setCollapsed = Collapse.wrap(card, collapsed)
	holder.LayoutOrder = 2
	holder.Parent = group

	-- `any` for the same reason components/Window.lua types its tab handle that
	-- way: the control surface grows the two collapse methods below, and under
	-- --!strict the inferred table type wouldn't take them.
	-- `Parent` on the card makes every bindable control inside it a sub-option of
	-- that feature for the bind HUD (util/Bind.lua's tree) — a group of Aimbot
	-- options says it once here rather than on every toggle.
	local handle: any = Controls.new(ctx, card, opts.Parent)

	-- Everything the titlebar search needs to filter this group, handed over as
	-- direct references.
	--
	-- The filter used to live in components/Window.lua and re-derive all three
	-- from instance NAMES on every keystroke — `page:GetDescendants()` for the
	-- groups, then a recursive `FindFirstChild("Card")` that searched each card's
	-- entire subtree (every control in it) before finding it. That put this file's
	-- layout — that the card is called "Card", that it sits under a "Collapse"
	-- holder, that the title is "Head"/"Title" — into a module that has no other
	-- reason to know any of it, where a rename here would have silently filtered
	-- nothing. The title is lowercased once, at build time, because the search
	-- compares against it lowercased on every keystroke.
	handle._search = {
		group = group,
		card = card,
		title = string.lower(opts.Title or "Group"),
	}

	-- Whether a group is folded is state the user set, and it had no
	-- representation anywhere: not readable, not settable, not in any config. The
	-- window persists it (`uranium_window`), and a host that wants to drive it —
	-- fold everything but the group its feature lives in — needs the same pair.
	function handle:IsCollapsed(): boolean
		return collapsed
	end

	-- `animate = false` snaps, which is what a restore wants: the window shouldn't
	-- play a fold animation for state the user set in a previous session.
	function handle:SetCollapsed(value: boolean, animate: boolean?)
		value = value == true
		if value == collapsed then
			return
		end
		collapsed = value
		if animate == false then
			chevron.Rotation = collapsed and 180 or 0
		else
			Tween.play(chevron, Tween.Spin, { Rotation = collapsed and 180 or 0 })
		end
		setCollapsed(collapsed, animate ~= false)
		ctx:WindowStateChanged()
	end

	head.Activated:Connect(function()
		ctx:User(function()
			handle:SetCollapsed(not collapsed)
		end)
	end)

	-- Registered even when the window isn't persisting anything: the registry is
	-- what assigns the stable key, and a group that only becomes interesting once
	-- a host asks for the snapshot would otherwise have no name to appear under.
	ctx:RegisterGroup(scope or "Tab", opts.Id or opts.Title or "Group", handle)

	return handle
end

end

__modules['components.Hud'] = function(...)
--!strict
-- components/Hud.lua — the floating bind HUD: a small draggable panel that
-- answers "what's on right now?" without opening the menu.
--
-- It reads util/Bind.lua's registry directly (`Bind:Observe` → `Bind:List`), so
-- it isn't a second list anyone has to maintain: every Toggle, every
-- activation-mode `Keybind` control and every `Window:Bind` shows up the moment
-- it has a key on it *or* is switched on, and lights while it's live. The
-- controls pass the `Label` from their own `Name`, so nothing has to be declared
-- twice.
--
-- What it deliberately does NOT show is every bindable feature in the menu:
-- that's a wall of unbound, idle rows that buries the few you actually use. The
-- inclusion rule lives in `Binding:IsListed` — a key, or currently active and
-- not a sub-option of something else — so the panel is "everything bound, plus
-- every top-level feature running".
--
-- That last clause is the roll-up. Bindings form a shallow tree (a control
-- declares `Parent = "<feature>"`, or inherits one from its Group / Section),
-- because turning Aimbot on means turning on the handful of sub-options that
-- make it work — and listing each of those as its own row said nothing the
-- "Aimbot" row above them didn't. A rolled-up sub-option shows as a `+n` count
-- on its parent instead; one the user put a key on is listed anyway, indented
-- under that parent, because a key is them asking for it by name.
--
-- Three deliberate shapes here:
--
--  * It's a SIBLING of the window frame, not a child. Minimizing the window (or
--    the toggle key) has to leave the HUD up — being able to read your binds
--    with the menu closed is the entire point — but it still lives in the
--    window's ScreenGui, so it dies with it and needs no teardown of its own
--    beyond its input connections.
--  * The FPS / ping readout is its OWN card under the panel, not a row inside
--    it — it isn't a bind and it doesn't come from the registry. Being outside
--    the collapsing body is the point: fold the binds away and the numbers stay.
--  * Rows are POOLED and repainted in place. The registry notifies on every
--    press, so a Hold key down/up must not churn instances.
--  * One accent element per row (the live dot). An active row lifts to `card`
--    instead of tinting accent, so a screen full of active binds still reads as
--    a list rather than a wall of green.

local Services = __require("util.Services")

local RunService = Services.RunService
local UserInputService = Services.UserInputService
local Stats = Services.Stats

local Create = __require("util.Create")
local Theme = __require("Theme")
local Tween = __require("util.Tween")
local Fade = __require("util.Fade")
local Icons = __require("Icons")
local Bind = __require("util.Bind")
local Collapse = __require("util.Collapse")
local Log = __require("util.Log")
local Gui = __require("util.Gui")

local WIDTH = 248
local HEADER_H = 30
local ROW_H = 22
local STATS_H = 26 -- the readout bar, which is its own card under the panel
local GAP = 6      -- ...and the air between the two
local PAD_X = 12
local NAME_X = 26
local KEY_W = 110 -- right column: "RShift · always" in 11px mono, with room to spare
local MARGIN = 8  -- keep-on-screen inset
local SUB_X = 12  -- how far a sub-option's row is indented under its parent

-- One pooled bind row: dot (live marker) · name · "KEY · mode".
type Row = { frame: Frame, dot: Frame, name: TextLabel, key: TextLabel }

-- The name label is RichText (for the dim "+2" roll-up count), and a label is
-- whatever the menu author called their feature — so it has to be escaped, or a
-- toggle named "HP < 50%" eats the rest of the row.
local function escape(s: string): string
	return (s:gsub("&", "&amp;"):gsub("<", "&lt;"):gsub(">", "&gt;"))
end

local SCHEMA: Log.Schema = {
	{ "Title", "string" },
	{ "X", "number" },
	{ "Y", "number" },
	{ "MaxRows", "number" },
	{ "Visible", "boolean" },
	{ "Collapsed", "boolean" },
	{ "Stats", "boolean" },
	{ "Fps", "boolean" },
	{ "Ping", "boolean" },
}

return function(ctx: any, parent: Instance, opts: any): any
	opts = opts or {}
	local colors = Theme.Colors
	Log.check("Hud", opts, SCHEMA)

	local maxRows = math.max(1, math.floor(tonumber(opts.MaxRows) or 10))
	-- `Stats = false` drops the whole readout row; Fps/Ping drop one each. The row
	-- also hides itself when nothing is in it, so turning both off (and never
	-- calling SetStat) doesn't leave an empty strip and a hairline behind.
	local showStats = opts.Stats ~= false
	local showFps = showStats and opts.Fps ~= false
	local showPing = showStats and opts.Ping ~= false

	local binds = Bind.get(ctx)
	local connections: { RBXScriptConnection } = {}
	local destroyed = false

	-- Built up front (its methods are filled in at the bottom) so the drag and
	-- collapse handlers below can reach `handle.OnChange` — the hook Window fans
	-- out to `Window:OnHudChanged`, which is how the HUD's flag gets a change
	-- notification. Everything the HUD persists (where it is, whether it's folded,
	-- whether it's up) moves without a control callback anywhere in sight, so
	-- there'd otherwise be nothing to hang one on.
	local handle: any = {}
	local function changed()
		if handle.OnChange then
			handle.OnChange()
		end
	end

	-- ── root ─────────────────────────────────────────────────────────────────
	-- Two cards stacked in one draggable unit: the bind panel, and the FPS/ping
	-- readout as its own bar beneath it. `root` is transparent — it exists to own
	-- the position, the drag, the fade and the entrance scale for both at once.
	local root = Create("Frame", {
		-- Neutral name: the HUD is a direct child of the ScreenGui, so it's as
		-- visible to a walk of the tree as the window itself (util/Gui.lua).
		Name = Gui.rname(),
		Position = UDim2.fromOffset(tonumber(opts.X) or 16, tonumber(opts.Y) or 140),
		Size = UDim2.fromOffset(WIDTH, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		BackgroundTransparency = 1,
		Visible = false, -- revealed below, so the fade snapshots a finished panel
		ZIndex = 10,
		Parent = parent,
	}, {
		Create.listLayout({ Padding = UDim.new(0, GAP) }),
		Create("UIScale", {}),
	})
	local panelScale = root:FindFirstChildOfClass("UIScale") :: UIScale
	local fade = Fade.new(root)

	-- ── panel ────────────────────────────────────────────────────────────────
	-- A miniature of the window: chrome header over a bg body, one border, same
	-- radius. It reads as part of the same UI without being a second window.
	local panel = Create("Frame", {
		Name = "Panel",
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		BackgroundColor3 = colors.bg,
		ClipsDescendants = true,
		LayoutOrder = 1,
		Parent = root,
	}, {
		Create.corner(10),
		Create.stroke(colors.border),
		Create.listLayout(),
	})

	local header = Create("Frame", {
		Name = "Header",
		Size = UDim2.new(1, 0, 0, HEADER_H),
		BackgroundColor3 = colors.chrome,
		LayoutOrder = 1,
		Parent = panel,
	}, {
		-- Round the top corners with the panel, then square off the bottom —
		-- same trick as the window titlebar (util note in Window.lua).
		Create.corner(10),
	})

	local squareFill = Create("Frame", {
		Name = "SquareFill",
		AnchorPoint = Vector2.new(0, 1),
		Position = UDim2.fromScale(0, 1),
		Size = UDim2.new(1, 0, 0, 10),
		BackgroundColor3 = colors.chrome,
		BorderSizePixel = 0,
		Parent = header,
	})
	local headerBorder = Create("Frame", {
		Name = "Border",
		AnchorPoint = Vector2.new(0, 1),
		Position = UDim2.fromScale(0, 1),
		Size = UDim2.new(1, 0, 0, 1),
		BackgroundColor3 = colors.border_soft,
		BorderSizePixel = 0,
		Parent = header,
	})

	local rail = Create("Frame", {
		Name = "Rail",
		AnchorPoint = Vector2.new(0, 0.5),
		Position = UDim2.new(0, PAD_X, 0.5, 0),
		Size = UDim2.fromOffset(3, 11),
		BackgroundColor3 = ctx.Accent,
		BorderSizePixel = 0,
		ZIndex = 2,
		Parent = header,
	}, {
		Create.corner(2),
	})

	local title = Create("TextLabel", {
		Name = "Title",
		BackgroundTransparency = 1,
		Position = UDim2.fromOffset(NAME_X - 4, 0),
		Size = UDim2.new(1, -(NAME_X + 26), 1, 0),
		Text = opts.Title or "Active Binds",
		TextColor3 = colors.text,
		TextSize = 11,
		FontFace = Theme.Font.Bold,
		TextXAlignment = Enum.TextXAlignment.Left,
		TextTruncate = Enum.TextTruncate.AtEnd,
		ZIndex = 2,
		Parent = header,
	})

	-- The caret is positioned by hand, not laid out: a UIListLayout suppresses
	-- child Rotation, and this one spins 180° when the panel collapses.
	local caretBtn = Create("TextButton", {
		Name = "Caret",
		AutoButtonColor = false,
		BackgroundTransparency = 1,
		AnchorPoint = Vector2.new(1, 0.5),
		Position = UDim2.new(1, -10, 0.5, 0),
		Size = UDim2.fromOffset(16, 16),
		Text = "",
		ZIndex = 2,
		Parent = header,
	})
	-- "chev" (up) at rest, spun 180° when collapsed — the same direction and the
	-- same Tween.Spin the group / section headers use.
	local caret = Icons.new("chev", 14, colors.text_dim)
	caret.AnchorPoint = Vector2.new(0.5, 0.5)
	caret.Position = UDim2.fromScale(0.5, 0.5);
	(caret :: any).Parent = caretBtn
	caretBtn.MouseEnter:Connect(function()
		Icons.tint(caret, colors.text)
	end)
	caretBtn.MouseLeave:Connect(function()
		Icons.tint(caret, colors.text_dim)
	end)

	-- ── body (collapsible) ───────────────────────────────────────────────────
	local body = Create("Frame", {
		Name = "Body",
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		BackgroundTransparency = 1,
	}, {
		Create.listLayout(),
	})

	local list = Create("Frame", {
		Name = "Binds",
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		BackgroundTransparency = 1,
		LayoutOrder = 1,
		Parent = body,
	}, {
		Create.padding(5, 0),
		Create.listLayout(),
	})

	local empty = Create("TextLabel", {
		Name = "Empty",
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, ROW_H),
		Text = "Nothing bound yet",
		TextColor3 = colors.text_dim,
		TextSize = 11,
		FontFace = Theme.Font.Regular,
		LayoutOrder = 1000,
		Parent = list,
	})
	local more = Create("TextLabel", {
		Name = "More",
		Visible = false,
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 16),
		Text = "",
		TextColor3 = colors.text_dim,
		TextSize = 10,
		FontFace = Theme.Font.Regular,
		LayoutOrder = 1001,
		Parent = list,
	})

	local holder, setCollapsedHeight = Collapse.wrap(body, opts.Collapsed == true)
	holder.LayoutOrder = 2
	holder.Parent = panel

	-- Collapsed, the header IS the whole panel, so its bottom corners have to
	-- round with it. ClipsDescendants clips to a RECTANGLE, not to the UICorner
	-- shape (see the same note in Window.lua), so the square chrome fill would
	-- otherwise poke past the panel's rounded bottom corners as two little nubs
	-- with the divider hairline drawn straight across them. Hiding both hands the
	-- corners back to the header's own UICorner, which matches the panel's radius.
	-- The hide waits out the collapse tween (the header's bottom isn't the panel's
	-- bottom until then); the show has to be immediate, before the body slides in
	-- behind it.
	local squareToken = 0
	local function setHeaderSquared(square: boolean, after: number?)
		squareToken += 1
		local token = squareToken
		local function apply()
			if destroyed or token ~= squareToken then
				return
			end
			squareFill.Visible = square
			headerBorder.Visible = square
		end
		if after and after > 0 then
			task.delay(after, apply)
		else
			apply()
		end
	end
	setHeaderSquared(opts.Collapsed ~= true)

	-- ── stat bar ─────────────────────────────────────────────────────────────
	-- FPS / ping is NOT a row inside the bind list: it isn't a bind, it doesn't
	-- come from the registry, and stuffing it above the rows behind a hairline
	-- made it read as a strange first entry. It's its own card below the panel —
	-- a sibling of it, not a child — which also means COLLAPSING the panel leaves
	-- the readout up. That's the state you want it in most: binds folded away,
	-- frames and ping still on screen.
	local statsBar = Create("Frame", {
		Name = "Stats",
		Visible = false,
		Size = UDim2.new(1, 0, 0, STATS_H),
		BackgroundColor3 = colors.chrome,
		LayoutOrder = 2,
		Parent = root,
	}, {
		Create.corner(8),
		Create.stroke(colors.border),
		Create.padding(0, PAD_X),
		Create.listLayout({
			FillDirection = Enum.FillDirection.Horizontal,
			VerticalAlignment = Enum.VerticalAlignment.Center,
			Padding = UDim.new(0, 14),
		}),
	})

	-- `key` is the trailing unit label AND the identity, so SetStat("FPS", …)
	-- updates the same pill every tick and a caller's SetStat("Coins", "1.2k")
	-- just appends another one.
	local statLabels: { [string]: TextLabel } = {}
	local statOrder = 0
	-- An empty bar is no bar at all: `Stats = false`, or both readouts off and
	-- nothing added by hand, and it disappears — the root's list layout skips
	-- invisible children, so the gap under the panel goes with it.
	local function syncStatsRow()
		statsBar.Visible = showStats and next(statLabels) ~= nil
	end
	local function setStat(key: string, value: string?)
		local label = statLabels[key]
		if value == nil then
			if label then
				label:Destroy()
				statLabels[key] = nil
				syncStatsRow()
			end
			return
		end
		if not label then
			statOrder += 1
			label = Create("TextLabel", {
				Name = key,
				BackgroundTransparency = 1,
				Size = UDim2.new(0, 0, 1, 0),
				AutomaticSize = Enum.AutomaticSize.X,
				RichText = true,
				Text = "",
				TextColor3 = colors.text,
				TextSize = 11,
				FontFace = Theme.Font.Mono,
				TextXAlignment = Enum.TextXAlignment.Left,
				LayoutOrder = statOrder,
				Parent = statsBar,
			}) :: TextLabel
			statLabels[key] = label
			syncStatsRow()
		end
		label.Text = ('%s<font color="#%s"> %s</font>'):format(value, colors.text_dim:ToHex(), key)
	end
	-- Seeded with dashes so FPS/MS hold the first two slots (and the row has its
	-- final height) before the first sample lands half a second later.
	if showFps then
		setStat("FPS", "—")
	end
	if showPing then
		setStat("MS", "—")
	end

	-- ── rows ─────────────────────────────────────────────────────────────────
	local rows: { Row } = {}

	local function newRow(index: number): Row
		local frame = Create("Frame", {
			Name = "Bind",
			Size = UDim2.new(1, 0, 0, ROW_H),
			BackgroundColor3 = colors.card,
			BackgroundTransparency = 1,
			BorderSizePixel = 0,
			Visible = false,
			LayoutOrder = index,
			Parent = list,
		}, {
			Create.corner(6),
		})
		local dot = Create("Frame", {
			Name = "Dot",
			AnchorPoint = Vector2.new(0, 0.5),
			Position = UDim2.new(0, PAD_X, 0.5, 0),
			Size = UDim2.fromOffset(6, 6),
			BackgroundColor3 = colors.border,
			BorderSizePixel = 0,
			Parent = frame,
		}, {
			Create.corner(999),
		})
		local name = Create("TextLabel", {
			Name = "Name",
			BackgroundTransparency = 1,
			Position = UDim2.fromOffset(NAME_X, 0),
			Size = UDim2.new(1, -(NAME_X + KEY_W + PAD_X), 1, 0),
			RichText = true,
			Text = "",
			TextColor3 = colors.text_muted,
			TextSize = 12,
			FontFace = Theme.Font.Medium,
			TextXAlignment = Enum.TextXAlignment.Left,
			TextTruncate = Enum.TextTruncate.AtEnd,
			Parent = frame,
		}) :: TextLabel
		local key = Create("TextLabel", {
			Name = "Key",
			BackgroundTransparency = 1,
			AnchorPoint = Vector2.new(1, 0.5),
			Position = UDim2.new(1, -PAD_X, 0.5, 0),
			Size = UDim2.new(0, KEY_W, 1, 0),
			RichText = true,
			Text = "",
			TextColor3 = colors.text_dim,
			TextSize = 11,
			FontFace = Theme.Font.Mono,
			TextXAlignment = Enum.TextXAlignment.Right,
			TextTruncate = Enum.TextTruncate.AtEnd,
			Parent = frame,
		}) :: TextLabel
		return { frame = frame, dot = dot, name = name, key = key }
	end

	-- `sub` = this row's parent is on screen right above it, so it draws indented
	-- with a smaller dot: a bound sub-option reads as belonging to the feature
	-- over it rather than as another top-level thing that's running.
	local function paintRow(row: Row, entry: any, sub: boolean)
		local active = entry:GetState() == true
		local keyName = Bind.name(entry:GetKey())
		if keyName == "None" then
			-- Idle unbound rows are filtered out by Binding:IsListed, so this is a
			-- keyless bind that's currently ON (an "Always", or a toggle switched on
			-- from the menu) or a `Hud = true` override. The em dash is the honest
			-- answer to "what key?" — there isn't one, it's running anyway.
			keyName = "—"
		end
		local indent = sub and SUB_X or 0
		local text = escape(entry:GetLabel() or "Bind")
		-- Sub-options that are on but rolled up into this row. The count is the
		-- whole point of the roll-up: "Aimbot +3" says the feature is running with
		-- more than its bare minimum on, without spending three rows saying it.
		local extra = entry.CountActive and entry:CountActive() or 0
		if extra > 0 then
			text ..= ('<font color="#%s"> +%d</font>'):format(colors.text_dim:ToHex(), extra)
		end
		row.name.Text = text
		row.name.Position = UDim2.fromOffset(NAME_X + indent, 0)
		row.name.Size = UDim2.new(1, -(NAME_X + indent + KEY_W + PAD_X), 1, 0)
		row.name.TextColor3 = active and colors.text or colors.text_muted
		row.key.Text = ('%s<font color="#%s"> · %s</font>')
			:format(keyName, colors.text_dim:ToHex(), entry:GetMode():lower())
		row.key.TextColor3 = active and colors.text or colors.text_dim
		row.dot.Position = UDim2.new(0, PAD_X + indent, 0.5, 0)
		row.dot.Size = sub and UDim2.fromOffset(4, 4) or UDim2.fromOffset(6, 6)
		row.dot.BackgroundColor3 = active and ctx.Accent or colors.border
		row.frame.BackgroundTransparency = active and 0 or 1
		row.frame.Visible = true
	end

	-- Scratch state for `refresh`, cleared and refilled rather than reallocated.
	-- The repaint runs on every registry edge — a Hold key down and up is two, and
	-- a re-key, a mode cycle, a register and a destroy each raise one — so six
	-- fresh tables plus one per block was garbage produced on the input thread, in
	-- a function whose entire premise is that it doesn't churn instances.
	local sListed: { any } = {}
	local sIsListed: { [any]: boolean } = {}
	local sBlocks: { any } = {}
	local sBlockOf: { [any]: any } = {}
	local sOrder: { any } = {}
	local sSubRow: { [any]: boolean } = {}
	local sActive: { any } = {}
	local sIdle: { any } = {}
	-- ...and the blocks with them. A block is `{ entries, active }`; the pool hands
	-- back the same tables every repaint and `blockUsed` is the high-water mark for
	-- this pass, so nothing beyond it is read.
	local blockPool: { any } = {}
	local blockUsed = 0
	local function takeBlock(entry: any): any
		blockUsed += 1
		local block = blockPool[blockUsed]
		if not block then
			block = { entries = {}, active = false }
			blockPool[blockUsed] = block
		end
		table.clear(block.entries)
		block.entries[1] = entry
		block.active = entry:GetState() == true
		return block
	end

	-- The parent of `entry`, but only if that parent is itself on screen — a bound
	-- sub-option whose feature isn't listed has nothing to sit under. Hoisted out
	-- of `refresh` because it closes over `sIsListed`, which is now stable: built
	-- inside, it was one more closure allocated per activation edge.
	local function parentOf(entry: any): any?
		local parent = entry.GetParent and entry:GetParent() or nil
		return (parent and sIsListed[parent]) and parent or nil
	end

	local function refresh()
		if destroyed then
			return
		end
		local listed, isListed = sListed, sIsListed
		table.clear(listed)
		table.clear(isListed)
		table.clear(sBlockOf)
		table.clear(sOrder)
		table.clear(sSubRow)
		blockUsed = 0
		-- `Entries`, not `List`: nothing in this walk registers or destroys a
		-- binding, so the copy `List` makes is pure garbage here.
		for _, entry in binds:Entries() do
			if entry:IsListed() then
				table.insert(listed, entry)
				isListed[entry] = true
			end
		end

		-- Gather each listed bind under its parent, if that parent made the list
		-- too. A bound sub-option whose feature isn't on screen (nothing switched
		-- on, no key on the parent) is its own top-level row — there's nothing for
		-- it to sit under, and hiding it would lose a key the user chose.
		--
		-- Blocks keep parent and children together through the cap sort below, so
		-- an indented row can never end up under an unrelated bind (or, worse, be
		-- the row that got cut).
		--
		-- TWO passes, because one pass silently depended on registration order: a
		-- child seen before its parent found no block to join, opened its own, and
		-- then the parent opened a second one — so the two drew as unrelated
		-- top-level rows and the roll-up count went missing. Parent-first is what
		-- `Parent = true` on a card produces, but an explicit `Parent = "aimbot"`
		-- is free to name a feature built in a later group, and did.
		local blocks, blockOf = sBlocks, sBlockOf
		table.clear(blocks)
		-- Roots first, in registration order — that's the order of the panel.
		for _, entry in listed do
			if not parentOf(entry) then
				local block = takeBlock(entry)
				blockOf[entry] = block
				table.insert(blocks, block)
			end
		end
		-- ...then everything that sits under one of them, attached to its nearest
		-- ancestor that owns a block. The tree is documented as shallow, so that
		-- ancestor is normally just the parent — but walking up rather than reading
		-- `blockOf[parent]` once keeps this independent of the order pass 2 happens
		-- to visit a deeper chain in, and flattening a deep chain into its root's
		-- block is what the renderer draws anyway (one level of indent). The hop
		-- bound is the cycle guard: `Parent` is matched by name, so nothing stops a
		-- menu from pointing two binds at each other.
		for _, entry in listed do
			if not blockOf[entry] then
				local block: any = nil
				local node, hops = parentOf(entry), 0
				while node and hops <= #listed do
					block = blockOf[node]
					if block then
						break
					end
					node = parentOf(node)
					hops += 1
				end
				if block then
					table.insert(block.entries, entry)
				else
					block = takeBlock(entry)
					table.insert(blocks, block)
				end
				blockOf[entry] = block
				block.active = block.active or entry:GetState() == true
			end
		end

		-- Under the cap, rows stay in registration order so nothing jumps around
		-- while you read it. Over the cap, what's LIVE has to be the part you can
		-- see, so active binds float to the top (relative order preserved).
		--
		-- Partitioned through two scratch lists and written back into `blocks`
		-- rather than rebound to a fresh array: `blocks` IS the scratch table, and
		-- pointing the local somewhere else would leave it holding the pooled
		-- blocks from the previous repaint.
		if #listed > maxRows then
			table.clear(sActive)
			table.clear(sIdle)
			for _, block in blocks do
				table.insert(block.active and sActive or sIdle, block)
			end
			table.clear(blocks)
			for _, block in sActive do
				table.insert(blocks, block)
			end
			for _, block in sIdle do
				table.insert(blocks, block)
			end
		end

		local order, subRow = sOrder, sSubRow
		for _, block in blocks do
			for i, entry in block.entries do
				table.insert(order, entry)
				subRow[entry] = i > 1
			end
		end

		local shown = math.min(#order, maxRows)
		for i = 1, shown do
			local row = rows[i]
			if not row then
				row = newRow(i)
				rows[i] = row
			end
			paintRow(row, order[i], subRow[order[i]] == true)
		end
		for i = shown + 1, #rows do
			rows[i].frame.Visible = false
		end
		empty.Visible = shown == 0
		local rest = #order - shown
		more.Visible = rest > 0
		-- Only formatted when it's actually on screen: the overflow line is empty
		-- in the overwhelmingly common case, and this runs on every key edge.
		if rest > 0 then
			more.Text = ("+%d more"):format(rest)
		end
	end

	local unsubscribeBinds = binds:Observe(refresh)
	local unsubscribeAccent = ctx:RegisterAccent(function(accent)
		rail.BackgroundColor3 = accent
		refresh() -- the live dots are the only accent inside the list
	end)

	-- ── position + drag ──────────────────────────────────────────────────────
	-- Offset-only position, rounded to whole pixels: the panel is small and full
	-- of 11px text, and a half-pixel origin is exactly what makes that text look
	-- soft (see Window.lua's snapToPixels).
	local pos = Vector2.new(tonumber(opts.X) or 16, tonumber(opts.Y) or 140)
	local function place(p: Vector2)
		local vp = (parent :: any).AbsoluteSize
		local size = root.AbsoluteSize
		if vp and vp.X > 0 and size.X > 0 then
			p = Vector2.new(
				math.clamp(p.X, MARGIN, math.max(MARGIN, vp.X - size.X - MARGIN)),
				math.clamp(p.Y, MARGIN, math.max(MARGIN, vp.Y - size.Y - MARGIN))
			)
		end
		pos = Vector2.new(math.round(p.X), math.round(p.Y))
		root.Position = UDim2.fromOffset(pos.X, pos.Y)
	end
	place(pos)
	-- A viewport (or a collapse) that shrinks under the panel would otherwise
	-- leave it hanging off an edge with nothing to grab.
	table.insert(connections, (parent :: any):GetPropertyChangedSignal("AbsoluteSize"):Connect(function()
		place(pos)
	end))
	root:GetPropertyChangedSignal("AbsoluteSize"):Connect(function()
		place(pos)
	end)

	-- Both cards drag as one unit — the handle is `root`, so the stat bar and the
	-- gap between them are grabbable too (the rows and pills are plain labels, so
	-- input reaches it through them). Only the caret button is a click target.
	local dragging = false
	local dragStart = Vector2.zero
	local dragOrigin = pos
	local dragMoved = false
	root.InputBegan:Connect(function(input)
		if input.UserInputType == Enum.UserInputType.MouseButton1
			or input.UserInputType == Enum.UserInputType.Touch then
			dragging = true
			dragMoved = false
			dragStart = Vector2.new(input.Position.X, input.Position.Y)
			dragOrigin = pos
		end
	end)
	table.insert(connections, UserInputService.InputChanged:Connect(function(input)
		if not dragging then
			return
		end
		if input.UserInputType == Enum.UserInputType.MouseMovement
			or input.UserInputType == Enum.UserInputType.Touch then
			local delta = Vector2.new(input.Position.X, input.Position.Y) - dragStart
			if math.abs(delta.X) + math.abs(delta.Y) > 4 then
				dragMoved = true
			end
			place(dragOrigin + delta)
		end
	end))
	table.insert(connections, UserInputService.InputEnded:Connect(function(input)
		if input.UserInputType == Enum.UserInputType.MouseButton1
			or input.UserInputType == Enum.UserInputType.Touch then
			local wasDragging = dragging
			dragging = false
			-- Announced on RELEASE, not per frame: `place` runs on every mouse move
			-- and the position is part of the HUD's persisted record, so a host
			-- writing on every change would write sixty times a second across a drag.
			if wasDragging and dragMoved then
				ctx:User(changed)
			end
			-- Clear the drag flag here rather than only in the caret's handler. The
			-- caret is a TextButton and sinks input, so a click on it never reaches
			-- root.InputBegan to reset the flag — after any drag of the panel, the
			-- NEXT caret click would be swallowed as "that was a drag". Deferred
			-- because Activated fires on this same release and has to still see it.
			task.defer(function()
				dragMoved = false
			end)
		end
	end))

	-- ── FPS / ping ───────────────────────────────────────────────────────────
	-- One connection, sampled twice a second: a per-frame label write would cost
	-- more than the whole rest of the HUD, and a jittering number is unreadable
	-- anyway. Skipped entirely while hidden — but NOT while collapsed: the bar is
	-- its own card outside the collapsing body and stays on screen, so it has to
	-- keep counting.
	local visible = opts.Visible ~= false
	local collapsed = opts.Collapsed == true
	if showFps or showPing then
		local frames, elapsed = 0, 0
		table.insert(connections, RunService.Heartbeat:Connect(function(dt)
			frames += 1
			elapsed += dt
			if elapsed < 0.5 then
				return
			end
			local fps = math.floor(frames / elapsed + 0.5)
			frames, elapsed = 0, 0
			if not visible then
				return
			end
			if showFps then
				setStat("FPS", tostring(fps))
			end
			if showPing then
				-- Not every executor/place exposes the network stats item, so this
				-- degrades to a dash rather than erroring every half second.
				local ok, ms = pcall(function()
					return Stats.Network.ServerStatsItem["Data Ping"]:GetValue()
				end)
				setStat("MS", (ok and type(ms) == "number") and tostring(math.floor(ms + 0.5)) or "—")
			end
		end))
	end

	-- ── handle ───────────────────────────────────────────────────────────────
	handle.Frame = root  -- the whole unit: panel + stat bar
	handle.Panel = panel
	handle.OnVisible = nil :: ((boolean) -> ())? -- Window syncs its settings toggle through this

	function handle:IsVisible(): boolean
		return visible
	end

	-- `animate = false` snaps (used by config load, which shouldn't play an
	-- animation for state the user set in a previous session).
	function handle:SetVisible(value: boolean, animate: boolean?)
		if destroyed then
			return
		end
		value = value ~= false
		-- Already there, and the panel agrees — nothing to do. Without this,
		-- `Window:SetHudVisible(true)` on a HUD that's already up replayed the whole
		-- entrance (fade to invisible, scale to 0.94, pop back) and announced a
		-- visibility change that hadn't happened, which the settings switch and any
		-- host watching OnHudVisible both had to filter out on their own.
		--
		-- `root.Visible` is part of the test on purpose rather than `value ==
		-- visible` alone: the deferred first reveal at the bottom of this file calls
		-- SetVisible(true) precisely when `visible` is *already* true (it comes from
		-- the options) and the panel is still hidden, and that call has to go through.
		if value == visible and root.Visible == value then
			return
		end
		visible = value
		if value then
			root.Visible = true
			-- Repaint once the fade lands: rows that changed state while the panel
			-- was hidden were driven by the fade's snapshot, not by their own paint,
			-- so their fill is stale until the snapshot is released at alpha 0.
			if animate == false then
				fade:Set(0)
				panelScale.Scale = 1
				refresh()
			else
				-- Back to rest FIRST, which releases the snapshot the hide left held.
				-- Rows registered while the panel was hidden aren't in that snapshot, so
				-- without this they sit fully opaque while everything around them fades
				-- in. Set(0) restores the old rows to their own resting transparencies
				-- and drops the cache; the Set(1) below then re-reads a tree that
				-- includes the new rows.
				fade:Set(0)
				fade:Set(1)
				panelScale.Scale = 0.94
				Tween.play(panelScale, Tween.Pop, { Scale = 1 })
				fade:To(Tween.Normal, 0, refresh)
			end
			place(pos)
		elseif animate == false then
			root.Visible = false
		else
			Tween.play(panelScale, Tween.MenuOut, { Scale = 0.94 })
			fade:To(Tween.MenuOut, 1, function()
				if not visible then
					root.Visible = false
				end
			end)
		end
		if handle.OnVisible then
			handle.OnVisible(visible)
		end
		changed()
	end

	function handle:Show()
		handle:SetVisible(true)
	end
	function handle:Hide()
		handle:SetVisible(false)
	end

	function handle:IsCollapsed(): boolean
		return collapsed
	end

	function handle:SetCollapsed(value: boolean, animate: boolean?)
		value = value == true
		if value == collapsed then
			return
		end
		collapsed = value
		setCollapsedHeight(collapsed, animate ~= false)
		setHeaderSquared(not collapsed, (collapsed and animate ~= false) and Tween.Slide.Time or 0)
		-- `animate = false` (a config load) has to snap the caret too, or the panel
		-- restores collapsed while its arrow spins into place a beat later.
		if animate == false then
			caret.Rotation = collapsed and 180 or 0
		else
			Tween.play(caret, Tween.Spin, { Rotation = collapsed and 180 or 0 })
		end
		changed()
	end

	function handle:SetTitle(text: string)
		title.Text = tostring(text)
	end

	-- Add / update / remove a stat pill next to FPS and MS. `SetStat("Coins",
	-- nil)` drops it again.
	function handle:SetStat(key: string, value: any)
		if type(key) ~= "string" or key == "" then
			return
		end
		setStat(key, value ~= nil and tostring(value) or nil)
	end

	function handle:GetPosition(): Vector2
		return pos
	end
	function handle:SetPosition(x: number, y: number)
		place(Vector2.new(tonumber(x) or pos.X, tonumber(y) or pos.Y))
		changed()
	end

	function handle:Refresh()
		refresh()
	end

	-- Config: the HUD persists as a small record rather than a bare value, so a
	-- saved config restores where you put it and whether it was up at all
	-- (util/Context.lua `hud` codec).
	function handle:GetFlag(): any
		return { Visible = visible, Collapsed = collapsed, X = pos.X, Y = pos.Y }
	end
	function handle:SetFlag(value: any)
		if type(value) ~= "table" then
			return
		end
		if tonumber(value.X) and tonumber(value.Y) then
			place(Vector2.new(tonumber(value.X) :: number, tonumber(value.Y) :: number))
		end
		if value.Collapsed ~= nil then
			handle:SetCollapsed(value.Collapsed == true, false)
		end
		if value.Visible ~= nil then
			handle:SetVisible(value.Visible == true, false)
		end
		-- A record that only moved the panel gets no notification from the setters
		-- above (`place` isn't one of them), and a host mirroring the HUD needs to
		-- hear about a restore either way. Deduped downstream by value.
		changed()
	end

	function handle:Destroy()
		if destroyed then
			return
		end
		destroyed = true
		for _, conn in connections do
			conn:Disconnect()
		end
		table.clear(connections)
		unsubscribeBinds()
		unsubscribeAccent()
		root:Destroy()
	end

	-- The caret is inside the drag surface, so a drag that happens to start on it
	-- must not also collapse the panel when the button comes back up.
	caretBtn.Activated:Connect(function()
		if dragMoved then
			dragMoved = false
			return
		end
		ctx:User(function()
			handle:SetCollapsed(not collapsed)
		end)
	end)

	refresh()
	if collapsed then
		caret.Rotation = 180
	end
	-- Reveal on a deferred pass: the fade has to snapshot a finished panel, and
	-- the caller's controls (and therefore its binds) are usually still being
	-- built at this point.
	-- `not root.Visible` so a caller that already showed it on this frame
	-- (Window:SetHudVisible, which builds and shows in one go) doesn't get the
	-- entrance played twice.
	if visible then
		task.defer(function()
			if not destroyed and visible and not root.Visible then
				handle:SetVisible(true)
			end
		end)
	end

	return handle
end

end

__modules['components.Image'] = function(...)
--!strict
-- components/Image.lua — drop a picture into a card.
--
-- The `Image` field takes anything util/Asset.lua can resolve: a bare decal id,
-- an `rbxassetid://` url, a local file written by the executor, or an https url
-- (downloaded + cached on first use). Everything else is chrome: rounded frame,
-- 1px border, an optional caption, and a placeholder icon while there's nothing
-- to show yet.
--
--   Group:Image({ Image = 91296376944710, Height = 160 })
--   Group:Image({ Name = "Banner", Image = "https://…/banner.png", Fit = "cover" })
--
-- The handle exposes :Set(source) / :Get(), so a live view (a thumbnail that
-- tracks a selection, say) just calls :Set with the new source.

local Create = __require("util.Create")
local Theme = __require("Theme")
local Icons = __require("Icons")
local Asset = __require("util.Asset")
local Field = __require("components.Field")

-- How the picture fills its frame. "cover" crops to fill (the sane default for
-- banners/art), "contain" fits the whole image inside, "stretch" distorts.
local FIT: { [string]: Enum.ScaleType } = {
	cover = Enum.ScaleType.Crop,
	contain = Enum.ScaleType.Fit,
	fit = Enum.ScaleType.Fit,
	stretch = Enum.ScaleType.Stretch,
	tile = Enum.ScaleType.Tile,
}

return function(ctx: any, opts: any)
	local colors = Theme.Colors
	opts = opts or {}

	local height = tonumber(opts.Height) or 140
	local radius = tonumber(opts.Corner) or Theme.Metrics.controlRadius
	local scaleType = FIT[tostring(opts.Fit or "cover"):lower()] or Enum.ScaleType.Crop

	-- Titled → the standard stacked field (name/desc above, image below).
	-- Bare → a plain padded row, like a bare Button.
	local container: Frame
	local field: Frame
	if opts.Name or opts.Desc then
		local f = Field.new(ctx, opts, true)
		field = f.field
		container = f.field
	else
		container = Create("Frame", {
			Name = "Image",
			BackgroundTransparency = 1,
			Size = UDim2.new(1, 0, 0, 0),
			AutomaticSize = Enum.AutomaticSize.Y,
		}, {
			Create.padding(10, 2),
			Create.listLayout({ Padding = UDim.new(0, 6) }),
		})
		field = container
	end

	-- The frame clips so the UICorner actually rounds the picture (a UICorner on
	-- the ImageLabel alone doesn't clip a Crop-scaled image).
	local frame = Create("Frame", {
		Name = "Frame",
		Size = opts.Width and UDim2.new(0, tonumber(opts.Width) or 0, 0, height)
			or UDim2.new(1, 0, 0, height),
		BackgroundColor3 = colors.control,
		ClipsDescendants = true,
		LayoutOrder = 2,
		Parent = container,
	}, {
		Create.corner(radius),
		Create.stroke(colors.border),
	})

	local picture = Create("ImageLabel", {
		Name = "Picture",
		BackgroundTransparency = 1,
		Size = UDim2.fromScale(1, 1),
		Image = "",
		ScaleType = scaleType,
		Parent = frame,
	}) :: ImageLabel

	-- Shown whenever there's no resolvable source (or it's still downloading).
	local placeholder = Icons.new("image", 22, colors.text_dim)
	placeholder.AnchorPoint = Vector2.new(0.5, 0.5)
	placeholder.Position = UDim2.fromScale(0.5, 0.5)
	;(placeholder :: any).Parent = frame

	local caption: TextLabel? = nil
	if opts.Caption then
		caption = Create("TextLabel", {
			Name = "Caption",
			BackgroundTransparency = 1,
			Size = UDim2.new(1, 0, 0, 0),
			AutomaticSize = Enum.AutomaticSize.Y,
			Text = opts.Caption,
			TextColor3 = colors.text_muted,
			TextSize = 12,
			FontFace = Theme.Font.Regular,
			TextXAlignment = Enum.TextXAlignment.Left,
			TextWrapped = true,
			LayoutOrder = 3,
			Parent = container,
		})
	end

	local source: any = nil

	local function apply(value: any)
		source = value
		-- The picture is never hidden (an ImageLabel the engine isn't rendering
		-- never loads in the first place) — only the placeholder icon behind it
		-- reacts, so a slow or dead source leaves the icon showing instead of an
		-- empty box, and a late arrival still paints over it.
		placeholder.Visible = true
		Asset.load(picture, value, function(loaded)
			placeholder.Visible = not loaded
		end)
	end

	-- Clickable variant: a transparent button over the picture. Only added when a
	-- Callback is given, so a plain image stays inert (and doesn't eat scrolls).
	if opts.Callback then
		local hit = Create("TextButton", {
			Name = "Hit",
			AutoButtonColor = false,
			BackgroundTransparency = 1,
			Text = "",
			Size = UDim2.fromScale(1, 1),
			ZIndex = 2,
			Parent = frame,
		})
		hit.Activated:Connect(function()
			task.spawn(opts.Callback, source)
		end)
	end

	local handle = {}
	function handle:Get(): any
		return source
	end
	function handle:Set(value: any)
		apply(value)
	end
	function handle:SetCaption(text: string)
		if caption then
			caption.Text = text
		end
	end
	handle.element = picture

	apply(opts.Image or opts.Source)

	return field, handle, true
end

end

__modules['components.Input'] = function(...)
--!strict
-- components/Input.lua — full-width 36px TextBox, accent stroke on focus.

local Create = __require("util.Create")
local Theme = __require("Theme")
local Tween = __require("util.Tween")
local Field = __require("components.Field")

-- Live character filters keyed by opts.Type. Each takes the raw box text and
-- returns it with disallowed characters stripped; the number kinds also collapse
-- to a single leading '-' and a single '.' so the result is always parseable.
local function sanitizer(kind: string?): (((string) -> string)?)
	if kind == "number" then
		return function(s)
			local neg = s:sub(1, 1) == "-"
			s = s:gsub("[^%d%.]", "")
			local dot = s:find("%.")
			if dot then
				s = s:sub(1, dot) .. (s:sub(dot + 1):gsub("%.", ""))
			end
			return neg and ("-" .. s) or s
		end
	elseif kind == "integer" then
		return function(s)
			local neg = s:sub(1, 1) == "-"
			s = (s:gsub("[^%d]", ""))
			return neg and ("-" .. s) or s
		end
	elseif kind == "alpha" then
		return function(s)
			return (s:gsub("[^%a]", ""))
		end
	elseif kind == "alphanumeric" then
		return function(s)
			return (s:gsub("[^%w]", ""))
		end
	end
	return nil
end

return function(ctx: any, opts: any)
	local colors = Theme.Colors
	local f = Field.new(ctx, opts, true)
	-- opts.Filter (function) wins; otherwise opts.Type selects a preset filter.
	local clean = opts.Filter or sanitizer(opts.Type)

	local box = Create("TextBox", {
		Name = "Input",
		Size = UDim2.new(1, 0, 0, 36),
		BackgroundColor3 = colors.control,
		Text = opts.Default or "",
		PlaceholderText = opts.Placeholder or "",
		PlaceholderColor3 = colors.text_dim,
		TextColor3 = colors.text,
		TextSize = 13,
		FontFace = Theme.Font.Regular,
		TextXAlignment = Enum.TextXAlignment.Left,
		ClearTextOnFocus = false,
		ClipsDescendants = true,
		LayoutOrder = 2,
		Parent = f.field,
	}, {
		Create.corner(Theme.Metrics.controlRadius),
		Create.stroke(colors.border),
		Create.padding(0, 12),
	})
	local stroke = box:FindFirstChildOfClass("UIStroke") :: UIStroke

	box.Focused:Connect(function()
		Tween.play(stroke, Tween.Fast, { Color = ctx.Accent })
	end)
	box.FocusLost:Connect(function(enterPressed)
		Tween.play(stroke, Tween.Fast, { Color = colors.border })
		if enterPressed and opts.OnEnter then
			opts.OnEnter(box.Text)
		end
	end)
	local guard = false
	box:GetPropertyChangedSignal("Text"):Connect(function()
		if guard then
			return
		end
		if clean then
			local filtered = clean(box.Text)
			if filtered ~= box.Text then
				-- Rewriting Text re-fires this signal synchronously; guard skips
				-- that pass so the callback below runs once with the clean value.
				guard = true
				box.Text = filtered
				guard = false
			end
		end
		if opts.Callback then
			-- The guard above means this signal only reaches here when the user typed
			-- (handle:Set writes under it and fires the callback itself), so it's an
			-- honest "user" for Context:OnFlagChanged.
			ctx:User(task.spawn, opts.Callback, box.Text)
		end
	end)

	local handle = {}
	function handle:Get(): string
		return box.Text
	end
	function handle:Set(value: any)
		-- Filter here and write under the same guard the live filter uses, then
		-- fire by hand: leaving the callback to the Text signal means setting the
		-- value the box already holds fires nothing, so a LoadConfig that restores
		-- an Input to its current text never re-applies it downstream. The guard
		-- is what keeps a genuine change from firing twice.
		--
		-- Coerced first: `TextBox.Text` refuses anything but a string, so a caller
		-- handing a number (which is what `Input{ Type = "number" }` invites — the
		-- control's whole job is numeric text) errored inside the engine instead of
		-- setting the field. The filters below assume a string too.
		local text = value == nil and "" or tostring(value)
		guard = true
		box.Text = clean and clean(text) or text
		guard = false
		if opts.Callback then
			task.spawn(opts.Callback, box.Text)
		end
	end

	return f.field, handle, true
end

end

__modules['components.Keybind'] = function(...)
--!strict
-- components/Keybind.lua — click the key half of the chip to listen, then press
-- the key (or right/middle click the chip for MB2/MB3); the chip's mode half
-- cycles Toggle/Hold/Always when there's more than one mode to pick.
--
-- The chip, the routing and the mode machine live in components/BindChip.lua +
-- util/Bind.lua; this file is the field row around them and the callback
-- contract:
--
--   Mode = "None" (the default)  — a pure key PICKER. Nothing is bound; the
--       control just holds a key and `Callback(key)` fires whenever it changes.
--       This is the original Keybind behaviour, kept so existing menus (and the
--       Settings tab's Toggle-UI bind) don't change under them.
--   Mode = "Toggle" / "Hold" / "Press" / "Always" — an ACTIVATION bind. The key
--       drives a value and `Callback(active, info)` fires on every activation,
--       with `info = { Key, Mode, KeyName }`.
--
-- `OnChanged(key, mode)` fires when the bind itself is re-keyed or its mode is
-- cycled, in every mode.

local Log = __require("util.Log")
local Bind = __require("util.Bind")
local Field = __require("components.Field")
local BindChip = __require("components.BindChip")

local SCHEMA: Log.Schema = {
	{ "Default", "EnumItem" },
	{ "Mode", "string" },
	{ "Modes", "table" },
	{ "OnChanged", "function" },
	{ "Hud", "boolean" },
	{ "Parent", { "string", "table" } },
}

return function(ctx: any, opts: any)
	opts = opts or {}
	local where = Log.where("Keybind", opts.Name)
	Log.check(where, opts, SCHEMA)

	local f = Field.new(ctx, opts)
	local mode = Bind.mode(opts.Mode, where, "None")
	local picker = mode == "None"

	local chip, handle = BindChip(ctx, {
		Key = opts.Default,
		Mode = mode,
		Modes = opts.Modes,
		Default = opts.DefaultState,
		Where = where,
		-- The field's own label is what the bind HUD lists it under. A picker
		-- (Mode = "None") never activates, so it stays out of the HUD regardless.
		Label = opts.Name,
		-- `Id` is what sub-options name this bind by; `Parent` makes this one a
		-- sub-option of another feature (util/Bind.lua's tree).
		Id = opts.Flag,
		Parent = opts.Parent,
		Hud = opts.Hud,
		-- Picker mode has no activation, so `Callback` keeps its original
		-- "the key changed" meaning there and only there.
		OnActivate = not picker and opts.Callback or nil,
		OnChanged = function(key, m)
			if picker and opts.Callback then
				task.spawn(opts.Callback, key)
			end
			if opts.OnChanged then
				task.spawn(opts.OnChanged, key, m)
			end
		end,
	})
	chip.Parent = f.row

	return f.field, handle, true
end

end

