__modules['components.MediaPlayer'] = function(...)
--!strict
-- components/MediaPlayer.lua — cover art + title/artist, a draggable scrub
-- timeline, transport (shuffle/prev/play·pause/next/repeat) and a volume bar.
--
-- Three ways to drive it, mixable per track:
--   1. `SoundId` (single) or `Queue = { { SoundId = ... }, ... }` (playlist) —
--      the component owns a real Instance.new("Sound") per track (parented to
--      SoundService), actually plays it, and drives the timeline from
--      Sound.TimePosition. Track-end advances the queue (respecting Loop /
--      Shuffle) automatically.
--   2. `Sound = <Instance>` (or a Queue entry's `Sound`) — a Sound you already
--      own; the component calls :Play()/:Pause()/sets .TimePosition/.Volume on
--      it but never destroys it, so you keep the instance's lifetime.
--   3. Neither — a pure remote-control surface. Play/Pause/Next/Previous/Seek/
--      Volume all just fire `Callback(action, payload)` + the matching event;
--      drive your own audio and push state back with :SetProgress/:SetPlaying/
--      :SetDuration.
--
-- Group:MediaPlayer({
--     Title = "Song Name", Artist = "Artist", Cover = "rbxassetid://...",
--     Queue = { { Title = "...", Artist = "...", SoundId = "rbxassetid://..." } },
--     Volume = 0.5, Shuffle = false, Loop = "off", -- "off" | "one" | "all"
--     ShowVolume = true, ShowShuffle = true, ShowLoop = true, ShowFavorite = false,
--     Callback = function(action, payload) end, -- "play"|"pause"|"next"|"previous"|"seek"|"volume"|"shuffle"|"loop"|"favorite"|"track"
-- })
-- handle:Play() :Pause() :TogglePlay() :IsPlaying() :Next() :Previous()
-- handle:Seek(t) :GetProgress() :SetProgress(t) :GetDuration() :SetDuration(t)
-- handle:GetVolume() :SetVolume(v) :GetShuffle() :SetShuffle(b)
-- handle:GetLoop() :SetLoop(mode) :SetTrack(data) :SetQueue(list, startIndex?)
-- handle:GetTrack()
-- handle.Played/.Paused/.NextTrack/.PreviousTrack/.Seeked/.VolumeChanged/
--        .ShuffleChanged/.LoopChanged/.TrackChanged/.Ended/.FavoriteChanged (all `.Event`)

local Services = __require("util.Services")

local UserInputService = Services.UserInputService
local RunService = Services.RunService
local SoundService = Services.SoundService

local Create = __require("util.Create")
local Theme = __require("Theme")
local Tween = __require("util.Tween")
local Icons = __require("Icons")
local Log = __require("util.Log")
local Asset = __require("util.Asset")
local Field = __require("components.Field")

local function clamp(v: number, a: number, b: number): number
	return math.max(a, math.min(b, v))
end

local function fmtTime(t: number): string
	if t ~= t or t == math.huge or t == -math.huge then -- guard NaN/inf
		t = 0
	end
	t = math.max(0, math.floor(t))
	return ("%d:%02d"):format(math.floor(t / 60), t % 60)
end

-- A draggable pill bar: `width` is the hit area's X UDim (fill = UDim.new(1,0),
-- fixed = UDim.new(0, px)). Returns the clickable hit frame + the fill/knob to
-- animate + the knob's UIScale (grown while dragging, like Slider.lua).
local function newBar(ctx: any, parent: Instance, width: UDim, hitHeight: number, barHeight: number, knobSize: number, order: number?)
	local colors = Theme.Colors
	local hit = Create("TextButton", {
		Name = "Hit",
		AutoButtonColor = false,
		Text = "",
		BackgroundTransparency = 1,
		Size = UDim2.new(width.Scale, width.Offset, 0, hitHeight),
		LayoutOrder = order,
		Parent = parent,
	}) :: TextButton
	local track = Create("Frame", {
		Name = "Track",
		AnchorPoint = Vector2.new(0, 0.5),
		Position = UDim2.new(0, 0, 0.5, 0),
		Size = UDim2.new(1, 0, 0, barHeight),
		BackgroundColor3 = colors.toggle_off,
		Parent = hit,
	}, { Create.corner(999) })
	local fill = Create("Frame", {
		Name = "Fill",
		Size = UDim2.fromScale(0, 1),
		BackgroundColor3 = ctx.Accent,
		Parent = track,
	}, { Create.corner(999) })
	local knob = Create("Frame", {
		Name = "Knob",
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromScale(0, 0.5),
		Size = UDim2.fromOffset(knobSize, knobSize),
		BackgroundColor3 = colors.text, -- see Slider.lua: knob leaves the accent fill at 0
		ZIndex = 2,
		Parent = track,
	}, { Create.corner(999), Create("UIScale", {}) })
	return hit, fill, knob, knob:FindFirstChildOfClass("UIScale") :: UIScale
end

-- Shared drag wiring (mirrors Slider.lua): global listeners only live for the
-- duration of one drag, so N idle bars never leak a permanent InputChanged
-- connection.
local function attachDrag(hit: GuiButton, knobScale: UIScale, setFromX: (number) -> (), onStart: (() -> ())?, onEnd: (() -> ())?)
	local conns: { RBXScriptConnection } = {}
	local function stop()
		for _, c in conns do
			c:Disconnect()
		end
		table.clear(conns)
		Tween.play(knobScale, Tween.Spring, { Scale = 1 })
		if onEnd then
			onEnd()
		end
	end
	hit.InputBegan:Connect(function(input)
		if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
			if #conns > 0 then
				return
			end
			if onStart then
				onStart()
			end
			Tween.play(knobScale, Tween.Spring, { Scale = 1.3 })
			setFromX(input.Position.X)
			table.insert(conns, UserInputService.InputChanged:Connect(function(move)
				if move.UserInputType == Enum.UserInputType.MouseMovement or move.UserInputType == Enum.UserInputType.Touch then
					setFromX(move.Position.X)
				end
			end))
			table.insert(conns, UserInputService.InputEnded:Connect(function(up)
				if up.UserInputType == Enum.UserInputType.MouseButton1 or up.UserInputType == Enum.UserInputType.Touch then
					stop()
				end
			end))
		end
	end)
end

-- Small hover-tint circular icon button, used for prev/next/shuffle/loop/favorite.
local function iconButton(parent: Instance, size: number, iconSize: number, iconName: string, order: number): (TextButton, GuiObject)
	local colors = Theme.Colors
	local btn = Create("TextButton", {
		Name = iconName,
		AutoButtonColor = false,
		Text = "",
		Size = UDim2.fromOffset(size, size),
		BackgroundColor3 = colors.control,
		LayoutOrder = order,
		Parent = parent,
	}, { Create.corner(999) }) :: TextButton
	local icon = Icons.new(iconName, iconSize, colors.text)
	icon.AnchorPoint = Vector2.new(0.5, 0.5)
	icon.Position = UDim2.fromScale(0.5, 0.5)
	;(icon :: any).Parent = btn
	Create.hover(btn, "BackgroundColor3", colors.control, colors.control_hi)
	return btn, icon
end

local SCHEMA: Log.Schema = {
	{ "Callback", "function" },
	{ "Queue", "table" },
	-- Cover is handed to Asset.resolve, which takes a bare decal id, an
	-- rbxassetid/url string, a file path or a fallback-chain array — so the only
	-- thing worth rejecting is something Asset can't read at all.
	{ "Cover", { "string", "number", "table" } },
}

return function(ctx: any, opts: any): (Instance, any, boolean)
	local colors = Theme.Colors
	opts = opts or {}
	local where = Log.where("MediaPlayer", opts.Name)
	Log.check(where, opts, SCHEMA)

	local showVolume = opts.ShowVolume ~= false
	local showShuffle = opts.ShowShuffle ~= false
	local showLoop = opts.ShowLoop ~= false
	local showFavorite = opts.ShowFavorite == true

	-- ── state ────────────────────────────────────────────────────────────────
	local rng = Random.new()
	local queue: { any } = (type(opts.Queue) == "table" and opts.Queue) or {}
	local useQueue = #queue > 0
	local index = useQueue and math.clamp(math.floor(opts.Index or 1), 1, #queue) or 1

	local current = { Title = "", Artist = "", Cover = nil :: string? }
	local elapsed, duration = 0, 0
	local playing = false
	local draggingProgress = false
	local loved = false

	local volume = clamp(opts.Volume ~= nil and opts.Volume or 0.5, 0, 1)
	local shuffle = opts.Shuffle == true
	local loopMode = opts.Loop or "off"
	if loopMode ~= "off" and loopMode ~= "one" and loopMode ~= "all" then
		Log.warn(where, ("Loop must be \"off\", \"one\" or \"all\", got \"%s\" — using \"off\"."):format(tostring(loopMode)))
		loopMode = "off"
	end

	local activeSound: Sound? = nil
	local ownsSound = false
	local soundConns: { RBXScriptConnection } = {}
	local tickConn: RBXScriptConnection? = nil

	local bindables = {
		Played = Instance.new("BindableEvent"),
		Paused = Instance.new("BindableEvent"),
		NextTrack = Instance.new("BindableEvent"),
		PreviousTrack = Instance.new("BindableEvent"),
		Seeked = Instance.new("BindableEvent"),
		VolumeChanged = Instance.new("BindableEvent"),
		ShuffleChanged = Instance.new("BindableEvent"),
		LoopChanged = Instance.new("BindableEvent"),
		TrackChanged = Instance.new("BindableEvent"),
		Ended = Instance.new("BindableEvent"),
		FavoriteChanged = Instance.new("BindableEvent"),
	}

	local function currentPayload()
		return {
			Title = current.Title,
			Artist = current.Artist,
			Cover = current.Cover,
			Duration = duration,
			Progress = elapsed,
			Index = useQueue and index or nil,
			Playing = playing,
		}
	end

	-- forward decls (mutually referential: track load ↔ sound end ↔ queue nav)
	local fireEvent: (string, any?) -> ()
	local renderMeta: () -> ()
	local renderProgress: () -> ()
	local renderVolume: () -> ()
	local paintPlayPause: () -> ()
	local paintShuffle: () -> ()
	local paintLoop: () -> ()
	local paintFavorite: () -> ()
	local startTicking: () -> ()
	local stopTicking: () -> ()
	local seekTo: (number, boolean) -> ()
	local attachTrackAudio: (any) -> ()
	local loadTrackData: (any, boolean) -> ()
	local gotoIndex: (number, boolean) -> ()
	local pickIndex: (number) -> number?
	local handleEnded: () -> ()
	local doPlay: () -> ()
	local doPause: () -> ()
	local applyVolume: (number, boolean) -> ()
	local applyShuffle: (boolean, boolean) -> ()
	local applyLoop: (string, boolean) -> ()
	local doNext: () -> ()
	local doPrevious: () -> ()

	-- ── layout ───────────────────────────────────────────────────────────────
	local f = Field.new(ctx, opts, true)

	local panel = Create("Frame", {
		Name = "MediaPlayer",
		BackgroundColor3 = colors.control,
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		LayoutOrder = 2,
		Parent = f.field,
	}, {
		Create.corner(Theme.Metrics.controlRadius),
		Create.stroke(colors.border),
		Create.padding(14),
		Create.listLayout({ Padding = UDim.new(0, 14) }),
	})

	-- meta row: cover · title/artist · (favorite) ──────────────────────────────
	local favW = showFavorite and 38 or 0
	local meta = Create("Frame", {
		Name = "Meta",
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 48),
		LayoutOrder = 1,
		Parent = panel,
	})

	local cover = Create("Frame", {
		Name = "Cover",
		Size = UDim2.fromOffset(48, 48),
		BackgroundColor3 = colors.control_hi,
		ClipsDescendants = true,
		Parent = meta,
	}, { Create.corner(10), Create.stroke(colors.border) })
	-- Flat surface placeholder (no gradient) until real cover art is set.
	local coverIcon = Icons.new("music", 20, colors.text_dim)
	coverIcon.AnchorPoint = Vector2.new(0.5, 0.5)
	coverIcon.Position = UDim2.fromScale(0.5, 0.5)
	;(coverIcon :: any).Parent = cover
	-- Stays visible with an empty Image when there's no art: the engine only
	-- fetches what it renders, so a hidden ImageLabel would never load and
	-- Asset.load's "did it arrive?" answer would always be no. The icon behind
	-- it is what toggles.
	local coverImage = Create("ImageLabel", {
		Name = "Art",
		BackgroundTransparency = 1,
		Size = UDim2.fromScale(1, 1),
		Image = "",
		ScaleType = Enum.ScaleType.Crop,
		Parent = cover,
	}) :: ImageLabel

	local info = Create("Frame", {
		Name = "Info",
		BackgroundTransparency = 1,
		AnchorPoint = Vector2.new(0, 0.5),
		Position = UDim2.new(0, 60, 0.5, 0),
		Size = UDim2.new(1, -60 - favW, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		Parent = meta,
	}, { Create.listLayout({ Padding = UDim.new(0, 3) }) })

	local titleLabel = Create("TextLabel", {
		Name = "Title",
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 18),
		Text = "No Track",
		TextColor3 = colors.text,
		TextSize = 14,
		FontFace = Theme.Font.Medium,
		TextXAlignment = Enum.TextXAlignment.Left,
		TextTruncate = Enum.TextTruncate.AtEnd,
		LayoutOrder = 1,
		Parent = info,
	})
	local artistLabel = Create("TextLabel", {
		Name = "Artist",
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 16),
		Text = "",
		TextColor3 = colors.text_muted,
		TextSize = 12,
		FontFace = Theme.Font.Regular,
		TextXAlignment = Enum.TextXAlignment.Left,
		TextTruncate = Enum.TextTruncate.AtEnd,
		LayoutOrder = 2,
		Parent = info,
	})

	local favoriteBtn, favoriteIcon
	if showFavorite then
		favoriteBtn, favoriteIcon = iconButton(meta, 28, 14, "heart", 1)
		favoriteBtn.AnchorPoint = Vector2.new(1, 0.5)
		favoriteBtn.Position = UDim2.new(1, 0, 0.5, 0)
	end

	-- progress row: scrub bar + time labels ─────────────────────────────────────
	local progress = Create("Frame", {
		Name = "Progress",
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 34),
		LayoutOrder = 2,
		Parent = panel,
	})
	local progressHit, progressFill, progressKnob, progressKnobScale =
		newBar(ctx, progress, UDim.new(1, 0), 16, 5, 13, 1)

	local timeCur = Create("TextLabel", {
		Name = "Current",
		BackgroundTransparency = 1,
		Position = UDim2.fromOffset(0, 20),
		Size = UDim2.fromOffset(40, 14),
		Text = "0:00",
		TextColor3 = colors.text_muted,
		TextSize = 11,
		FontFace = Theme.Font.Regular,
		TextXAlignment = Enum.TextXAlignment.Left,
		Parent = progress,
	})
	local timeDur = Create("TextLabel", {
		Name = "Duration",
		BackgroundTransparency = 1,
		AnchorPoint = Vector2.new(1, 0),
		Position = UDim2.new(1, 0, 0, 20),
		Size = UDim2.fromOffset(40, 14),
		Text = "0:00",
		TextColor3 = colors.text_muted,
		TextSize = 11,
		FontFace = Theme.Font.Regular,
		TextXAlignment = Enum.TextXAlignment.Right,
		Parent = progress,
	})

	-- transport row: shuffle · prev · play/pause · next · loop  +  volume ───────
	local transport = Create("Frame", {
		Name = "Transport",
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 44),
		LayoutOrder = 3,
		Parent = panel,
	})
	local center = Create("Frame", {
		Name = "Center",
		BackgroundTransparency = 1,
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.new(0.5, 0, 0.5, 0),
		Size = UDim2.new(0, 0, 0, 44),
		AutomaticSize = Enum.AutomaticSize.X,
		Parent = transport,
	}, {
		Create.listLayout({
			FillDirection = Enum.FillDirection.Horizontal,
			VerticalAlignment = Enum.VerticalAlignment.Center,
			Padding = UDim.new(0, 10),
		}),
	})

	local shuffleBtn, shuffleIcon
	if showShuffle then
		shuffleBtn, shuffleIcon = iconButton(center, 30, 15, "shuffle", 1)
	end
	local prevBtn, _prevIcon = iconButton(center, 34, 16, "skip-back", 2)
	local playBtn = Create("TextButton", {
		Name = "PlayPause",
		AutoButtonColor = false,
		Text = "",
		Size = UDim2.fromOffset(44, 44),
		BackgroundColor3 = ctx.Accent,
		LayoutOrder = 3,
		Parent = center,
	}, { Create.corner(999), Create("UIScale", {}) }) :: TextButton
	local playScale = playBtn:FindFirstChildOfClass("UIScale") :: UIScale
	local playIcon = Icons.new("play", 18, colors.knockout)
	playIcon.AnchorPoint = Vector2.new(0.5, 0.5)
	playIcon.Position = UDim2.fromScale(0.5, 0.5)
	;(playIcon :: any).Parent = playBtn
	local nextBtn, _nextIcon = iconButton(center, 34, 16, "skip-forward", 4)
	local loopBtn, loopIcon
	if showLoop then
		loopBtn, loopIcon = iconButton(center, 30, 15, "repeat", 5)
	end

	local volumeGroup, volumeBtn, volumeIcon, volumeHit, volumeFill, volumeKnob, volumeKnobScale
	if showVolume then
		volumeGroup = Create("Frame", {
			Name = "Volume",
			BackgroundTransparency = 1,
			AnchorPoint = Vector2.new(1, 0.5),
			Position = UDim2.new(1, 0, 0.5, 0),
			Size = UDim2.new(0, 0, 0, 22),
			AutomaticSize = Enum.AutomaticSize.X,
			Parent = transport,
		}, {
			Create.listLayout({
				FillDirection = Enum.FillDirection.Horizontal,
				VerticalAlignment = Enum.VerticalAlignment.Center,
				Padding = UDim.new(0, 8),
			}),
		})
		volumeBtn, volumeIcon = iconButton(volumeGroup, 22, 14, "volume-2", 1)
		volumeBtn.BackgroundTransparency = 1
		volumeHit, volumeFill, volumeKnob, volumeKnobScale = newBar(ctx, volumeGroup, UDim.new(0, 64), 16, 4, 10, 2)
	end

	-- ── playback plumbing ────────────────────────────────────────────────────
	fireEvent = function(name, payload)
		local b = (bindables :: any)[name]
		if b then
			b:Fire(payload)
		end
	end

	-- Bumped on every renderMeta so a cover that resolves late can tell whether
	-- the track it was fetched for is still the one on screen.
	local coverGen = 0

	renderMeta = function()
		titleLabel.Text = (current.Title ~= "" and current.Title) or "No Track"
		artistLabel.Text = current.Artist or ""
		artistLabel.Visible = current.Artist ~= nil and current.Artist ~= ""

		coverGen += 1
		local gen = coverGen
		local art = current.Cover -- captured: `current` is replaced wholesale per track
		coverIcon.Visible = true
		if art == nil then
			coverImage.Image = ""
			return
		end
		-- Through Asset so a track's Cover can be a bare id / url / file path, and
		-- off-thread because resolving an https cover downloads + caches it —
		-- inline, that stalled the menu build and every Next click.
		task.spawn(function()
			Asset.load(coverImage, art, function(loaded)
				if gen ~= coverGen then
					return -- the track moved on while this was in flight
				end
				coverIcon.Visible = not loaded
			end)
		end)
	end

	-- Whole seconds currently ON the two labels, so the strings are only rebuilt
	-- when they'd actually read differently. `renderProgress` runs every Heartbeat
	-- while a track plays: the fill and the knob genuinely move every frame, but
	-- the clocks change once a second, and reformatting both plus writing both
	-- `Text` properties 60 times a second was ~59 wasted string allocations and
	-- two wasted layout invalidations per second, forever, on the render path.
	-- `-1` can't collide with a real value (both are floored to ≥ 0), so the first
	-- call always paints.
	local shownElapsed, shownDuration = -1, -1

	renderProgress = function()
		local pct = duration > 0 and clamp(elapsed / duration, 0, 1) or 0
		progressFill.Size = UDim2.fromScale(pct, 1)
		progressKnob.Position = UDim2.fromScale(pct, 0.5)
		local secs = math.floor(math.max(0, elapsed))
		if secs ~= shownElapsed then
			shownElapsed = secs
			timeCur.Text = fmtTime(elapsed)
		end
		local total = math.floor(math.max(0, duration))
		if total ~= shownDuration then
			shownDuration = total
			timeDur.Text = duration > 0 and fmtTime(duration) or "0:00"
		end
	end

	renderVolume = function()
		if not showVolume then
			return
		end
		volumeFill.Size = UDim2.fromScale(volume, 1)
		volumeKnob.Position = UDim2.fromScale(volume, 0.5)
		if volume <= 0 then
			Icons.apply(volumeIcon :: any, "volume-x")
		elseif volume < 0.5 then
			Icons.apply(volumeIcon :: any, "volume-1")
		else
			Icons.apply(volumeIcon :: any, "volume-2")
		end
	end

	paintPlayPause = function()
		if playing then
			Icons.apply(playIcon :: any, "pause")
		else
			Icons.apply(playIcon :: any, "play")
		end
	end

	paintShuffle = function()
		if not showShuffle then
			return
		end
		Icons.tint(shuffleIcon, shuffle and ctx.Accent or colors.text_dim)
		shuffleBtn.BackgroundColor3 = shuffle and colors.control_hi or colors.control
	end

	paintLoop = function()
		if not showLoop then
			return
		end
		if loopMode == "one" then
			Icons.apply(loopIcon :: any, "repeat-1")
		else
			Icons.apply(loopIcon :: any, "repeat")
		end
		local active = loopMode ~= "off"
		Icons.tint(loopIcon, active and ctx.Accent or colors.text_dim)
		loopBtn.BackgroundColor3 = active and colors.control_hi or colors.control
	end

	paintFavorite = function()
		if not showFavorite then
			return
		end
		Icons.tint(favoriteIcon, loved and ctx.Accent or colors.text_dim)
	end

	stopTicking = function()
		if tickConn then
			tickConn:Disconnect()
			tickConn = nil
		end
	end

	startTicking = function()
		if tickConn or not activeSound then
			return
		end
		tickConn = RunService.Heartbeat:Connect(function()
			local snd = activeSound
			if draggingProgress or not snd then
				return
			end
			elapsed = snd.TimePosition
			if duration <= 0 and snd.TimeLength > 0 then
				duration = snd.TimeLength
			end
			renderProgress()
		end)
	end

	seekTo = function(t, fireCB)
		t = clamp(t, 0, math.max(duration, 0))
		elapsed = t
		renderProgress()
		local snd = activeSound
		if snd then
			pcall(function()
				snd.TimePosition = t
			end)
		end
		if fireCB then
			fireEvent("Seeked", t)
			if opts.Callback then
				task.spawn(opts.Callback, "seek", t)
			end
		end
	end

	attachTrackAudio = function(data)
		for _, c in soundConns do
			c:Disconnect()
		end
		table.clear(soundConns)
		local prev = activeSound
		if prev then
			if ownsSound then
				prev:Stop()
				prev:Destroy()
			else
				-- A caller's Sound is theirs to destroy, but we still have to let go
				-- of it *quiet*: leaving it playing strands audio with nothing left
				-- driving it (no transport, no timeline, no volume).
				prev:Pause()
			end
		end
		activeSound = nil
		ownsSound = false

		if data.Sound then
			activeSound = data.Sound
			ownsSound = false
		elseif data.SoundId then
			local snd = Instance.new("Sound")
			snd.Name = "Uranium_MediaPlayerSound"
			snd.SoundId = data.SoundId
			snd.Parent = SoundService
			activeSound = snd
			ownsSound = true
		end

		local snd = activeSound
		if snd then
			snd.Volume = volume
			table.insert(soundConns, snd.Ended:Connect(function()
				handleEnded()
			end))
			table.insert(soundConns, snd:GetPropertyChangedSignal("TimeLength"):Connect(function()
				if not data.Duration or data.Duration <= 0 then
					duration = snd.TimeLength
					renderProgress()
				end
			end))
			if snd.TimeLength > 0 and (not data.Duration or data.Duration <= 0) then
				duration = snd.TimeLength
			end
		end
	end

	loadTrackData = function(data, autoplayThis)
		data = data or {}
		current = { Title = data.Title or "", Artist = data.Artist, Cover = data.Cover }
		elapsed = 0
		duration = data.Duration or 0
		draggingProgress = false
		attachTrackAudio(data)
		renderMeta()
		renderProgress()

		if autoplayThis then
			playing = true
			if activeSound then
				activeSound:Play()
			end
			startTicking()
		else
			playing = false
			if activeSound then
				activeSound:Pause()
			end
			stopTicking()
		end
		paintPlayPause()

		fireEvent("TrackChanged", currentPayload())
		if opts.Callback then
			task.spawn(opts.Callback, "track", currentPayload())
		end
	end

	pickIndex = function(direction)
		if not useQueue or #queue <= 1 then
			return nil
		end
		if shuffle then
			local n
			repeat
				n = rng:NextInteger(1, #queue)
			until n ~= index
			return n
		end
		local n = index + direction
		if n < 1 then
			return loopMode == "all" and #queue or nil
		elseif n > #queue then
			return loopMode == "all" and 1 or nil
		end
		return n
	end

	gotoIndex = function(n, autoplayThis)
		index = n
		loadTrackData(queue[n], autoplayThis)
	end

	handleEnded = function()
		if loopMode == "one" then
			seekTo(0, false)
			if activeSound then
				activeSound:Play()
			end
			return
		end
		if useQueue then
			local n = pickIndex(1)
			if n then
				gotoIndex(n, true)
				fireEvent("Ended")
				return
			end
		end
		playing = false
		elapsed = duration
		renderProgress()
		paintPlayPause()
		stopTicking()
		fireEvent("Ended")
	end

	doPlay = function()
		if playing then
			return
		end
		playing = true
		if activeSound then
			activeSound:Play()
		end
		paintPlayPause()
		startTicking()
		fireEvent("Played")
		if opts.Callback then
			task.spawn(opts.Callback, "play", currentPayload())
		end
	end

	doPause = function()
		if not playing then
			return
		end
		playing = false
		if activeSound then
			activeSound:Pause()
		end
		paintPlayPause()
		stopTicking()
		fireEvent("Paused")
		if opts.Callback then
			task.spawn(opts.Callback, "pause", currentPayload())
		end
	end

	applyVolume = function(v, fireCB)
		volume = clamp(v, 0, 1)
		if activeSound then
			activeSound.Volume = volume
		end
		renderVolume()
		if fireCB then
			fireEvent("VolumeChanged", volume)
			if opts.Callback then
				task.spawn(opts.Callback, "volume", volume)
			end
		end
	end

	applyShuffle = function(v, fireCB)
		shuffle = v == true
		paintShuffle()
		if fireCB then
			fireEvent("ShuffleChanged", shuffle)
			if opts.Callback then
				task.spawn(opts.Callback, "shuffle", shuffle)
			end
		end
	end

	applyLoop = function(mode, fireCB)
		if mode ~= "off" and mode ~= "one" and mode ~= "all" then
			Log.warn(where, ("Loop must be \"off\", \"one\" or \"all\", got \"%s\" — using \"off\"."):format(tostring(mode)))
			mode = "off"
		end
		loopMode = mode
		paintLoop()
		if fireCB then
			fireEvent("LoopChanged", loopMode)
			if opts.Callback then
				task.spawn(opts.Callback, "loop", loopMode)
			end
		end
	end

	doNext = function()
		if useQueue then
			local n = pickIndex(1)
			if n then
				gotoIndex(n, playing)
			end
		end
		fireEvent("NextTrack")
		if opts.Callback then
			task.spawn(opts.Callback, "next", currentPayload())
		end
	end

	doPrevious = function()
		if elapsed > 3 then
			seekTo(0, true)
		elseif useQueue then
			local n = pickIndex(-1)
			if n then
				gotoIndex(n, playing)
			else
				seekTo(0, true)
			end
		else
			seekTo(0, true)
		end
		fireEvent("PreviousTrack")
		if opts.Callback then
			task.spawn(opts.Callback, "previous", currentPayload())
		end
	end

	-- ── wire the chrome ──────────────────────────────────────────────────────
	attachDrag(progressHit, progressKnobScale, function(x)
		local w = progressHit.AbsoluteSize.X
		local pos = progressHit.AbsolutePosition.X
		local pct = w > 0 and clamp((x - pos) / w, 0, 1) or 0
		seekTo(pct * math.max(duration, 0), true)
	end, function()
		draggingProgress = true
	end, function()
		draggingProgress = false
	end)

	if showVolume then
		attachDrag(volumeHit, volumeKnobScale, function(x)
			local w = volumeHit.AbsoluteSize.X
			local pos = volumeHit.AbsolutePosition.X
			local pct = w > 0 and clamp((x - pos) / w, 0, 1) or 0
			applyVolume(pct, true)
		end)
		local lastVolume = volume > 0 and volume or 0.5
		volumeBtn.Activated:Connect(function()
			if volume > 0 then
				lastVolume = volume
				applyVolume(0, true)
			else
				applyVolume(lastVolume > 0 and lastVolume or 0.5, true)
			end
		end)
	end

	-- The setter is kept: SetAccent moves both ends of this hover, and it can land
	-- while the pointer is already on the button (see Create.hover).
	local _, setPlayHover = Create.hover(playBtn, "BackgroundColor3", ctx.Accent, ctx.AccentHover)
	playBtn.Activated:Connect(function()
		playScale.Scale = 0.92
		Tween.play(playScale, Tween.Spring, { Scale = 1 })
		if playing then
			doPause()
		else
			doPlay()
		end
	end)

	prevBtn.Activated:Connect(function()
		doPrevious()
	end)

	nextBtn.Activated:Connect(function()
		doNext()
	end)

	if showShuffle then
		shuffleBtn.Activated:Connect(function()
			applyShuffle(not shuffle, true)
		end)
	end
	if showLoop then
		local order = { "off", "all", "one" }
		loopBtn.Activated:Connect(function()
			local nextMode = "off"
			for i, m in order do
				if m == loopMode then
					nextMode = order[(i % 3) + 1]
					break
				end
			end
			applyLoop(nextMode, true)
		end)
	end
	if showFavorite then
		favoriteBtn.Activated:Connect(function()
			loved = not loved
			paintFavorite()
			fireEvent("FavoriteChanged", loved)
			if opts.Callback then
				task.spawn(opts.Callback, "favorite", loved)
			end
		end)
	end

	ctx:RegisterAccent(function(accent)
		progressFill.BackgroundColor3 = accent
		-- Repaints playBtn itself, to whichever end applies right now — so a
		-- re-theme under a hovered button doesn't snap it back to the resting fill.
		setPlayHover(ctx.Accent, ctx.AccentHover)
		if showVolume then
			volumeFill.BackgroundColor3 = accent
		end
		paintShuffle()
		paintLoop()
		paintFavorite()
	end)

	-- ── public handle ────────────────────────────────────────────────────────
	local handle = {}
	handle.Played = bindables.Played.Event
	handle.Paused = bindables.Paused.Event
	handle.NextTrack = bindables.NextTrack.Event
	handle.PreviousTrack = bindables.PreviousTrack.Event
	handle.Seeked = bindables.Seeked.Event
	handle.VolumeChanged = bindables.VolumeChanged.Event
	handle.ShuffleChanged = bindables.ShuffleChanged.Event
	handle.LoopChanged = bindables.LoopChanged.Event
	handle.TrackChanged = bindables.TrackChanged.Event
	handle.Ended = bindables.Ended.Event
	handle.FavoriteChanged = bindables.FavoriteChanged.Event

	function handle:Play()
		doPlay()
	end
	function handle:Pause()
		doPause()
	end
	function handle:TogglePlay()
		if playing then
			doPause()
		else
			doPlay()
		end
	end
	function handle:IsPlaying(): boolean
		return playing
	end
	function handle:Next()
		doNext()
	end
	function handle:Previous()
		doPrevious()
	end
	function handle:Seek(t: number)
		seekTo(t, true)
	end
	function handle:GetProgress(): number
		return elapsed
	end
	function handle:SetProgress(t: number)
		elapsed = clamp(t, 0, math.max(duration, 0))
		renderProgress()
	end
	function handle:GetDuration(): number
		return duration
	end
	function handle:SetDuration(t: number)
		duration = math.max(0, t)
		renderProgress()
	end
	function handle:SetPlaying(v: boolean)
		if v then
			doPlay()
		else
			doPause()
		end
	end
	function handle:GetVolume(): number
		return volume
	end
	function handle:SetVolume(v: number)
		applyVolume(v, true)
	end
	function handle:GetShuffle(): boolean
		return shuffle
	end
	function handle:SetShuffle(v: boolean)
		applyShuffle(v, true)
	end
	function handle:GetLoop(): string
		return loopMode
	end
	function handle:SetLoop(mode: string)
		applyLoop(mode, true)
	end
	function handle:GetTrack()
		return currentPayload()
	end
	function handle:SetTrack(data: any)
		useQueue = false
		loadTrackData(data, playing)
	end
	function handle:SetQueue(list: { any }, startIndex: number?)
		queue = list or {}
		useQueue = #queue > 0
		index = useQueue and math.clamp(math.floor(startIndex or 1), 1, #queue) or 1
		if useQueue then
			loadTrackData(queue[index], false)
		end
	end

	-- ── cleanup ──────────────────────────────────────────────────────────────
	-- Heartbeat + the owned Sound live outside the GUI tree, so they need
	-- explicit teardown — Destroying is the one signal that fires regardless of
	-- who tears down the ancestor (Group/Tab/Window:Destroy).
	f.field.Destroying:Connect(function()
		stopTicking()
		for _, c in soundConns do
			c:Disconnect()
		end
		table.clear(soundConns)
		local snd = activeSound
		if snd then
			if ownsSound then
				snd:Stop()
				snd:Destroy()
			else
				snd:Pause() -- same rule as attachTrackAudio: don't destroy it, don't leave it playing
			end
		end
		activeSound = nil
	end)

	-- ── initial load ─────────────────────────────────────────────────────────
	local initial
	if useQueue then
		initial = queue[index]
	else
		initial = {
			Title = opts.Title,
			Artist = opts.Artist,
			Cover = opts.Cover,
			Duration = opts.Duration,
			SoundId = opts.SoundId,
			Sound = opts.Sound,
		}
	end
	renderVolume()
	loadTrackData(initial, opts.Autoplay == true)

	return f.field, handle, true
end

end

__modules['components.Notify'] = function(...)
--!strict
-- components/Notify.lua — bottom-right toast. Slides + fades in (0.22s), holds
-- for `Duration` (default 3.2s), slides out (0.25s), then destroys itself.

local Create = __require("util.Create")
local Theme = __require("Theme")
local Tween = __require("util.Tween")
local Fade = __require("util.Fade")
local Icons = __require("Icons")

-- Semantic notification kinds. Each colors the accent bar + adds a matching
-- icon. Anything else (incl. nil / "default") keeps the original accent-themed
-- toast with no icon. Keys are matched case-insensitively; "warn" aliases
-- "warning".
local C = Theme.Colors
local TYPES: { [string]: { color: Color3, icon: string } } = {
	success = { color = C.success, icon = "success" },
	info    = { color = C.info,    icon = "info" },
	warning = { color = C.warning, icon = "warning" },
	error   = { color = C.danger,  icon = "error" },
}

return function(ctx: any, container: Frame, opts: any)
	local colors = Theme.Colors
	opts = opts or {}

	-- Resolve the requested Type → semantic color + icon (nil = default look).
	local kind: { color: Color3, icon: string }? = nil
	if type(opts.Type) == "string" then
		local key = opts.Type:lower()
		kind = TYPES[key == "warn" and "warning" or key]
	end
	local barColor = kind and kind.color or ctx.Accent

	-- The toast is a clipping shell: the card slides horizontally inside it and
	-- is cut at the edge (no layout reflow), and the whole thing fades as a unit
	-- through util/Fade.lua. It was a CanvasGroup, which did both for free but
	-- rasterized the title and body text into a buffer and blurred them.
	local order = (container:GetAttribute("count") or 0) + 1
	container:SetAttribute("count", order)

	-- Cap the visible stack: the container grows upward with AutomaticSize, so a
	-- burst of notifications used to run off the top of the window and sit there
	-- clipped. Retire the oldest instead.
	local MAX_TOASTS = 4
	local live: { GuiObject } = {}
	for _, child in container:GetChildren() do
		if child:IsA("GuiObject") and child.Name == "Toast" then
			table.insert(live, child)
		end
	end
	if #live >= MAX_TOASTS then
		table.sort(live, function(a, b)
			return a.LayoutOrder < b.LayoutOrder
		end)
		for i = 1, #live - MAX_TOASTS + 1 do
			live[i]:Destroy()
		end
	end

	local toast = Create("Frame", {
		Name = "Toast",
		BackgroundTransparency = 1,
		Size = UDim2.fromOffset(240, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		ClipsDescendants = true, -- the card slides in from off its right edge
		LayoutOrder = order,
		Parent = container,
	})

	local card = Create("Frame", {
		Name = "Card",
		Position = UDim2.fromOffset(20, 0),
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		BackgroundColor3 = colors.pop,
		ClipsDescendants = true,
		Parent = toast,
	}, {
		Create.corner(9),
		Create.stroke(colors.border),
	})

	-- content holds the vertical text stack; the card sizes to it. The accent
	-- bar is positioned absolutely (height tracked) so it never feeds the
	-- card's AutomaticSize — otherwise its (1,0) height would run away.
	-- A typed toast reserves a left gutter for its icon; the default keeps the
	-- original snug padding.
	local leftPad = kind and 40 or 16
	local content = Create("Frame", {
		Name = "Content",
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		Parent = card,
	}, {
		Create.padding(10, 13, 10, leftPad),
		Create.listLayout({ Padding = UDim.new(0, 3) }),
	})

	-- Type icon, tinted to match the bar, pinned top-left inside the gutter.
	-- Positioned absolutely so it never feeds the card's AutomaticSize.
	if kind then
		local icon = Icons.new(kind.icon, 18, kind.color)
		icon.Position = UDim2.fromOffset(13, 11)
		icon.ZIndex = 2
		icon.Parent = card
	end

	-- Scale height (1,0 on Y) fills the card natively. Scale-sized children are
	-- excluded from AutomaticSize, so the bar never feeds the card's height and
	-- can't trigger AbsoluteSizeChanged re-entrancy.
	local bar = Create("Frame", {
		Name = "AccentBar",
		Position = UDim2.fromOffset(0, 0),
		Size = UDim2.new(0, 3, 1, 0),
		BackgroundColor3 = barColor,
		BorderSizePixel = 0,
		ZIndex = 2,
		Parent = card,
	})
	-- Only the default (accent-themed) toast tracks live accent changes; typed
	-- toasts have a fixed semantic color. A toast is transient, so drop the
	-- subscription when it dies — otherwise the registry grows by one dead
	-- closure per notification.
	local unsubscribeAccent: (() -> ())? = nil
	if not kind then
		unsubscribeAccent = ctx:RegisterAccent(function(accent)
			bar.BackgroundColor3 = accent
		end)
	end

	if opts.Title then
		Create("TextLabel", {
			Name = "Title",
			BackgroundTransparency = 1,
			Size = UDim2.new(1, 0, 0, 0),
			AutomaticSize = Enum.AutomaticSize.Y,
			Text = opts.Title,
			TextColor3 = colors.text,
			TextSize = 13,
			FontFace = Theme.Font.Medium,
			TextXAlignment = Enum.TextXAlignment.Left,
			TextWrapped = true,
			LayoutOrder = 1,
			Parent = content,
		})
	end

	Create("TextLabel", {
		Name = "Text",
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		Text = opts.Text or "",
		TextColor3 = colors.text_muted,
		TextSize = 12,
		FontFace = Theme.Font.Regular,
		TextXAlignment = Enum.TextXAlignment.Left,
		TextYAlignment = Enum.TextYAlignment.Top,
		TextWrapped = true,
		LayoutOrder = 2,
		Parent = content,
	})

	-- in — the fade is built last, so its snapshot covers the finished toast.
	local fade = Fade.new(toast)
	fade:Set(1)
	fade:To(Tween.Toast, 0)
	Tween.play(card, Tween.Toast, { Position = UDim2.fromOffset(0, 0) })

	-- A toast doesn't always live to its own timer: the MAX_TOASTS cap above
	-- destroys the oldest ones outright, and the window can be unloaded at any
	-- point. Both used to leave this toast's accent subscription in the registry
	-- and its exit animation still queued — a quarter-second of tweening a
	-- destroyed subtree, and a dead closure firing on every SetAccent until the
	-- timer that was going to clean it up finally came round. Destroying is the
	-- one signal that covers every way it can go.
	local finished = false
	local function retire()
		if finished then
			return
		end
		finished = true
		if unsubscribeAccent then
			unsubscribeAccent()
			unsubscribeAccent = nil
		end
		fade:Destroy()
	end
	toast.Destroying:Connect(retire)

	-- hold → out → destroy
	task.delay(opts.Duration or 3.2, function()
		if finished then
			return -- already retired (capped out, or the window went away)
		end
		Tween.play(card, Tween.ToastOut, { Position = UDim2.fromOffset(20, 0) })
		fade:To(Tween.ToastOut, 1, function()
			retire()
			toast:Destroy()
		end)
	end)
end

end

__modules['components.Paragraph'] = function(...)
--!strict
-- components/Paragraph.lua — optional title + body copy.

local Create = __require("util.Create")
local Theme = __require("Theme")

return function(ctx: any, opts: any)
	local colors = Theme.Colors

	local p = Create("Frame", {
		Name = "Paragraph",
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
	}, {
		Create.padding(11, 2),
		Create.listLayout({ Padding = UDim.new(0, 5) }),
	})

	if opts.Title then
		Create("TextLabel", {
			Name = "Title",
			BackgroundTransparency = 1,
			Size = UDim2.new(1, 0, 0, 0),
			AutomaticSize = Enum.AutomaticSize.Y,
			Text = opts.Title,
			TextColor3 = colors.text,
			TextSize = 13,
			FontFace = Theme.Font.Medium,
			TextXAlignment = Enum.TextXAlignment.Left,
			TextWrapped = true,
			LayoutOrder = 1,
			Parent = p,
		})
	end

	Create("TextLabel", {
		Name = "Body",
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		Text = opts.Body or "",
		TextColor3 = colors.text_muted,
		TextSize = 12,
		FontFace = Theme.Font.Regular,
		TextXAlignment = Enum.TextXAlignment.Left,
		TextYAlignment = Enum.TextYAlignment.Top,
		TextWrapped = true,
		LineHeight = 1.3,
		LayoutOrder = 2,
		Parent = p,
	})

	return p, {}, true
end

end

__modules['components.Player'] = function(...)
--!strict
-- components/Player.lua — avatar + name/badge + @username · ID info panel.

local Create = __require("util.Create")
local Theme = __require("Theme")
local Icons = __require("Icons")
local Asset = __require("util.Asset")

return function(ctx: any, opts: any)
	local colors = Theme.Colors

	local panel = Create("Frame", {
		Name = "Player",
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
	}, {
		Create.padding(12, 2),
		Create.listLayout({
			FillDirection = Enum.FillDirection.Horizontal,
			VerticalAlignment = Enum.VerticalAlignment.Center,
			Padding = UDim.new(0, 14),
		}),
	})

	-- avatar ───────────────────────────────────────────────────────────────
	-- The placeholder tile is accent-*tinted*, with the accent carried by the
	-- icon on top. A 56px solid-accent square was the biggest block of colour
	-- on the Home tab and it wasn't even real content.
	local avatar = Create("Frame", {
		Name = "Avatar",
		Size = UDim2.fromOffset(56, 56),
		BackgroundColor3 = colors.accent_soft,
		ClipsDescendants = true,
		LayoutOrder = 1,
		Parent = panel,
	}, {
		Create.corner(14),
		Create.stroke(colors.border),
	})

	local picture = Create("ImageLabel", {
		Name = "Image",
		BackgroundTransparency = 1,
		Size = UDim2.fromScale(1, 1),
		Image = "",
		ScaleType = Enum.ScaleType.Crop,
		Parent = avatar,
	}) :: ImageLabel

	-- The glyph is always built and only toggled, never swapped for the picture:
	-- `Avatar` goes through Asset.resolve (bare id / url / file path / fallback
	-- chain), so there's a window with a source but nothing drawn yet, and a
	-- source that never loads should leave the icon up rather than an empty tile.
	-- The picture itself is never hidden — an ImageLabel the engine isn't
	-- rendering never loads in the first place.
	local placeholder: GuiObject = Icons.new("avatar", 34, colors.accent) -- may be a glyph TextLabel
	placeholder.AnchorPoint = Vector2.new(0.5, 0.5)
	placeholder.Position = UDim2.fromScale(0.5, 0.5);
	(placeholder :: any).Parent = avatar

	if opts.Avatar then
		-- Off-thread: resolving an https avatar downloads + caches it on first
		-- use, which must not stall the window build.
		task.spawn(function()
			Asset.load(picture, opts.Avatar, function(loaded)
				placeholder.Visible = not loaded
			end)
		end)
	end

	-- info ─────────────────────────────────────────────────────────────────
	local info = Create("Frame", {
		Name = "Info",
		BackgroundTransparency = 1,
		Size = UDim2.new(1, -70, 0, 0), -- fills past the 56px avatar + 14px gap
		AutomaticSize = Enum.AutomaticSize.Y,
		LayoutOrder = 2,
		Parent = panel,
	}, {
		Create.listLayout({ Padding = UDim.new(0, 2) }),
	})

	local nameRow = Create("Frame", {
		Name = "NameRow",
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		LayoutOrder = 1,
		Parent = info,
	}, {
		Create.listLayout({
			FillDirection = Enum.FillDirection.Horizontal,
			VerticalAlignment = Enum.VerticalAlignment.Center,
			Padding = UDim.new(0, 8),
		}),
	})

	Create("TextLabel", {
		Name = "Name",
		BackgroundTransparency = 1,
		AutomaticSize = Enum.AutomaticSize.XY,
		Text = opts.DisplayName or opts.Username or "Player",
		TextColor3 = colors.text,
		TextSize = 16,
		FontFace = Theme.Font.Medium,
		TextXAlignment = Enum.TextXAlignment.Left,
		LayoutOrder = 1,
		Parent = nameRow,
	})

	local badge: TextLabel? = nil
	if opts.Badge then
		-- A filled chip (tinted surface + accent text) rather than an outlined
		-- one: an accent hairline that small reads as a stray line at a glance,
		-- and the fill gives the label something to sit on.
		badge = Create("TextLabel", {
			Name = "Badge",
			AutomaticSize = Enum.AutomaticSize.X,
			Size = UDim2.fromOffset(17, 17),
			BackgroundColor3 = colors.accent_soft,
			Text = string.upper(opts.Badge),
			TextColor3 = colors.accent,
			TextSize = 10,
			FontFace = Theme.Font.Bold,
			LayoutOrder = 2,
			Parent = nameRow,
		}, {
			Create.corner(999),
			Create.padding(1, 7),
		})
	end

	local sub = "@" .. (opts.Username or "player")
	if opts.UserId and opts.UserId ~= 0 then
		sub = sub .. "  ·  ID " .. tostring(opts.UserId)
	end
	Create("TextLabel", {
		Name = "Sub",
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		Text = sub,
		TextColor3 = colors.text_muted,
		TextSize = 12,
		FontFace = Theme.Font.Regular,
		TextXAlignment = Enum.TextXAlignment.Left,
		LayoutOrder = 2,
		Parent = info,
	})

	ctx:RegisterAccent(function(accent)
		avatar.BackgroundColor3 = ctx.AccentSoft
		Icons.tint(placeholder, accent)
		if badge then
			badge.BackgroundColor3 = ctx.AccentSoft
			badge.TextColor3 = accent
		end
	end)

	return panel, {}, false
end

end

__modules['components.PlayerSelect'] = function(...)
--!strict
-- components/PlayerSelect.lua — single + multi player picker.
-- Same box/popover shell as Dropdown, but the menu lists Players:GetPlayers()
-- live (refetched on every open, and kept in sync while open) with a headshot
-- thumbnail, display name and @username per row. Selection is tracked by UserId
-- so it round-trips through config Flags; :Get() always resolves live against the
-- current player list, so a player who leaves quietly drops out instead of
-- leaving a stale handle.
--
-- The menu SCROLLS: a full server is 30+ players, so the row list lives in a
-- ScrollingFrame capped at MENU_MAX_H. (It used to be a plain auto-sized frame
-- under a UISizeConstraint, which clipped everyone past the sixth player with no
-- way to reach them.)

local Services = __require("util.Services")

local Players = Services.Players

local Create = __require("util.Create")
local Theme = __require("Theme")
local Tween = __require("util.Tween")
local Icons = __require("Icons")
local Field = __require("components.Field")

local MENU_MAX_H = 264 -- popover height cap; rows scroll past it
local MENU_MIN_W = 230
local ROW_H = 40
local TICK_W, AVATAR_W, GAP = 15, 28, 9

-- Headshot URLs are a network round-trip and never change within a session, so
-- they're cached process-wide and in-flight requests are shared. Re-opening the
-- menu (or toggling a row in a multi-select) then reuses the resolved image
-- instead of re-fetching every avatar, which is what made them flicker.
local thumbCache: { [number]: string } = {}
local thumbWaiters: { [number]: { (string) -> () } } = {}

local function requestThumb(userId: number, apply: (string) -> ())
	local cached = thumbCache[userId]
	if cached then
		apply(cached)
		return
	end
	local waiting = thumbWaiters[userId]
	if waiting then
		table.insert(waiting, apply)
		return
	end
	thumbWaiters[userId] = { apply }
	task.spawn(function()
		local ok, content = pcall(
			Players.GetUserThumbnailAsync,
			Players,
			userId,
			Enum.ThumbnailType.HeadShot,
			Enum.ThumbnailSize.Size48x48
		)
		local list = thumbWaiters[userId]
		thumbWaiters[userId] = nil
		if not ok or type(content) ~= "string" or content == "" then
			return
		end
		thumbCache[userId] = content
		for _, fn in list or {} do
			pcall(fn, content)
		end
	end)
end

local function displayName(p: Player): string
	if p.DisplayName ~= "" and p.DisplayName ~= p.Name then
		return p.DisplayName
	end
	return p.Name
end

local function toId(v: any): number?
	if typeof(v) == "Instance" and v:IsA("Player") then
		return v.UserId
	elseif type(v) == "number" then
		return v
	end
	return nil
end

local function build(ctx: any, opts: any, multi: boolean)
	local colors = Theme.Colors
	local placeholder = opts.Placeholder or (multi and "Select players..." or "Select a player...")
	local stack = opts.Stack == true

	local singleId: number? = toId(opts.Default)
	local selected: { [number]: boolean } = {}
	if multi and type(opts.Default) == "table" then
		for _, v in opts.Default do
			local id = toId(v)
			if id then
				selected[id] = true
			end
		end
	end

	local f = Field.new(ctx, opts, stack)

	-- box ────────────────────────────────────────────────────────────────────
	local box = Create("TextButton", {
		Name = "PlayerSelect",
		AutoButtonColor = false,
		Text = "",
		Size = stack and UDim2.new(1, 0, 0, 32) or UDim2.fromOffset(opts.Width or 160, 32),
		BackgroundColor3 = colors.control,
		LayoutOrder = 2,
		Parent = stack and f.field or f.row,
	}, {
		Create.corner(Theme.Metrics.controlRadius),
		Create.stroke(colors.border),
		Create.padding(0, 8, 0, 12),
	})
	local boxStroke = box:FindFirstChildOfClass("UIStroke") :: UIStroke

	local valLabel = Create("TextLabel", {
		Name = "Value",
		BackgroundTransparency = 1,
		Size = UDim2.new(1, -24, 1, 0),
		Text = placeholder,
		TextColor3 = colors.text_muted,
		TextSize = 13,
		FontFace = Theme.Font.Regular,
		TextXAlignment = Enum.TextXAlignment.Left,
		TextTruncate = Enum.TextTruncate.AtEnd,
		Parent = box,
	})

	local chevron = Icons.new("caret", 14, colors.text_dim)
	chevron.AnchorPoint = Vector2.new(1, 0.5)
	chevron.Position = UDim2.new(1, 0, 0.5, 0);
	(chevron :: any).Parent = box

	-- menu ─────────────────────────────────────────────────────────────────── (parented to overlay on open)
	-- The menu auto-sizes to the scroller, whose height is fitted to the row list
	-- up to MENU_MAX_H (see fitMenu) — past that the content overflows and the
	-- list scrolls instead of being silently cut off. A Frame, not a CanvasGroup:
	-- a group buffer would blur every name in the list (see util/Fade.lua).
	local menu = Create("Frame", {
		Name = "PlayerMenu",
		Visible = false,
		AutomaticSize = Enum.AutomaticSize.Y,
		Size = UDim2.fromOffset(MENU_MIN_W, 0),
		BackgroundColor3 = colors.pop,
		ClipsDescendants = true,
	}, {
		Create.corner(8),
		Create.stroke(colors.border),
		Create.padding(5),
	})

	local scroller = Create("ScrollingFrame", {
		Name = "Rows",
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		Size = UDim2.new(1, 0, 0, 0),
		CanvasSize = UDim2.new(),
		AutomaticCanvasSize = Enum.AutomaticSize.Y,
		ScrollingDirection = Enum.ScrollingDirection.Y,
		ScrollBarThickness = 4,
		ScrollBarImageColor3 = colors.text_dim,
		ScrollBarImageTransparency = 0.35,
		Parent = menu,
	}, {
		Create.listLayout({ Padding = UDim.new(0, 2) }),
	})

	-- The viewport is driven off the layout's measured content height rather than
	-- AutomaticSize, so the menu is exactly as tall as its rows up to MENU_MAX_H
	-- and scrolls beyond it. (The canvas keeps auto-sizing, which is what gives
	-- the overflow something to scroll through.)
	local rowLayout = scroller:FindFirstChildOfClass("UIListLayout") :: UIListLayout
	local function fitMenu()
		scroller.Size = UDim2.new(1, 0, 0, math.min(MENU_MAX_H, rowLayout.AbsoluteContentSize.Y))
	end
	rowLayout:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(fitMenu)

	local function selectedPlayers(): { Player }
		local list = {}
		for _, p in Players:GetPlayers() do
			if selected[p.UserId] then
				table.insert(list, p)
			end
		end
		return list
	end

	local function valueLabelText(): (string, boolean)
		if multi then
			local names = {}
			for _, p in selectedPlayers() do
				table.insert(names, displayName(p))
			end
			if #names == 0 then
				return placeholder, false
			end
			return table.concat(names, ", "), true
		else
			local p = singleId and Players:GetPlayerByUserId(singleId)
			if not p then
				return placeholder, false
			end
			return displayName(p), true
		end
	end

	local function relabel()
		local text, hasVal = valueLabelText()
		valLabel.Text = text
		valLabel.TextColor3 = hasVal and colors.text or colors.text_muted
	end

	local function fireCallback()
		if not opts.Callback then
			return
		end
		if multi then
			task.spawn(opts.Callback, selectedPlayers())
		else
			task.spawn(opts.Callback, singleId and Players:GetPlayerByUserId(singleId) or nil)
		end
	end

	local function isSelected(userId: number): boolean
		if multi then
			return selected[userId] == true
		end
		return singleId == userId
	end

	-- Live row handles, keyed by UserId, so picking (or an external :Set) repaints
	-- the affected rows in place instead of tearing the whole menu down — a
	-- rebuild would drop every hover state and restart the open animation.
	type Row = { tick: GuiObject, name: TextLabel }
	local rows: { [number]: Row } = {}

	local function paintRow(userId: number)
		local row = rows[userId]
		if not row then
			return
		end
		local sel = isSelected(userId)
		row.tick.Visible = sel
		row.name.TextColor3 = sel and colors.text or colors.text_muted
	end

	local function repaintAll()
		for userId in rows do
			paintRow(userId)
		end
	end

	local function pick(p: Player)
		if multi then
			local was = selected[p.UserId] == true
			selected[p.UserId] = (not was) or nil
			paintRow(p.UserId)
			relabel()
		else
			local previous = singleId
			singleId = p.UserId
			if previous then
				paintRow(previous)
			end
			paintRow(p.UserId)
			relabel()
			ctx:ClosePopover()
		end
		fireCallback()
	end

	local function rebuild()
		table.clear(rows)
		for _, child in scroller:GetChildren() do
			if child:IsA("GuiButton") or child:IsA("TextLabel") then
				child:Destroy()
			end
		end

		local players = Players:GetPlayers()
		table.sort(players, function(a, b)
			return displayName(a):lower() < displayName(b):lower()
		end)

		if #players == 0 then
			Create("TextLabel", {
				Name = "Empty",
				BackgroundTransparency = 1,
				Size = UDim2.new(1, 0, 0, 28),
				Text = "No players online",
				TextColor3 = colors.text_muted,
				TextSize = 13,
				FontFace = Theme.Font.Regular,
				Parent = scroller,
			})
			return
		end

		for i, p in players do
			local userId = p.UserId

			local row = Create("TextButton", {
				Name = tostring(userId),
				AutoButtonColor = false,
				Text = "",
				BackgroundColor3 = colors.control_hi,
				BackgroundTransparency = 1,
				Size = UDim2.new(1, -4, 0, ROW_H), -- -4 keeps rows clear of the scrollbar
				LayoutOrder = i,
				ClipsDescendants = true,
				Parent = scroller,
			}, {
				Create.corner(6),
				Create.padding(0, 8),
				Create.listLayout({
					FillDirection = Enum.FillDirection.Horizontal,
					VerticalAlignment = Enum.VerticalAlignment.Center,
					Padding = UDim.new(0, GAP),
				}),
			})

			local tickHolder = Create("Frame", {
				Name = "Tick",
				BackgroundTransparency = 1,
				Size = UDim2.fromOffset(TICK_W, TICK_W),
				LayoutOrder = 1,
				Parent = row,
			})
			local tick = Icons.new("check", 14, ctx.Accent)
			tick.Visible = false;
			(tick :: any).Parent = tickHolder

			-- avatar: accent-tinted placeholder with a generic icon, swapped for the
			-- real headshot once the (cached) thumbnail lookup resolves — the fetch
			-- runs off-thread so opening the menu never blocks on the network.
			local avatar = Create("Frame", {
				Name = "Avatar",
				Size = UDim2.fromOffset(AVATAR_W, AVATAR_W),
				BackgroundColor3 = ctx.AccentSoft,
				ClipsDescendants = true,
				LayoutOrder = 2,
				Parent = row,
			}, {
				Create.corner(8),
			})
			local avatarIcon = Icons.new("avatar", 16, ctx.Accent)
			avatarIcon.AnchorPoint = Vector2.new(0.5, 0.5)
			avatarIcon.Position = UDim2.fromScale(0.5, 0.5);
			(avatarIcon :: any).Parent = avatar

			requestThumb(userId, function(image)
				if not avatar.Parent then
					return
				end
				avatarIcon.Visible = false
				local existing = avatar:FindFirstChild("Image")
				if existing and existing:IsA("ImageLabel") then
					existing.Image = image
					return
				end
				Create("ImageLabel", {
					Name = "Image",
					BackgroundTransparency = 1,
					Size = UDim2.fromScale(1, 1),
					Image = image,
					Parent = avatar,
				})
			end)

			-- Names take the row's leftover width (offset-sized, truncated) so a long
			-- display name can't push the @username past the menu edge.
			local names = Create("Frame", {
				Name = "Names",
				BackgroundTransparency = 1,
				Size = UDim2.new(1, -(TICK_W + AVATAR_W + GAP * 2), 0, 0),
				AutomaticSize = Enum.AutomaticSize.Y,
				LayoutOrder = 3,
				Parent = row,
			}, {
				Create.listLayout({ Padding = UDim.new(0, 1) }),
			})

			local nameLabel = Create("TextLabel", {
				Name = "Display",
				BackgroundTransparency = 1,
				Size = UDim2.new(1, 0, 0, 15),
				Text = displayName(p),
				TextColor3 = colors.text_muted,
				TextSize = 13,
				FontFace = Theme.Font.Regular,
				TextXAlignment = Enum.TextXAlignment.Left,
				TextTruncate = Enum.TextTruncate.AtEnd,
				LayoutOrder = 1,
				Parent = names,
			})
			Create("TextLabel", {
				Name = "Username",
				BackgroundTransparency = 1,
				Size = UDim2.new(1, 0, 0, 13),
				Text = "@" .. p.Name,
				TextColor3 = colors.text_dim,
				TextSize = 11,
				FontFace = Theme.Font.Regular,
				TextXAlignment = Enum.TextXAlignment.Left,
				TextTruncate = Enum.TextTruncate.AtEnd,
				LayoutOrder = 2,
				Parent = names,
			})

			rows[userId] = { tick = tick, name = nameLabel }
			paintRow(userId)

			Create.hover(row, "BackgroundTransparency", 1, 0)
			-- Tagged as user-driven for Context:OnFlagChanged; `handle:Set` reaches
			-- the same state through its own path and keeps its ambient tag.
			row.Activated:Connect(function()
				ctx:User(pick, p)
			end)
		end
	end

	local function setOpenVisual(open: boolean)
		Tween.play(boxStroke, Tween.Fast, { Color = open and ctx.Accent or colors.border })
		Tween.play(chevron, Tween.Spin, { Rotation = open and 180 or 0 })
	end

	-- Roster changes while the menu is open rebuild it, so someone joining or
	-- leaving mid-pick doesn't leave a row pointing at a player who's gone.
	local liveConns: { RBXScriptConnection } = {}
	local function stopWatching()
		for _, conn in liveConns do
			conn:Disconnect()
		end
		table.clear(liveConns)
	end

	box.Activated:Connect(function()
		if ctx:IsOpen(menu) then
			ctx:ClosePopover()
			return
		end
		rebuild()
		fitMenu()
		scroller.CanvasPosition = Vector2.new(0, 0)
		menu.Size = UDim2.fromOffset(math.max(box.AbsoluteSize.X, MENU_MIN_W), 0)
		setOpenVisual(true)
		table.insert(liveConns, Players.PlayerAdded:Connect(rebuild))
		table.insert(liveConns, Players.PlayerRemoving:Connect(function()
			-- PlayerRemoving fires before the player leaves GetPlayers(), so rebuild
			-- on the next step to get the post-departure roster.
			task.defer(function()
				if ctx:IsOpen(menu) then
					rebuild()
				end
			end)
		end))
		ctx:OpenPopover(menu, box, function()
			stopWatching()
			setOpenVisual(false)
		end)
	end)
	Create.hover(box, "BackgroundColor3", colors.control, colors.control_hi)

	-- The box label resolves UserIds to live players, so it has to be redrawn when
	-- someone selected leaves (or rejoins) — otherwise it keeps naming a player
	-- who isn't in the server any more. These signals outlive the ScreenGui, so
	-- they're torn down off the box's own Destroying.
	do
		local rosterConns: { RBXScriptConnection } = {}
		local function stopRoster()
			for _, conn in rosterConns do
				conn:Disconnect()
			end
			table.clear(rosterConns)
		end
		local function onRoster(p: Player)
			if not box:IsDescendantOf(game) then
				stopRoster()
				return
			end
			if isSelected(p.UserId) then
				task.defer(relabel)
			end
		end
		table.insert(rosterConns, Players.PlayerRemoving:Connect(onRoster))
		table.insert(rosterConns, Players.PlayerAdded:Connect(onRoster))
		-- Destroying is the deterministic half: the descendant check above only
		-- runs on the *next* join or leave, so in a quiet server these two would
		-- survive Window:Destroy indefinitely, pinning the whole control closure.
		box.Destroying:Connect(stopRoster)
	end

	relabel()

	local handle = {}
	function handle:Get(): any
		if multi then
			return selectedPlayers()
		end
		return singleId and Players:GetPlayerByUserId(singleId) or nil
	end
	function handle:Set(value: any)
		if multi then
			table.clear(selected)
			if type(value) == "table" then
				for _, v in value do
					local id = toId(v)
					if id then
						selected[id] = true
					end
				end
			end
		else
			singleId = toId(value)
		end
		relabel()
		repaintAll()
		fireCallback()
	end

	return f.field, handle, true
end

return build

end

__modules['components.Screen'] = function(...)
--!strict
-- components/Screen.lua — the full-screen status page: what Uranium says when
-- there is no window to say it in.
--
-- A hub has exactly two ways to talk to a user — a toast, or `warn()` — and
-- everything fatal falls into the second one: the hub's own scripts failing on
-- the way up, and, before the hub exists at all, the delivery server refusing a
-- client (banned, stale loader, kill switch, nothing to serve). All of those are
-- invisible. The line lands behind whatever else is in the executor console, the
-- UI never appears, and what comes back is "it doesn't work". So the library
-- owns the failure state the same way it owns the window, and it has to read as
-- *Uranium saying something*, not as an executor error.
--
--   local page = Uranium:Screen({
--       Title = "You've been banned",
--       Text  = "Reason: reselling builds.",
--       Code  = "BANNED",
--       Icon  = "ban",
--       Tone  = "error",
--       Discord = "discord.gg/uranium",
--       Dismissable = false,
--   })
--
-- Four things shape the whole file:
--
--   * **No window, no Context, no singleton.** The main case is a page shown
--     when `CreateWindow` has never been called and never will be, so nothing
--     here may touch per-window state. The theme is read statically; the accent
--     is the palette's, not a live one.
--   * **Never throws.** This is the code that runs when everything else already
--     failed, so every option is optional and a junk value degrades to the
--     generic page. `str()` is the funnel — anything that isn't a usable string
--     becomes nil and that row hides itself. What it deliberately does *not* do
--     is swallow its own internal errors: the callers wrap the call in `pcall`
--     and fall back to a console warning, and quietly rendering nothing would
--     rob them of that.
--   * **Identity is the ScreenGui attribute**, set by `mountGui` — so the
--     singleton sweep in util/Singleton.lua removes a live page exactly like it
--     removes a stale window, which is what stops a ban page from surviving the
--     re-run of a fixed loader. It never *claims* the singleton record, so
--     `Uranium:IsLoaded()` keeps meaning "a window exists".
--   * **It can take a value back, not just hand one out.** The optional `Input`
--     block is a key gate: the hub refusing to load until the user types a key,
--     with this page as the only UI on screen. It's built LAZILY and
--     `handle.Input` is absent without it — callers probe that absence to decide
--     whether to fall back to a clipboard button, so it has to mean something.
--   * **One source, two builds.** Everything below the `--@body` marker is
--     shared verbatim with the standalone `ui/screen.lua` (bundle.py glues it to
--     `standalone/screen.prelude.lua` instead of the requires below). The body
--     may therefore use ONLY the small surface the prelude defines — see the
--     contract at the marker — and never `require`, `Services`, `Theme`, `Log`
--     or anything else by name. Blocks between `--@lib` and `--@endlib` are
--     dropped from the standalone build, which is where `Detail` lives: the
--     refusal path never passes one and every byte there is inlined into every
--     refusal reply.

local Services = __require("util.Services")
local Create = __require("util.Create")
local Theme = __require("Theme")
local Tween = __require("util.Tween")
local Fade = __require("util.Fade")
local Icons = __require("Icons")
local Asset = __require("util.Asset")
local Gui = __require("util.Gui")

local UIS = Services.UserInputService
local C = Theme.Colors
local F = Theme.Font
local new = Create
local corner, stroke, pad, list = Create.corner, Create.stroke, Create.padding, Create.listLayout
local tw = Tween.play
local TW = Tween
local newIcon = Icons.new
local tintIcon = Icons.tint
local newFade = Fade.new
local gname = Gui.rname
local BRAND = Theme.Brand.name

-- Paint the brand mark into `image` and report whether it rendered — the body
-- draws the accent square + initial underneath and hides that on `true`, so the
-- titlebar is never a hole (same contract Window.lua's logo follows).
--
-- The zoom lives here, not in the shared body: it's a property of the shipped
-- art (see Theme.Brand.zoom), and the standalone build has no art at all — it
-- runs on a client our own API has just refused, so there is no network to fetch
-- a PNG over. Its prelude answers `false` at once and the fallback mark IS the
-- logo there.
local function loadLogo(image: ImageLabel, done: (boolean) -> ())
	local zoom = tonumber(Theme.Brand.zoom) or 1
	image.Size = UDim2.fromScale(zoom, zoom)
	Asset.load(image, Theme.Brand.logo, done)
end

-- Parent the page and stamp the identity attribute. `Gui.mount` already does
-- both (opts.Parent → gethui → CoreGui → PlayerGui, protect_gui first), and the
-- standalone prelude reimplements exactly this much of it.
local function mountGui(gui: ScreenGui, preferred: Instance?)
	Gui.mount(gui, preferred)
end

--@body
-- ─────────────────────────────────────────────────────────────────────────────
-- SHARED SOURCE. Everything from here down is copied verbatim into the
-- standalone build, so it may use only these names, all supplied by whichever
-- prelude is glued on top:
--
--   UIS                              UserInputService
--   C, F                             Theme.Colors, Theme.Font
--   new(class, props, children?)     the instance factory (Parent applied last)
--   corner(r) stroke(c, t?) pad(t, r?, b?, l?) list(props?)
--   tw(inst, info, goals)            Tween.play
--   TW.Fast / .Normal / .Pop / .MenuOut
--   newIcon(name, size, color)       → ImageLabel, or a glyph TextLabel
--   tintIcon(inst, color)            colours either shape
--   newFade(root)                    → :Set(a) :To(info, a, done?) :Destroy()
--   mountGui(gui, preferred?)        parent it + stamp the identity attribute
--   gname()                          a neutral, per-load ScreenGui name
--   BRAND                            the brand name, for the wordmark
--   loadLogo(image, done)            paint the brand mark; done(loaded). The
--                                    library downloads it; the standalone reads
--                                    the copy already cached on disk, if any.
--
-- Plus the engine globals (Enum, UDim2, Color3, Vector2, task, typeof, …).
-- Nothing else. No `require`, no library table, no executor globals except the
-- clipboard lookup below, which is guarded.
-- ─────────────────────────────────────────────────────────────────────────────

local ORDER = 1000000 -- above the window's ScreenGui, which leaves DisplayOrder at 0
local DIM = 0.28      -- backdrop transparency at rest (lower = darker)
local CARD_W = 420    -- max card width; below that it tracks the viewport
local PAD = 16
local GAP = 12
-- The card is a miniature of the window, the same way the bind HUD is: window
-- radius, a chrome titlebar with the mark in it over a `bg` body, one border,
-- and a soft shadow under the whole thing. It used to be a lone `card`-coloured
-- box with an icon chip at the top — correct palette, but nothing about it said
-- Uranium, which is a strange thing for the one screen that exists to be the
-- product speaking.
local RADIUS = 12  -- Theme.Metrics.windowRadius
local BAR = 42     -- titlebar height (the window's own is 50; this is a dialog)
local LOGO = 24    -- brand mark, square
local CHIP = 36    -- tone icon chip
--@lib
local SHADOW_PAD = 48 -- how far the shadow's soft tail bleeds past the card
local SHADOW_T = 0.72 -- resting transparency (high = faint)
--@endlib

-- The one input funnel. Anything that isn't usable text becomes nil, and every
-- caller treats nil as "hide that row" — which is how a junk options table
-- degrades to the generic page instead of erroring.
local function str(v: any): string?
	if type(v) == "string" then
		return v ~= "" and v or nil
	end
	if type(v) == "number" then
		return tostring(v)
	end
	return nil
end

-- Tone TINTS, it doesn't repaint: only the icon chip and the hairline under the
-- header take this colour, and the card stays the library's own dark surface.
-- `info` deliberately maps to the accent rather than Notify's neutral grey — a
-- grey chip on a grey card is no mark at all at this size, and a page is the one
-- place the product should be visibly speaking.
local function toneOf(v: any): Color3
	local name = type(v) == "string" and string.lower(v) or ""
	if name == "warning" or name == "warn" then
		return C.warning
	elseif name == "info" then
		return C.accent
	end
	return C.danger
end

-- Best-effort clipboard. Guarded twice over: the global may not exist (Studio),
-- and reading it may itself throw in a locked-down sandbox.
local function copyText(text: string): boolean
	local fn: any = nil
	pcall(function()
		if type(setclipboard) == "function" then
			fn = setclipboard
		elseif type(toclipboard) == "function" then
			fn = toclipboard
		end
	end)
	if not fn then
		return false
	end
	return (pcall(fn, text))
end

-- The read half, for the paste affordance on an `Input` block. Resolved once per
-- page and handed back as a function or nil — where the executor exposes none,
-- the affordance is never drawn rather than drawn dead. `toclipboard` is last:
-- on some builds it's the *write* half under another name, so it's the fallback
-- rather than something we'd rather call.
local function clipboardFn(): any
	local fn: any = nil
	pcall(function()
		if type(getclipboard) == "function" then
			fn = getclipboard
		elseif type(getclipboardtext) == "function" then
			fn = getclipboardtext
		elseif type(toclipboard) == "function" then
			fn = toclipboard
		end
	end)
	return fn
end

-- Uppercase, with a literal space between every glyph: Roblox has no
-- letter-spacing property, so a wordmark is spelled out that way. Same helper
-- the titlebar and the splash use, and it's resolved once at load rather than
-- per page.
local WORDMARK = (function(): string
	local out = {}
	for _, c in utf8.codes(string.upper(BRAND)) do
		table.insert(out, utf8.char(c))
	end
	return table.concat(out, " ")
end)()

local function putIcon(parent: Instance, name: string, size: number, color: Color3): any
	local i: any = newIcon(name, size, color)
	i.AnchorPoint = Vector2.new(0.5, 0.5)
	i.Position = UDim2.fromScale(0.5, 0.5)
	i.Parent = parent
	return i
end

-- The page currently up, if any. A second call replaces the first — two stacked
-- failure pages is never the right answer, and the newer one is the truer one.
-- Cleared from `Destroying` as well as from `Close`, because the singleton sweep
-- destroys the ScreenGui out from under us without going through the handle.
local active: any = nil

return function(opts: any): any
	-- The caller's table is copied, never held: `Set` patches this copy, so a
	-- loader that reuses one options table across two pages doesn't find our
	-- edits in it afterwards (same rule components/Settings.lua follows).
	local o: any = {}
	if type(opts) == "table" then
		for key, value in opts :: any do
			o[key] = value
		end
	end

	if active then
		local previous = active
		active = nil
		previous:Close(true)
	end

	local dismissable = o.Dismissable ~= false
	local tone = toneOf(o.Tone)

	local screenGui = new("ScreenGui", {
		Name = gname(),
		DisplayOrder = ORDER,
		IgnoreGuiInset = true,
		ResetOnSpawn = false,
		ZIndexBehavior = Enum.ZIndexBehavior.Sibling,
	})

	-- A TextButton, not a Frame: it sinks every click, so a page over a live
	-- window (or over the game) is modal rather than decorative. `Modal = true`
	-- also unlocks the mouse in a game that captured it — without it a shift-lock
	-- title leaves the user looking at buttons they can't reach.
	local backdrop = new("TextButton", {
		Name = "Backdrop",
		AutoButtonColor = false,
		Modal = true,
		Text = "",
		Size = UDim2.fromScale(1, 1),
		BackgroundColor3 = C.chrome,
		BackgroundTransparency = DIM,
		BorderSizePixel = 0,
		Parent = screenGui,
	})

	--@lib
	-- The elevation under the card, same radial image and the same job as the
	-- window's: it's what stops a flat rectangle from reading as part of the
	-- backdrop. Sized off the card rather than a constant, because the card grows
	-- with its content (and shrinks with the entrance UIScale, which the shadow
	-- should follow rather than sit still through).
	--
	-- Library-only, and this is a deliberate quality-for-bytes trade rather than
	-- a design decision: the standalone build is ~1 KB off its ceiling and the
	-- brand mark is worth more there than a shadow that's mostly hidden by the
	-- backdrop dim anyway. If that build ever gets room back, this is the first
	-- thing to give it.
	local shadow = new("ImageLabel", {
		Name = "Shadow",
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.new(0.5, 0, 0.5, 6),
		Size = UDim2.fromOffset(CARD_W + SHADOW_PAD, SHADOW_PAD),
		BackgroundTransparency = 1,
		Image = "rbxassetid://1316045217", -- soft radial blur
		ImageColor3 = Color3.new(0, 0, 0),
		ImageTransparency = SHADOW_T,
		ScaleType = Enum.ScaleType.Stretch,
		ZIndex = 0,
		Parent = backdrop,
	})
	--@endlib

	-- Scale width + a max-size cap: 420px on anything desktop-shaped, and a
	-- proportion of the viewport once the screen is narrower than that.
	local card = new("Frame", {
		Name = "Card",
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromScale(0.5, 0.5),
		Size = UDim2.new(0.92, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		BackgroundColor3 = C.bg,
		ZIndex = 1,
		Parent = backdrop,
	}, {
		corner(RADIUS),
		stroke(C.border),
		list(),
		new("UISizeConstraint", { MaxSize = Vector2.new(CARD_W, math.huge) }),
	})
	local scale = new("UIScale", { Parent = card })
	--@lib
	card:GetPropertyChangedSignal("AbsoluteSize"):Connect(function()
		local size = card.AbsoluteSize
		shadow.Size = UDim2.fromOffset(size.X + SHADOW_PAD, size.Y + SHADOW_PAD)
	end)
	--@endlib

	-- ── titlebar: the mark, the wordmark, the close ──────────────────────────
	-- Chrome over the `bg` body, one hairline between them, top corners rounded
	-- to the card — the window's titlebar at dialog scale.
	local bar = new("Frame", {
		Name = "Titlebar",
		Size = UDim2.new(1, 0, 0, BAR),
		BackgroundColor3 = C.chrome,
		LayoutOrder = 1,
		Parent = card,
	}, {
		-- Only the TOP corners should round. A UICorner rounds all four, and the
		-- card clips to a rectangle rather than to its own rounded shape, so the
		-- square strip would otherwise poke past the card's corners. Window.lua
		-- squares the bottom off the same way.
		corner(RADIUS),
		new("Frame", {
			Name = "SquareFill",
			AnchorPoint = Vector2.new(0, 1),
			Position = UDim2.fromScale(0, 1),
			Size = UDim2.new(1, 0, 0, RADIUS),
			BackgroundColor3 = C.chrome,
			BorderSizePixel = 0,
		}),
		new("Frame", {
			Name = "Border",
			AnchorPoint = Vector2.new(0, 1),
			Position = UDim2.fromScale(0, 1),
			Size = UDim2.new(1, 0, 0, 1),
			BackgroundColor3 = C.border_soft,
			BorderSizePixel = 0,
		}),
	})

	-- The mark. Accent square + the brand initial is the backdrop and the art is
	-- drawn over it, never instead of it: `loadLogo` only ever *hides* the
	-- fallback, so a client with no art (every standalone one — no network) gets
	-- the square, and none of them gets a hole. The holder clips, which is what
	-- lets the library build crop the dead margin out of the shipped tile — and
	-- that tile's baked-in background is exactly `chrome`, which is the other
	-- reason the mark belongs on the titlebar rather than on the card: the crop
	-- edge disappears into the bar the same way it does in the window.
	local logo = new("Frame", {
		Name = "Logo",
		AnchorPoint = Vector2.new(0, 0.5),
		Position = UDim2.new(0, 14, 0.5, 0),
		Size = UDim2.fromOffset(LOGO, LOGO),
		BackgroundTransparency = 1,
		ClipsDescendants = true,
		Parent = bar,
	}, {
		corner(7),
	})
	-- The fallback is a MARK, not a letter. An accent square with a "U" in it is
	-- what a missing logo looks like, and it's what everyone without file access
	-- was looking at; Lucide's `atom` is a nucleus crossed by two elliptical
	-- orbits, which is the Uranium mark's own composition, and it's a spritesheet
	-- slice — a Roblox asset the engine fetches itself, so it needs no network of
	-- ours, no `getcustomasset`, and no executor at all. Tinted tile + accent
	-- glyph is the palette's own `accent_soft` pattern (same as the active nav).
	local logoSquare = new("Frame", {
		Name = "Square",
		Size = UDim2.fromScale(1, 1),
		BackgroundColor3 = C.accent_soft,
		BorderSizePixel = 0,
		Parent = logo,
	}, {
		corner(7),
	})
	local logoInitial = putIcon(logo, "atom", 16, C.accent)
	local logoImage = new("ImageLabel", {
		Name = "Mark",
		BackgroundTransparency = 1,
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromScale(0.5, 0.5),
		Size = UDim2.fromScale(1, 1),
		Image = "",
		-- Fit, not Crop: a brand mark must never lose an edge or change
		-- proportion. The zoom the prelude applies is what fills the holder.
		ScaleType = Enum.ScaleType.Fit,
		Parent = logo,
	})
	-- `Visible`, not transparency: this lands whenever the asset does, which can
	-- be mid-fade, and writing a transparency util/Fade.lua is driving strands
	-- the mark half-painted. `loaded = false` is not a failure state — it just
