	-- ── handle ───────────────────────────────────────────────────────────────
	local handle: any = {}
	handle.ScreenGui = screenGui
	handle.Card = card

	local fade = newFade(backdrop)
	local closing = false
	local conns: { RBXScriptConnection } = {}
	local flashToken = 0

	function handle:Close(immediate: boolean?)
		if closing then
			return
		end
		closing = true
		if active == handle then
			active = nil
		end
		if immediate then
			screenGui:Destroy()
			return
		end
		tw(scale, TW.MenuOut, { Scale = 0.96 })
		fade:To(TW.MenuOut, 1, function()
			screenGui:Destroy()
		end)
	end

	-- The Esc listener lives on UserInputService, so it outlives the tree — and
	-- the singleton sweep destroys the ScreenGui without going through `Close`.
	-- `Destroying` is the one signal that covers every way this page can go.
	screenGui.Destroying:Connect(function()
		closing = true
		if active == handle then
			active = nil
		end
		for _, conn in conns do
			conn:Disconnect()
		end
		table.clear(conns)
		fade:Destroy()
	end)

	function handle:Flash(text: any)
		local s = str(text)
		flash.Text = s or ""
		flash.Visible = s ~= nil
		if not s then
			flash.TextTransparency = 1
			return
		end
		flashToken += 1
		local token = flashToken
		tw(flash, TW.Fast, { TextTransparency = 0 })
		task.delay(3, function()
			if closing or token ~= flashToken then
				return
			end
			tw(flash, TW.Normal, { TextTransparency = 1 })
		end)
	end

	-- ── buttons ──────────────────────────────────────────────────────────────
	-- `parent` defaults to the action row; the submit button of an `Input` block
	-- borrows the same button rather than growing a second one.
	local function newButton(label: string, icon: string?, primary: boolean, onClick: () -> (), parent: any?): any
		local base = primary and C.accent_fill or C.control
		local over = primary and C.accent or C.control_hi
		local btn = new("TextButton", {
			Name = "Action",
			AutoButtonColor = false,
			AutomaticSize = Enum.AutomaticSize.X,
			Size = UDim2.fromOffset(0, 34),
			BackgroundColor3 = base,
			Text = "",
			Parent = parent or actions,
		}, {
			corner(8),
			pad(0, 14, 0, 14),
			-- Icon + label are laid out as a row rather than the icon being
			-- absolutely positioned into a wider left padding: a UIPadding shifts
			-- the button's CHILDREN too, so that gutter moved the glyph *and* the
			-- text by the same amount and the two drew on top of each other.
			list({
				FillDirection = Enum.FillDirection.Horizontal,
				HorizontalAlignment = Enum.HorizontalAlignment.Center,
				VerticalAlignment = Enum.VerticalAlignment.Center,
				Padding = UDim.new(0, 8),
			}),
			new("UISizeConstraint", { MinSize = Vector2.new(76, 34) }),
		})
		if icon then
			local bi: any = newIcon(icon, 14, primary and C.knockout or C.text_muted)
			bi.LayoutOrder = 1
			bi.Parent = btn
		end
		new("TextLabel", {
			Name = "Label",
			BackgroundTransparency = 1,
			AutomaticSize = Enum.AutomaticSize.X,
			Size = UDim2.fromOffset(0, 34),
			Text = label,
			TextColor3 = primary and C.knockout or C.text,
			TextSize = 13,
			FontFace = F.Medium,
			LayoutOrder = 2,
			Parent = btn,
		})
		-- The `busy` attribute is how a disabled button keeps its disabled fill:
		-- these closures own `base`/`over`, so nothing outside could otherwise stop
		-- a hover from painting a dead button as a live one.
		btn.MouseEnter:Connect(function()
			if btn:GetAttribute("busy") then
				return
			end
			tw(btn, TW.Fast, { BackgroundColor3 = over })
		end)
		btn.MouseLeave:Connect(function()
			if btn:GetAttribute("busy") then
				return
			end
			tw(btn, TW.Fast, { BackgroundColor3 = base })
		end)
		btn.Activated:Connect(onClick)
		return btn
	end

	-- ── the entry block ──────────────────────────────────────────────────────
	-- Built only when an `Input` option was passed, and never torn down again: a
	-- page without one has to be exactly the page it was before this existed, and
	-- `handle.Input` is the capability probe a caller uses to decide whether to
	-- fall back to a clipboard button, so its absence has to be load-bearing
	-- rather than incidental.
	--
	-- Everything the block needs lives in this closure. The only things reaching
	-- out of it are `inputBlock` (so `apply` can tell built from not) and
	-- `applyInput` (so `apply` can re-read the options over a live block).
	local INPUT_H = 34  -- the action buttons' height: the row has to read as one
	local MIN_BOX = 200 -- below this the box can't show a full key, so the button wraps
	local inputBlock: any = nil
	local applyInput: any = nil

	local function ensureInput()
		if inputBlock then
			return
		end
		local reader = clipboardFn()
		local submitFn: any, filterFn: any, maxLen: any, seenCfg: any = nil, nil, nil, nil
		local busy, guard, pasteOn, isError = false, false, false, false
		local estW = 76

		inputBlock = new("Frame", {
			Name = "Input",
			BackgroundTransparency = 1,
			Size = UDim2.new(1, 0, 0, 0),
			AutomaticSize = Enum.AutomaticSize.Y,
			LayoutOrder = 5,
			Parent = content,
		}, {
			list({ Padding = UDim.new(0, 6) }),
		})
		local capLabel = new("TextLabel", {
			Name = "Label",
			BackgroundTransparency = 1,
			Size = UDim2.new(1, 0, 0, 12),
			Text = "",
			TextColor3 = C.text_dim,
			TextSize = 10,
			FontFace = F.Medium,
			TextXAlignment = Enum.TextXAlignment.Left,
			Visible = false,
			LayoutOrder = 1,
			Parent = inputBlock,
		})

		-- The row lays itself out by hand (see relayout) rather than with a
		-- UIListLayout, because the wrap has to be decided on measured width.
		local row = new("Frame", {
			Name = "Row",
			BackgroundTransparency = 1,
			Size = UDim2.new(1, 0, 0, INPUT_H),
			LayoutOrder = 2,
			Parent = inputBlock,
		})
		local field = new("Frame", {
			Name = "Field",
			Size = UDim2.new(1, 0, 0, INPUT_H),
			BackgroundColor3 = C.control,
			Parent = row,
		}, {
			corner(8),
			stroke(C.border),
		})
		local fieldStroke: any = field:FindFirstChildOfClass("UIStroke")
		-- Mono, like the invite: what goes in here is a key, and a key is read
		-- character by character.
		local box = new("TextBox", {
			Name = "Box",
			BackgroundTransparency = 1,
			Position = UDim2.fromOffset(12, 0),
			Size = UDim2.new(1, -24, 1, 0),
			Text = "",
			PlaceholderText = "",
			PlaceholderColor3 = C.text_dim,
			TextColor3 = C.text,
			TextSize = 13,
			FontFace = F.Mono,
			TextXAlignment = Enum.TextXAlignment.Left,
			ClearTextOnFocus = false,
			ClipsDescendants = true,
			Parent = field,
		})
		local paste = new("TextButton", {
			Name = "Paste",
			AutoButtonColor = false,
			Text = "",
			AnchorPoint = Vector2.new(1, 0.5),
			Position = UDim2.new(1, -6, 0.5, 0),
			Size = UDim2.fromOffset(24, 24),
			BackgroundColor3 = C.control_hi,
			Visible = false,
			Parent = field,
		}, {
			corner(6),
		})
		local pasteIcon = putIcon(paste, "clipboard", 13, C.text_dim)

		local status = new("TextLabel", {
			Name = "Status",
			BackgroundTransparency = 1,
			Size = UDim2.new(1, 0, 0, 0),
			AutomaticSize = Enum.AutomaticSize.Y,
			Text = "",
			TextColor3 = C.danger,
			TextSize = 11,
			FontFace = F.Regular,
			TextXAlignment = Enum.TextXAlignment.Left,
			TextWrapped = true,
			Visible = false,
			LayoutOrder = 3,
			Parent = inputBlock,
		})

		-- `Filter` is the caller's code running on every keystroke, so it's pcalled
		-- and ignored unless it hands back a string. MaxLength clamps AFTER it, or a
		-- filter that expands its input (grouping dashes into a key) could push the
		-- value past the limit it was clamped to.
		local function clean(text: string): string
			local out = text
			if filterFn then
				local ok, filtered = pcall(filterFn, out)
				if ok and type(filtered) == "string" then
					out = filtered
				end
			end
			if maxLen and #out > maxLen then
				out = string.sub(out, 1, maxLen)
			end
			return out
		end

		-- Error and Success share one line — the second replaces the first — and an
		-- error clears itself as soon as the user edits, because a red line under a
		-- box they're already fixing is noise.
		local function setStatus(text: string?, bad: boolean)
			isError = text ~= nil and bad
			status.Text = text or ""
			status.TextColor3 = bad and C.danger or C.accent
			status.Visible = text ~= nil
		end

		-- Busy repaints with COLOURS, never transparency: transparency in this tree
		-- belongs to util/Fade.lua, and writing one it's driving is how a control
		-- ends up stuck half-visible after the next fade.
		local btn: any = nil
		local function paintBusy()
			box.TextEditable = not busy
			box.TextColor3 = busy and C.text_muted or C.text
			paste.Visible = pasteOn and not busy
			if btn then
				btn:SetAttribute("busy", busy)
				btn.BackgroundColor3 = busy and C.accent_dim or C.accent_fill
			end
		end

		local ui: any = {}

		-- An empty submit does nothing at all — no callback, and no error flash for
		-- something the user hasn't done yet.
		local function submit()
			if busy or closing or not submitFn then
				return
			end
			local value = box.Text
			if value == "" then
				return
			end
			-- Same contract as an Action's callback: it gets an object it can talk
			-- back through, and one that errors or yields can't take the page down.
			local fn = submitFn
			task.spawn(function()
				pcall(fn, value, ui)
			end)
		end

		btn = newButton("Continue", nil, true, submit, row)
		local btnLabel: any = btn:FindFirstChild("Label")

		-- The wrap is done by hand: `UIListLayout.Wraps` is a recent property and
		-- this is the file that has to run on whatever engine the client is on.
		-- The DECISION uses the button's estimated width, never its measured one —
		-- a stacked button is as wide as the row, so measuring would latch the
		-- layout into the stacked branch and never come back out of it.
		local function relayout()
			local w = row.AbsoluteSize.X
			if w > 0 and (w - estW - 8) < MIN_BOX then
				btn.AutomaticSize = Enum.AutomaticSize.None
				btn.AnchorPoint = Vector2.new(0, 0)
				btn.Position = UDim2.fromOffset(0, INPUT_H + 8)
				btn.Size = UDim2.new(1, 0, 0, INPUT_H)
				field.Size = UDim2.new(1, 0, 0, INPUT_H)
				row.Size = UDim2.new(1, 0, 0, INPUT_H * 2 + 8)
			else
				-- Measured only while it's auto-sizing, so the field never gets sized
				-- off a width the button is about to stop having.
				local bw = estW
				if btn.AutomaticSize == Enum.AutomaticSize.X and btn.AbsoluteSize.X > 0 then
					bw = btn.AbsoluteSize.X
				end
				btn.AutomaticSize = Enum.AutomaticSize.X
				btn.AnchorPoint = Vector2.new(1, 0)
				btn.Position = UDim2.new(1, 0, 0, 0)
				btn.Size = UDim2.fromOffset(0, INPUT_H)
				field.Size = UDim2.new(1, -(bw + 8), 0, INPUT_H)
				row.Size = UDim2.new(1, 0, 0, INPUT_H)
			end
		end

		function ui:Get(): string
			return box.Text
		end
		function ui:Set(value: any)
			-- Cleaned here and written under the guard, so the Text signal below
			-- doesn't filter it a second time. Coerced first: TextBox.Text refuses
			-- anything that isn't a string.
			local text = value == nil and "" or tostring(value)
			guard = true
			box.Text = clean(text)
			guard = false
		end
		function ui:Clear()
			ui:Set("")
		end
		function ui:Focus()
			if busy then
				return
			end
			pcall(function()
				box:CaptureFocus()
			end)
		end
		function ui:Busy(on: any)
			busy = on and true or false
			paintBusy()
			if busy then
				pcall(function()
					box:ReleaseFocus()
				end)
			end
		end
		-- An error never clears the box: someone who typed nineteen characters and
		-- got one wrong should be editing, not retyping. So it puts the caret back
		-- where they left it instead.
		function ui:Error(text: any)
			setStatus(str(text) or "That didn't work.", true)
			ui:Focus()
		end
		function ui:Success(text: any)
			setStatus(str(text), false)
		end

		box:GetPropertyChangedSignal("Text"):Connect(function()
			if guard then
				return
			end
			local filtered = clean(box.Text)
			if filtered ~= box.Text then
				-- Rewriting Text re-fires this signal synchronously; the guard skips
				-- that pass so the filter can't chase its own tail.
				guard = true
				box.Text = filtered
				guard = false
			end
			if isError then
				setStatus(nil, true)
			end
		end)
		box.Focused:Connect(function()
			tw(fieldStroke, TW.Fast, { Color = C.accent })
		end)
		box.FocusLost:Connect(function(enterPressed)
			tw(fieldStroke, TW.Fast, { Color = C.border })
			if enterPressed then
				submit()
			end
		end)

		paste.Activated:Connect(function()
			if busy or not reader then
				return
			end
			local ok, text = pcall(reader)
			if ok and type(text) == "string" and text ~= "" then
				ui:Set(text)
				submit()
			else
				handle:Flash("Nothing on the clipboard.")
			end
		end)
		paste.MouseEnter:Connect(function()
			tw(paste, TW.Fast, { BackgroundColor3 = C.pop })
			tintIcon(pasteIcon, C.text)
		end)
		paste.MouseLeave:Connect(function()
			tw(paste, TW.Fast, { BackgroundColor3 = C.control_hi })
			tintIcon(pasteIcon, C.text_dim)
		end)

		row:GetPropertyChangedSignal("AbsoluteSize"):Connect(relayout)
		btn:GetPropertyChangedSignal("AbsoluteSize"):Connect(relayout)

		applyInput = function(cfg: any)
			submitFn = type(cfg.Submit) == "function" and cfg.Submit or nil
			filterFn = type(cfg.Filter) == "function" and cfg.Filter or nil
			maxLen = nil
			if type(cfg.MaxLength) == "number" and cfg.MaxLength >= 1 then
				maxLen = math.floor(cfg.MaxLength)
			end

			local cap = str(cfg.Label)
			capLabel.Text = cap and string.upper(cap) or ""
			capLabel.Visible = cap ~= nil

			box.PlaceholderText = str(cfg.Placeholder) or ""

			local text = str(cfg.Button) or "Continue"
			btnLabel.Text = text
			estW = math.clamp(#text * 8 + 28, 76, 220)

			-- Where there's no clipboard function at all the affordance isn't drawn,
			-- rather than drawn and dead.
			pasteOn = cfg.Paste == true and reader ~= nil
			box.Size = UDim2.new(1, pasteOn and -48 or -24, 1, 0)
			paintBusy()

			-- `Value` lands only when the Input TABLE itself changed. `apply` re-reads
			-- every option on every patch, so a `Set{ Text = … }` — the gate
			-- rewording itself mid-attempt — would otherwise re-apply the original
			-- `Value = ""` over whatever the user has typed.
			if cfg ~= seenCfg then
				seenCfg = cfg
				local v = cfg.Value
				if type(v) == "string" or type(v) == "number" then
					ui:Set(v)
				end
			end
			relayout()
		end

		handle.Input = ui
	end

	-- Rebuilt rather than patched, so `Set{ Actions = … }` is the same code path
	-- as the initial build and can't drift from it.
	local function buildActions()
		for _, child in actions:GetChildren() do
			if child:IsA("GuiObject") then
				child:Destroy()
			end
		end
		local n = 0
		if type(o.Actions) == "table" then
			for _, def in o.Actions :: any do
				if type(def) == "table" then
					local closeAfter = def.Close ~= false
					local callback = type(def.Callback) == "function" and def.Callback or nil
					local btn = newButton(str(def.Label) or "OK", str(def.Icon), def.Primary == true, function()
						-- The handle is the argument, and a callback that errors
						-- (or yields) must not take the close with it.
						if callback then
							task.spawn(function()
								pcall(callback, handle)
							end)
						end
						if closeAfter then
							handle:Close()
						end
					end)
					n += 1
					btn.LayoutOrder = n
				end
			end
		end

		-- Discord is a first-class option, not something the caller assembles out
		-- of `Actions` — every caller wants the same button, after their own, and
		-- wants the confirmation wired to it.
		local invite = str(o.Discord)
		if invite then
			local only = n == 0
			n += 1
			local btn = newButton("Copy Discord", "message-circle", only, function()
				if copyText(invite) then
					handle:Flash("Copied " .. invite)
				else
					handle:Flash("No clipboard here — select the invite above.")
				end
			end)
			btn.LayoutOrder = n
		end
		actions.Visible = n > 0
	end

	-- ── options → screen ─────────────────────────────────────────────────────
	-- One function for the initial build and for `Set`, so a patched page and a
	-- freshly built one can never disagree about what an option means.
	local function apply(patch: any?)
		if patch ~= nil then
			if type(patch) ~= "table" then
				return
			end
			for key, value in patch :: any do
				o[key] = value
			end
		end

		dismissable = o.Dismissable ~= false
		closeBtn.Visible = dismissable

		tone = toneOf(o.Tone)
		chip.BackgroundColor3 = C.bg:Lerp(tone, 0.18)
		rule.BackgroundColor3 = tone

		-- `newIcon` hands back an ImageLabel for a name it knows and a glyph
		-- TextLabel for one it doesn't, so a *changed* name is a rebuild rather
		-- than a property write that would be wrong half the time.
		local nextIcon = str(o.Icon) or "triangle-alert"
		if nextIcon ~= iconName then
			iconName = nextIcon
			iconInst:Destroy()
			iconInst = putIcon(chip, iconName, 18, tone)
		else
			tintIcon(iconInst, tone)
		end

		title.Text = str(o.Title) or "Something went wrong"

		local code = str(o.Code)
		codeLabel.Text = code or ""
		codeLabel.Visible = code ~= nil

		local text = str(o.Text)
		body.Text = text or ""
		body.Visible = text ~= nil

		-- Built on the first apply that sees an `Input`, patched on every one
		-- after. Dropping the option later only hides the block — `handle.Input`
		-- stays valid, because a caller holding it shouldn't have it turn into a
		-- nil index underneath them.
		if type(o.Input) == "table" then
			ensureInput()
			applyInput(o.Input)
		elseif inputBlock then
			inputBlock.Visible = false
		end

		local invite = str(o.Discord)
		inviteBox.Text = invite or ""
		inviteRow.Visible = invite ~= nil

		local foot = str(o.Footer)
		footer.Text = foot or ""
		footer.Visible = foot ~= nil
		footerRule.Visible = foot ~= nil

		--@lib
		local detail = str(o.Detail)
		detailText.Text = detail or ""
		detailToggle.Visible = detail ~= nil
		if detail == nil then
			detailOpen = false
			detailBox.Visible = false
		end
		--@endlib

		buildActions()
	end

	function handle:Set(patch: any)
		if closing then
			return
		end
		apply(patch or {})
	end

	--@lib
	detailToggle.Activated:Connect(function()
		detailOpen = not detailOpen
		detailBox.Visible = detailOpen
		tw(detailChev, TW.Normal, { Rotation = detailOpen and 0 or -90 })
	end)
	detailCopy.Activated:Connect(function()
		if copyText(detailText.Text) then
			handle:Flash("Details copied")
		else
			handle:Flash("No clipboard here — select the text instead.")
		end
	end)
	detailCopy.MouseEnter:Connect(function()
		tw(detailCopy, TW.Fast, { BackgroundColor3 = C.pop })
	end)
	detailCopy.MouseLeave:Connect(function()
		tw(detailCopy, TW.Fast, { BackgroundColor3 = C.control_hi })
	end)
	--@endlib

	closeBtn.Activated:Connect(function()
		if dismissable then
			handle:Close()
		end
	end)

	-- `Dismissable = false` means the only way out is re-running the loader.
	-- That's the point for a ban: read it, then get a new loadstring.
	--
	-- Guarded on UIS existing at all: the standalone build resolves its own
	-- services and hands back nil rather than throwing if one won't resolve, and
	-- losing the Esc shortcut is a far better outcome than losing the page.
	--
	-- With an `Input` block focused, the first Escape is the engine's — it
	-- releases text capture and arrives here `gameProcessed`, so the page closes
	-- on the second press. That's deliberate: taking Escape off the guard would
	-- mean a game that consumes it closes the page out from under itself.
	if UIS then
		table.insert(conns, UIS.InputBegan:Connect(function(input, gameProcessed)
			if gameProcessed or not dismissable or closing then
				return
			end
			if input.KeyCode == Enum.KeyCode.Escape then
				handle:Close()
			end
		end))
	end

	-- Fill it in BEFORE the fade snapshots the tree, or a row hidden by `apply`
	-- would be caught in the snapshot at its built transparency and revealed by
	-- the entrance (see util/Fade.lua — hidden subtrees are pruned).
	apply(nil)
	mountGui(screenGui, typeof(o.Parent) == "Instance" and o.Parent or nil)

	fade:Set(1)
	scale.Scale = 0.94
	tw(scale, TW.Pop, { Scale = 1 })
	fade:To(TW.Normal, 0)

	active = handle
	return handle
end

end

__modules['components.Section'] = function(...)
--!strict
-- components/Section.lua — a nested collapsible group (indented, left rule).
-- Returns the section frame plus the inner body that controls mount into.

local Create = __require("util.Create")
local Theme = __require("Theme")
local Tween = __require("util.Tween")
local Icons = __require("Icons")
local Collapse = __require("util.Collapse")

return function(ctx: any, opts: any): (Frame, Frame)
	local colors = Theme.Colors
	local collapsed = opts.Collapsed == true

	local section = Create("Frame", {
		Name = "Section",
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
	}, {
		Create.listLayout({}),
	})

	-- No UIListLayout on the header: a layout-managed child won't render its
	-- Rotation, so the chevron is positioned manually to keep it free to spin.
	local head = Create("TextButton", {
		Name = "Head",
		AutoButtonColor = false,
		Text = "",
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		LayoutOrder = 1,
		Parent = section,
	}, {
		Create.padding(9, 2),
	})

	Create("TextLabel", {
		Name = "Title",
		BackgroundTransparency = 1,
		AutomaticSize = Enum.AutomaticSize.Y,
		Size = UDim2.new(1, -18, 0, 0), -- leaves room for the chevron flush right
		Text = opts.Title or "Section",
		TextColor3 = colors.text,
		TextSize = 13,
		FontFace = Theme.Font.Medium,
		TextXAlignment = Enum.TextXAlignment.Left,
		Parent = head,
	})

	local chevron = Icons.new("chev", 14, colors.text_dim)
	chevron.AnchorPoint = Vector2.new(1, 0.5)
	chevron.Position = UDim2.new(1, 0, 0.5, 0)
	chevron.Rotation = collapsed and 180 or 0;
	(chevron :: any).Parent = head

	local bodyWrap = Create("Frame", {
		Name = "BodyWrap",
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
	})

	local body = Create("Frame", {
		Name = "Body",
		BackgroundTransparency = 1,
		Position = UDim2.fromOffset(14, 0),
		Size = UDim2.new(1, -14, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		Parent = bodyWrap,
	}, {
		Create.padding(1, 0, 8, 0),
		Create.listLayout({}),
	})

	-- Left rule. Scale height (1,0 on Y) fills bodyWrap natively; scale-sized
	-- children are ignored by AutomaticSize, so the rule can't feed back into
	-- bodyWrap's height and cause AbsoluteSizeChanged re-entrancy.
	Create("Frame", {
		Name = "Rule",
		Position = UDim2.fromOffset(2, 1),
		Size = UDim2.new(0, 1, 1, 0),
		BackgroundColor3 = colors.border,
		BorderSizePixel = 0,
		Parent = bodyWrap,
	})

	-- Clipping holder owns the body's height so it slides open/closed.
	local holder, setCollapsed = Collapse.wrap(bodyWrap, collapsed)
	holder.LayoutOrder = 2
	holder.Parent = section

	head.Activated:Connect(function()
		collapsed = not collapsed
		Tween.play(chevron, Tween.Spin, { Rotation = collapsed and 180 or 0 })
		setCollapsed(collapsed, true)
	end)

	return section, body
end

end

__modules['components.Settings'] = function(...)
--!strict
-- components/Settings.lua — the built-in settings panel, as three INDEPENDENT
-- group builders rather than one sealed tab.
--
-- `Window:CreateSettingsTab` composes all three (that's still the one-line
-- drop-in), but the panel used to be all-or-nothing: a host with its own config
-- UI got the library's Configuration group whether it wanted it or not, couldn't
-- switch it off, and couldn't even fake it off — the group tested util/Config.lua's
-- own `supported` flag rather than the public `window.ConfigSupported`. So:
--
--   * `CreateSettingsTab{ Sections = { Config = false } }` drops a section, and
--   * every builder here is public (`Uranium.Settings.ConfigGroup(window, tab)`),
--     so a host can compose its own settings tab out of the parts it likes and
--     put its own controls in between.
--
-- Everything below goes through the PUBLIC window API — nothing reaches into the
-- Context, the flag registry or util/Config.lua directly. That's deliberate: it's
-- the proof that a host can build the same panel, and it means the auto-load
-- pointer (the one config path that used to bypass `window:`) is interceptable
-- like every other.

local Theme = __require("Theme")
local Log = __require("util.Log")
local Signal = __require("util.Signal")

local Settings = {}

-- Toasts, unless the caller said not to. A host that wraps the window's config
-- methods to add its own rules (per-place scoping, say) already tells the user
-- why a load was refused; the panel piling a generic "Couldn't load X" on top of
-- that is noise it had no way to suppress.
local function notifier(window: any, opts: any): (string) -> ()
	local enabled = not (opts and opts.Notify == false)
	return function(text: string)
		if enabled then
			window:Notify({ Title = "Config", Text = text })
		end
	end
end

-- "Couldn't load "x" — corrupt JSON." out of the `(ok, reason)` pair.
local function because(text: string, reason: string?): string
	if type(reason) == "string" and reason ~= "" then
		return ("%s — %s."):format(text, reason)
	end
	return text .. "."
end

local function group(tab: any, opts: any, title: string, column: number): any
	if opts.Group then
		return opts.Group
	end
	return tab:CreateGroup({ Title = opts.Title or title, Column = opts.Column or column })
end

-- ── Interface ────────────────────────────────────────────────────────────────
-- Accent colour, the toggle keybind, notifications, the bind HUD switch.
-- Returns `{ Group, Accent, ToggleKey, Notifications, Hud }`.
function Settings.InterfaceGroup(window: any, tab: any, opts: any?): any
	local o: any = opts or {}
	local g = group(tab, o, "Interface", 1)
	local controls: any = { Group = g }

	controls.Accent = g:Colorpicker({
		Name = "Accent Color",
		Desc = "Re-themes the whole UI.",
		Flag = o.AccentFlag or "uranium_accent",
		Default = window:GetAccent(),
		Callback = function(c)
			window:SetAccent(c)
		end,
	})
	controls.ToggleKey = g:Keybind({
		Name = "Toggle UI",
		Desc = "Show or hide the window.",
		Flag = o.ToggleKeyFlag or "uranium_togglekey",
		Default = window:GetToggleKey(),
		Callback = function(k)
			window:SetToggleKey(k)
		end,
	})
	-- `Hud = false` on the switches below: they're preferences about the UI, not
	-- features running in the game, and the bind HUD lists what's running. Left to
	-- the default rule they'd all qualify — a keyless toggle that's ON is listed —
	-- so every user would open the panel to find "Notifications" and, absurdly,
	-- "Keybind HUD" at the top of it.
	controls.Notifications = g:Toggle({
		Name = "Notifications",
		Desc = "Show toast notifications.",
		Flag = o.NotificationsFlag or "uranium_notifications",
		Default = window:GetNotificationsEnabled(),
		Hud = false,
		Callback = function(on)
			window:SetNotificationsEnabled(on)
		end,
	})

	-- The bind HUD switch. Deliberately NOT flagged itself: the HUD is the source
	-- of truth (it also persists its position and collapsed state), and two flags
	-- for one thing would fight each other on load. Instead the flag below proxies
	-- to the HUD — built on demand, so a config that has it off never creates one —
	-- and the switch mirrors whatever the HUD ends up at. Both directions no-op
	-- when already in step, so the sync can't loop.
	local hud = window:GetHud()
	local hudSwitch = g:Toggle({
		Name = "Keybind HUD",
		Desc = "Floating panel: active binds, FPS and ping.",
		Default = hud ~= nil and hud:IsVisible(),
		Hud = false,
		Callback = function(on)
			local live = window:GetHud()
			if live and live:IsVisible() == on then
				return
			end
			window:SetHudVisible(on)
		end,
	})
	controls.Hud = hudSwitch
	-- Fires once immediately with the HUD's current state, so the switch is in
	-- step even if the HUD moved between being built and this tab existing.
	controls.HudMirror = window:OnHudVisible(function(value: boolean)
		if hudSwitch:Get() ~= value then
			hudSwitch:Set(value)
		end
	end)
	local hudFlag = o.HudFlag or "uranium_hud"
	window:RegisterFlag(hudFlag, {
		GetFlag = function(): any
			local live = window:GetHud()
			return live and live:GetFlag() or { Visible = false }
		end,
		SetFlag = function(_, value: any)
			if type(value) ~= "table" then
				return
			end
			if value.Visible == true then
				window:CreateHud():SetFlag(value)
			else
				local live = window:GetHud()
				if live then
					live:SetFlag(value)
				end
			end
		end,
	}, "hud")
	-- The HUD's state moves with the mouse, so nothing in the flag system hears
	-- about it on its own — a host persisting on change (`Window:OnFlagChanged`)
	-- would miss a dragged or folded HUD entirely. This is the one flag whose
	-- change notification has to be wired by whoever registered it.
	controls.HudChanges = window:OnHudChanged(function()
		window:NotifyFlag(hudFlag)
	end)

	return controls
end

-- ── Configuration ────────────────────────────────────────────────────────────
-- Save / load / delete + the auto-load pointer. Returns
-- `{ Group, Name, List, AutoLoad, Refresh, Save, Load, Delete }` — the handles
-- used to be locals in a closure, so a host couldn't refresh the list after its
-- own write, read what was selected, or hang its own button off the selection.
--
-- `Notify = false` silences the panel's own toasts. A host wrapping
-- `window:LoadConfig` can also return `false, "handled"` from its wrapper to
-- suppress the failure toast for one call while keeping the rest.
function Settings.ConfigGroup(window: any, tab: any, opts: any?): any
	local o: any = opts or {}
	local g = group(tab, o, "Configuration", 2)
	local controls: any = { Group = g }
	local say = notifier(window, o)

	-- The PUBLIC flag, not util/Config.lua's own — a host that wants the library's
	-- config UI to stand down (because it owns persistence itself) can set
	-- `window.ConfigSupported = false` and get the same honest "unavailable" panel
	-- an executor without file access gets.
	if not window.ConfigSupported then
		controls.Unavailable = g:Paragraph({
			Title = "Unavailable",
			Body = o.UnavailableText
				or "Your executor doesn't expose file functions, so configs can't "
					.. "be saved. Everything else here still works.",
		})
		-- There's no dropdown on this panel, so nothing can ever be picked — but a
		-- host subscribing unconditionally shouldn't index nil for it.
		controls.OnSelect = function(_fn: (string?) -> ()): () -> ()
			return function() end
		end
		return controls
	end

	local nameBox = g:Input({ Name = "Config Name", Placeholder = "my config" })
	local list: any
	local autoSwitch: any

	-- Picking a saved config fills the name box with it, so the obvious gesture —
	-- pick "main", press Save — overwrites the config you just picked instead of
	-- silently writing a second one under whatever stale text the box still held.
	-- `filled` is the name WE last put there: anything else in the box is the
	-- user's own typing and is never clobbered. Clearing the selection clears
	-- nothing, for the same reason.
	local filled: string? = nil
	local function prefill(name: string?)
		if name == nil or name == "" then
			return
		end
		local cur = nameBox:Get()
		-- `cur == name` adopts a name the user typed and then saved (`save` re-selects
		-- it), so the pick after that one is fillable again.
		if cur == nil or cur == "" or cur == filled or cur == name then
			filled = name
			nameBox:Set(name)
		end
	end

	-- The selection as a signal. A host whose list isn't a flat set of local file
	-- names — Uranium itself lists other games' configs as "main - Some Game" —
	-- has to substitute the real name after a pick, and could only do that by
	-- polling `List:Get()`: `controls` handed back the box and the dropdown but no
	-- event. A watcher that writes the box wins over the prefill above, and what it
	-- wrote becomes the new `filled`, so the next pick isn't mistaken for typing.
	local watchers = Signal.new() :: any
	local lastPick: string? = nil
	local function fireSelect(name: string?)
		if watchers:Count() == 0 then
			return
		end
		local before = nameBox:Get()
		-- Guarded: a host's bookkeeping blowing up doesn't take the pick down with
		-- it, same contract as OnFlagChanged's watchers.
		watchers:FireGuarded(function(err)
			Log.warn("Settings.OnSelect", tostring(err))
		end, name)
		local after = nameBox:Get()
		if after ~= before then
			filled = after
		end
	end

	-- Auto Load points at whatever is selected NOW. It used to be written only
	-- from the switch's own callback, so picking a different config afterwards
	-- left the pointer on the old one — and flipping the switch on with nothing
	-- selected wrote nil, silently clearing it while the switch read "on".
	local function syncAutoload()
		if not autoSwitch then
			return
		end
		local on = autoSwitch:Get()
		local name = list:Get()
		if on and (name == nil or name == "") then
			window:SetAutoload(nil)
			autoSwitch:Set(false) -- re-enters here with `on` false; terminates
			say("Pick a config to auto-load first.")
			return
		end
		window:SetAutoload(on and name or nil)
	end

	-- The dropdown's one callback: fill the name box, point auto-load at the new
	-- selection, then tell the host. Deduped against the last name we announced, so
	-- the `list:Set` in `save` (and in the auto-load pass) is silent when it lands
	-- on what's already picked.
	local function picked(name: string?)
		prefill(name)
		syncAutoload()
		if name == lastPick then
			return
		end
		lastPick = name
		fireSelect(name)
	end

	list = g:Dropdown({
		Name = "Saved Configs",
		Placeholder = "None saved",
		Stack = true,
		Options = window:ListConfigs(),
		Callback = picked,
	})
	local function refresh()
		list:SetOptions(window:ListConfigs())
	end
	-- Re-scoping persistence (window:SetConfigFolder — per-place folders, profiles)
	-- makes this list a different folder's; it fires once immediately, which is a
	-- harmless second read of the list we just built.
	controls.FolderWatch = window:OnConfigFolder(function()
		refresh()
	end)

	local function save()
		local n = nameBox:Get()
		if n == nil or n == "" then
			say("Enter a name first.")
			return
		end
		local ok, reason = window:SaveConfig(n)
		if ok then
			refresh()
			list:Set(n)
			say(('Saved "%s".'):format(n))
		elseif reason ~= "handled" then
			say(because(('Couldn\'t save "%s"'):format(n), reason))
		end
	end

	local function load()
		local n = list:Get()
		if not n then
			say("Pick a config to load.")
			return
		end
		local ok, reason = window:LoadConfig(n)
		if ok then
			say(('Loaded "%s".'):format(n))
		elseif reason ~= "handled" then
			-- Saying nothing on failure made a missing or corrupt file look like a
			-- dead button; saying only "Couldn't load" made it look like a bug. The
			-- reason comes straight off the (ok, reason) pair.
			say(because(('Couldn\'t load "%s"'):format(n), reason))
		end
	end

	local function remove()
		local n = list:Get()
		if not n then
			say("Pick a config to delete.")
			return
		end
		local deleted, reason = window:DeleteConfig(n)
		refresh()
		if deleted then
			say(('Deleted "%s".'):format(n))
		elseif reason ~= "handled" then
			say(because(('Couldn\'t delete "%s"'):format(n), reason))
		end
	end

	g:ButtonRow({
		{ Label = "Save", Callback = save },
		{ Label = "Load", Callback = load },
	})
	g:ButtonRow({
		{ Label = "Delete", Callback = remove },
		{ Label = "Refresh", Callback = refresh },
	})
	autoSwitch = g:Toggle({
		Name = "Auto Load",
		Desc = "Apply the selected config on launch.",
		Default = window:GetAutoload() ~= nil,
		Hud = false, -- a config preference, not a feature (see InterfaceGroup)
		Callback = syncAutoload,
	})

	controls.Name = nameBox
	controls.List = list
	controls.AutoLoad = autoSwitch
	-- `fn(name)` on every selection change, `nil` when the selection is dropped.
	-- No initial call — there's nothing selected when this returns. Returns an
	-- unsubscribe, like the window's own watchers.
	controls.OnSelect = function(fn: (string?) -> ()): () -> ()
		return watchers:Connect(fn)
	end
	controls.Refresh = refresh
	controls.Save = save
	controls.Load = load
	controls.Delete = remove

	-- Apply the auto-load config once the rest of the UI has finished building
	-- (this tab is meant to be created last, so all flags exist). `AutoLoad = false`
	-- opts out for a host that decides itself what to apply on boot.
	if o.AutoLoad ~= false then
		task.defer(function()
			local auto = window:GetAutoload()
			if auto then
				list:Set(auto)
				window:LoadConfig(auto)
			end
		end)
	end

	return controls
end

-- ── Danger Zone ──────────────────────────────────────────────────────────────
-- Pass `Group` (the Configuration group) to append into it behind a divider,
-- which is where it has always lived; without one it gets its own card, so a tab
-- built with `Sections = { Config = false }` still has an unload button.
function Settings.DangerGroup(window: any, tab: any, opts: any?): any
	local o: any = opts or {}
	local inline = o.Group ~= nil
	local g = group(tab, o, "Danger Zone", 2)
	local controls: any = { Group = g }
	if inline then
		g:Divider()
	end
	controls.Unload = g:Button({
		Name = inline and "Danger Zone" or nil,
		Label = o.Label or ("Unload " .. Theme.Brand.name),
		Callback = function()
			window:Destroy()
		end,
	})
	return controls
end

-- ── the whole panel ──────────────────────────────────────────────────────────
-- What `Window:CreateSettingsTab` calls. `opts.Sections` switches sections off
-- individually (`{ Config = false }`); everything else is forwarded to the
-- builders. Returns the flat control table the tab hands back alongside itself.
function Settings.build(window: any, tab: any, opts: any?): any
	local o: any = opts or {}
	local sections: any = o.Sections or {}
	if type(sections) ~= "table" then
		Log.warn("CreateSettingsTab", ("Sections must be a table like { Config = false }, got %s"
			.. " — building all of them."):format(typeof(sections)))
		sections = {}
	end
	local controls: any = {}

	-- Copied, never edited in place: `o.Config` / `o.Danger` are the caller's own
	-- tables, and a loader that reuses one options table across two windows
	-- shouldn't find our defaults baked into it afterwards.
	local function sub(key: string): any
		local out: any = {}
		if type(o[key]) == "table" then
			for k, v in o[key] :: any do
				out[k] = v
			end
		end
		return out
	end

	if sections.Interface ~= false then
		local iface = Settings.InterfaceGroup(window, tab, sub("Interface"))
		controls.Interface = iface.Group
		controls.Accent = iface.Accent
		controls.ToggleKey = iface.ToggleKey
		controls.Notifications = iface.Notifications
		controls.Hud = iface.Hud
		-- Carried through for the same reason as the config group's below: a host
		-- that tears its own settings UI down needs the unsubscribers, and there is
		-- no second way to reach them once this returns.
		controls.HudMirror = iface.HudMirror
		controls.HudChanges = iface.HudChanges
	end

	local cfgGroup: any = nil
	if sections.Config ~= false then
		local cfgOpts: any = sub("Config")
		if cfgOpts.Notify == nil then
			cfgOpts.Notify = o.Notify -- `CreateSettingsTab{ Notify = false }` covers the panel
		end
		local cfg = Settings.ConfigGroup(window, tab, cfgOpts)
		cfgGroup = cfg.Group
		controls.Configuration = cfg.Group
		controls.Name = cfg.Name
		controls.List = cfg.List
		controls.AutoLoad = cfg.AutoLoad
		controls.Refresh = cfg.Refresh
		controls.Save = cfg.Save
		controls.Load = cfg.Load
		controls.Delete = cfg.Delete
		-- The selection event, and the unsubscriber for the folder watch. These
		-- were built by ConfigGroup and then dropped on the floor here, which made
		-- `OnSelect` — a documented part of what CreateSettingsTab hands back, and
		-- the only way to correct the name box for a list whose entries aren't file
		-- names — a nil index for everyone who reached it the documented way. The
		-- ConfigSupported = false branch returns a no-op OnSelect for the same
		-- reason, so this is never nil.
		controls.OnSelect = cfg.OnSelect
		controls.FolderWatch = cfg.FolderWatch
	end

	if sections.Danger ~= false then
		local dangerOpts: any = sub("Danger")
		if dangerOpts.Group == nil then
			dangerOpts.Group = cfgGroup -- nil when Config is off → its own card
		end
		local danger = Settings.DangerGroup(window, tab, dangerOpts)
		controls.Danger = danger.Group
		controls.Unload = danger.Unload
	end

	return controls
end

return Settings

end

__modules['components.Slider'] = function(...)
--!strict
-- components/Slider.lua — 6px pill track, accent fill, 15px white knob.
-- Live drag via UserInputService (no tween), clamped + stepped.

local Services = __require("util.Services")

local UserInputService = Services.UserInputService

local Create = __require("util.Create")
local Theme = __require("Theme")
local Tween = __require("util.Tween")
local Log = __require("util.Log")
local Field = __require("components.Field")

local function clamp(v: number, a: number, b: number): number
	return math.max(a, math.min(b, v))
end

local function format(v: number, suffix: string): string
	return ("%g"):format(v) .. suffix
end

local SCHEMA: Log.Schema = {
	{ "Min", "number" },
	{ "Max", "number" },
	{ "Step", "number" },
}

return function(ctx: any, opts: any)
	local colors = Theme.Colors
	local where = Log.where("Slider", opts.Name)
	Log.check(where, opts, SCHEMA)

	local min = opts.Min or 0
	local max = opts.Max or 100
	-- An inverted or collapsed range makes every position map to the same value
	-- (render()/snap() guard the maths, but the control would be dead). Warn and
	-- fall back to a sane [min, min+1] so it's at least usable.
	if min >= max then
		Log.warn(where, ("Min (%s) must be less than Max (%s) — using [%s, %s]."):format(
			("%g"):format(min), ("%g"):format(max), ("%g"):format(min), ("%g"):format(min + 1)))
		max = min + 1
	end
	local step = opts.Step or 1
	if step < 0 then
		Log.warn(where, ("Step (%s) can't be negative — using 1."):format(("%g"):format(step)))
		step = 1
	end
	local suffix = opts.Suffix or ""

	local function snap(v: number): number
		-- guard a zero step so a bad config can't divide-by-zero. (Explicit if,
		-- not `and/or` — the snapped value can legitimately be 0, which the idiom
		-- would mistake for false and fall through to v.)
		-- Steps are counted from min, not from zero: quantizing in absolute value
		-- space means a range like Min=1, Max=10, Step=2 lands on 2/4/6/8/10 and
		-- can never produce 1, so the slider couldn't report its own minimum.
		if step > 0 then
			return min + math.round((v - min) / step) * step
		end
		return v
	end

	-- The default is snapped as well as clamped, or the control opens showing a
	-- value it can't otherwise produce (and hands that value to :Get()/the config
	-- snapshot) until the first drag quietly moves it onto the grid.
	local value = clamp(snap(opts.Default or min), min, max)

	local f = Field.new(ctx, opts, true)

	local valBox = Create("TextLabel", {
		Name = "Value",
		AutomaticSize = Enum.AutomaticSize.X,
		Size = UDim2.fromOffset(38, 22),
		BackgroundColor3 = colors.control,
		Text = format(value, suffix),
		TextColor3 = colors.text_muted,
		TextSize = 12,
		FontFace = Theme.Font.Medium,
		LayoutOrder = 2,
		Parent = f.row,
	}, {
		Create.corner(6),
		Create.stroke(colors.border),
		Create.padding(2, 9),
		Create("UISizeConstraint", { MinSize = Vector2.new(38, 22) }),
	})

	-- The grab area is 18px tall and transparent; the visible 6px rail is centered
	-- inside it. A 6px-tall button is a genuinely hard target to hit with a mouse
	-- (and near-impossible on touch), which is what made the slider feel broken.
	local track = Create("TextButton", {
		Name = "Slider",
		AutoButtonColor = false,
		Text = "",
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 18),
		LayoutOrder = 2,
		Parent = f.field,
	})

	local rail = Create("Frame", {
		Name = "Rail",
		AnchorPoint = Vector2.new(0, 0.5),
		Position = UDim2.fromScale(0, 0.5),
		Size = UDim2.new(1, 0, 0, 6),
		BackgroundColor3 = colors.toggle_off,
		Parent = track,
	}, {
		Create.corner(999),
	})

	local fill = Create("Frame", {
		Name = "Fill",
		Size = UDim2.fromScale(0, 1),
		BackgroundColor3 = ctx.Accent,
		Parent = rail,
	}, {
		Create.corner(999),
	})

	local knob = Create("Frame", {
		Name = "Knob",
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromScale(0, 0.5),
		Size = UDim2.fromOffset(15, 15),
		-- Text (not knockout): at value 0 the knob sits off the accent fill, on
		-- the bare rail, where a knockout-dark knob would disappear.
		BackgroundColor3 = colors.text,
		ZIndex = 2,
		Parent = rail,
	}, {
		Create.corner(999),
		Create("UIScale", {}),
	})
	local knobScale = knob:FindFirstChildOfClass("UIScale") :: UIScale

	local function render()
		-- guard min==max (degenerate range) so the ratio never produces NaN
		local span = max - min
		local pct = span ~= 0 and (value - min) / span or 0
		fill.Size = UDim2.fromScale(pct, 1)
		knob.Position = UDim2.fromScale(pct, 0.5)
		valBox.Text = format(value, suffix)
	end

	-- Drag is the only caller, so the whole body is user-driven — tagged for
	-- Context:OnFlagChanged, which is how a host tells a slider someone dragged
	-- from one a script moved.
	local function setFromX(x: number)
		local span = rail.AbsoluteSize.X
		local pct = span > 0 and clamp((x - rail.AbsolutePosition.X) / span, 0, 1) or 0
		local target = clamp(snap(min + pct * (max - min)), min, max)
		-- The mouse moves ~60 times a second and the value is quantized to `step`,
		-- so most of those frames land on the value we're already at. Firing anyway
		-- meant dragging a plain 0–100 slider one notch handed the consumer's
		-- callback a few dozen identical values — and the consumer is game code
		-- doing real work per call (a tween, a remote, a property write on every
		-- part it manages). Nothing downstream can tell those apart from a genuine
		-- change, so the filter belongs here.
		if target == value then
			return
		end
		value = target
		render()
		if opts.Callback then
			ctx:User(task.spawn, opts.Callback, value)
		end
	end

	-- The move/release listeners are global (UserInputService), so they're only
	-- connected for the duration of a drag and torn down on release. That avoids
	-- N idle sliders each leaking a permanent listener that fires on every mouse
	-- move and survives Window:Destroy.
	local dragConns: { RBXScriptConnection } = {}
	local function endDrag()
		for _, c in dragConns do
			c:Disconnect()
		end
		table.clear(dragConns)
		Tween.play(knobScale, Tween.Spring, { Scale = 1 }) -- settle back on release
	end
	-- The move/release pair lives on UserInputService, which outlives the tree the
	-- slider is in: unloading the window (or a config swapping a tab out) mid-drag
	-- left them connected forever, running setFromX against a destroyed rail on
	-- every mouse move for the rest of the session. Releasing the button is the
	-- normal exit; this is the one that can't be relied on to happen.
	track.Destroying:Connect(endDrag)
	track.InputBegan:Connect(function(input)
		if input.UserInputType == Enum.UserInputType.MouseButton1
			or input.UserInputType == Enum.UserInputType.Touch then
			if #dragConns > 0 then
				return
			end
			Tween.play(knobScale, Tween.Spring, { Scale = 1.3 }) -- grow while grabbed
			setFromX(input.Position.X)
			table.insert(dragConns, UserInputService.InputChanged:Connect(function(move)
				if move.UserInputType == Enum.UserInputType.MouseMovement
					or move.UserInputType == Enum.UserInputType.Touch then
					setFromX(move.Position.X)
				end
			end))
			table.insert(dragConns, UserInputService.InputEnded:Connect(function(up)
				if up.UserInputType == Enum.UserInputType.MouseButton1
					or up.UserInputType == Enum.UserInputType.Touch then
					endDrag()
				end
			end))
		end
	end)

	ctx:RegisterAccent(function(accent)
		fill.BackgroundColor3 = accent
	end)
	render()

	local handle = {}
	function handle:Get(): number
		return value
	end
	function handle:Set(v: number)
		value = clamp(snap(v), min, max)
		render()
		if opts.Callback then
			task.spawn(opts.Callback, value)
		end
	end

	return f.field, handle, true
end

end

__modules['components.Splash'] = function(...)
--!strict
-- components/Splash.lua — the boot screen. A dimmed backdrop with the brand mark,
-- the wordmark, a status line and a progress bar, played once before the window
-- itself appears (`CreateWindow{ Splash = true }`).
--
-- It's deliberately small: no gradients, no glow, no spinner — the palette rules
-- apply here too. The whole effect is a 4-beat stagger in, a bar that fills for
-- the rest of the budget, then a fade out. `onDone` fires as the fade *starts*,
-- not after it, so the window pops in behind the dim and the two cross-fade
-- instead of the screen blinking empty between them.
--
-- Two structural rules, both about keeping the type sharp:
--   * No CanvasGroup anywhere — it would rasterize the wordmark into a buffer
--     and blur it (see util/Fade.lua). Every fade here runs through Fade.
--   * Nothing is on a UIListLayout — a layout owns its children's Position,
--     which would suppress the slide-up each element enters with. The stack is a
--     fixed-size frame with the four pieces placed by hand.

local Create = __require("util.Create")
local Theme = __require("Theme")
local Tween = __require("util.Tween")
local Fade = __require("util.Fade")
local Asset = __require("util.Asset")
local Log = __require("util.Log")

-- Timeline. `Duration` is the *whole* on-screen time; the bar's fill soaks up
-- whatever is left after the entrance stagger and the exit fade, so a longer
-- duration reads as a slower bar rather than a longer wait on a full one.
local IN_STAGGER = 0.07 -- beat between each element entering
local BAR_DELAY = IN_STAGGER * 3 -- the bar is the 4th element in
local OUT_TIME = 0.2 -- matches Tween.MenuOut, the window's own leaving fade
local MIN_FILL = 0.35

local LOGO = 76
local STACK_W = 280
local BAR_W = 168

-- Layout, top-down inside the stack (offsets, like every other metric here).
-- Both stack dimensions are kept EVEN on purpose — see centerStack below.
local Y_LOGO = 0
local Y_TITLE = Y_LOGO + LOGO + 20
local Y_SUB = Y_TITLE + 26
local Y_BAR = Y_SUB + 16 + 23
local STACK_H = Y_BAR + 3

-- Same trick as the titlebar: Roblox has no letter-spacing, so a wordmark is
-- literal spaces between the glyphs.
local function wordmark(s: string): string
	local out = {}
	for _, c in utf8.codes(s:upper()) do
		table.insert(out, utf8.char(c))
	end
	return table.concat(out, " ")
end

local SCHEMA: Log.Schema = {
	{ "Title", "string" },
	{ "Subtitle", "string" },
	{ "Duration", "number" },
	{ "Dim", "number" },
	{ "Steps", "table" },
}

return function(ctx: any, parent: Instance, opts: any): any
	opts = opts or {}
	local colors = Theme.Colors

	Log.check("Splash", opts, SCHEMA)

	local duration = math.clamp(tonumber(opts.Duration) or 2, 1, 8)
	-- `Dim` is opacity (1 = solid chrome over the game), not transparency.
	local dim = math.clamp(tonumber(opts.Dim) or 0.88, 0, 1)
	local title = opts.Title or Theme.Brand.name
	local steps: { string }? = nil
	if type(opts.Steps) == "table" and #opts.Steps > 0 then
		steps = opts.Steps
	end
	local fillTime = math.max(MIN_FILL, duration - BAR_DELAY - OUT_TIME)

	local root = Create("Frame", {
		Name = "Splash",
		Size = UDim2.fromScale(1, 1),
		BackgroundColor3 = colors.chrome,
		BackgroundTransparency = 1, -- faded up to `dim` on Play
		BorderSizePixel = 0,
		ZIndex = 1000, -- above the window frame and its overlay
		Parent = parent,
	})
	-- The exit is one Fade over the whole tree, so backdrop, mark and text leave
	-- together the way a CanvasGroup would have done it — minus the blur.
	local rootFade = Fade.new(root)

	local stack = Create("Frame", {
		Name = "Stack",
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromScale(0.5, 0.5),
		Size = UDim2.fromOffset(STACK_W, STACK_H),
		BackgroundTransparency = 1,
		Parent = root,
	}, {
		Create("UIScale", {}),
	})
	local stackScale = stack:FindFirstChildOfClass("UIScale") :: UIScale

	-- Whole-pixel placement. A scale-centered stack lands on a half pixel on any
	-- odd viewport dimension, and a wordmark rasterized half a pixel off the
	-- display grid is exactly the kind of soft that looks like a bad font. Both
	-- stack dimensions are even, so a rounded centre gives a whole-pixel
	-- top-left. (Window.lua snaps itself the same way.)
	local function centerStack()
		local vp = root.AbsoluteSize
		if vp.X <= 0 then
			return
		end
		stack.Position = UDim2.fromOffset(math.round(vp.X / 2), math.round(vp.Y / 2))
	end
	root:GetPropertyChangedSignal("AbsoluteSize"):Connect(centerStack)
	task.defer(centerStack)

	-- Each element parks 8px low + invisible and is released a beat after the one
	-- above it: the slide is one Position tween, `fadeIn` brings the element up
	-- however it needs to. Built here, *played* by :Play so nothing moves until
	-- asked.
	local reveals: { () -> () } = {}
	local function reveal(inst: GuiObject, y: number, order: number, fadeIn: () -> ())
		inst.AnchorPoint = Vector2.new(0.5, 0)
		inst.Position = UDim2.new(0.5, 0, 0, y + 8)
		table.insert(reveals, function()
			task.delay(order * IN_STAGGER, function()
				if inst.Parent then
					Tween.play(inst, Tween.Slide, { Position = UDim2.new(0.5, 0, 0, y) })
					fadeIn()
				end
			end)
		end)
	end

	-- ── brand mark ───────────────────────────────────────────────────────────
	-- Same contract as the titlebar logo: the accent square + initial is the
	-- backdrop, the art is drawn over it and NEVER hidden by the load check
	-- (see util/Asset.lua) — worst case you get the square, never a hole.
	local holder = Create("Frame", {
		Name = "Logo",
		Size = UDim2.fromOffset(LOGO, LOGO),
		BackgroundTransparency = 1,
		ClipsDescendants = true, -- crops the margin the zoom pushes past the edge
		Parent = stack,
	}, {
		Create.corner(opts.LogoRadius or (Theme.Brand.radius * 2)),
		Create("UIScale", { Scale = 0.86 }),
	})
	local holderScale = holder:FindFirstChildOfClass("UIScale") :: UIScale
	-- The fallback pair is its own layer rather than the holder's own background,
	-- so the load check can hide it with `Visible` alone. Writing a transparency
	-- there would collide with the fade driving the same property.
	local square = Create("Frame", {
		Name = "Square",
		Size = UDim2.fromScale(1, 1),
		BackgroundColor3 = ctx.Accent,
		BorderSizePixel = 0,
		Parent = holder,
	}, {
		Create.corner(opts.LogoRadius or (Theme.Brand.radius * 2)),
	})
	local initial = Create("TextLabel", {
		Name = "Initial",
		BackgroundTransparency = 1,
		Size = UDim2.fromScale(1, 1),
		Text = title:sub(1, 1):upper(),
		TextColor3 = colors.knockout,
		TextSize = 40,
		FontFace = Theme.Font.Bold,
		Parent = holder,
	})
	if opts.Logo ~= nil and opts.Logo ~= false then
		local zoom = tonumber(opts.LogoZoom) or 1
		if zoom <= 0 then
			zoom = 1
		end
		local mark = Create("ImageLabel", {
			Name = "Mark",
			BackgroundTransparency = 1,
			AnchorPoint = Vector2.new(0.5, 0.5),
			Position = UDim2.fromScale(0.5, 0.5),
			Size = UDim2.fromScale(zoom, zoom),
			Image = "",
			ScaleType = Enum.ScaleType.Fit,
			Parent = holder,
		}) :: ImageLabel
		Asset.load(mark, opts.Logo, function(loaded)
			-- Only the fallback reacts — the art is left alone either way.
			square.Visible = not loaded
			initial.Visible = not loaded
		end)
	end
	local holderFade = Fade.new(holder)
	holderFade:Set(1)
	reveal(holder, Y_LOGO, 0, function()
		holderFade:To(Tween.Slide, 0)
		-- The mark gets the extra pop the text doesn't: it's the thing you're
		-- meant to look at.
		Tween.play(holderScale, Tween.Pop, { Scale = 1 })
	end)

	-- ── wordmark + status line ───────────────────────────────────────────────
	local titleLabel = Create("TextLabel", {
		Name = "Title",
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 26),
		Text = wordmark(title),
		TextColor3 = colors.text,
		TextSize = 22,
		TextTransparency = 1,
		FontFace = Theme.Font.Bold,
		Parent = stack,
	})
	reveal(titleLabel, Y_TITLE, 1, function()
		Tween.play(titleLabel, Tween.Slide, { TextTransparency = 0 })
	end)

	local subtitle = Create("TextLabel", {
		Name = "Subtitle",
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 16),
		Text = steps and steps[1] or (opts.Subtitle or ""),
		TextColor3 = colors.text_dim,
		TextSize = 12,
		TextTransparency = 1,
		FontFace = Theme.Font.Regular,
		Parent = stack,
	})
	reveal(subtitle, Y_SUB, 2, function()
		Tween.play(subtitle, Tween.Slide, { TextTransparency = 0 })
	end)

	-- ── progress bar ─────────────────────────────────────────────────────────
	local track = Create("Frame", {
		Name = "Track",
		Size = UDim2.fromOffset(BAR_W, 3),
		BackgroundColor3 = colors.toggle_off,
		BorderSizePixel = 0,
		Parent = stack,
	}, {
		Create.corner(2),
	})
	local fill = Create("Frame", {
		Name = "Fill",
		Size = UDim2.fromScale(0, 1),
		BackgroundColor3 = ctx.Accent,
		BorderSizePixel = 0,
		Parent = track,
	}, {
		Create.corner(2),
	})
	local trackFade = Fade.new(track) -- track + fill, so the bar enters as one
	trackFade:Set(1)
	reveal(track, Y_BAR, 3, function()
		trackFade:To(Tween.Slide, 0)
	end)

	-- ── play ─────────────────────────────────────────────────────────────────
	local splash = {}
	local finished = false

	-- Swap the status line through `Steps` across the fill, so the bar and the
	-- text tell the same story. One step = no cycling, it's just a caption.
	local function cycleSteps()
		local list = steps
		if not list or #list <= 1 then
			return
		end
		task.spawn(function()
			local slot = fillTime / #list
			for i = 2, #list do
				task.wait(slot)
				if not subtitle.Parent or finished then
					return
				end
				Tween.play(subtitle, Tween.Fast, { TextTransparency = 1 }).Completed:Wait()
				subtitle.Text = list[i]
				Tween.play(subtitle, Tween.Fast, { TextTransparency = 0 })
			end
		end)
	end

	-- `onDone` fires when the fade BEGINS — the window mounts behind the dim and
	-- the two cross-fade. Waiting for the fade to finish would show a blank
	-- screen for a fifth of a second in between.
	function splash:Play(onDone: (() -> ())?)
		task.spawn(function()
			Tween.play(root, Tween.Slide, { BackgroundTransparency = 1 - dim })
			for _, run in reveals do
				run()
			end

			task.wait(BAR_DELAY)
			Tween.play(
				fill,
				TweenInfo.new(fillTime, Enum.EasingStyle.Quad, Enum.EasingDirection.InOut),
				{ Size = UDim2.fromScale(1, 1) }
			)
			cycleSteps()

			task.wait(fillTime + 0.06) -- a beat on a full bar before it leaves
			finished = true
			if onDone then
				onDone()
			end
			Tween.play(stackScale, Tween.MenuOut, { Scale = 1.05 })
			rootFade:To(Tween.MenuOut, 1).Completed:Wait()
			root:Destroy()
		end)
	end

	function splash:Destroy()
		finished = true
		root:Destroy()
	end

	return splash
end

end

__modules['components.Tab'] = function(...)
--!strict
-- components/Tab.lua — a sidebar nav button + a two-column content page.
--
-- The nav is icon-only (a 64px sidebar, 40px tiles), so everything that tells
-- one tab from another has to fit in that tile. The knobs, all optional:
--
--   Pin       "top" (default) / "bottom" — which end of the rail it sits at.
--   Color     a per-tab accent for the active tile / rail / dot / badge.
--   Style     "tile" (default) / "solid" / "plain" — how the active state draws.
--   Rail      false drops the accent rail in the gutter.
--   Dot       a small always-on marker (true = the tab colour, or a Color3).
--   Separator a hairline above the button, to break the rail into clusters.
--   Name/Desc/Badge  the hover flyout's three lines.
--
-- That set exists for the case the sidebar is actually bad at: one tab is
-- "universal player mods" and the next is specific to the game you're in, and
-- as a stack of grey glyphs they look like the same kind of thing. Give the two
-- clusters different colours, pin the global one to the other end, separate
-- them with a hairline, and the rail reads as two groups.
--
-- The flyout is also the tab's *name*, which the port never showed anywhere:
-- the reference mock carried it as a `data-tip` attribute on the nav button
-- (`.coreui-navbtn[data-tip]:hover::after`) and DOCS.md has always described
-- `Name` as the "sidebar label / tooltip". It mounts into `ctx.overlay`, not the
-- sidebar — the sidebar is inside `body`, and a flyout parented there would be
-- drawn under the content it has to overlap.

local Create = __require("util.Create")
local Theme = __require("Theme")
local Tween = __require("util.Tween")
local Icons = __require("Icons")
local Fade = __require("util.Fade")
local Log = __require("util.Log")
local Group = __require("components.Group")

local M = Theme.Metrics

local PINS: { [string]: boolean } = { top = true, bottom = true }
local STYLES: { [string]: boolean } = { tile = true, solid = true, plain = true }

-- Everything `CreateTab` accepts, declared where it's read.
--
-- This list used to live in components/Window.lua as fifteen consecutive
-- `Log.field` calls, while the two normalizers below sat here — so one option's
-- contract was spread across two files and adding a knob meant editing both,
-- with nothing to notice if you only did one. Window forwards its options and
-- says nothing about their shape now.
--
-- `Pin`/`Style` are typed `string` here and *valued* by the normalizers, which
-- warn-and-default rather than fail: a wrong type is a mistake about the API, a
-- wrong string is a typo, and only the first is worth refusing to build over.
local SCHEMA: Log.Schema = {
	{ "Name", "string" },
	{ "Id", "string" },
	{ "Icon", "string" },
	{ "Desc", "string" },
	{ "Badge", "string" },
	{ "Pin", "string" },
	{ "Style", "string" },
	{ "Color", "Color3" },
	{ "Dot", { "boolean", "Color3" } },
	{ "Rail", "boolean" },
	{ "Separator", "boolean" },
	{ "Order", "number" },
	{ "Visible", "boolean" },
	{ "Callback", "function" },
}

-- Both of these are spelling-tolerant on case only ("Bottom" is a reasonable
-- thing to type) and warn-and-default on anything else, like Group's Column.
local function normalizePin(value: any, where: string): string
	if value == nil then
		return "top"
	end
	local text = type(value) == "string" and string.lower(value) or nil
	if text and PINS[text] then
		return text
	end
	Log.warn(where, ('Pin must be "top" or "bottom", got %s — pinning to the top.')
		:format(tostring(value)))
	return "top"
end

local function normalizeStyle(value: any, where: string): string
	if value == nil then
		return "tile"
	end
	local text = type(value) == "string" and string.lower(value) or nil
	if text and STYLES[text] then
		return text
	end
	Log.warn(where, ('Style must be "tile", "solid" or "plain", got %s — using "tile".')
		:format(tostring(value)))
	return "tile"
end

local function newColumn(order: number): Frame
	return Create("Frame", {
		Name = "Column",
		BackgroundTransparency = 1,
		AnchorPoint = order == 2 and Vector2.new(1, 0) or Vector2.new(0, 0),
		Position = order == 2 and UDim2.fromScale(1, 0) or UDim2.fromScale(0, 0),
		Size = UDim2.new(0.5, -(M.columnGap / 2), 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
	}, {
		Create.listLayout({ Padding = UDim.new(0, M.groupGap) }),
	})
end

return function(ctx: any, opts: any)
	local colors = Theme.Colors
	local where = Log.where("CreateTab", opts.Name)
	Log.check(where, opts, SCHEMA)

	local label: string = opts.Name or "Tab"
	local desc: string? = opts.Desc
	local badge: string? = opts.Badge
	local pin = normalizePin(opts.Pin, where)
	local style = normalizeStyle(opts.Style, where)
	local showRail = opts.Rail ~= false
	-- `Color` overrides the window accent for this tab alone; nil follows it live.
	local tabColor: Color3? = opts.Color
	-- `Dot = true` uses the tab's colour, `Dot = Color3` picks its own.
	local dotColor: Color3? = typeof(opts.Dot) == "Color3" and opts.Dot or nil
	local showDot = opts.Dot ~= nil and opts.Dot ~= false

	-- The tab's accent weights (mark / large fill / tinted tile): its own colour
	-- if it has one, otherwise the window's live accent. A per-tab colour is
	-- derived through ctx:Shades, so it gets exactly the same treatment SetAccent
	-- gives the global one instead of a second, hand-rolled ramp.
	local function shades(): (Color3, Color3, Color3)
		if tabColor then
			local _, f, s = ctx:Shades(tabColor)
			return tabColor, f, s
		end
		return ctx.Accent, ctx.AccentFill, ctx.AccentSoft
	end

	-- nav button ──────────────────────────────────────────────────────────
	local button = Create("TextButton", {
		Name = "Nav_" .. label,
		AutoButtonColor = false,
		Text = "",
		Size = UDim2.fromOffset(M.navButton, M.navButton),
		BackgroundColor3 = colors.accent_soft,
		BackgroundTransparency = 1,
	}, {
		Create.corner(M.navRadius),
	})

	-- A hairline above the button, for breaking the rail into clusters. It's a
	-- sibling of the button in the nav frame (Window parents it and orders it
	-- just above), so the nav's UIListLayout spaces it like any other item.
	local separator: Frame? = nil
	if opts.Separator == true then
		separator = Create("Frame", {
			Name = "NavSeparator",
			BackgroundTransparency = 1,
			Size = UDim2.new(1, 0, 0, 9),
		}, {
			Create("Frame", {
				Name = "Line",
				AnchorPoint = Vector2.new(0.5, 0.5),
				Position = UDim2.fromScale(0.5, 0.5),
				Size = UDim2.fromOffset(24, 1),
				BackgroundColor3 = colors.border,
				BorderSizePixel = 0,
			}),
		})
	end

	-- No glow behind the active button: the Uranium palette is flat fills only.
	-- The active state is a *tinted* tile (accent_soft) with an accent icon on
	-- it, plus the rail below — a solid accent tile put a neon block in the
	-- sidebar of every screenshot, and it fought the primary button for the eye.
	-- (`Style = "solid"` opts back into a filled tile per tab: as one tab out of
	-- six, marking a different *class* of tab, it earns the area it takes.)
	--
	-- The rail is the loud half of the active state, and it can afford to be:
	-- it's 3×18px. It lives in the sidebar gutter left of the button (the nav
	-- frame doesn't clip), and grows out of nothing on select.
	local rail = Create("Frame", {
		Name = "Rail",
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.new(0, -9, 0.5, 0),
		Size = UDim2.fromOffset(3, 0),
		BackgroundColor3 = colors.accent,
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		Visible = showRail,
		Parent = button,
	}, {
		Create.corner(999),
	})

	-- The always-on marker. Unlike the tile and the rail it doesn't wait for the
	-- tab to be active, which is the whole point: you can tell the clusters apart
	-- without hovering or clicking. It hides *while* active, because by then the
	-- tile is already carrying the colour (and on a solid tile a same-coloured
	-- dot would simply disappear).
	local dot = Create("Frame", {
		Name = "Marker",
		AnchorPoint = Vector2.new(1, 0),
		Position = UDim2.new(1, -3, 0, 3),
		Size = UDim2.fromOffset(7, 7),
		BackgroundColor3 = colors.accent,
		BorderSizePixel = 0,
		Visible = false,
		ZIndex = 2,
		Parent = button,
	}, {
		Create.corner(999),
		-- A chrome-coloured ring so the dot reads as a marker on the tile rather
		-- than a stray pixel touching the icon.
		Create.stroke(colors.chrome, 2),
	})

	local icon = Icons.new(opts.Icon or "gear", M.navIcon, colors.text_dim)
	icon.AnchorPoint = Vector2.new(0.5, 0.5)
	icon.Position = UDim2.fromScale(0.5, 0.5);
	(icon :: any).Parent = button
	local iconScale = Create("UIScale", { Parent = icon })

	-- hover flyout ────────────────────────────────────────────────────────
	-- Built on first hover, not up front: a tab that's never hovered never pays
	-- for it, and the tree it snapshots for the fade is the one it's about to
	-- show. Lives in ctx.overlay so it draws over the content, not under it.
	local TIP_GAP = 10
	local TIP_MARGIN = 4
	local TIP_MAX_W = 200
	local tip: Frame? = nil
	local tipFade: any = nil
	local tipName: TextLabel? = nil
	local tipDesc: TextLabel? = nil
	local tipBadge: Frame? = nil
	local tipBadgeText: TextLabel? = nil
	local tipSizeConn: RBXScriptConnection? = nil -- permanent (auto-size settles late)
	local tipMoveConn: RBXScriptConnection? = nil -- only while the flyout is up
	local hovering = false
	local active = false

	local function placeTip()
		local frame = tip
		if not frame or not frame.Visible then
			return
		end
		local overlay = ctx.overlay
		local o, os = overlay.AbsolutePosition, overlay.AbsoluteSize
		local b, bs = button.AbsolutePosition, button.AbsoluteSize
		local ts = frame.AbsoluteSize
		if os.X <= 0 then
			return
		end
		local x = (b.X - o.X) + bs.X + TIP_GAP
		local y = (b.Y - o.Y) + bs.Y / 2 - ts.Y / 2
		x = math.min(x, math.max(TIP_MARGIN, os.X - ts.X - TIP_MARGIN))
		y = math.clamp(y, TIP_MARGIN, math.max(TIP_MARGIN, os.Y - ts.Y - TIP_MARGIN))
		-- Whole pixels, same reason as the window itself: a flyout landing on a
		-- half pixel rasterizes its label half a pixel off the display grid.
		frame.Position = UDim2.fromOffset(math.round(x), math.round(y))
	end

	local function paintTip()
		if not (tipBadge and tipBadgeText) then
			return
		end
		local accent, _, accentSoft = shades()
		tipBadge.BackgroundColor3 = accentSoft
		tipBadgeText.TextColor3 = accent
	end

	local function buildTip()
		if tip then
			return
		end
		local frame = Create("Frame", {
			Name = "NavTip",
			Visible = false,
			Size = UDim2.fromOffset(0, 0),
			AutomaticSize = Enum.AutomaticSize.XY,
			BackgroundColor3 = colors.pop,
			ZIndex = 70,
		}, {
			Create.corner(7),
			Create.stroke(colors.border),
			Create.padding(7, 9),
			Create.listLayout({ Padding = UDim.new(0, 3) }),
		})
		tipName = Create("TextLabel", {
			Name = "Title",
			BackgroundTransparency = 1,
			Size = UDim2.fromOffset(0, 0),
			AutomaticSize = Enum.AutomaticSize.XY,
			Text = label,
			TextColor3 = colors.text,
			TextSize = 12,
			FontFace = Theme.Font.Medium,
			TextXAlignment = Enum.TextXAlignment.Left,
			TextWrapped = true,
			LayoutOrder = 1,
			Parent = frame,
		}, {
			-- AutomaticSize grows the label to its text; the constraint caps the
			-- width and TextWrapped then takes over, so a long line wraps instead
			-- of running a flyout off the side of the window.
			Create("UISizeConstraint", { MaxSize = Vector2.new(TIP_MAX_W, math.huge) }),
		})
		if desc and desc ~= "" then
			tipDesc = Create("TextLabel", {
				Name = "Desc",
				BackgroundTransparency = 1,
				Size = UDim2.fromOffset(0, 0),
				AutomaticSize = Enum.AutomaticSize.XY,
				Text = desc,
				TextColor3 = colors.text_muted,
				TextSize = 11,
				FontFace = Theme.Font.Regular,
				TextXAlignment = Enum.TextXAlignment.Left,
				TextWrapped = true,
				LayoutOrder = 2,
				Parent = frame,
			}, {
				Create("UISizeConstraint", { MaxSize = Vector2.new(TIP_MAX_W, math.huge) }),
			})
		end
		if badge and badge ~= "" then
			tipBadge = Create("Frame", {
				Name = "Badge",
				Size = UDim2.fromOffset(0, 0),
				AutomaticSize = Enum.AutomaticSize.XY,
				BackgroundColor3 = colors.accent_soft,
				LayoutOrder = 3,
				Parent = frame,
			}, {
				Create.corner(4),
				Create.padding(2, 5),
			})
			tipBadgeText = Create("TextLabel", {
				Name = "Text",
				BackgroundTransparency = 1,
				Size = UDim2.fromOffset(0, 0),
				AutomaticSize = Enum.AutomaticSize.XY,
				Text = string.upper(badge),
				TextColor3 = colors.accent,
				TextSize = 10,
				FontFace = Theme.Font.Bold,
				TextXAlignment = Enum.TextXAlignment.Left,
				Parent = tipBadge,
			})
		end
		frame.Parent = ctx.overlay
		tip = frame
		tipFade = Fade.new(frame)
		-- AutomaticSize settles a frame late, so the first place() ran against a
		-- zero size — re-place whenever it changes (which is also what covers
		-- SetName / SetDesc growing the flyout while it's up).
		tipSizeConn = frame:GetPropertyChangedSignal("AbsoluteSize"):Connect(placeTip)
		paintTip()
	end

	local function showTip()
		if label == "" then
			return
		end
		buildTip()
		local frame = tip :: Frame
		frame.Visible = true
		placeTip()
		tipFade:Set(1)
		tipFade:To(Tween.Fast, 0)
		-- Only tracked while it's up: dragging the window fires this every frame
		-- and there's no reason for a hidden flyout to listen.
		if not tipMoveConn then
			tipMoveConn = button:GetPropertyChangedSignal("AbsolutePosition"):Connect(placeTip)
		end
	end

	local function hideTip(immediate: boolean?)
		local frame = tip
		if not frame or not frame.Visible then
			return
		end
		if tipMoveConn then
			tipMoveConn:Disconnect()
			tipMoveConn = nil
		end
		local function done()
			if not hovering and tip then
				tip.Visible = false
				-- Land the fade back on its resting values before hiding, exactly
				-- like Context:ClosePopover — reopening mid-fade would otherwise
				-- snapshot the half-faded labels as the new baseline.
				tipFade:Set(0)
			end
		end
		if immediate then
			tipFade:Set(1)
			done()
			return
		end
		tipFade:To(Tween.MenuOut, 1, done)
	end

	-- content page ────────────────────────────────────────────────────────
	local page = Create("Frame", {
		Name = "Page_" .. label,
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		Visible = false,
	})
	local columns = Create("Frame", {
		Name = "Columns",
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		Parent = page,
	})
	local col1 = newColumn(1)
	col1.Parent = columns
	local col2 = newColumn(2)
	col2.Parent = columns

	-- Scale height (1,0 on Y) so the divider fills the column block natively.
	-- Roblox excludes scale-sized children from a parent's AutomaticSize, so this
	-- can't feed back into `columns` and trigger AbsoluteSizeChanged re-entrancy
	-- (the old signal-driven offset height oscillated on subpixel rounding).
	Create("Frame", {
		Name = "ColDivider",
		AnchorPoint = Vector2.new(0.5, 0),
		Position = UDim2.fromScale(0.5, 0),
		Size = UDim2.new(0, 1, 1, 0),
		BackgroundColor3 = colors.border_soft,
		BorderSizePixel = 0,
		Parent = columns,
	})

	-- nav state ──────────────────────────────────────────────────────────
	-- Crossfade both colour and transparency in a single tween. The old code
	-- snapped BackgroundColor3 to white instantly while the fill was still
	-- opaque (and snapped transparency to 0 on activate), so a switched-off tab
	-- showed a solid flash for one frame before fading. Idle keeps the *tint*
	-- colour and only fades the transparency, so there's no intermediate solid
	-- colour to flash — the tile simply fades in / out.
	local function paint(animate: boolean?)
		local accent, accentFill, accentSoft = shades()
		local goal, railGoal
		rail.BackgroundColor3 = accent
		dot.BackgroundColor3 = dotColor or accent
		dot.Visible = showDot and not active
		if active then
			-- "solid" fills the tile and knocks the icon out of it; "plain" drops
			-- the tile entirely and lets the icon + rail carry the state.
			local fill = style == "solid" and accentFill or accentSoft
			goal = {
				BackgroundColor3 = fill,
				BackgroundTransparency = style == "plain" and 1 or 0,
			}
			Icons.tint(icon, style == "solid" and colors.knockout or accent)
			railGoal = { Size = UDim2.fromOffset(3, 18), BackgroundTransparency = 0 }
		else
			goal = {
				-- idle (transparency 1) keeps the tint colour so the fade-out is a
				-- pure fade; hover is one step lighter than the chrome.
				BackgroundColor3 = hovering and colors.control_hi
					or (style == "solid" and accentFill or accentSoft),
				BackgroundTransparency = hovering and 0 or 1,
			}
			Icons.tint(icon, hovering and colors.text_muted or colors.text_dim)
			railGoal = { Size = UDim2.fromOffset(3, 0), BackgroundTransparency = 1 }
		end
		if animate == false then
			for key, value in goal do
				(button :: any)[key] = value
			end
			for key, value in railGoal do
				(rail :: any)[key] = value
			end
		else
			Tween.play(button, Tween.Fast, goal)
			-- Overshoot on the way in only: Back easing on the way *out* would
			-- pull the height below zero before settling.
			Tween.play(rail, active and Tween.Spring or Tween.Fast, railGoal)
		end
		paintTip()
	end
	button.MouseEnter:Connect(function()
		hovering = true
		showTip()
		if not active then
			paint()
		end
	end)
	button.MouseLeave:Connect(function()
		hovering = false
		hideTip()
		if not active then
			paint()
		end
	end)
	-- A tab with its own Color is pinned to it and ignores SetAccent; everything
	-- else re-themes live.
	ctx:RegisterAccent(function()
		if not tabColor then
			paint(false)
		end
	end)

	-- Every group on this page, in build order, so the titlebar search can filter
	-- them from direct references instead of re-deriving the page's shape from
	-- instance names (see tab:Filter).
	local groups: { any } = {}

	local tab: any = {
		button = button,
		page = page,
		separator = separator,
		pin = pin,
		order = tonumber(opts.Order),
		-- Installed by Window, which owns the nav frames and the selection: one
		-- fires when this tab is hidden/shown (it may have to select another), the
		-- other when it moves between the top and bottom clusters.
		_onVisible = (nil :: any),
		_onPin = (nil :: any),
	}

	-- The page's resting position is captured once, on first activation (Window
	-- sets it before selecting the first tab). Re-reading page.Position on every
	-- activation meant a fast tab switch sampled a mid-tween value and adopted it
	-- as "rest", so the page crept further down the screen with each switch.
	local restPos: UDim2? = nil
	local slideTween: Tween? = nil

	function tab:_setActive(value: boolean)
		local becameActive = value and not active
		active = value
		page.Visible = value
		paint()
		if becameActive then
			iconScale.Scale = 0.8
			Tween.play(iconScale, Tween.Spring, { Scale = 1 }) -- pop on select
			-- ease the page up into place so switching tabs settles instead of
			-- hard-cutting (rest position is set by Window; nudge down, slide back)
			local rest = restPos or page.Position
			restPos = rest
			if slideTween then
				slideTween:Cancel()
			end
			page.Position = rest + UDim2.fromOffset(0, 10)
			slideTween = Tween.play(page, Tween.Normal, { Position = rest })
			-- Spawned: a Callback that errors (or yields) is the caller's problem,
			-- not something that should take the tab switch down with it.
			if opts.Callback then
				task.spawn(opts.Callback, tab)
			end
		end
	end

	function tab:IsActive(): boolean
		return active
	end

	-- ── runtime customization ────────────────────────────────────────────────
	-- Everything the options table sets is also settable later, so a menu can
	-- react to what it finds (mark the game tab red when the game isn't
	-- supported, dot the tab that has features running, …).
	function tab:SetColor(color: Color3?)
		if color ~= nil and typeof(color) ~= "Color3" then
			Log.fail("SetColor", ("expects a Color3 or nil, got %s"):format(typeof(color)))
		end
		tabColor = color
		paint(false)
	end

	function tab:GetColor(): Color3
		return tabColor or ctx.Accent
	end

	function tab:SetStyle(value: string?)
		style = normalizeStyle(value, "SetStyle")
		paint(false)
	end

	function tab:SetRail(enabled: boolean)
		showRail = enabled ~= false
		rail.Visible = showRail
	end

	function tab:SetDot(value: any)
		showDot = value ~= nil and value ~= false
		dotColor = typeof(value) == "Color3" and value or nil
		paint(false)
	end

	function tab:SetIcon(name: string)
		if type(name) ~= "string" then
			Log.fail("SetIcon", ('expects an icon name, got %s (try tab:SetIcon("gear"))')
				:format(typeof(name)))
		end
		-- Icons.apply only works on an ImageLabel, and a name with no Lucide entry
		-- builds a glyph TextLabel instead — so swap the instance rather than
		-- branching on which of the two we happen to be holding.
		local fresh = Icons.new(name, M.navIcon, colors.text_dim)
		fresh.AnchorPoint = Vector2.new(0.5, 0.5)
		fresh.Position = UDim2.fromScale(0.5, 0.5)
		icon:Destroy()
		icon = fresh;
		(icon :: any).Parent = button
		iconScale = Create("UIScale", { Parent = icon })
		paint(false)
	end

	-- Tear the flyout down so the next hover rebuilds it. Needed when a line it
	-- wasn't built with appears (a desc/badge set at runtime): the rows are only
	-- created for the lines that had content.
	local function rebuildTip()
		hideTip(true)
		if tipSizeConn then
			tipSizeConn:Disconnect()
			tipSizeConn = nil
		end
		if tipFade then
			tipFade:Destroy()
			tipFade = nil
		end
		if tip then
			tip:Destroy()
		end
		tip, tipName, tipDesc, tipBadge, tipBadgeText = nil, nil, nil, nil, nil
		if hovering then
			showTip()
		end
	end

	-- The flyout's three lines. Name is also what the button/page instances are
	-- named after, but renaming those buys nothing — the flyout is the label.
	function tab:SetName(text: string)
		Log.field("SetName", "text", text, "string")
		label = text or ""
		if tipName then
			tipName.Text = label
		end
	end

	function tab:SetDesc(text: string?)
		local had = desc ~= nil and desc ~= ""
		desc = text
		if tipDesc then
			tipDesc.Text = text or ""
			tipDesc.Visible = (text ~= nil and text ~= "")
		elseif not had and text and text ~= "" then
			rebuildTip()
		end
	end

	function tab:SetBadge(text: string?)
		local had = badge ~= nil and badge ~= ""
		badge = text
		if tipBadge and tipBadgeText then
			tipBadgeText.Text = string.upper(text or "")
			tipBadge.Visible = (text ~= nil and text ~= "")
		elseif not had and text and text ~= "" then
			rebuildTip()
		end
	end

	-- Drop the flyout without waiting for a MouseLeave that may never come: the
	-- window minimizing or unloading takes the button off screen under the cursor,
	-- and a flyout left visible would still be in the window fade's snapshot —
	-- two fades writing the same transparencies (see util/Fade.lua).
	function tab:_hideFlyout()
		hovering = false
		hideTip(true)
	end

	function tab:IsVisible(): boolean
		return button.Visible
	end

	-- Hiding a tab hides its nav button (and its separator), not its page —
	-- Window decides what to select instead through `_onVisible`.
	function tab:SetVisible(value: boolean)
		local visible = value ~= false
		if button.Visible == visible then
			return
		end
		button.Visible = visible
		if separator then
			separator.Visible = visible
		end
		if not visible then
			hovering = false
			hideTip(true)
		end
		if tab._onVisible then
			tab._onVisible(visible)
		end
	end

	-- Moving between the two clusters is a reparent, which only Window can do
	-- (it owns the nav frames) — it installs `_onPin` when it mounts the tab.
	function tab:SetPin(value: string?)
		local target = normalizePin(value, "SetPin")
		if target == tab.pin then
			return
		end
		tab.pin = target
		if tab._onPin then
			tab._onPin(target)
		end
	end

	-- The tab's identity for the window's persisted group-collapse map, fixed at
	-- creation: `SetName` renames the flyout, and letting that re-key every group
	-- underneath it would quietly orphan them in configs already on disk.
	local scope: string = opts.Id or label or "Tab"

	function tab:CreateGroup(groupOpts: any)
		if groupOpts ~= nil and type(groupOpts) ~= "table" then
			Log.fail("CreateGroup", ("options must be a table like { Title = ..., Column = 1 }, got %s")
				:format(typeof(groupOpts)))
		end
		Log.field("CreateGroup", "Id", groupOpts and groupOpts.Id, "string")
		-- `Parent` scopes every bindable control in the card to one feature for the
		-- bind HUD: a name, or `true` to mean "the first bindable control here".
		Log.field("CreateGroup", "Parent", groupOpts and groupOpts.Parent, { "string", "boolean", "table" })
		-- Column is 1 (left) or 2 (right). A stray value (e.g. Column = 3, or a
		-- string) would silently land the group in the left column — warn and
		-- fall back so the author knows their column choice was ignored.
		local column = groupOpts and groupOpts.Column
		if column ~= nil and column ~= 1 and column ~= 2 then
			Log.warn(Log.where("CreateGroup", groupOpts and groupOpts.Title),
				("Column must be 1 (left) or 2 (right), got %s — using column 1."):format(tostring(column)))
		end
		local target = (column == 2) and col2 or col1
		local handle = Group(ctx, target, groupOpts or {}, scope)
		table.insert(groups, handle)
		return handle
	end

	-- ── titlebar search ───────────────────────────────────────────────────────
	-- Show a group if its title matches; otherwise show only the fields whose text
	-- matches, and hide a group left with nothing. An empty query restores
	-- everything.
	--
	-- This lives here rather than in components/Window.lua, where it used to, for
	-- the reason spelled out on `handle._search` in Group.lua: it is entirely a
	-- statement about the page's layout, and the page is this file's. Window now
	-- asks the active tab to filter itself and knows none of it.
	--
	-- The per-field text is collected once per search SESSION, not per keystroke —
	-- `ResetFilter` is the invalidation, called when the search box is opened,
	-- which is the only moment the menu can have grown or lost controls since the
	-- last one. Caching also means the filter matches the labels a field was BUILT
	-- with rather than whatever a live value reads at this instant, which is what
	-- people are typing at. Weak keys, so a destroyed control doesn't pin its
	-- strings until the next reset.
	local searchText: { [Instance]: string } = setmetatable({}, { __mode = "k" }) :: any

	local function collectText(inst: Instance): string
		local hit = searchText[inst]
		if hit then
			return hit
		end
		local parts = {}
		for _, d in inst:GetDescendants() do
			if (d:IsA("TextLabel") or d:IsA("TextButton") or d:IsA("TextBox")) and d.Text ~= "" then
				table.insert(parts, d.Text)
			end
		end
		local text = string.lower(table.concat(parts, " "))
		searchText[inst] = text
		return text
	end

	function tab:ResetFilter()
		table.clear(searchText)
	end

	function tab:Filter(query: string?)
		local q = string.lower(query or "")
		for _, handle in groups do
			local entry = handle._search
			if entry then
				local groupMatch = q == "" or string.find(entry.title, q, 1, true) ~= nil
				local anyVisible = false

				-- Fields and their trailing hairlines are siblings ordered field,
				-- separator, field, separator… so filter the fields first, then
				-- re-derive each separator: visible only when the field above it
				-- survived AND some field still follows it. (Leaving separators alone
				-- stranded hairlines wherever a field was hidden; showing them all put
				-- one under the last row.)
				local ordered: { GuiObject } = {}
				for _, child in entry.card:GetChildren() do
					if child:IsA("GuiObject") then -- skip UICorner/UIStroke/UIPadding/UIListLayout
						table.insert(ordered, child)
					end
				end
				table.sort(ordered, function(a, b)
					return a.LayoutOrder < b.LayoutOrder
				end)
				for _, item in ordered do
					if item.Name ~= "Separator" then
						local matches = groupMatch
							or string.find(collectText(item), q, 1, true) ~= nil
						item.Visible = matches
						if matches then
							anyVisible = true
						end
					end
				end
				local previousVisible = false
				local lastSeparator: GuiObject? = nil
				for _, item in ordered do
					if item.Name == "Separator" then
						item.Visible = previousVisible
						if previousVisible then
							lastSeparator = item
						end
					else
						if item.Visible and lastSeparator then
							lastSeparator = nil -- a field follows it, so it stays
						end
						previousVisible = item.Visible
					end
				end
				if lastSeparator then
					lastSeparator.Visible = false -- trailing hairline, nothing below
				end

				entry.group.Visible = q == "" or groupMatch or anyVisible
			end
		end
	end

	paint(false)
	return tab
end

end

__modules['components.Toggle'] = function(...)
--!strict
-- components/Toggle.lua — 42×23 pill, 17px knob, +19px travel.
--
-- Every toggle carries a keybind chip in the same row, so "hold B for
-- walkspeed" is one option on the control rather than a second control wired up
-- by hand. The chip owns a binding in util/Bind.lua; the toggle's value stays
-- the single source of truth, which is why Toggle mode asks for it via
-- `GetState` instead of tracking its own.
--
-- The chip is built even when the call site says nothing about keys — empty,
-- in Toggle mode — because "is this bindable?" isn't a decision the menu author
-- should have to make on the user's behalf. It used to be opt-in, which meant
-- hubs hardcoded a default key just to get the chip on screen, and every one of
-- those landed in the bind HUD as a bind nobody asked for. An unbound chip on an
-- *off* toggle costs the HUD nothing (util/Bind.lua's `IsListed` keeps idle
-- keyless binds out; switching the toggle on lists it, keyed or not, because the
-- HUD's job is to say what's running), so the default is free.
-- `Keybind` / `KeybindMode` / `KeybindModes` still
-- preset it exactly as before; `Keybind = false` opts one control out, and
-- `CreateWindow{ Keybinds = false }` opts the whole window out.

local Create = __require("util.Create")
local Theme = __require("Theme")
local Tween = __require("util.Tween")
local Log = __require("util.Log")
local Field = __require("components.Field")
local BindChip = __require("components.BindChip")

local OFF_POS = UDim2.fromOffset(3, 3)
local ON_POS = UDim2.fromOffset(22, 3) -- 3 + 19px travel

-- The options this control adds on top of the ones every control takes
-- (`Name`/`Desc`/`Default`/`Callback`/`Flag`, checked by components/Controls.lua).
local SCHEMA: Log.Schema = {
	-- `false` is the opt-out ("this toggle isn't bindable"), so it's a legal value
	-- here alongside a key.
	{ "Keybind", { "EnumItem", "boolean" } },
	{ "KeybindMode", "string" },
	{ "KeybindModes", "table" },
	{ "KeybindFlag", "string" },
	{ "Hud", "boolean" },
	{ "Parent", { "string", "table" } },
}

return function(ctx: any, opts: any)
	opts = opts or {}
	local colors = Theme.Colors
	local where = Log.where("Toggle", opts.Name)
	Log.check(where, opts, SCHEMA)

	local f = Field.new(ctx, opts)
	local state = opts.Default == true

	local track = Create("TextButton", {
		Name = "Toggle",
		AutoButtonColor = false,
		Text = "",
		Size = UDim2.fromOffset(42, 23),
		BackgroundColor3 = colors.toggle_off,
		LayoutOrder = 3,
		Parent = f.row,
	}, {
		Create.corner(999),
	})

	local knob = Create("Frame", {
		Name = "Knob",
		Size = UDim2.fromOffset(17, 17),
		Position = OFF_POS,
		BackgroundColor3 = colors.knob,
		Parent = track,
	}, {
		Create.corner(999),
	})

	local function paint(animate: boolean)
		local trackColor = state and ctx.Accent or colors.toggle_off
		-- on = knockout knob on the accent track, off = text-faint knob on surface
		local knobColor = state and colors.knockout or colors.knob
		local pos = state and ON_POS or OFF_POS
		if animate then
			Tween.play(track, Tween.Normal, { BackgroundColor3 = trackColor })
			Tween.play(knob, Tween.Normal, { BackgroundColor3 = knobColor })
			Tween.play(knob, Tween.Spring, { Position = pos }) -- slight overshoot on the slide
		else
			track.BackgroundColor3 = trackColor
			knob.BackgroundColor3 = knobColor
			knob.Position = pos
		end
	end

	local bind: any = nil

	local handle = {}
	function handle:Get(): boolean
		return state
	end
	function handle:Set(value: boolean)
		state = value == true
		paint(true)
		-- Keep the chip's idea of the value in step (so a Hold chip un-lights, and
		-- a Toggle press after a manual click flips the right way) without letting
		-- it re-enter the callback.
		if bind then
			bind:SetState(state)
		end
		if opts.Callback then
			task.spawn(opts.Callback, state)
		end
	end

	-- Tagged so a host watching Context:OnFlagChanged can tell a switch the user
	-- flipped from one a script set. The tag is dynamically scoped and task.spawn
	-- resumes immediately, so it still covers the callback :Set fires.
	track.Activated:Connect(function()
		ctx:User(function()
			handle:Set(not state)
		end)
	end)

	-- ── keybind ──────────────────────────────────────────────────────────────
	-- On unless someone said otherwise. A keybind option on the control is that
	-- someone either way: `Keybind = false` opts this one out, and any explicit
	-- key / mode / mode-list turns it back on over a window-wide
	-- `CreateWindow{ Keybinds = false }`.
	local bindable
	if opts.Keybind == false then
		bindable = false
	elseif opts.Keybind ~= nil or opts.KeybindMode ~= nil or opts.KeybindModes ~= nil then
		bindable = true
	else
		bindable = ctx.Keybinds ~= false
	end

	if bindable then
		-- Resolved before the chip is built so the chip's OnChanged can name it —
		-- re-keying or mode-cycling the chip is a change to this flag, and it's the
		-- only one whose value never passes through a control callback (the chip
		-- isn't mounted through components/Controls.lua, the toggle is).
		local keyFlag = opts.KeybindFlag
		if keyFlag == nil and type(opts.Flag) == "string" and opts.Flag ~= "" then
			keyFlag = opts.Flag .. "_key"
		end

		local chip, chipHandle = BindChip(ctx, {
			-- `true` (force the chip on) isn't a key — only a real one presets it.
			Key = typeof(opts.Keybind) == "EnumItem" and opts.Keybind or nil,
			Mode = opts.KeybindMode or "Toggle",
			Modes = opts.KeybindModes,
			Default = state,
			Compact = true,
			LayoutOrder = 2,
			Where = where,
			-- The toggle's own label is what the bind HUD lists it under, so
			-- "hold B for aim" appears there without a second declaration.
			Label = opts.Name,
			-- ...and its Flag is what a sub-option points `Parent` at. Either name
			-- resolves (util/Bind.lua `Binding:_named`), so a section of sub-toggles
			-- can say `Parent = "aimbot"` or `Parent = "Aimbot"`.
			Id = opts.Flag,
			-- Declaring this toggle a sub-option of another feature keeps it out of
			-- the bind HUD when it's merely switched on — its parent's row speaks for
			-- it. A key of its own still lists it.
			Parent = opts.Parent,
			Hud = opts.Hud,
			GetState = function()
				return state
			end,
			OnActivate = function(active)
				handle:Set(active)
			end,
			OnChanged = function()
				if keyFlag then
					ctx:NotifyFlag(keyFlag)
				end
			end,
		})
		chip.Parent = f.row
		bind = chipHandle
		handle.Bind = chipHandle
		-- The key + mode persist separately from the toggle's own value, so a saved
		-- config restores "hold B" as well as "on". A chip whose key doesn't
		-- survive a config load is worse than no chip, and nothing now asks the
		-- call site for one — so with no `KeybindFlag` given, derive it from the
		-- toggle's own `Flag` (resolved above). `<flag>_key` is the convention
		-- consumers were already spelling out by hand, so a derived name matches
		-- what's in the configs they've already saved. An explicit `KeybindFlag`
		-- still wins.
		if keyFlag then
			ctx:RegisterFlag(keyFlag, chipHandle, "bind")
		end
	end

	ctx:RegisterAccent(function()
		paint(false)
	end)

	return f.field, handle, true
end

end

__modules['components.Window'] = function(...)
--!strict
-- components/Window.lua — the window shell: titlebar, sidebar, scrolling content,
-- status bar and overlay. Owns the Context, the tab list, notifications and the
-- live accent.
--
-- The ScreenGui is mounted through util/Gui.lua — `opts.Parent` → `gethui()` →
-- `CoreGui` → `PlayerGui`, parented exactly once at whichever wins — and carries
-- a neutral per-load name plus `Gui.Attribute` for identity. It's exposed as
-- `window.ScreenGui` so a host can re-check where it ended up.

local Services = __require("util.Services")

local UserInputService = Services.UserInputService

local Create = __require("util.Create")
local Theme = __require("Theme")
local Tween = __require("util.Tween")
local Icons = __require("Icons")
local Context = __require("util.Context")
local Bind = __require("util.Bind")
local Fade = __require("util.Fade")
local Config = __require("util.Config")
local Asset = __require("util.Asset")
local Log = __require("util.Log")
local Gui = __require("util.Gui")
local Singleton = __require("util.Singleton")
local Tab = __require("components.Tab")
local Notify = __require("components.Notify")
local Splash = __require("components.Splash")
local SettingsPanel = __require("components.Settings")
-- Three slices of the window's API that have nothing to do with its chrome, each
-- installing its own methods onto the `window` table below. This file was 2178
-- lines and eight jobs; these were the three that came out cleanly.
local WindowConfig = __require("components.WindowConfig")
local WindowHud = __require("components.WindowHud")
local WindowState = __require("components.WindowState")

local M = Theme.Metrics

-- Everything `CreateWindow` accepts. Options belonging to a piece that was split
-- out are still declared here, because this is the entry point that receives
-- them: `ConfigFolder` is read by components/WindowConfig.lua, `Hud` by
-- components/WindowHud.lua, `PersistWindow`/`WindowFlag` by
-- components/WindowState.lua. Every option a TAB takes is declared in
-- components/Tab.lua instead — that one Window only forwards.
local WINDOW_SCHEMA: Log.Schema = {
	{ "Title", "string" },
	{ "ToggleKey", "EnumItem" },
	{ "Accent", "Color3" },
	{ "ConfigFolder", "string" },
	{ "LogoRadius", "number" },
	{ "LogoZoom", "number" },
	{ "AllowMultiple", "boolean" },
	{ "Splash", { "boolean", "table" } },
	{ "Hud", { "boolean", "table" } },
	{ "Keybinds", "boolean" },
	{ "OnFlag", "function" },
	{ "OnFlagChanged", "function" },
	{ "PersistWindow", "boolean" },
	{ "WindowFlag", "string" },
	{ "Parent", "Instance" },
	{ "GuiName", "string" },
	{ "Verbose", "boolean" },
}

-- `Window:Bind` — a headless keybind, no control attached.
local BIND_SCHEMA: Log.Schema = {
	{ "Key", "EnumItem" },
	{ "Callback", "function" },
	{ "Mode", "string" },
	{ "Label", "string" },
	{ "Id", "string" },
	{ "Parent", { "string", "table" } },
	{ "Hud", "boolean" },
}

return function(opts: any)
	opts = opts or {}
	local colors = Theme.Colors

	-- Validate the window options up front so a wrong type surfaces here (naming
	-- the field) rather than as a mystery error much later when it's first used.
	Log.check("CreateWindow", opts, WINDOW_SCHEMA)

	-- Console output is off by default (see util/Log.lua): a game scraping
	-- LogService gets a free fingerprint out of every branded line we print. This
	-- is set before anything below can log, so `Verbose = true` still catches the
	-- build stamp and the "already loaded" line.
	if opts.Verbose ~= nil then
		Log.setVerbose(opts.Verbose == true)
	end
	Log.banner()
	Log.info(Config.report)

	-- which key shows/hides the window (where configs live is WindowConfig's)
	local toggleKey: Enum.KeyCode = opts.ToggleKey or Enum.KeyCode.RightShift
	local notificationsEnabled = true
	-- UserInputService connections live past the ScreenGui's lifetime, so they're
	-- tracked here and disconnected by Window:Destroy.
	local connections: { RBXScriptConnection } = {}

	-- ── single instance ───────────────────────────────────────────────────────
	-- Only one Uranium on screen at a time: re-running the loadstring unloads the
	-- window the previous run left behind (util/Singleton.lua — the handle lives
	-- on getgenv()._URANIUM_LOADED so it survives across chunks), then builds
	-- fresh below. That way the loader refreshes the UI instead of stacking a
	-- second copy over the first. `AllowMultiple = true` opts out of both halves.
	local singleton = opts.AllowMultiple ~= true
	local record: any = nil
	if singleton and Singleton.unloadExisting() then
		Log.info("already loaded — unloaded the previous window and refreshing.")
	end

	-- ── ScreenGui + window frame ────────────────────────────────────────────
	-- Neutral, per-load name (`GuiName` pins it) + an attribute for identity: a
	-- fixed brand-shaped name is the cheapest thing in the whole library for a
	-- place to detect, and the singleton sweep that used to need it now matches
	-- the attribute instead. See util/Gui.lua. The frame names below are random
	-- for the same reason — they're direct children, so they're visible to
	-- anything that can see the ScreenGui at all.
	local screenGui = Create("ScreenGui", {
		Name = opts.GuiName or Gui.rname(),
		IgnoreGuiInset = true,
		ResetOnSpawn = false,
		ZIndexBehavior = Enum.ZIndexBehavior.Sibling,
	})

	-- A plain Frame, deliberately. This was a CanvasGroup, because one
	-- GroupTransparency tween fades the whole window for mount / minimize /
	-- close. The cost was invisible in Studio and glaring in game: a CanvasGroup
	-- rasterizes everything inside it into an offscreen buffer, so every label in
	-- the UI was a resampled bitmap instead of SDF text — soft at any size, and
	-- worse the bigger the window got (fullscreen was the worst case). The fade
	-- now runs through util/Fade.lua, which drives the real transparency
	-- properties of the subtree instead. Never put text under a CanvasGroup.
	local main = Create("Frame", {
		Name = Gui.rname(),
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromScale(0.5, 0.5),
		Size = UDim2.fromOffset(M.windowWidth, M.windowHeight),
		BackgroundColor3 = colors.bg,
		ClipsDescendants = true,
		Parent = screenGui,
	}, {
		Create.corner(M.windowRadius),
		Create.stroke(Color3.new(0, 0, 0)),
		Create("UIScale", {}),
	})
	local mainScale = main:FindFirstChildOfClass("UIScale") :: UIScale
	-- Fades the whole window subtree (see the note above): mount, minimize,
	-- restore and close all go through this.
	local mainFade = Fade.new(main)

	-- ── drop shadow ─────────────────────────────────────────────────────────
	-- The reference window floats: `box-shadow: 0 30px 80px -20px rgba(0,0,0,.8)`.
	-- A 9-sliced soft-shadow image behind the window gives it that elevation. It
	-- lives in the ScreenGui (a sibling behind `main`, not a child — `main`
	-- clips, and the shadow has to bleed past the window edges) and tracks the
	-- window as it's dragged / resized.
	-- A *radial* shadow image (one smooth centre→edge gradient) stretched behind
	-- the window. A 9-slice shadow only softens its ~49px border and stretches a
	-- solid core, so it reads as a hard dark band that ends abruptly — this fades
	-- gradually the whole way out instead. Big PAD = the gradient's soft tail is
	-- what shows past the window edge; the dark middle stays hidden behind it.
	local SHADOW_PAD = 60 -- how far the soft tail bleeds past each edge (bigger = more gradual falloff)
	local SHADOW_DROP = 8  -- nudge down so the light reads as coming from above (kept small so the bottom doesn't read heavy)
	local SHADOW_T = 0.82  -- resting image transparency (high = faint, barely-there shadow)
	local shadow = Create("ImageLabel", {
		Name = "Shadow",
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = main.Position,
		Size = UDim2.fromOffset(M.windowWidth + SHADOW_PAD, M.windowHeight + SHADOW_PAD),
		BackgroundTransparency = 1,
		Image = "rbxassetid://1316045217", -- soft radial blur
		ImageColor3 = Color3.new(0, 0, 0),
		ImageTransparency = 1, -- faded in on mount, alongside the window
		ScaleType = Enum.ScaleType.Stretch,
		ZIndex = 0,
		Parent = screenGui,
	})
	local function syncShadow()
		shadow.Position = main.Position + UDim2.fromOffset(0, SHADOW_DROP)
		shadow.Size = UDim2.new(
			main.Size.X.Scale, main.Size.X.Offset + SHADOW_PAD,
			main.Size.Y.Scale, main.Size.Y.Offset + SHADOW_PAD
		)
	end
	main:GetPropertyChangedSignal("Position"):Connect(syncShadow)
	main:GetPropertyChangedSignal("Size"):Connect(syncShadow)

	-- Never exceed the viewport — on small screens the window shrinks to fit
	-- (centered) instead of spilling content off the right/bottom edge. Maximized
	-- goes through the same reconciliation rather than around it (an earlier
	-- version skipped the clamp entirely while maximized, which is how a maximized
	-- window could end up bigger than the screen it was on).
	local maximized = false
	-- The size the window wants to be, which is the theme's until someone says
	-- otherwise (`Window:SetSize`, or a restored `uranium_window` record). It's the
	-- *unclamped* wish: fitWindow below is what actually reconciles it with the
	-- viewport, so a size saved on a big monitor survives a session on a laptop
	-- instead of being permanently shrunk to fit it.
	local baseWidth, baseHeight = M.windowWidth, M.windowHeight
	-- Below this the sidebar and the two columns stop being a layout.
	local MIN_W, MIN_H = 420, 320
	local VIEWPORT_INSET = 24 -- air left around the window at full size
	-- The size the window should be right now, reconciling the wish (`baseWidth`/
	-- `baseHeight`, or "as big as it goes" while maximized) with the viewport.
	--
	-- One function, because the two callers used to spell the same arithmetic out
	-- separately and disagreed: maximize was `math.max(baseWidth, vp.X - 24)`,
	-- which takes the LARGER of the two — so a window whose saved size came off a
	-- bigger monitor maximized to that saved size on a laptop and hung off the
	-- screen, and `fitWindow` then couldn't pull it back because it took the
	-- maximized branch too. The floor belongs at MIN_W/MIN_H (the point below
	-- which the sidebar and two columns stop being a layout), not at whatever the
	-- window happened to be. Returns nil when the viewport hasn't been measured.
	local function targetSize(): UDim2?
		local vp = screenGui.AbsoluteSize
		if vp.X <= 0 or vp.Y <= 0 then
			return nil
		end
		local availW = math.max(MIN_W, vp.X - VIEWPORT_INSET)
		local availH = math.max(MIN_H, vp.Y - VIEWPORT_INSET)
		if maximized then
			return UDim2.fromOffset(availW, availH)
		end
		return UDim2.fromOffset(math.min(baseWidth, availW), math.min(baseHeight, availH))
	end
	local function fitWindow()
		local size = targetSize()
		if size then
			main.Size = size
		end
	end
	screenGui:GetPropertyChangedSignal("AbsoluteSize"):Connect(fitWindow)
	task.defer(fitWindow)

	-- ── titlebar ───────────────────────────────────────────────────────────
	local titlebar = Create("Frame", {
		Name = "Titlebar",
		Size = UDim2.new(1, 0, 0, M.titlebar),
		BackgroundColor3 = colors.chrome,
		Parent = main,
	}, {
		-- Round the top corners to match the window. main's ClipsDescendants
		-- clips to a rectangle (not the rounded shape), so without this the
		-- square chrome corners poke past main's rounded corners.
		Create.corner(M.windowRadius),
		Create("Frame", { -- square off the bottom so only the top corners round
			Name = "SquareFill",
			AnchorPoint = Vector2.new(0, 1),
			Position = UDim2.fromScale(0, 1),
			Size = UDim2.new(1, 0, 0, M.windowRadius),
			BackgroundColor3 = colors.chrome,
			BorderSizePixel = 0,
		}),
		Create("Frame", { -- bottom hairline
			Name = "Border",
			AnchorPoint = Vector2.new(0, 1),
			Position = UDim2.fromScale(0, 1),
			Size = UDim2.new(1, 0, 0, 1),
			BackgroundColor3 = colors.border_soft,
			BorderSizePixel = 0,
		}),
	})

	-- logo — the brand mark, square art rounded off by the holder's UICorner.
	-- `Logo` accepts anything util/Asset.lua resolves (id, url, file path); the
	-- accent square with the brand initial is the fallback while it loads or if
	-- it never resolves (Studio without executor globals, bad id, …).
	local logo = Create("Frame", {
		Name = "Logo",
		Size = UDim2.fromOffset(M.logo, M.logo),
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.new(0, M.sidebar / 2, 0.5, 0),
		BackgroundTransparency = 1,
		ClipsDescendants = true,
		Parent = titlebar,
	}, {
		Create.corner(opts.LogoRadius or Theme.Brand.radius),
	})
	-- The accent square is its own layer under the art rather than the holder's
	-- background, so the async load result can hide it with `Visible` alone.
	-- Writing a transparency from a load callback would fight util/Fade.lua if
	-- the asset happened to arrive mid mount/minimize fade.
	-- The fallback is a mark, not a letter. An accent square with the brand's
	-- initial in it is indistinguishable from "the logo failed to load" — which
	-- is what it *was*, for every client whose executor can't fetch the art (and
	-- for a while, for everyone, because the art URL had gone stale). Lucide's
	-- `atom` is a nucleus crossed by two elliptical orbits: the Uranium mark's own
	-- composition, drawn from a spritesheet the engine fetches itself, so it needs
	-- nothing from the executor. Tinted tile + accent glyph is the `accent_soft`
	-- pattern the active nav button uses. components/Screen.lua does the same.
	local logoSquare = Create("Frame", {
		Name = "Square",
		Size = UDim2.fromScale(1, 1),
		BackgroundColor3 = colors.accent_soft,
		BorderSizePixel = 0,
		Parent = logo,
	}, {
		Create.corner(opts.LogoRadius or Theme.Brand.radius),
	})
	local brandName = opts.Title or Theme.Brand.name
	local logoFallback = Icons.new("atom", 20, colors.accent) :: any
	logoFallback.Name = "Glyph"
	logoFallback.AnchorPoint = Vector2.new(0.5, 0.5)
	logoFallback.Position = UDim2.fromScale(0.5, 0.5)
	logoFallback.Parent = logo
	-- Fit, not Crop: a brand mark must never lose an edge or change proportion.
	-- Fit letterboxes non-square art inside the square holder; the zoom below is
	-- what fills the holder, and it's a scale on both axes so it can't stretch.
	local logoImage = Create("ImageLabel", {
		Name = "Mark",
		BackgroundTransparency = 1,
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromScale(0.5, 0.5),
		Size = UDim2.fromScale(1, 1),
		Image = "",
		ScaleType = Enum.ScaleType.Fit,
		Visible = false,
		Parent = logo,
	}) :: ImageLabel
	-- `zoom` > 1 draws the art oversized inside the clipping holder, trimming a
	-- margin baked into the source (see Theme.Brand.zoom). nil = draw it 1:1.
	local function setLogo(source: any, zoom: number?)
		local z = tonumber(zoom) or 1
		if z <= 0 then
			z = 1
		end
		logoImage.Size = UDim2.fromScale(z, z)
		-- The mark is ALWAYS visible — it has to be, or the engine never fetches
		-- the texture — and it's drawn over the accent square, which stays put as
		-- a backdrop. So the art covers the square when it loads, and if it never
		-- loads you're left with the accent square + initial. Never a hole,
		-- whatever the load check believes.
		logoImage.Visible = true
		logoFallback.Visible = true
		logoSquare.Visible = true
		Asset.load(logoImage, source, function(loaded)
			-- Only the fallback reacts; the image is left alone.
			logoFallback.Visible = not loaded
			logoSquare.Visible = not loaded
			if not loaded and source ~= nil then
				Log.warn("CreateWindow", ("Logo %s hasn't loaded — the fallback mark is showing. "
					.. "Check the id is an image/decal, that it passed moderation, and that "
					.. "it isn't Restricted in Creator Dashboard."):format(tostring(source)))
			end
		end)
	end
	-- `Logo = false` means "no art at all" — keep the accent square + initial.
	-- The built-in mark gets Theme.Brand.zoom (its margin is known); art the
	-- caller supplied is drawn 1:1 unless they ask for a zoom themselves.
	-- Resolved into locals because the splash screen shows the same mark.
	local logoSource: any = nil
	local logoZoom: number? = nil
	if opts.Logo == false then
		logoSource = nil
	elseif opts.Logo ~= nil then
		logoSource, logoZoom = opts.Logo, opts.LogoZoom
	else
		logoSource, logoZoom = Theme.Brand.logo, opts.LogoZoom or Theme.Brand.zoom
	end
	setLogo(logoSource, logoZoom)

	-- Wordmark: uppercase with wide letter-spacing. Roblox has no tracking /
	-- letter-spacing property on TextLabel, so the spacing is literal — a space
	-- between every glyph. A word break becomes three spaces, which still reads
	-- as a wordmark. Short brand names only; that's what a titlebar title is.
	local function wordmark(s: string): string
		local out = {}
		for _, c in utf8.codes(s:upper()) do
			table.insert(out, utf8.char(c))
		end
		return table.concat(out, " ")
	end

	Create("TextLabel", {
		Name = "Title",
		BackgroundTransparency = 1,
		Size = UDim2.fromScale(1, 1),
		Text = wordmark(brandName),
		TextColor3 = colors.text,
		TextSize = 16,
		FontFace = Theme.Font.Bold,
		Parent = titlebar,
	})

	-- Right cluster holds a collapsible search field followed by the window
	-- buttons; the horizontal list keeps them packed against the right edge.
	local rightCluster = Create("Frame", {
		Name = "RightCluster",
		AnchorPoint = Vector2.new(1, 0.5),
		Position = UDim2.new(1, -18, 0.5, 0),
		Size = UDim2.fromOffset(0, M.titlebar),
		AutomaticSize = Enum.AutomaticSize.X,
		BackgroundTransparency = 1,
		Parent = titlebar,
	}, {
		Create.listLayout({
			FillDirection = Enum.FillDirection.Horizontal,
			VerticalAlignment = Enum.VerticalAlignment.Center,
			Padding = UDim.new(0, 14),
		}),
	})

	-- search field — hidden until the search button is clicked. Its width slides
	-- open while the contents fade in together (util/Fade.lua, not a CanvasGroup:
	-- that would blur the text you're typing); ClipsDescendants keeps the
	-- icon/box from spilling out while it's narrower than its content.
	local SEARCH_W = 180
	local searchField = Create("Frame", {
		Name = "Search",
		Visible = false,
		Size = UDim2.fromOffset(SEARCH_W, 30),
		BackgroundColor3 = colors.control,
		ClipsDescendants = true,
		LayoutOrder = 1,
		Parent = rightCluster,
	}, {
		Create.corner(M.controlRadius),
		Create.stroke(colors.border),
		Create.padding(0, 10),
		Create.listLayout({
			FillDirection = Enum.FillDirection.Horizontal,
			VerticalAlignment = Enum.VerticalAlignment.Center,
			Padding = UDim.new(0, 8),
		}),
	})
	local searchIcon = Icons.new("search", 14, colors.text_dim)
	searchIcon.LayoutOrder = 1;
	(searchIcon :: any).Parent = searchField
	local searchBox = Create("TextBox", {
		Name = "Box",
		BackgroundTransparency = 1,
		Size = UDim2.new(1, -22, 1, 0),
		Text = "",
		PlaceholderText = "Search",
		PlaceholderColor3 = colors.text_dim,
		TextColor3 = colors.text,
		TextSize = 13,
		FontFace = Theme.Font.Regular,
