	})

	local clock = Create("TextLabel", {
		Name = "Clock",
		BackgroundTransparency = 1,
		Size = UDim2.fromScale(0.4, 1),
		Text = "—",
		TextColor3 = colors.text_muted,
		TextSize = 12,
		FontFace = Theme.Font.Regular,
		TextXAlignment = Enum.TextXAlignment.Left,
		Parent = status,
	})
	Create("TextLabel", {
		Name = "Subtitle",
		BackgroundTransparency = 1,
		Size = UDim2.fromScale(1, 1),
		Text = opts.Subtitle or "",
		TextColor3 = colors.text_muted,
		TextSize = 12,
		FontFace = Theme.Font.Regular,
		Parent = status,
	})
	Create("TextLabel", {
		Name = "Version",
		BackgroundTransparency = 1,
		AnchorPoint = Vector2.new(1, 0),
		Position = UDim2.fromScale(1, 0),
		Size = UDim2.fromScale(0.4, 1),
		Text = opts.Version or "",
		TextColor3 = colors.text_dim,
		TextSize = 12,
		FontFace = Theme.Font.Mono,
		TextXAlignment = Enum.TextXAlignment.Right,
		Parent = status,
	})

	-- live clock
	task.spawn(function()
		while clock.Parent do
			local t = os.date("*t")
			local h = t.hour % 12
			if h == 0 then
				h = 12
			end
			local ap = t.hour >= 12 and "PM" or "AM"
			clock.Text = ("%d:%02d %s"):format(h, t.min, ap)
			task.wait(10)
		end
	end)

	-- ── overlay (popovers + toasts) ──────────────────────────────────────────
	local overlay = Create("Frame", {
		Name = "Overlay",
		Size = UDim2.fromScale(1, 1),
		BackgroundTransparency = 1,
		ClipsDescendants = false,
		ZIndex = 100,
		Parent = main,
	})
	local toasts = Create("Frame", {
		Name = "Toasts",
		AnchorPoint = Vector2.new(1, 1),
		Position = UDim2.new(1, -16, 1, -46),
		Size = UDim2.fromOffset(260, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		BackgroundTransparency = 1,
		Parent = overlay,
	}, {
		Create.listLayout({
			VerticalAlignment = Enum.VerticalAlignment.Bottom,
			HorizontalAlignment = Enum.HorizontalAlignment.Right,
			Padding = UDim.new(0, 9),
		}),
	})

	local ctx = Context.new(Theme, overlay, opts.Accent or colors.accent)
	-- `Keybinds = false` takes the bind chip off every control that would
	-- otherwise grow one by default (Toggle). A control that asks for a keybind
	-- explicitly still gets it — this is the default, not a ban.
	ctx.Keybinds = opts.Keybinds ~= false

	-- `CreateWindow{ OnFlag = function(name, kind) end }` — installed before a
	-- single control exists, so a loader sees every flag the menu ever registers,
	-- in order, including the ones the built-in Settings tab adds. Fires
	-- synchronously from inside the registration (see Context:OnFlag), which is
	-- what makes "tag this flag with the module I'm building right now" work.
	if opts.OnFlag then
		ctx:OnFlag(opts.OnFlag)
	end

	-- `CreateWindow{ OnFlagChanged = function(name, value, kind, source) end }` —
	-- the same hook as `Window:OnFlagChanged`, installed early enough that a host
	-- persisting continuously catches the first change the menu ever makes,
	-- including ones the built-in Settings tab causes while it builds.
	if opts.OnFlagChanged then
		ctx:OnFlagChanged(opts.OnFlagChanged)
	end

	-- The keybind router (util/Bind.lua): one pair of input listeners shared by
	-- every bound control, created here so its connections are tracked and die
	-- with the window like the toggle-key listener below.
	local binds = Bind.get(ctx)
	for _, conn in binds.connections do
		table.insert(connections, conn)
	end

	-- The fallback mark is only on screen when the art hasn't loaded, but it still
	-- has to track SetAccent for that case — the tile off `ctx.AccentSoft`, the
	-- glyph off the accent itself, both derived on the Context so the ramp is
	-- never recomputed here.
	ctx:RegisterAccent(function(accent)
		logoSquare.BackgroundColor3 = ctx.AccentSoft
		Icons.tint(logoFallback, accent)
	end)

	-- ── titlebar dragging ────────────────────────────────────────────────────
	local dragging, dragStart, startPos
	titlebar.InputBegan:Connect(function(input)
		if input.UserInputType == Enum.UserInputType.MouseButton1
			or input.UserInputType == Enum.UserInputType.Touch then
			dragging = true
			dragStart = input.Position
			startPos = main.Position
		end
	end)
	-- Keep the window reachable: a drag can't push the titlebar off the top or
	-- shove the window so far past an edge that there's nothing left to grab.
	local KEEP_ON_SCREEN = 80
	local function clampToViewport(pos: UDim2): UDim2
		local vp = screenGui.AbsoluteSize
		local size = main.AbsoluteSize
		if vp.X <= 0 or size.X <= 0 then
			return pos
		end
		local halfX, halfY = size.X / 2, size.Y / 2
		local cx = pos.X.Scale * vp.X + pos.X.Offset
		local cy = pos.Y.Scale * vp.Y + pos.Y.Offset
		cx = math.clamp(cx, KEEP_ON_SCREEN - halfX, vp.X - KEEP_ON_SCREEN + halfX)
		cy = math.clamp(cy, halfY, math.max(halfY, vp.Y - KEEP_ON_SCREEN + halfY))
		return UDim2.new(
			pos.X.Scale, cx - pos.X.Scale * vp.X,
			pos.Y.Scale, cy - pos.Y.Scale * vp.Y
		)
	end

	-- Whole-pixel snapping — the other half of the "why is the text soft" answer
	-- (util/Fade.lua has the first half). The window is centered with a *scale*
	-- position and AnchorPoint (0.5, 0.5), so its top-left lands on a half pixel
	-- whenever the viewport or the window has an odd dimension — and then every
	-- glyph in the UI is rasterized half a pixel off the display grid, which
	-- reads as a soft, faintly smeared version of the same text. Rounding the
	-- top-left costs nothing and puts the whole tree back on integer coordinates.
	local function snapToPixels(pos: UDim2): UDim2
		local vp = screenGui.AbsoluteSize
		local size = main.AbsoluteSize
		if vp.X <= 0 or size.X <= 0 then
			return pos
		end
		local left = pos.X.Scale * vp.X + pos.X.Offset - size.X / 2
		local top = pos.Y.Scale * vp.Y + pos.Y.Offset - size.Y / 2
		return UDim2.new(
			pos.X.Scale, pos.X.Offset + (math.round(left) - left),
			pos.Y.Scale, pos.Y.Offset + (math.round(top) - top)
		)
	end
	-- Re-snap whenever the geometry moves under us: viewport resize, the fit
	-- clamp, maximize. (Setting Position can't change AbsoluteSize, so this
	-- can't feed itself.)
	local function resnap()
		main.Position = snapToPixels(main.Position)
	end
	-- The window's LAYOUT size, which is not `main.AbsoluteSize`: that one is run
	-- through the UIScale, which sits at 0.92 through the mount animation and 0.9
	-- the whole time the window is minimized. Reading the rendered size in those
	-- states and writing it back later restores the window a few percent off
	-- centre — so every geometry read below uses the size the layout actually
	-- asked for. `fitWindow` / `setMaximized` only ever set pure offsets, so the
	-- two halves of the UDim2 are the answer.
	local function layoutSize(): Vector2
		return Vector2.new(main.Size.X.Offset, main.Size.Y.Offset)
	end

	-- The window's TOP-LEFT in screen pixels — the only coordinate worth
	-- persisting, since the live Position is a scale/offset pair carrying whatever
	-- the drag left in it and its numbers mean nothing on a viewport of another
	-- size.
	local function topLeft(): Vector2
		local vp = screenGui.AbsoluteSize
		local pos, size = main.Position, layoutSize()
		return Vector2.new(
			pos.X.Scale * vp.X + pos.X.Offset - size.X / 2,
			pos.Y.Scale * vp.Y + pos.Y.Offset - size.Y / 2
		)
	end

	-- The exact inverse of `topLeft`. The scale halves are preserved rather than
	-- flattened to pure offsets, so a restored window keeps tracking the viewport
	-- exactly like a dragged one does, and the same clamp a drag goes through
	-- guarantees a record saved on a 1440p monitor can't put the window off a
	-- laptop screen.
	local function moveTo(x: number, y: number)
		local vp = screenGui.AbsoluteSize
		local size = layoutSize()
		if vp.X <= 0 or size.X <= 0 then
			return
		end
		local pos = main.Position
		local cx, cy = x + size.X / 2, y + size.Y / 2
		main.Position = snapToPixels(clampToViewport(UDim2.new(
			pos.X.Scale, cx - pos.X.Scale * vp.X,
			pos.Y.Scale, cy - pos.Y.Scale * vp.Y
		)))
	end
	main:GetPropertyChangedSignal("AbsoluteSize"):Connect(resnap)
	screenGui:GetPropertyChangedSignal("AbsoluteSize"):Connect(resnap)
	task.defer(resnap)

	table.insert(connections, UserInputService.InputChanged:Connect(function(input)
		if dragging and (input.UserInputType == Enum.UserInputType.MouseMovement
			or input.UserInputType == Enum.UserInputType.Touch) then
			local delta = input.Position - dragStart
			main.Position = snapToPixels(clampToViewport(UDim2.new(
				startPos.X.Scale, startPos.X.Offset + delta.X,
				startPos.Y.Scale, startPos.Y.Offset + delta.Y
			)))
		end
	end))
	table.insert(connections, UserInputService.InputEnded:Connect(function(input)
		if input.UserInputType == Enum.UserInputType.MouseButton1
			or input.UserInputType == Enum.UserInputType.Touch then
			local wasDragging = dragging
			dragging = false
			-- On RELEASE, not per frame: the position is part of the persisted window
			-- record, and a host writing on every change would otherwise write once
			-- per mouse move for the length of the drag.
			if wasDragging then
				ctx:User(function()
					ctx:WindowStateChanged()
				end)
			end
		end
	end))

	-- ── public API ───────────────────────────────────────────────────────────
	local tabs = {}
	local activeIndex = 1
	local window = {}
	-- The ScreenGui itself, exposed so a host can re-check where it landed (and
	-- re-parent or re-protect it): the parent is resolved at mount time from
	-- whatever the executor offers, so it isn't knowable up front. Also on the
	-- singleton record.
	window.ScreenGui = screenGui
	local applySearch -- forward declaration (used by select)
	local splash: any = nil -- the boot screen, while it's playing (see the mount)

	-- ── the installed halves ──────────────────────────────────────────────────
	-- `CreateHud` / `GetHud` / `SetHudVisible` / `OnHudVisible` / `OnHudChanged`
	-- (components/WindowHud.lua) and the whole flag + config surface
	-- (components/WindowConfig.lua) are installed onto `window` here. Both are
	-- built before a single tab exists: `CreateWindow{ OnFlag }` has to see every
	-- flag the menu ever registers, and `Hud = true` builds one below.
	--
	-- The window-state flag (components/WindowState.lua) is registered further
	-- down instead, once the geometry helpers it depends on exist.
	local hudApi = WindowHud(window, ctx, screenGui, opts)
	local configApi = WindowConfig(window, ctx, opts)

	local searchOpen = false
	local function currentQuery(): string
		return searchOpen and searchBox.Text or ""
	end

	local function select(index: number)
		activeIndex = index
		-- Popovers live in the overlay, not in the page, so an open dropdown would
		-- otherwise hang around over the tab you just switched to.
		ctx:ClosePopover()
		for i, tab in tabs do
			tab:_setActive(i == index)
		end
		content.CanvasPosition = Vector2.new(0, 0)
		applySearch(currentQuery()) -- keep the filter consistent across tabs
	end

	-- Selecting a tab *deliberately* — a click, `Window:Select`, `tab:Select`. The
	-- plain `select` above is also how the window picks a tab for itself while it
	-- builds (the first tab, or a fallback when the open one is hidden), and
	-- announcing those as window-state changes would report the menu's own
	-- construction as a run of edits worth persisting.
	local function chooseTab(index: number)
		select(index)
		ctx:WindowStateChanged()
	end

	-- ── search ────────────────────────────────────────────────────────────────
	-- The filtering itself is `tab:Filter(query)` (components/Tab.lua). It used to
	-- live here and re-derive the page's entire shape from instance names on every
	-- keystroke — which put Tab's and Group's layout into this file, where a
	-- rename over there would have silently filtered nothing. All that's left here
	-- is the box and which tab is showing.
	applySearch = function(query: string)
		local tab = tabs[activeIndex]
		if tab then
			tab:Filter(query)
		end
	end

	searchBox:GetPropertyChangedSignal("Text"):Connect(function()
		applySearch(searchBox.Text)
	end)
	winBtns.search.Activated:Connect(function()
		searchOpen = not searchOpen
		if searchOpen then
			-- Drop every tab's collected-text cache: opening the box is the one
			-- moment the menu can have grown or lost controls since the last search,
			-- and it's the cheapest possible invalidation point (once, off the typing
			-- path). All tabs, not just the active one — switching tabs mid-search
			-- filters the new page without reopening the box.
			for _, tab in tabs do
				tab:ResetFilter()
			end
			-- slide + fade open from a zero-width sliver, then focus the box
			searchField.Visible = true
			searchField.Size = UDim2.fromOffset(0, 30)
			searchFade:Set(1)
			Tween.play(searchField, Tween.Slide, { Size = UDim2.fromOffset(SEARCH_W, 30) })
			searchFade:To(Tween.Slide, 0)
			searchBox:CaptureFocus()
		else
			searchBox.Text = "" -- fires the Text signal → clears the filter
			-- slide + fade closed, then hide once it's fully collapsed
			Tween.play(searchField, Tween.Slide, { Size = UDim2.fromOffset(0, 30) })
			searchFade:To(Tween.Slide, 1, function()
				if not searchOpen then
					searchField.Visible = false
				end
			end)
		end
	end)

	-- ── minimize / restore (toggle key) ────────────────────────────────────────
	local restoreHint = Create("Frame", {
		Name = "MinimizedHint",
		Visible = false,
		AnchorPoint = Vector2.new(1, 1),
		Position = UDim2.new(1, -16, 1, -16),
		Size = UDim2.fromOffset(220, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		BackgroundColor3 = colors.pop,
		Parent = screenGui,
	}, {
		Create.corner(9),
		Create.stroke(colors.border),
		Create.padding(11, 14),
		Create.listLayout({ Padding = UDim.new(0, 3) }),
	})
	Create("TextLabel", {
		Name = "Title",
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		Text = "UI Minimized",
		TextColor3 = colors.text,
		TextSize = 13,
		FontFace = Theme.Font.Medium,
		TextXAlignment = Enum.TextXAlignment.Left,
		LayoutOrder = 1,
		Parent = restoreHint,
	})
	-- What the minimized card says. `CreateWindow{ ToggleKey = Enum.KeyCode.Unknown }`
	-- is a legal way to say "no toggle key", and building the label inline printed
	-- the literal "Press None to show it again." for it — a window with no way back
	-- telling the user to press a key that doesn't exist. SetToggleKey already had
	-- the right wording; this is the same answer at build time.
	local function hintText(): string
		if toggleKey == nil or toggleKey == Enum.KeyCode.Unknown then
			return "Re-bind a toggle key to show it again."
		end
		return ("Press %s to show it again."):format(Bind.name(toggleKey))
	end
	local restoreHintText = Create("TextLabel", {
		Name = "Text",
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		Text = hintText(),
		TextColor3 = colors.text_muted,
		TextSize = 12,
		FontFace = Theme.Font.Regular,
		TextXAlignment = Enum.TextXAlignment.Left,
		TextWrapped = true,
		LayoutOrder = 2,
		Parent = restoreHint,
	})

	local minimized = false
	-- Nav flyouts don't get a MouseLeave when the window vanishes from under the
	-- cursor, so hiding/unloading drops them explicitly (see Tab:_hideFlyout).
	local function hideFlyouts()
		for _, tab in tabs do
			tab:_hideFlyout()
		end
	end
	local function setMinimized(value: boolean)
		minimized = value
		if value then
			hideFlyouts()
			-- shrink + fade the whole window away together, then hide it once the
			-- fade has fully played (no abrupt cut — it's already invisible).
			Tween.play(mainScale, Tween.MenuOut, { Scale = 0.9 })
			Tween.play(shadow, Tween.MenuOut, { ImageTransparency = 1 })
			mainFade:To(Tween.MenuOut, 1, function()
				if minimized then
					main.Visible = false
				end
			end)
			restoreHint.Visible = true
		else
			-- restore from the shrunk/faded state: pop the scale, ease the fade in
			main.Visible = true
			mainScale.Scale = 0.9
			-- Rest first so the hide's snapshot is released: anything built while the
			-- window was minimized isn't in it, and would pop in fully opaque against
			-- a subtree that's still fading. Set(0) puts the old instances back at
			-- their own resting transparencies and drops the cache, so the Set(1)
			-- below re-reads the tree as it is now.
			mainFade:Set(0)
			mainFade:Set(1)
			Tween.play(mainScale, Tween.Pop, { Scale = 1 })
			mainFade:To(Tween.Normal, 0)
			Tween.play(shadow, Tween.Normal, { ImageTransparency = SHADOW_T })
			restoreHint.Visible = false
		end
	end
	winBtns.min.Activated:Connect(function()
		setMinimized(true)
	end)
	-- The toggle key hides AND restores (a single press flips the window's state),
	-- ignored while the player is typing into a textbox / capturing a keybind.
	table.insert(connections, UserInputService.InputBegan:Connect(function(input, gameProcessed)
		if gameProcessed or ctx:IsCapturing() then
			return -- typing in a textbox, or a Keybind is listening for this press
		end
		-- Compare against `Bind.of`, not `input.KeyCode`: a mouse press reports
		-- KeyCode.Unknown, so a toggle key bound to MB2/MB3 (which the Settings
		-- tab's chip happily captures) matched nothing and left the window with no
		-- way to be shown again — silently, since the chip still read "MB2".
		local pressed = Bind.of(input)
		if pressed ~= nil and toggleKey ~= Enum.KeyCode.Unknown and pressed == toggleKey then
			-- Defensive: if anything disabled the ScreenGui, flipping the minimize
			-- state would just toggle an invisible window and the UI would look
			-- permanently gone. Re-enable it instead. (Close no longer takes this
			-- path — it destroys the ScreenGui outright.)
			if not screenGui.Enabled then
				-- Run the real restore rather than hand-setting the flags: if the window
				-- was minimized when the ScreenGui went dark, mainFade is parked at
				-- alpha 1 and mainScale at 0.9, so flipping Visible alone hands back a
				-- window that is present and completely invisible — and leaves
				-- `minimized` reading false, which cost two more presses to sort out.
				screenGui.Enabled = true
				minimized = true
				setMinimized(false)
				return
			end
			setMinimized(not minimized)
		end
	end))

	-- ── maximize toggle ─────────────────────────────────────────────────────────
	-- `animate = false` snaps, which is what restoring a saved record wants — the
	-- window shouldn't play the maximize animation for a state the user set in a
	-- previous session.
	local function setMaximized(value: boolean, animate: boolean?)
		value = value == true
		if value == maximized then
			return
		end
		maximized = value
		local size = targetSize()
		if size then
			if animate == false then
				main.Size = size
			else
				Tween.play(main, Tween.Normal, { Size = size })
			end
		end
		ctx:WindowStateChanged()
	end
	winBtns.max.Activated:Connect(function()
		ctx:User(function()
			setMaximized(not maximized)
		end)
	end)

	-- ── close ────────────────────────────────────────────────────────────────
	-- Close is a real unload, not a hide: same shrink+fade as minimize, but the
	-- listeners come off, the ScreenGui is destroyed and the singleton slot is
	-- freed. Use the minimize button (or the toggle key) to stash it temporarily.
	winBtns.close.Activated:Connect(function()
		window:Destroy()
	end)

	function window:CreateTab(tabOpts: any)
		if tabOpts ~= nil and type(tabOpts) ~= "table" then
			Log.fail("CreateTab", ("options must be a table like { Name = ..., Icon = ... }, got %s"
				.. " — if you meant a title, write CreateTab({ Name = %s })")
				:format(typeof(tabOpts), type(tabOpts) == "string" and ('"%s"'):format(tabOpts) or "..."))
		end
		-- The option SHAPE is components/Tab.lua's to declare and check (its
		-- `SCHEMA`), since it's the file that reads every one of them. Only the
		-- "you passed something that isn't an options table at all" case is caught
		-- here, because that one has to be caught before the table is indexed.
		--
		-- `any`: the handle grows a Select method below, and the hooks the tab
		-- exposes for us are deliberately untyped.
		local tab: any = Tab(ctx, tabOpts or {})
		tab.page.Parent = content

		-- Inset the page explicitly and size it to the scroll area's *visible*
		-- width (AbsoluteWindowSize excludes the scrollbar). This guarantees the
		-- right column keeps its margin regardless of executor quirks.
		tab.page.Position = UDim2.fromOffset(CONTENT_PAD_X, 0)
		local function fitPage()
			local avail = content.AbsoluteWindowSize.X
			if avail <= 0 then
				avail = content.AbsoluteSize.X
			end
			tab.page.Size = UDim2.new(0, math.max(0, avail - CONTENT_PAD_X * 2), 0, 0)
		end
		content:GetPropertyChangedSignal("AbsoluteSize"):Connect(fitPage)
		content:GetPropertyChangedSignal("AbsoluteWindowSize"):Connect(fitPage)
		task.defer(fitPage)

		local index = #tabs + 1
		-- ×10 so a tab's separator hairline can be ordered just above its button
		-- (order*10 - 1) without colliding with the tab before it. `Order` overrides
		-- creation order, for a menu that builds its tabs in a different sequence
		-- from the one it wants them shown in.
		local order = tab.order or index
		tab.button.LayoutOrder = order * 10
		if tab.separator then
			tab.separator.LayoutOrder = order * 10 - 1
		end

		-- Mount into the cluster its Pin asked for; `tab:SetPin` re-runs this,
		-- since the nav frames live here and the tab can't reach them itself.
		local function mountNav(pin: string)
			local cluster = navFor(pin)
			tab.button.Parent = cluster
			if tab.separator then
				tab.separator.Parent = cluster
			end
		end
		mountNav(tab.pin)
		tab._onPin = mountNav

		table.insert(tabs, tab)
		tab.button.Activated:Connect(function()
			ctx:User(chooseTab, index)
		end)
		function tab:Select()
			chooseTab(index)
		end

		-- Hiding the tab that's currently open would otherwise leave its page on
		-- screen with nothing in the sidebar selected, so fall through to the next
		-- visible tab (and re-open this one if it comes back while it's the active
		-- index).
		tab._onVisible = function(visible: boolean)
			if visible then
				-- Claim the selection when it's ours OR when nothing visible holds it —
				-- hiding the last visible tab leaves activeIndex pointing at a hidden
				-- one, and without this second case revealing a *different* tab would
				-- leave the window blank.
				local active = tabs[activeIndex]
				if activeIndex == index or not (active and active:IsVisible()) then
					select(index)
				end
				return
			end
			if activeIndex ~= index then
				return
			end
			for i, other in tabs do
				if i ~= index and other:IsVisible() then
					select(i)
					return
				end
			end
			tab:_setActive(false) -- nothing left to show
		end

		if index == 1 then
			select(1)
		end
		-- Routed through SetVisible rather than hiding the button here, so a tab
		-- built hidden takes the same "select something else" path as one hidden
		-- later (a game-specific tab that only appears in the games it supports).
		if tabOpts and tabOpts.Visible == false then
			tab:SetVisible(false)
		end
		-- ...which is also why the selection is re-checked here rather than only on
		-- `index == 1`: a first tab built hidden ran select(1) above and then hid
		-- itself, and tab 2 never claimed the empty slot — the window opened blank,
		-- with a sidebar showing no active tab. Any tab that arrives while nothing
		-- visible is selected takes the slot.
		local active = tabs[activeIndex]
		if tab:IsVisible() and not (active and active:IsVisible()) then
			select(index)
		end
		return tab
	end

	function window:Select(index: number)
		if type(index) ~= "number" or index < 1 or index > #tabs or index % 1 ~= 0 then
			Log.warn("Select", ("no tab #%s (there %s %d tab%s) — ignoring.")
				:format(tostring(index), #tabs == 1 and "is" or "are", #tabs, #tabs == 1 and "" or "s"))
			return
		end
		chooseTab(index)
	end

	-- Which tab is open, 1-based — the read that makes "restore the menu where the
	-- user left it" expressible at all, whether the window persists it itself or a
	-- host rolls its own record.
	function window:GetSelected(): number
		return activeIndex
	end

	function window:Notify(notifyOpts: any)
		if notifyOpts ~= nil and type(notifyOpts) ~= "table" then
			Log.fail("Notify", ("options must be a table like { Title = ..., Text = ... }, got %s")
				:format(typeof(notifyOpts)))
		end
		if not notificationsEnabled then
			return
		end
		Notify(ctx, toasts, notifyOpts)
	end

	-- Swap the brand mark at runtime — same source types as the Logo option
	-- (asset id, https url, local file path). `zoom` crops a margin baked into
	-- the art (see Theme.Brand.zoom); omit it and the art is drawn 1:1.
	function window:SetLogo(source: any, zoom: number?)
		setLogo(source, zoom)
	end

	function window:SetAccent(color: Color3)
		if typeof(color) ~= "Color3" then
			Log.fail("SetAccent", ("expects a Color3, got %s (try Color3.fromHex(\"7be04a\"))")
				:format(typeof(color)))
		end
		ctx:SetAccent(color)
	end

	-- The live accent. A host building its own settings panel needs it to seed a
	-- colour picker with what the window is actually wearing.
	function window:GetAccent(): Color3
		return ctx.Accent
	end

	-- ── settings: theme / keybind / notifications ─────────────────────────────
	function window:SetToggleKey(key: Enum.KeyCode)
		if key ~= nil and typeof(key) ~= "EnumItem" then
			Log.fail("SetToggleKey", ("expects an Enum.KeyCode, got %s (try Enum.KeyCode.RightShift)")
				:format(typeof(key)))
		end
		toggleKey = key or Enum.KeyCode.Unknown
		restoreHintText.Text = hintText()
	end

	function window:GetToggleKey(): Enum.KeyCode
		return toggleKey
	end

	function window:SetNotificationsEnabled(enabled: boolean)
		notificationsEnabled = enabled ~= false
	end

	function window:GetNotificationsEnabled(): boolean
		return notificationsEnabled
	end

	-- ── settings: headless keybinds ───────────────────────────────────────────
	-- A bind with no control attached, for logic the menu doesn't expose:
	--   Window:Bind(Enum.KeyCode.B, function(on) ... end, "Hold")
	--   Window:Bind({ Key = Enum.KeyCode.B, Mode = "Toggle", Callback = fn })
	-- Returns the binding — :SetKey / :SetMode / :GetState / :Destroy. It rides
	-- the same router as the controls, so it honours gameProcessed and pauses
	-- while a Keybind chip is capturing.
	--
	-- Give it a `Label` to have it listed in the bind HUD; without one it's
	-- treated as internal plumbing and stays out (there'd be nothing to call it).
	-- `Parent = "<feature>"` makes it a sub-option of another bind, which keeps it
	-- out of that list while it's merely on (util/Bind.lua's tree).
	function window:Bind(keyOrOpts: any, callback: any, mode: any): any
		local o = keyOrOpts
		if typeof(keyOrOpts) == "EnumItem" then
			o = { Key = keyOrOpts, Callback = callback, Mode = mode }
		elseif type(keyOrOpts) ~= "table" then
			Log.fail("Bind", ("expects a key or an options table, got %s (try Window:Bind(Enum.KeyCode.B, fn, \"Hold\"))")
				:format(typeof(keyOrOpts)))
		end
		Log.check("Bind", o, BIND_SCHEMA)
		return binds:Register(o)
	end

	-- ── settings: window geometry + UI state ──────────────────────────────────
	-- Where the window is, how big it is, which tab is open and which groups are
	-- folded — all of it state the user set with the mouse, none of it readable
	-- until now, so "put the menu back where I left it" wasn't expressible by
	-- anyone, library or host.
	--
	-- Position is the window's TOP-LEFT in screen pixels, matching the HUD's
	-- convention. Setting it clamps the same way a drag does, so a coordinate from
	-- a bigger monitor can't strand the window off-screen.
	function window:GetPosition(): Vector2
		return topLeft()
	end

	function window:SetPosition(x: number, y: number)
		local px, py = tonumber(x), tonumber(y)
		if not px or not py then
			Log.warn("SetPosition", ("expects two numbers (x, y), got %s, %s — ignoring.")
				:format(typeof(x), typeof(y)))
			return
		end
		moveTo(px, py)
		ctx:WindowStateChanged()
	end

	-- The size the window is actually drawn at. `SetSize` sets the size it *wants*
	-- — it's still clamped to the viewport (and overridden while maximized), so a
	-- laptop session doesn't permanently shrink a size set on a bigger screen.
	function window:GetSize(): Vector2
		return layoutSize()
	end

	function window:SetSize(width: number, height: number)
		local w, h = tonumber(width), tonumber(height)
		if not w or not h then
			Log.warn("SetSize", ("expects two numbers (width, height), got %s, %s — ignoring.")
				:format(typeof(width), typeof(height)))
			return
		end
		baseWidth = math.max(MIN_W, math.floor(w))
		baseHeight = math.max(MIN_H, math.floor(h))
		fitWindow()
		ctx:WindowStateChanged()
	end

	function window:IsMaximized(): boolean
		return maximized
	end

	function window:SetMaximized(value: boolean, animate: boolean?)
		setMaximized(value ~= false, animate)
	end

	-- ── the window-state flag ─────────────────────────────────────────────────
	-- `uranium_window` — position, size, maximize, the open tab and every folded
	-- group, in one flag. It lives in components/WindowState.lua and reaches back
	-- in here through this table: a restore has to move real geometry, and that's
	-- the one thing about the window a config can drive. Everything it's handed is
	-- behaviour, never state, so it can't read a field it wasn't given.
	--
	-- `select` is the PLAIN one, not `chooseTab`: restoring a saved record is not
	-- a run of deliberate tab clicks, and announcing it as one would report the
	-- restore back as a fresh change worth persisting.
	WindowState(ctx, opts, {
		topLeft = topLeft,
		wantedSize = function(): Vector2
			return Vector2.new(baseWidth, baseHeight)
		end,
		setSize = function(w: number, h: number)
			window:SetSize(w, h)
		end,
		moveTo = moveTo,
		setMaximized = setMaximized,
		isMaximized = function(): boolean
			return maximized
		end,
		viewportWidth = function(): number
			return screenGui.AbsoluteSize.X
		end,
		tabs = function(): { any }
			return tabs
		end,
		selected = function(): number
			return activeIndex
		end,
		select = select,
	})


	-- ── teardown ───────────────────────────────────────────────────────────────
	-- Full unload: the lingering UserInputService listeners come off, the popover
	-- overlay closes, the singleton slot is freed and the ScreenGui is destroyed.
	-- This is what both the close button and the Settings tab's Unload run.
	--
	-- The listeners are disconnected UP FRONT rather than in the tween callback —
	-- during the ~0.16s fade the window is on its way out, and a toggle-key press
	-- landing in that gap would otherwise "restore" a window about to be deleted.
	-- `immediate` skips the fade entirely (used when a re-run is unloading us to
	-- take our place — the new window shouldn't wait on the old one's animation).
	local destroyed = false
	function window:Destroy(immediate: boolean?)
		if destroyed then
			return
		end
		destroyed = true
		for _, conn in connections do
			conn:Disconnect()
		end
		table.clear(connections)
		binds:Destroy() -- drops every registered binding with the listeners
		ctx:ClosePopover()
		hideFlyouts()
		Singleton.release(record)
		if splash then
			splash:Destroy() -- torn down mid-boot: don't leave the splash on screen
			splash = nil
		end
		-- The HUD's own input listeners outlive the ScreenGui, same as ours.
		hudApi.Destroy()

		if immediate then
			screenGui:Destroy()
			return
		end
		Tween.play(mainScale, Tween.MenuOut, { Scale = 0.9 })
		Tween.play(shadow, Tween.MenuOut, { ImageTransparency = 1 })
		mainFade:To(Tween.MenuOut, 1, function()
			screenGui:Destroy()
		end)
	end

	-- ── built-in Settings tab ───────────────────────────────────────────────────
	-- A drop-in panel: accent color, the toggle keybind, a notifications switch,
	-- and full config save / load / delete + auto-load. Call it LAST so the
	-- auto-load pass sees every flagged control your other tabs registered.
	--
	-- Returns `tab, controls` — the second value is every handle the panel built
	-- (`controls.List`, `.Name`, `.AutoLoad`, `.Accent`, `.Hud`, `.Refresh`, …).
	-- They used to be locals in this closure, which left a host unable to refresh
	-- the saved-config list after its own write, read what was selected, or put its
	-- own button next to it. Also on `tab.Controls`, for callers that want one value.
	--
	-- `Sections = { Config = false }` drops a section; the groups themselves are
	-- public (components/Settings.lua → `Uranium.Settings`) so a host can compose
	-- its own settings tab out of the parts it wants.
	function window:CreateSettingsTab(settingsOpts: any?): (any, any)
		settingsOpts = settingsOpts or {}
		if type(settingsOpts) ~= "table" then
			Log.fail("CreateSettingsTab", ("options must be a table like { Pin = \"bottom\" }, got %s")
				:format(typeof(settingsOpts)))
		end
		Log.field("CreateSettingsTab", "Sections", settingsOpts.Sections, "table")
		Log.field("CreateSettingsTab", "Notify", settingsOpts.Notify, "boolean")
		Log.infof("CreateSettingsTab: building (config supported=%s)", tostring(Config.supported))
		-- Every CreateTab option is forwarded, so the settings tab can be pinned
		-- away from the feature tabs (`CreateSettingsTab{ Pin = "bottom" }`) or
		-- given its own colour like any other. Defaults are unchanged: top of the
		-- rail, window accent.
		local tab = window:CreateTab({
			Name = settingsOpts.Name or "Settings",
			Icon = settingsOpts.Icon or "gear",
			Desc = settingsOpts.Desc,
			Badge = settingsOpts.Badge,
			Pin = settingsOpts.Pin,
			Style = settingsOpts.Style,
			Color = settingsOpts.Color,
			Dot = settingsOpts.Dot,
			Rail = settingsOpts.Rail,
			Separator = settingsOpts.Separator,
			Order = settingsOpts.Order,
		})

		-- The panel itself lives in components/Settings.lua, built entirely on this
		-- window's public API — which is what makes the same groups reusable from a
		-- host's own tab (Uranium.Settings.ConfigGroup(window, tab)).
		local controls = SettingsPanel.build(window, tab, settingsOpts)
		tab.Controls = controls

		local flagCount = 0
		for _ in ctx.Flags do
			flagCount += 1
		end
		Log.infof("CreateSettingsTab: done (%d flags registered)", flagCount)
		return tab, controls
	end

	-- ── bind HUD ──────────────────────────────────────────────────────────────
	-- Opt-in, like the splash: `Hud = true` (or a table of overrides). Built here,
	-- before the caller has created a single control — it fills itself in from the
	-- bind registry as the binds are registered, so ordering doesn't matter.
	if opts.Hud ~= nil and opts.Hud ~= false then
		window:CreateHud()
	end

	-- mount — pop the window in from a touch smaller and faded so it eases in
	-- rather than just appearing.
	--
	-- It's hidden with `Visible` (not a fade) until then, because the fade has to
	-- snapshot the window's resting transparencies and the caller hasn't built
	-- its tabs yet — this runs on a deferred pass, by which point the whole tree
	-- exists and the snapshot covers it.
	mainScale.Scale = 0.92
	main.Visible = false
	syncShadow()
	local function mountWindow()
		if destroyed then
			return -- unloaded while the splash was still playing
		end
		main.Visible = true
		mainFade:Set(1)
		Tween.play(mainScale, Tween.Pop, { Scale = 1 })
		mainFade:To(Tween.Normal, 0)
		Tween.play(shadow, Tween.Normal, { ImageTransparency = SHADOW_T })
	end

	-- ── boot splash ────────────────────────────────────────────────────────────
	-- `Splash = true` (or a table of overrides) plays components/Splash.lua first
	-- and mounts the window when it's on its way out. The window is built either
	-- way — the caller's tabs populate it while the splash is up — it's just kept
	-- hidden, so nothing about the rest of the API changes. Off by default: a
	-- boot screen on every re-run of a loader that doesn't want one is a tax.
	local splashOpts = opts.Splash
	if splashOpts ~= nil and splashOpts ~= false then
		local so: any = type(splashOpts) == "table" and splashOpts or {}
		-- The splash shows the window's mark unless it's given one of its own;
		-- its own art brings its own zoom (a different source, a different crop).
		local splashLogo, splashZoom = logoSource, logoZoom
		if so.Logo ~= nil then
			splashLogo, splashZoom = so.Logo, so.LogoZoom
		elseif so.LogoZoom ~= nil then
			splashZoom = so.LogoZoom
		end
		main.Visible = false
		splash = Splash(ctx, screenGui, {
			Title = so.Title or brandName,
			Subtitle = so.Subtitle or opts.Subtitle,
			Logo = splashLogo,
			LogoZoom = splashZoom,
			LogoRadius = so.LogoRadius,
			Duration = so.Duration,
			Dim = so.Dim,
			Steps = so.Steps,
		})
		splash:Play(function()
			splash = nil -- it fades itself out from here; the window takes over
			mountWindow()
		end)
	else
		task.defer(mountWindow)
	end

	-- Mount LAST, and exactly once. This used to go straight to PlayerGui, which
	-- any LocalScript in the place can walk; `Gui.mount` runs protect_gui where
	-- the executor has it and then picks the most hidden container available —
	-- opts.Parent → gethui() → CoreGui → PlayerGui. Parenting somewhere first and
	-- moving it after would leave a frame where the place can see us, so there's
	-- one write, at the resolved target.
	local guiParent, guiParentLabel = Gui.mount(screenGui, opts.Parent)
	if guiParent then
		Log.infof("mounted into %s", guiParentLabel)
	else
		Log.warn("CreateWindow", "no GUI container available (no gethui, CoreGui or PlayerGui) — the window is built but not on screen")
	end

	-- Claim the global slot LAST, once this window is actually on screen — the
	-- next run of the loadstring finds this record and unloads us before it
	-- builds. `Unload` tears down without the fade: the replacement window is
	-- already being built and shouldn't overlap the outgoing one.
	--
	-- ...but not if we were torn down on the way here. `Destroy` can land during
	-- construction — a host's `OnFlag` watcher, a tab `Callback`, another chunk
	-- running `Uranium:Unload()` while this one is still building — and it calls
	-- `Singleton.release(record)` with `record` still nil, so it can't unclaim a
	-- slot that hadn't been claimed yet. Claiming anyway parked a record pointing
	-- at a destroyed window in the shared env, after which `IsLoaded()` reported a
	-- window that isn't there and the next loader run "unloaded" a corpse instead
	-- of finding nothing.
	if singleton and not destroyed then
		record = Singleton.claim({
			Name = Theme.Brand.name,
			Window = window,
			ScreenGui = screenGui,
			Unload = function()
				window:Destroy(true)
			end,
		})
	end

	return window
end

end

__modules['components.WindowConfig'] = function(...)
--!strict
-- components/WindowConfig.lua — the window's flag + config surface.
--
-- Split out of components/Window.lua. Everything here is either a pass-through
-- to util/Context.lua's flag registry or that registry plus util/Config.lua's
-- file layer; not one method in the file touches an Instance, which is what made
-- it ~240 lines of the window shell that had nothing to do with the shell.
--
-- The split it draws is the same one the API draws: `GetConfig`/`ApplyConfig`
-- are the primitives, and `SaveConfig`/`LoadConfig` are those plus a file. A host
-- that wants its own layout on disk uses the first pair and never comes here.

local Config = __require("util.Config")
local Log = __require("util.Log")
local Signal = __require("util.Signal")

-- Options for ApplyConfig / LoadConfig. `Filter(name, kind) -> boolean` decides
-- per flag whether it's applied; see Context:LoadConfig for the contract.
export type LoadOpts = { Filter: ((string, string) -> boolean)? }

return function(window: any, ctx: any, opts: any)
	-- Where configs are saved on disk. No longer fixed at CreateWindow — see
	-- window:SetConfigFolder — so anything showing a config list has to be told
	-- when the list it's showing became a different folder's.
	local configFolder = opts.ConfigFolder or "uranium"
	local folderWatchers = Signal.new() :: any

	-- ── settings: the flag registry ───────────────────────────────────────────
	-- The two primitives everything else here is built on. The named-file methods
	-- below are just these plus util/Config.lua — which is the point: a host that
	-- wants its own layout on disk, remote or shared configs, in-memory profiles
	-- or a "reset to defaults" button needs the snapshot/apply pair WITHOUT the
	-- library's file path in the middle, and previously the only way to apply a
	-- table of flags was to write it to <ConfigFolder>/configs/<name>.json first.
	--
	--   local snapshot = Window:GetConfig()      -- exactly what SaveConfig serializes
	--   Window:ApplyConfig(snapshot)             -- exactly what LoadConfig applies
	--
	-- GetConfig returns flags only — no `Config.MetaKey` stamp; that's SaveConfig's
	-- doing, and a host composing its own file adds whatever metadata it wants.
	function window:GetConfig(): { [string]: any }
		return ctx:GetConfig()
	end

	-- Apply a table of flags. Returns how many were applied and how many keys were
	-- skipped (unknown flag, failed decode, control refused the value, or filtered
	-- out). Keys with no registered flag are skipped rather than erroring — see
	-- Context:LoadConfig, where that promise is spelled out.
	--
	-- `opts.Filter = function(name, kind) -> boolean` applies only the flags it
	-- says yes to, for a host whose registry is split (a portable half, a per-place
	-- half). One predicate rather than a list of names, because that split is
	-- computed, not enumerable; `Config.MetaKey` and every other unregistered key
	-- is skipped before the filter is consulted, so it never sees one.
	function window:ApplyConfig(data: { [string]: any }, loadOpts: LoadOpts?): (number, number)
		if type(data) ~= "table" then
			Log.warn("ApplyConfig", ("expects a table of flags, got %s — ignoring.")
				:format(typeof(data)))
			return 0, 0
		end
		return ctx:LoadConfig(data, loadOpts)
	end

	-- Every registered flag as `{ [name] = kind }`. Snapshot it at two moments —
	-- before and after a per-place module builds its controls — and the difference
	-- is that module's flags, which is how a config gets scoped (apply the portable
	-- half anywhere, the game-specific half only in the right game) instead of
	-- being all-or-nothing.
	function window:GetFlags(): { [string]: string }
		return ctx:GetFlags()
	end

	-- Register a flag by hand. `handle` needs `:Get()`/`:Set(v)` (or `:GetFlag()`/
	-- `:SetFlag(v)` when the persisted value isn't the primary one), `kind` names
	-- the codec — the same contract every control satisfies. This is how the
	-- built-in Settings tab persists the bind HUD, which isn't a control at all,
	-- and it's how a host puts its own non-control state in the same config file.
	function window:RegisterFlag(name: string, handle: any, kind: string)
		ctx:RegisterFlag(name, handle, kind)
	end

	-- Watch flags as they're registered — `fn(name, kind)`, synchronously, so the
	-- callback can attribute the flag to whatever is being built at that instant.
	-- Returns an unsubscribe. `CreateWindow{ OnFlag = fn }` is the same hook,
	-- installed early enough to catch every flag in the menu.
	function window:OnFlag(fn: (string, string) -> ()): () -> ()
		return ctx:OnFlag(fn)
	end

	-- Watch flag VALUES as they move — `fn(name, value, kind, source)`, where
	-- `value` is the encoded value (what `GetConfig()` would file under that name)
	-- and `source` is `"user"` / `"code"` / `"config"`. Fires synchronously, and
	-- never for a control taking its default or for a `:Set` that lands on the
	-- value already held. Returns an unsubscribe.
	--
	-- This is what a host persisting continuously hangs off: without it the only
	-- way to notice a change is to poll `GetConfig()` and diff it, which loses
	-- everything since the last poll whenever the client script dies without a
	-- clean unload. `source` is what keeps a config landing 40 flags from looking
	-- like 40 edits worth writing back.
	function window:OnFlagChanged(fn: (string, any, string, string) -> ()): () -> ()
		if type(fn) ~= "function" then
			Log.fail("OnFlagChanged", ("expects a function fn(name, value, kind, source), got %s")
				:format(typeof(fn)))
		end
		return ctx:OnFlagChanged(fn)
	end

	-- Tell the watchers a flag's value moved. Only needed for state YOU registered
	-- with `RegisterFlag` — every control notifies for itself. Re-reads and
	-- re-encodes the flag and stays silent unless the value actually differs from
	-- the last one reported, so it's safe to call on any suspicion of a change.
	function window:NotifyFlag(name: string, source: string?)
		if type(name) ~= "string" or name == "" then
			Log.warn("NotifyFlag", ("expects a flag name, got %s — ignoring.")
				:format(name == "" and '""' or typeof(name)))
			return
		end
		if not ctx.Flags[name] then
			Log.warn("NotifyFlag", ('no flag named "%s" is registered — ignoring.'):format(name))
			return
		end
		ctx:NotifyFlag(name, source)
	end

	-- ── settings: config persistence ──────────────────────────────────────────
	-- These are the flag registry (above) plus a file on disk. Every one of them
	-- returns `(result, reason)`: the library always knew whether it was a missing
	-- file, corrupt JSON or an executor with no file access, and a bare `false`
	-- threw that away — leaving a host with nothing to say but "Couldn't load".
	window.ConfigSupported = Config.supported

	local function badConfigName(where: string, name: any): boolean
		if type(name) ~= "string" or name == "" then
			Log.warn(where, ("config name must be a non-empty string, got %s — ignoring.")
				:format(name == "" and '""' or typeof(name)))
			return true
		end
		return false
	end

	-- `meta` is stamped into the file under `Config.MetaKey` alongside the flags,
	-- and read back by ConfigInfo without applying anything — provenance
	-- ("which game / profile / build wrote this?") without a second file to keep
	-- in sync. It's skipped on load like any unregistered key.
	function window:SaveConfig(name: string, meta: any?): (boolean, string?)
		if badConfigName("SaveConfig", name) then
			return false, "invalid name"
		end
		if meta ~= nil and type(meta) ~= "table" then
			Log.warn("SaveConfig", ("meta must be a table, got %s — saving without it.")
				:format(typeof(meta)))
			meta = nil
		end
		local snapshot = ctx:GetConfig()
		local n = 0
		for _ in snapshot do
			n += 1
		end
		if meta then
			snapshot[Config.MetaKey] = meta
		end
		local ok, reason = Config.save(configFolder, name, snapshot)
		Log.infof("SaveConfig(%q) -> %s  (%d flags%s)",
			tostring(name), tostring(ok), n, ok and "" or ", " .. tostring(reason))
		return ok, reason
	end

	-- `opts` is ApplyConfig's, and it's here for the same reason: a host that
	-- scopes its registry — a portable half applied anywhere, a per-place half
	-- only in the right game — could otherwise only land *part* of a file by
	-- abandoning this method entirely and rebuilding it out of `Uranium.Config` +
	-- ApplyConfig, losing the name validation, the log line and the (ok, reason)
	-- shape in the process. A filtered-out flag counts as skipped, so "applied
	-- nothing" still means what it says.
	function window:LoadConfig(name: string, loadOpts: LoadOpts?): (boolean, string?)
		if badConfigName("LoadConfig", name) then
			return false, "invalid name"
		end
		local data, reason = Config.load(configFolder, name)
		Log.infof("LoadConfig(%q) -> %s%s",
			tostring(name), tostring(data ~= nil), data and "" or " (" .. tostring(reason) .. ")")
		if not data then
			return false, reason
		end
		local applied = ctx:LoadConfig(data, loadOpts)
		if applied == 0 then
			-- The file was fine and nothing in it matched a control we have (or the
			-- caller's filter wanted none of what did). That's a different failure
			-- from "no such config" and it used to read as success.
			return false, "applied nothing"
		end
		return true
	end

	function window:DeleteConfig(name: string): (boolean, string?)
		if badConfigName("DeleteConfig", name) then
			return false, "invalid name"
		end
		return Config.delete(configFolder, name)
	end

	function window:ListConfigs(): { string }
		return Config.list(configFolder)
	end

	-- The metadata a config was saved with, without touching a single control —
	-- the read a "does this config belong to this game?" check actually wants.
	function window:ConfigInfo(name: string): (any?, string?)
		if badConfigName("ConfigInfo", name) then
			return nil, "invalid name"
		end
		return Config.info(configFolder, name)
	end

	-- ── settings: auto-load pointer ───────────────────────────────────────────
	-- The Settings tab used to call Config.setAutoload/getAutoload directly, which
	-- made it the one config path a host couldn't intercept — every other one goes
	-- through a window: method. Now it goes through these too.
	function window:SetAutoload(name: string?)
		if name ~= nil and type(name) ~= "string" then
			Log.warn("SetAutoload", ("expects a config name or nil, got %s — ignoring.")
				:format(typeof(name)))
			return
		end
		Config.setAutoload(configFolder, name)
	end

	function window:GetAutoload(): string?
		return Config.getAutoload(configFolder)
	end

	-- ── settings: where configs live ──────────────────────────────────────────
	function window:GetConfigFolder(): string
		return configFolder
	end

	-- Re-scope persistence at runtime — per-place config folders, user profiles,
	-- an account switch. Anything already showing a config list is notified
	-- (window:OnConfigFolder) because its contents just became a different
	-- folder's; the built-in Settings tab refreshes its dropdown from that.
	function window:SetConfigFolder(path: string)
		if type(path) ~= "string" or path == "" then
			Log.warn("SetConfigFolder", ("expects a non-empty path, got %s — ignoring.")
				:format(path == "" and '""' or typeof(path)))
			return
		end
		if path == configFolder then
			return
		end
		configFolder = path
		folderWatchers:Fire(configFolder)
	end

	-- Fires immediately with the current folder, then on every change; returns an
	-- unsubscribe.
	function window:OnConfigFolder(fn: (string) -> ()): () -> ()
		local unsubscribe = folderWatchers:Connect(fn)
		fn(configFolder) -- the current folder; Signal never replays
		return unsubscribe
	end

	-- The folder moves at runtime, so anything else that needs it gets a getter
	-- rather than a value captured at build time.
	return {
		folder = function(): string
			return configFolder
		end,
	}
end

end

__modules['components.WindowHud'] = function(...)
--!strict
-- components/WindowHud.lua — the window's bind-HUD ownership.
--
-- Split out of components/Window.lua, which was 2178 lines and eight jobs. This
-- is one of them: building the HUD on demand, merging the two places its options
-- can come from, and the two watcher lists anything mirroring it subscribes to.
-- None of it touches the window's chrome, geometry or tabs.
--
-- Installs `CreateHud` / `GetHud` / `SetHudVisible` / `OnHudVisible` /
-- `OnHudChanged` onto `window`, and returns a teardown the window calls from
-- `Destroy` — the HUD's drag/Heartbeat listeners outlive instances the same way
-- the window's own do.

local Log = __require("util.Log")
local Signal = __require("util.Signal")
local Hud = __require("components.Hud")

return function(window: any, ctx: any, screenGui: ScreenGui, opts: any)
	-- The bind HUD, once something asks for one (components/Hud.lua). It's a
	-- sibling of `main` in the ScreenGui, not a child, so minimize leaves it up.
	local hud: any = nil
	-- Anything mirroring the HUD's visibility — the Settings tab's switch is one,
	-- but a host that builds its own settings UI needs the same signal, so it's a
	-- signal behind `window:OnHudVisible` rather than the panel's private hook it
	-- used to be.
	local hudWatchers = Signal.new() :: any
	-- ...and the same for anything else the HUD persists (its position, whether
	-- it's collapsed), which no visibility signal covers — see Window:OnHudChanged.
	local hudChangeWatchers = Signal.new() :: any

	-- ── settings: the bind HUD ────────────────────────────────────────────────
	-- A small draggable overlay listing every named bind, lit while it's live,
	-- plus FPS / ping — the answer to "what's on right now?" with the menu closed.
	-- It reads util/Bind.lua's registry, so it needs nothing declared twice; a
	-- bind appears as soon as it has a `Label` (the controls pass their `Name`).
	--
	-- Built on demand and only once: `CreateWindow{ Hud = true }`, the Settings
	-- tab's switch and a loaded config all land here.
	function window:CreateHud(hudOpts: any?): any
		if hudOpts ~= nil and type(hudOpts) ~= "table" then
			Log.fail("CreateHud", ("options must be a table like { Title = ... }, got %s")
				:format(typeof(hudOpts)))
		end
		if hud then
			-- Already built — which is the common case, since `CreateWindow{ Hud = true }`
			-- builds one before the caller has run a line of their own code, and
			-- SetHudVisible routes through here too. Returning early swallowed the
			-- options entirely; apply the ones the handle can move at runtime and say
			-- so for the rest, rather than silently ignoring the whole table.
			if type(hudOpts) == "table" then
				local o: any = hudOpts
				if type(o.Title) == "string" then
					hud:SetTitle(o.Title)
				end
				if tonumber(o.X) and tonumber(o.Y) then
					hud:SetPosition(tonumber(o.X) :: number, tonumber(o.Y) :: number)
				end
				if o.Collapsed ~= nil then
					hud:SetCollapsed(o.Collapsed == true)
				end
				if o.Visible ~= nil then
					hud:SetVisible(o.Visible ~= false)
				end
				for _, key in { "MaxRows", "Stats", "Fps", "Ping" } do
					if o[key] ~= nil then
						Log.warn("CreateHud", ("%s is only read when the HUD is first built — the existing HUD keeps its own.")
							:format(key))
					end
				end
			end
			return hud
		end
		-- CreateWindow{ Hud = {...} } is the baseline; a later CreateHud{...} (or the
		-- Settings switch, which passes nothing) overrides field by field.
		local merged: any = {}
		if type(opts.Hud) == "table" then
			for key, value in opts.Hud :: any do
				merged[key] = value
			end
		end
		if type(hudOpts) == "table" then
			for key, value in hudOpts :: any do
				merged[key] = value
			end
		end
		hud = Hud(ctx, screenGui, merged)
		-- Keep the Settings tab's switch in step with the HUD however it moved
		-- (its own :SetVisible, a loaded config, the panel being dismissed).
		hud.OnVisible = function(value: boolean)
			hudWatchers:Fire(value)
		end
		-- Everything the HUD persists — where it sits, whether it's folded, whether
		-- it's up — is moved with the mouse, not through a control, so there's no
		-- callback anywhere for a change notification to hang off. This is that
		-- callback; components/Settings.lua turns it into one for the HUD's flag.
		hud.OnChange = function()
			hudChangeWatchers:Fire()
		end
		return hud
	end

	-- Mirror the HUD's visibility however it moved (its own :SetVisible, a loaded
	-- config, the panel being dismissed). Fires immediately with the current
	-- state, like ctx:RegisterAccent, so a switch built from it starts in step;
	-- returns an unsubscribe.
	function window:OnHudVisible(fn: (boolean) -> ()): () -> ()
		local unsubscribe = hudWatchers:Connect(fn)
		fn(hud ~= nil and hud:IsVisible()) -- the initial state; Signal never replays
		return unsubscribe
	end

	-- Fires whenever anything the HUD *persists* moves — dragged to a new spot,
	-- folded, shown or hidden. Unlike `OnHudVisible` it doesn't fire immediately
	-- (there's no single value to hand you) and it takes no argument: read the
	-- HUD, or just re-save. The built-in Settings tab uses it to keep the HUD's
	-- flag in the change stream, which is the only reason a dragged HUD shows up
	-- in `OnFlagChanged` at all. Returns an unsubscribe.
	function window:OnHudChanged(fn: () -> ()): () -> ()
		return hudChangeWatchers:Connect(fn)
	end

	function window:GetHud(): any
		return hud
	end

	-- Show/hide the HUD, building it the first time it's asked for. Hiding one
	-- that was never built is a no-op rather than a pointless build.
	function window:SetHudVisible(value: boolean)
		if not hud and value == false then
			return
		end
		window:CreateHud():SetVisible(value ~= false)
	end


	return {
		-- Called from Window:Destroy. The HUD's own input listeners outlive the
		-- ScreenGui, same as the window's.
		Destroy = function()
			if hud then
				hud:Destroy()
				hud = nil
			end
		end,
	}
end

end

__modules['components.WindowState'] = function(...)
--!strict
-- components/WindowState.lua — the `uranium_window` flag.
--
-- Split out of components/Window.lua. Position, size, maximize, the selected tab
-- and the folded state of every group, persisted as one flag on the same terms
-- as the bind HUD's: every host wants the menu to come back where it was left,
-- and asking each of them to reimplement the clamping and the "that tab doesn't
-- exist any more" fallbacks is how those get written four different ways and
-- wrong three of them.
--
-- This is the one extraction that genuinely reaches back into the window — a
-- restore moves the geometry, picks a tab and folds groups — so it takes those
-- as an explicit `deps` table rather than pretending it doesn't. That the list
-- is short, and that all of it is behaviour rather than state, is what makes the
-- split hold: nothing here can reach a field it wasn't handed.

export type Deps = {
	-- Geometry, in the window's own terms.
	--
	-- `wantedSize` is the size the window ASKED for, which is not the size it is
	-- drawn at: the viewport clamps it, and maximize overrides it entirely. The
	-- wish is what's persisted, so a size chosen on a big monitor survives a
	-- session on a laptop instead of being permanently shrunk to fit it. `setSize`
	-- is its inverse — it sets the wish and lets the window reconcile.
	--
	-- `topLeft` / `moveTo` are the window's top-left in screen pixels, which is
	-- the only coordinate worth persisting (the live Position is a scale/offset
	-- pair whose numbers mean nothing on a viewport of another size). `moveTo`
	-- clamps exactly as a drag does.
	topLeft: () -> Vector2,
	wantedSize: () -> Vector2,
	setSize: (number, number) -> (),
	moveTo: (number, number) -> (),
	setMaximized: (boolean, boolean?) -> (),
	isMaximized: () -> boolean,
	-- Viewport width, or 0 before it has been measured: a snapshot taken on the
	-- frame the window is built must not write down a position resolved against a
	-- zero viewport as if the user had chosen it.
	viewportWidth: () -> number,
	-- Tabs: the list, which one is open, and how to open one WITHOUT announcing it
	-- as a window-state change (restoring a record is not a run of edits).
	tabs: () -> { any },
	selected: () -> number,
	select: (number) -> (),
}

-- No `window` argument, unlike the other two installers: this registers a flag
-- on the Context and installs no public method, so it never needs the handle.
return function(ctx: any, opts: any, deps: Deps)
	-- ── the window-state flag ─────────────────────────────────────────────────
	-- Registered by the library itself, on the same terms as the bind HUD's flag:
	-- every host wants the menu to come back where it was left, and asking each of
	-- them to reimplement the clamping and the "that tab doesn't exist any more"
	-- fallbacks is how those get written four different ways and wrong three of
	-- them. `CreateWindow{ PersistWindow = false }` opts out; `WindowFlag` renames
	-- it, exactly like `HudFlag`.
	local windowFlagName = opts.WindowFlag or "uranium_window"
	local persistWindow = opts.PersistWindow ~= false
	local applyingWindowState = false

	local function windowState(): any
		local groups: { [string]: boolean } = {}
		for _, entry in ctx.Groups do
			groups[entry.key] = entry.handle:IsCollapsed() == true
		end
		-- The size the window WANTS, not the size it's drawn at. Those differ
		-- whenever the viewport clamped it (or it's maximized), and persisting the
		-- drawn one would permanently shrink a size set on a big monitor the first
		-- time the menu opened on a laptop.
		local wanted = deps.wantedSize()
		local record: any = {
			Width = wanted.X,
			Height = wanted.Y,
			Maximized = deps.isMaximized(),
			Tab = deps.selected(),
			Groups = groups,
		}
		-- Position only once the viewport has actually been measured. A snapshot
		-- taken on the frame the window is built (a host that saves immediately)
		-- would otherwise resolve the scale half of the Position against a zero
		-- viewport and record the window as sitting off the top-left corner — a
		-- coordinate that means nothing, written down as if the user had chosen it.
		-- Omitted, the restore just leaves the window where it opens.
		if deps.viewportWidth() > 0 then
			local origin = deps.topLeft()
			record.X = origin.X
			record.Y = origin.Y
		end
		return record
	end

	-- Every field is optional and every one of them is allowed to be wrong: a
	-- record is written by one session and applied by another, with a different
	-- viewport, a different set of tabs (a game script that isn't loaded this
	-- time) and possibly a different build of the menu. Nothing in here errors on
	-- a mismatch — it restores what still makes sense and drops the rest.
	--
	-- Split out from `applyWindowState` below so the suppression flag that call
	-- runs under can be cleared even if something in here does throw.
	local function restoreWindowState(value: any)
		-- Size first (the position clamp is computed against it), then maximize
		-- (which overrides the size), then the position it's clamped into.
		if value.Width and value.Height then
			-- setSize floors and clamps to the window's own minimum, which is where
			-- that rule belongs; this only has to hand it two numbers.
			deps.setSize(value.Width, value.Height)
		end
		if value.Maximized ~= nil then
			deps.setMaximized(value.Maximized == true, false)
		end
		if value.X and value.Y then
			deps.moveTo(value.X, value.Y)
		end

		if value.Tab then
			local index = math.floor(value.Tab)
			local tabs = deps.tabs()
			local target = tabs[index]
			if target and target:IsVisible() then
				deps.select(index)
			else
				-- The saved tab is gone (or hidden) — a config written with a
				-- game-specific tab loaded, restored without it. Fall through to the
				-- first tab that's actually there rather than erroring or leaving the
				-- window on a page nobody can navigate back to.
				for i, other in tabs do
					if other:IsVisible() then
						deps.select(i)
						break
					end
				end
			end
		end

		-- Only groups that still exist under the same key. Anything built after
		-- this runs isn't in the registry yet and keeps its own `Collapsed` option,
		-- which is the same ordering rule as every other flag: state is restored
		-- for the controls that exist when the config is applied.
		if type(value.Groups) == "table" then
			for _, entry in ctx.Groups do
				local collapsed = value.Groups[entry.key]
				if collapsed ~= nil then
					entry.handle:SetCollapsed(collapsed == true, false)
				end
			end
		end
	end

	-- `restoreWindowState` under the notification-suppression flag, which has to
	-- come back down whatever happens in there.
	--
	-- It used to be a bare `flag = true … flag = false` around the body, and the
	-- body is called from inside Context:LoadConfig's pcall — so anything that
	-- threw mid-restore was swallowed upstream and left the flag stuck ON for the
	-- rest of the session. From then on every drag, maximize, tab click and folded
	-- group stopped notifying `uranium_window`: the window silently stopped
	-- persisting, with no error and nothing on screen to say so.
	local function applyWindowState(value: any)
		if type(value) ~= "table" then
			return
		end
		applyingWindowState = true
		local ok, err = pcall(restoreWindowState, value)
		applyingWindowState = false
		if not ok then
			error(err, 0) -- re-raised untouched; LoadConfig names the flag that failed
		end
	end

	if persistWindow then
		ctx:RegisterFlag(windowFlagName, {
			GetFlag = function(): any
				return windowState()
			end,
			SetFlag = function(_, value: any)
				applyWindowState(value)
			end,
		}, "window")
		-- One funnel for everything that moves the record — a drag landing, a
		-- maximize, a tab click, a group folded three components away. Suppressed
		-- while a restore is in flight: applying one record would otherwise report
		-- a change per field, each with a half-applied value, and Context:LoadConfig
		-- announces the finished result once anyway.
		ctx:OnWindowState(function()
			if not applyingWindowState then
				ctx:NotifyFlag(windowFlagName)
			end
		end)
	end

end

end

__modules['util.Asset'] = function(...)
--!strict
-- util/Asset.lua — turn "whatever the caller has" into something an ImageLabel
-- can actually render.
--
-- Roblox's `Image` property only accepts content URLs (`rbxassetid://…`,
-- `rbxthumb://…`, `rbxasset://…`). Everything else people naturally have — a
-- bare decal id copied off the creator dashboard, a PNG on disk, an https URL to
-- an image — has to be converted first. That conversion is the whole point of
-- this module, so a caller can write any of these and it just works:
--
--   Asset.resolve(91296376944710)                    -- number / numeric string
--   Asset.resolve("rbxassetid://91296376944710")     -- already a content url
--   Asset.resolve("uranium/logo.png")                -- local file (getcustomasset)
--   Asset.resolve("https://example.com/logo.png")    -- downloaded, cached, loaded
--   Asset.headshot(userId)                           -- avatar thumbnail
--
-- Local files and URL downloads need executor globals (`getcustomasset`,
-- `writefile`, …). They're feature-detected and pcall-guarded exactly like
-- util/Config.lua, so in Studio (or an executor missing them) the call returns
-- "" and the caller shows its placeholder instead of erroring.

local Services = __require("util.Services")

local Asset = {}

-- Executor globals live on the SHARED env (getgenv), not the chunk env. Some
-- sandboxes throw merely on touching getgenv/_G, so every lookup is guarded —
-- this module is required at load time and a raw error would kill the library.
local genv: any = nil
pcall(function()
	if type(getgenv) == "function" then
		genv = getgenv()
	end
end)

local function g(name: string): any
	if type(genv) == "table" then
		local ok, v = pcall(function()
			return genv[name]
		end)
		if ok and v ~= nil then
			return v
		end
	end
	local ok2, v2 = pcall(function()
		return (_G :: any)[name]
	end)
	if ok2 and v2 ~= nil then
		return v2
	end
	return nil
end

local g_getcustomasset = g("getcustomasset") or g("getsynasset") or g("get_custom_asset")
local g_writefile = g("writefile")
local g_isfile = g("isfile")
local g_isfolder = g("isfolder")
local g_makefolder = g("makefolder")

-- Can we hand a *local file* to Roblox as an image? (asset ids always work)
Asset.supported = type(g_getcustomasset) == "function"
-- Can we additionally fetch a remote image and cache it on disk?
Asset.canDownload = Asset.supported and type(g_writefile) == "function"

-- Where downloaded images are cached. Set once at startup if you want them
-- somewhere other than the default (e.g. alongside your configs).
Asset.CacheFolder = "uranium/images"

-- Base URL for art hosted in the public asset repo. init.lua points this at
-- `Theme.Brand.assets`; `Asset.url("logo.png")` then builds the full URL, so
-- adding a new image is "commit the file, reference it by name".
Asset.Base = ""

function Asset.url(name: string): string
	if type(name) ~= "string" or name == "" then
		return ""
	end
	if name:match("^https?://") then
		return name -- already absolute — pass it through untouched
	end
	return Asset.Base .. name
end

local IMAGE_EXT = { png = true, jpg = true, jpeg = true, webp = true, tga = true, bmp = true }

local function extensionOf(path: string): string?
	local ext = tostring(path):match("%.([%a%d]+)$")
	return ext and IMAGE_EXT[ext:lower()] and ext:lower() or nil
end

local function ensureFolder()
	if type(g_isfolder) ~= "function" or type(g_makefolder) ~= "function" then
		return
	end
	pcall(function()
		-- Walk the path so a nested default like "uranium/images" creates both
		-- levels — makefolder doesn't do parents.
		local built = ""
		for segment in tostring(Asset.CacheFolder):gmatch("[^/\\]+") do
			built = built == "" and segment or (built .. "/" .. segment)
			if not g_isfolder(built) then
				g_makefolder(built)
			end
		end
	end)
end

-- getcustomasset for a path already on disk. Returns nil (never throws) when the
-- global is missing or the file isn't there.
function Asset.fromFile(path: string): string?
	if not Asset.supported or type(path) ~= "string" or path == "" then
		return nil
	end
	if type(g_isfile) == "function" then
		local okExists, exists = pcall(g_isfile, path)
		if okExists and not exists then
			return nil
		end
	end
	local ok, content = pcall(g_getcustomasset, path)
	if ok and type(content) == "string" and content ~= "" then
		return content
	end
	return nil
end

-- Magic bytes for the formats Roblox will actually render, so a downloaded body
-- can be checked before it's committed to the disk cache.
local function looksLikeImage(body: string): boolean
	local head = body:sub(1, 12)
	return head:sub(1, 8) == "\137PNG\r\n\26\n"       -- png
		or head:sub(1, 2) == "\255\216"                -- jpeg
		or head:sub(1, 6) == "GIF89a" or head:sub(1, 6) == "GIF87a"
		or (head:sub(1, 4) == "RIFF" and head:sub(9, 12) == "WEBP")
		or head:sub(1, 2) == "BM"                      -- bmp
end

-- url → disk → content id. Cached twice: in memory for the session, and on disk
-- across sessions (a re-run reuses the file instead of re-downloading).
local urlCache: { [string]: string } = {}

-- URLs with a fetch in flight right now. Resolving is a yielding operation on a
-- spawned thread (every component calls it that way), so the same url is
-- routinely asked for two or three times before the first answer lands —
-- `Theme.Brand.logo` alone is resolved by the titlebar, the splash and the status
-- page. Without this they each ran their own HttpGet and each wrote the same
-- bytes to the same path, which is a wasted round trip per caller and two
-- writefiles racing for one file. The later callers wait for the first instead.
local urlPending: { [string]: boolean } = {}

-- The download itself. Split out so `Asset.fromUrl` can hold the in-flight mark
-- across it and clear the mark on every exit, including a throw.
local function download(url: string, filename: string?): string?
	-- Name the cache file after the url so repeat calls land on the same file.
	local name = filename
	if not name then
		local hash = 5381
		for i = 1, #url do
			hash = (hash * 33 + string.byte(url, i)) % 4294967296
		end
		name = ("%010d.%s"):format(hash, extensionOf(url) or "png")
	end
	local path = Asset.CacheFolder .. "/" .. name

	local cached = Asset.fromFile(path)
	if cached then
		urlCache[url] = cached
		return cached
	end

	ensureFolder()
	-- HttpGet hands back the body as a Lua string, which is binary-safe — so a
	-- PNG survives the round trip to writefile intact.
	local okGet, body = pcall(function()
		return game:HttpGet(url)
	end)
	if not okGet or type(body) ~= "string" or body == "" then
		return nil
	end
	-- Refuse to cache a body that isn't actually an image. A 404 page or a rate
	-- limit notice would otherwise be written to <name>.png and cached on disk
	-- forever, so one bad fetch would permanently break that image.
	if not looksLikeImage(body) then
		return nil
	end
	if not (pcall(g_writefile, path, body)) then
		return nil
	end
	local content = Asset.fromFile(path)
	if content then
		urlCache[url] = content
	end
	return content
end

-- How long a second caller waits on the first one's fetch before giving up and
-- showing its placeholder. Comfortably past `whenLoaded`'s own budget, since the
-- fetch it's waiting on is one HttpGet plus a writefile.
local PENDING_WAIT = 15

function Asset.fromUrl(url: string, filename: string?): string?
	if type(url) ~= "string" or url == "" then
		return nil
	end
	local hit = urlCache[url]
	if hit then
		return hit
	end
	if not Asset.canDownload then
		return nil
	end

	-- Someone else is already fetching this one: wait for their answer rather than
	-- starting a second download of the same bytes. Polling, not a signal —
	-- BindableEvents here would mean an instance per url and a deferred resumption
	-- on a path that already yields for a network round trip.
	if urlPending[url] then
		local deadline = os.clock() + PENDING_WAIT
		while urlPending[url] and os.clock() < deadline do
			task.wait(0.05)
		end
		return urlCache[url]
	end

	urlPending[url] = true
	-- pcall so a throw anywhere in the fetch can't strand the mark — every later
	-- caller for this url would then wait out PENDING_WAIT and give up, turning one
	-- bad download into a permanently dead image.
	local ok, content = pcall(download, url, filename)
	urlPending[url] = nil
	return (ok and content) or nil
end

-- The body of Asset.resolve (below), plus the chain-depth counter.
--
-- The counter lives here rather than as a second parameter of `Asset.resolve`
-- itself, because that one is public (`Uranium.Asset.resolve`) and an optional
-- trailing argument is exactly what a caller feeds an array index to by
-- accident: `for i, v in list do Asset.resolve(v, i) end` would silently start
-- at depth i and refuse a chain. Nothing outside this file can reach it.
local resolveValue: (any, number) -> string

resolveValue = function(value: any, depth: number): string
	if value == nil then
		return ""
	end

	if type(value) == "table" then
		-- A chain of chains is legal (a caller composing `{ Theme.Brand.logo, myId }`
		-- nests one without thinking about it), so the recursion is real — but a
		-- table that contains itself would spin here forever, and this runs on the
		-- render path for every image in the UI. Four levels is far past any honest
		-- fallback chain.
		if depth >= 4 then
			return ""
		end
		for _, candidate in value do
			local resolved = resolveValue(candidate, depth + 1)
			if resolved ~= "" then
				return resolved
			end
		end
		return ""
	end

	if type(value) == "number" then
		return "rbxassetid://" .. tostring(math.floor(value))
	end
	if type(value) ~= "string" or value == "" then
		return ""
	end

	-- already a content url
	if value:match("^rbxassetid://") or value:match("^rbxthumb://")
		or value:match("^rbxasset://") or value:match("^rbxgameasset://") then
		return value
	end
	-- bare id, with or without stray whitespace
	local digits = value:match("^%s*(%d+)%s*$")
	if digits then
		return "rbxassetid://" .. digits
	end
	-- a roblox catalog/library link — pull the id out of it
	local libraryId = value:match("roblox%.com/[^%s]-/(%d+)")
	if libraryId then
		return "rbxassetid://" .. libraryId
	end
	-- remote image → download + cache
	if value:match("^https?://") then
		return Asset.fromUrl(value) or ""
	end
	-- otherwise treat it as a path on disk
	return Asset.fromFile(value) or ""
end

-- The one every component calls. Accepts an id, a content url, a file path, an
-- http(s) url, or nil. Always returns a string — "" means "nothing to show", so
-- callers can assign it straight to `Image` and fall back on their placeholder.
--
-- It also accepts an ARRAY of any of those: a fallback chain, tried in order,
-- first one that resolves wins. That's how you survive Roblox's asset rules —
-- put a `https://…/logo.png` first (downloaded to disk, loaded via
-- getcustomasset, so moderation / Asset Privacy / decal-vs-image ids never
-- apply) and a plain asset id after it for executors with no file access.
--
-- One argument, exactly as before.
function Asset.resolve(value: any): string
	return resolveValue(value, 0)
end

-- ── Actually loading it ──────────────────────────────────────────────────────
-- `resolve` only proves the *shape* of a source is usable — it can't know the
-- asset renders. So `Asset.load` sets the image and reports back whether it
-- really arrived, letting callers keep a placeholder up.
--
-- Two hard rules here, both learned the painful way:
--
--   1. **Never use ContentProvider:PreloadAsync to decide.** It doesn't work on
--      ImageLabels (a documented engine limitation) and fails constantly on
--      content strings, so it reports Failure for images that render fine.
--      `ImageLabel.IsLoaded` is the only signal that tells the truth.
--   2. **Never clear or hide the image based on that check.** Detection is
--      advisory. The image is assigned immediately and stays assigned; a
--      negative result only means "keep the placeholder", never "erase the art".
--      Anything else risks blanking a picture that was about to appear.
--
-- The engine also only fetches textures for instances it's *rendering*, so an
-- unparented or hidden ImageLabel never loads at all. Callers must keep the
-- image visible while it loads — which the no-hiding rule above already gives.

local LOAD_TIMEOUT = 8

-- `alive` lets a superseded load give up mid-wait instead of holding the label
-- hostage for the rest of its timeout (see `generation` below).
local function whenLoaded(image: ImageLabel, timeout: number?, alive: (() -> boolean)?): boolean
	if image.IsLoaded then
		return true
	end
	local deadline = os.clock() + (timeout or LOAD_TIMEOUT)
	while not image.IsLoaded and os.clock() < deadline do
		if alive and not alive() then
			return false
		end
		task.wait(0.15)
	end
	return image.IsLoaded
end

-- Put `content` on the image and wait for it. Also tries the decal→image id
-- shuffle: a Decal asset and the Image it wraps live at adjacent ids, and the
-- decals that don't render directly need the underlying image (decalId - 1).
local function tryContent(image: ImageLabel, content: string, timeout: number, alive: (() -> boolean)?): boolean
	if alive and not alive() then
		return false
	end
	image.Image = content
	if whenLoaded(image, timeout, alive) then
		return true
	end
	local id = tonumber(content:match("rbxassetid://(%d+)$"))
	if id and id > 1 then
		if alive and not alive() then
			return false
		end
		image.Image = "rbxassetid://" .. tostring(id - 1)
		if whenLoaded(image, timeout, alive) then
			return true
		end
	end
	return false
end

-- Which load is the live one for a given ImageLabel. A walk can sit in
-- `whenLoaded` for 8s per candidate (plus a download), so two calls on the same
-- label overlap freely — and the loser used to keep writing: it painted its own
-- content over the winner's and then called `onDone(false)`, putting the
-- placeholder back on top of art that had already arrived. That's `Window:SetLogo`
-- during the default logo's chain, or `Image:Set` twice in a row. Weak keys so a
-- destroyed label doesn't pin an entry here.
local generation: { [ImageLabel]: number } = setmetatable({}, { __mode = "k" }) :: any

-- Point `image` at `source`; `onDone(loaded)` reports whether it rendered.
-- `source` may be a single value or a fallback chain (see Asset.resolve) — each
-- candidate gets a short window, the last gets the full timeout.
--
-- `onDone` can fire twice — false on timeout, then true if the asset shows up
-- late — so keep it idempotent (toggling a placeholder is the ideal shape).
function Asset.load(image: ImageLabel, source: any, onDone: ((boolean) -> ())?)
	local chain: { any } = (type(source) == "table") and source or { source }
	local token = (generation[image] or 0) + 1
	generation[image] = token
	local function current(): boolean
		return generation[image] == token
	end

	task.spawn(function()
		local firstContent = ""
		for i, candidate in chain do
			-- Resolving can download (an https candidate is fetched to disk on
			-- first use), which is why the whole walk lives on this thread.
			local content = Asset.resolve(candidate)
			if not current() then
				return -- a newer load owns this label now
			end
			if content ~= "" then
				if firstContent == "" then
					firstContent = content
				end
				-- Don't spend the full budget on early candidates — there's
				-- another source waiting behind them.
				local budget = (i < #chain) and 3 or LOAD_TIMEOUT
				if tryContent(image, content, budget, current) then
					if onDone then
						onDone(true)
					end
					return
				end
			end
		end

		if not current() then
			return
		end
		-- Nothing loaded. Leave the best candidate assigned rather than blanking
		-- it, so a slow asset can still paint itself in later.
		image.Image = firstContent
		if onDone then
			onDone(false)
			if firstContent ~= "" then
				image:GetPropertyChangedSignal("IsLoaded"):Once(function()
					if image.IsLoaded and current() then
						onDone(true)
					end
				end)
			end
		end
	end)
end

-- Avatar thumbnails without an API round-trip. `kind` is "head" (default),
-- "bust" or "body"; rbxthumb only accepts a fixed set of sizes.
function Asset.headshot(userId: number, size: number?, kind: string?): string
	local kinds = {
		head = "AvatarHeadShot",
		bust = "AvatarBust",
		body = "Avatar",
	}
	local thumbType = kinds[kind or "head"] or "AvatarHeadShot"
	local px = size or 150
	-- snap to the sizes rbxthumb actually serves
	local allowed = { 48, 60, 75, 100, 150, 180, 352, 420 }
	local best = allowed[1]
	for _, candidate in allowed do
		if math.abs(candidate - px) < math.abs(best - px) then
			best = candidate
		end
	end
	return ("rbxthumb://type=%s&id=%d&w=%d&h=%d"):format(thumbType, math.floor(userId), best, best)
end

-- Pre-warm a set of images (ids, paths or urls) off the caller's thread, so the
-- first frame that shows them isn't the one that downloads them.
function Asset.preload(list: { any })
	task.spawn(function()
		local contents = {}
		for _, item in list do
			local resolved = Asset.resolve(item)
			if resolved ~= "" then
				local holder = Instance.new("ImageLabel")
				holder.Image = resolved
				table.insert(contents, holder)
			end
		end
		pcall(function()
			Services.ContentProvider:PreloadAsync(contents)
		end)
		for _, holder in contents do
			holder:Destroy()
		end
	end)
end

return Asset

end

__modules['util.Bind'] = function(...)
--!strict
-- util/Bind.lua — the keybind router + mode machine behind every bindable
-- control.
--
-- One pair of UserInputService listeners (created with the Window, torn down
-- with it) fans every press out to the registered bindings, so N bound controls
-- cost 2 connections instead of 2N — and every binding gets the same
-- gameProcessed / key-capture gating for free.
--
-- A binding is a key + a MODE, and the mode is the point:
--
--   Toggle   press flips the value (the default)
--   Hold     value is true only while the key is held down
--   Press    fires once per press, carries no state (commands: rejoin, respawn)
--   Always   value is forced on; the key does nothing while it's selected
--   None     no activation at all — the control is only a key picker
--
-- Bindings never poll input themselves; the router pushes to them. Mouse
-- buttons are routed as well as keyboard keys (pass
-- `Enum.UserInputType.MouseButton2` as the key); components/BindChip.lua binds
-- MB2/MB3 from a click on the armed chip, and leaves MB1 to the caller.
--
-- The router is also the *registry* every binding is already in, which is what
-- components/Hud.lua reads: `Bind:Observe(fn)` fires on any change (a bind
-- registered, re-keyed, mode-cycled, activated, destroyed) and `Bind:List()`
-- hands back the live entries. A binding carries a `Label` so it has something
-- to be called in that list — an unlabeled one is internal plumbing and stays
-- out of it (`Binding:IsListed`).
--
-- Bindings also form a shallow TREE. A control declares `Parent = "<id>"` (see
-- `Binding:GetParent`) to say "I'm a sub-option of that feature" — Sticky Aim
-- under Aimbot, Wall Check under ESP. That relationship is what keeps the HUD
-- from turning into an inventory of the menu: switching one parent on used to
-- put every sub-option it enables on screen as its own row, which is the exact
-- wall of text the panel exists to avoid.

local Services = __require("util.Services")

local UserInputService = Services.UserInputService

local Log = __require("util.Log")
local Signal = __require("util.Signal")

local Bind = {}
Bind.__index = Bind

local Binding = {}
Binding.__index = Binding

-- ── keys ────────────────────────────────────────────────────────────────────
-- A "key" is an Enum.KeyCode, or one of the mouse UserInputTypes below.
local MOUSE_NAME: { [Enum.UserInputType]: string } = {
	[Enum.UserInputType.MouseButton1] = "MB1",
	[Enum.UserInputType.MouseButton2] = "MB2",
	[Enum.UserInputType.MouseButton3] = "MB3",
}
local NAME_MOUSE: { [string]: Enum.UserInputType } = {}
for input, name in MOUSE_NAME do
	NAME_MOUSE[name] = input
end

-- The chip is ~44px wide in a toggle row, and "RightControl" is not going to
-- fit. Shorten the ones people actually bind; everything else keeps its name.
local SHORT: { [string]: string } = {
	LeftShift = "LShift",
	RightShift = "RShift",
	LeftControl = "LCtrl",
	RightControl = "RCtrl",
	LeftAlt = "LAlt",
	RightAlt = "RAlt",
	LeftSuper = "LSuper",
	RightSuper = "RSuper",
	Backspace = "Bksp",
	CapsLock = "Caps",
	PageDown = "PgDn",
	PageUp = "PgUp",
	Insert = "Ins",
	Delete = "Del",
	Escape = "Esc",
	Return = "Enter",
}
local LONG: { [string]: string } = {}
for long, short in SHORT do
	LONG[short] = long
end

-- Is `v` something the router can bind? (KeyCode, or a mouse button.)
function Bind.isKey(v: any): boolean
	if typeof(v) ~= "EnumItem" then
		return false
	end
	return (v :: any).EnumType == Enum.KeyCode or MOUSE_NAME[v :: any] ~= nil
end

-- Display name for a key. `nil` / Unknown reads as "None" — an unbound control.
function Bind.name(key: any): string
	if not Bind.isKey(key) or key == Enum.KeyCode.Unknown then
		return "None"
	end
	local mouse = MOUSE_NAME[key]
	if mouse then
		return mouse
	end
	return SHORT[key.Name] or key.Name
end

-- Inverse of Bind.name, for config load. Accepts both the short display name
-- and the raw enum name, so hand-written configs work either way.
function Bind.parse(name: any): any
	if Bind.isKey(name) then
		return name
	end
	if type(name) ~= "string" or name == "" then
		return Enum.KeyCode.Unknown
	end
	local mouse = NAME_MOUSE[name]
	if mouse then
		return mouse
	end
	local ok, key = pcall(function()
		return (Enum.KeyCode :: any)[LONG[name] or name]
	end)
	return (ok and key) or Enum.KeyCode.Unknown
end

-- ── modes ───────────────────────────────────────────────────────────────────
local CANON: { [string]: string } = {
	none = "None",
	toggle = "Toggle",
	hold = "Hold",
	press = "Press",
	always = "Always",
}
-- What right-clicking a chip cycles through when the caller doesn't say.
Bind.DefaultModes = { "Toggle", "Hold", "Always" }

-- Normalize a caller-supplied mode. Case-insensitive; an unknown value warns
-- and falls back rather than killing the build over a typo.
function Bind.mode(value: any, where: string?, fallback: string?): string
	if value == nil then
		return fallback or "Toggle"
	end
	local canon = type(value) == "string" and CANON[(value :: string):lower()] or nil
	if not canon then
		Log.warn(where or "Keybind", ('Mode "%s" is not one of Toggle / Hold / Press / Always / None — using %s.')
			:format(tostring(value), fallback or "Toggle"))
		return fallback or "Toggle"
	end
	return canon
end

-- ── parent references ───────────────────────────────────────────────────────
-- `Parent` is matched by NAME, not by object, because the sub-option is almost
-- always built before the caller has anything to hand it: the parent toggle's
-- handle exists, but the section under it is written in the same breath and a
-- hub that builds its menu from a table has no locals at all. A name also
-- survives the parent being rebuilt.
--
-- Matching is case- and space-insensitive against the parent's `Id` (a control's
-- Flag) *or* its `Label` (the control's Name), so `Parent = "Aimbot"` and
-- `Parent = "aimbot"` both find the toggle named "Aimbot" with `Flag = "aimbot"`
-- — the two things a call site actually has to hand.
local function normalize(s: string): string
	return (s:lower():gsub("%s+", ""))
end

-- A handle is accepted too (the toggle handle, its `.Bind` chip handle, or a
-- raw binding), for the case where the caller does have the parent in a local.
local function refKey(v: any): any
	if type(v) == "string" and v ~= "" then
		return normalize(v)
	end
	if type(v) == "table" then
		local binding = v
		if type(rawget(binding, "Bind")) == "table" then
			binding = rawget(binding, "Bind")
		end
		if type(rawget(binding, "Binding")) == "table" then
			binding = rawget(binding, "Binding")
		end
		if getmetatable(binding) == Binding then
			return binding
		end
	end
	return nil
end

-- ── manager ─────────────────────────────────────────────────────────────────
function Bind.new(ctx: any): any
	local self = setmetatable({
		ctx = ctx,
		entries = {} :: { any },
		connections = {} :: { RBXScriptConnection },
		observers = Signal.new(),
		-- Bumped on every registry change — what observers (the HUD) repaint off.
		revision = 0,
		-- Bumped only when the bind TREE itself can have moved: a binding
		-- registered or destroyed, a label renamed, a parent re-pointed. The
		-- parent/children lookups memoize against THIS, not `revision`.
		--
		-- They used to memoize against `revision`, which moves on every
		-- activation — so a single key press (and again on release) invalidated
		-- every cached parent in the window, and the HUD's repaint re-resolved the
		-- whole graph from scratch: an O(n) scan per parented binding, with a
		-- `:lower():gsub()` per candidate, plus an O(n) child walk per drawn row.
		-- Since components/Toggle.lua gives every toggle a binding, a big hub is
		-- 100+ entries and that was thousands of string allocations per keystroke,
		-- on the input thread. None of it can change from an activation.
		structure = 0,
	}, Bind)

	table.insert(self.connections, UserInputService.InputBegan:Connect(function(input, gameProcessed)
		self:_dispatch(input, gameProcessed, true)
	end))
	-- Releases are NOT gated on gameProcessed / capture: a Hold binding that went
	-- down legitimately must come back up even if focus moved to a textbox in
	-- between, or the feature sticks on with no key to turn it off.
	table.insert(self.connections, UserInputService.InputEnded:Connect(function(input)
		self:_dispatch(input, false, false)
	end))

	return self
end

-- The manager lives on the Context so every component can reach it. Window
-- creates it up front (and tracks its connections for teardown); this lazy
-- accessor is just so a control built outside a Window still works.
function Bind.get(ctx: any): any
	local existing = rawget(ctx, "_binds")
	if not existing then
		existing = Bind.new(ctx)
		rawset(ctx, "_binds", existing)
	end
	return existing
end

-- ── registry observers ──────────────────────────────────────────────────────
-- Anything that draws the bind list (components/Hud.lua) subscribes here rather
-- than hooking each binding's `onState` — which is already spoken for by the
-- chip that owns it. Returns an unsubscribe function; a consumer that outlives
-- nothing (a HUD is destroyed with the window) must still call it, or its dead
-- closure runs on every keypress forever.
function Bind:Observe(fn: () -> ()): () -> ()
	return self.observers:Connect(fn)
end

-- Every registered binding, in registration order. A snapshot: callers are free
-- to add or drop bindings while walking it.
function Bind:List(): { any }
	return table.clone(self.entries)
end

-- `Bind:List()` without the copy — the LIVE array, for a walk that only reads,
-- doesn't outlive itself, and happens often enough for the copy to matter.
-- components/Hud.lua's repaint is the case: it runs on every activation edge (a
-- Hold key down and up is two) and only asks each binding what it currently is.
--
-- Registering or destroying a binding while iterating this will corrupt the walk.
-- If you might do either, or you're keeping the result, use `List`.
function Bind:Entries(): { any }
	return self.entries
end

-- Called synchronously on every change, so a HUD repaints in the same frame as
-- the key that moved it (the same reason Binding:_set paints before it spawns
-- the user callback).
function Bind:_changed()
	self.revision += 1
	self.observers:Fire()
end

-- A change that can move the parent/child graph, as opposed to one that only
-- moves a value. The structural counter is bumped BEFORE the observers run, so
-- a HUD repainting from inside `fn` resolves against the new tree rather than a
-- memo of the old one.
function Bind:_restructured()
	self.structure += 1
	self:_changed()
end

-- Unknown is NOT a key: it's what an unbound binding stores (a fresh chip, one
-- cleared with Backspace, a config whose key name didn't parse). The engine also
-- reports KeyCode.Unknown for keys it has no mapping for, and without this every
-- unbound binding in the window would fire on one of them at once.
-- Exported as `Bind.of` because the router isn't the only listener that has to
-- turn an InputObject into a key: Window's toggle-key listener compares against
-- one too, and comparing `input.KeyCode` alone silently ignored every mouse
-- binding (a mouse press reports KeyCode.Unknown).
function Bind.of(input: InputObject): any?
	if input.UserInputType == Enum.UserInputType.Keyboard then
		return input.KeyCode ~= Enum.KeyCode.Unknown and input.KeyCode or nil
	end
	return MOUSE_NAME[input.UserInputType] and input.UserInputType or nil
end
local keyOf = Bind.of

function Bind:_dispatch(input: InputObject, gameProcessed: boolean, began: boolean)
	local key = keyOf(input)
	if not key then
		return
	end
	if began and (gameProcessed or self.ctx:IsCapturing()) then
		return -- typing into a textbox, or a chip is listening for this very press
	end
	-- Walked by index over the LIVE array rather than over a clone.
	--
	-- This runs on every key and every mouse press in the game, in both
	-- directions, over an array that holds one entry per bindable control — and
	-- since components/Toggle.lua gives every toggle a chip, a large hub is 150+
	-- of them. `table.clone` there was a 150-element allocation per press edge, on
	-- the input thread, purely to survive a callback that mutates the registry.
	--
	-- A callback is free to register or destroy bindings from inside this loop, so
	-- nothing here assumes the array is stable. What it guarantees instead:
	--   * nothing is dispatched to twice;
	--   * nothing still registered when the walk ends is skipped. The index only
	--     advances when the entry it just handled is STILL at that index — a
	--     destroy shifts everything after it down by one, so whatever moved into
	--     this slot is visited next rather than stepped over;
	--   * `n` pins the length on entry, so the walk can't be extended by a
	--     registration (a binding created by this press doesn't receive it).
	--
	-- It is NOT identical to the clone, and the difference is the point: the
	-- snapshot went on dispatching to bindings a callback had already destroyed
	-- earlier in the same press — flipping `state` on a dead binding and waking
	-- every registry observer for it, after `Destroy` had nil'd its callbacks.
	-- Those are skipped now. A destroyed binding shouldn't activate.
	--
	-- (One consequence, for completeness: a callback that destroys one binding and
	-- registers another in the same press leaves the length unchanged, so the new
	-- one lands in a slot this walk still visits. Nothing in the library does that,
	-- and either answer is defensible.)
	local entries = self.entries
	local n = #entries
	local i = 1
	while i <= n do
		local entry = entries[i]
		if entry == nil then
			break
		end
		if began then
			if entry.key == key then
				entry:_press()
			end
		elseif entry._downKey == key then
			entry:_release()
		end
		if entries[i] == entry then
			i += 1
		end
		-- Removals shrink the walk; registrations don't extend it.
		if #entries < n then
			n = #entries
		end
	end
end

-- Register a binding.
--   Key        Enum.KeyCode | mouse Enum.UserInputType   (Unknown = unbound)
--   Mode       "Toggle" | "Hold" | "Press" | "Always" | "None"
--   Modes      the cycle list a UI chip offers (defaults to Bind.DefaultModes)
--   Default    starting state for Toggle/Hold
--   Label      what to call this bind in a bind list / HUD (unnamed = hidden)
--   Id         name other binds refer to this one by (defaults to Label)
--   Parent     the Id / Label of the feature this one is a sub-option of
--   Hud        true / false to force it into or out of that list
--   Callback   fn(active, info) — info = { Key, Mode, KeyName }
--   OnChanged  fn(key, mode) — the bind itself changed
--   OnState    internal, synchronous paint hook (used by the chip)
--   GetState   external source of truth for Toggle mode (a Toggle's own value)
function Bind:Register(opts: any): any
	opts = opts or {}
	local where = opts.Where or "Keybind"
	local entry = setmetatable({
		manager = self,
		key = Bind.isKey(opts.Key) and opts.Key or Enum.KeyCode.Unknown,
		mode = Bind.mode(opts.Mode, where),
		modes = opts.Modes or Bind.DefaultModes,
		state = opts.Default == true,
		enabled = true,
		label = (type(opts.Label) == "string" and opts.Label ~= "") and opts.Label or nil,
		id = (type(opts.Id) == "string" and opts.Id ~= "") and opts.Id or nil,
		-- Normalized once here (and again in SetLabel) rather than per comparison:
		-- `Binding:_named` is called O(entries) times per unresolved parent, and
		-- lowercasing + stripping spaces on both sides of every one of those was
		-- the bulk of a HUD repaint's cost.
		_normId = nil :: string?,
		_normLabel = nil :: string?,
		parentKey = refKey(opts.Parent),
		hud = opts.Hud,
		callback = opts.Callback,
		onChanged = opts.OnChanged,
		onState = opts.OnState,
		getState = opts.GetState,
		destroyed = false,
		_downKey = nil :: any,
		_parentRev = nil :: number?,
		_parentCache = nil :: any,
		_childRev = nil :: number?,
		_childCache = nil :: { any }?,
	}, Binding)
	entry._normId = entry.id and normalize(entry.id) or nil
	entry._normLabel = entry.label and normalize(entry.label) or nil
	table.insert(self.entries, entry)
	self:_restructured()

	-- "Always" means on, so a control that loads in Always mode is on from the
	-- first frame without anyone touching a key. Deferred so the caller has its
	-- handle back before the callback runs.
	if entry.mode == "Always" and not entry.state then
		task.defer(function()
			if entry.mode == "Always" then
				entry:_set(true)
			end
		end)
	end
	return entry
end

function Bind:Destroy()
	for _, conn in self.connections do
		conn:Disconnect()
	end
	table.clear(self.connections)
	-- Mark before clearing. `Binding:GetParent` reports a direct-reference parent
	-- as live purely on `not ref.destroyed`, so dropping the entries list on its
	-- own left every binding in a torn-down window still claiming to exist — a
	-- control the caller kept a handle to (or a `Parent = <handle>` child that
	-- outlives us) then went on consulting a dead tree. Clearing the callbacks is
	-- the other half: a `_pulse` timer already in flight must not resume into the
	-- old window's code.
	for _, entry in self.entries do
		entry.destroyed = true
		entry.callback = nil
		entry.onChanged = nil
		entry.onState = nil
	end
	table.clear(self.entries)
	self.observers:Clear()
	self.structure += 1
	self.revision += 1
end

-- ── binding ─────────────────────────────────────────────────────────────────
function Binding:_info(): any
	return { Key = self.key, Mode = self.mode, KeyName = Bind.name(self.key) }
end

-- The binding's idea of the current value. `getState` (a Toggle handing over its
-- own value) wins when it's there — written out rather than `getState() or state`
-- because that idiom falls through to `state` on a legitimate `false`.
function Binding:_value(): boolean
	if self.getState then
		return self.getState() == true
	end
	return self.state
end

-- Push a new activation state out: paint first (synchronous, so the UI never
-- lags a frame behind the key), then the user callback on its own thread so a
-- slow or erroring callback can't stall input dispatch.
function Binding:_set(active: boolean)
	self.state = active
	if self.onState then
		self.onState(active)
	end
	self.manager:_changed()
	if self.callback then
		task.spawn(self.callback, active, self:_info())
	end
end

-- A "Press" bind carries no state, so it blinks instead: on for a beat, then
-- back off. Same signal the chip already showed, now visible to the registry
-- too, so a HUD row flashes when a one-shot command fires.
function Binding:_pulse()
	self.state = true
	if self.onState then
		self.onState(true)
	end
	self.manager:_changed()
	task.delay(0.12, function()
		self.state = false
		if self.onState then
			self.onState(false)
		end
		self.manager:_changed()
	end)
end

function Binding:_press()
	if not self.enabled then
		return
	end
	local mode = self.mode
	if mode == "None" or mode == "Always" then
		return -- Always is on regardless of the key; None never activates
	end
	self._downKey = self.key
	if mode == "Hold" then
		self:_set(true)
	elseif mode == "Press" then
		-- Fire-and-forget command: no state to carry, so both edges read true.
		if self.callback then
			task.spawn(self.callback, true, self:_info())
		end
		self:_pulse()
	else -- Toggle
		self:_set(not self:_value())
	end
end

function Binding:_release()
	self._downKey = nil
	-- Deliberately NOT gated on `enabled`: a Hold bind that was disabled while its
	-- key was down still has to come back up, or it sticks on with `_press` now
	-- gated too — nothing left that could ever turn it off. Same reasoning as the
	-- gameProcessed exemption in the header.
	if self.mode == "Hold" and self.state then
		self:_set(false)
	end
end

function Binding:GetKey(): any
	return self.key
end

function Binding:SetKey(key: any, silent: boolean?)
	-- Re-keying with a press still outstanding strands the feature ON: _downKey is
	-- cleared below, so the old key's release matches nothing and there is no
	-- longer anything that turns it off. Drop it first. Gated on `_downKey` rather
	-- than on `state` alone — a Hold bind whose key isn't down but whose value is
	-- true is a config being restored, and that value is the caller's to keep.
	if self._downKey ~= nil and self.mode == "Hold" and self.state then
		self:_set(false)
	end
	self.key = Bind.isKey(key) and key or Enum.KeyCode.Unknown
	self._downKey = nil
	self.manager:_changed()
	if not silent and self.onChanged then
		self.onChanged(self.key, self.mode)
	end
end

function Binding:GetMode(): string
	return self.mode
end

function Binding:SetMode(mode: string, silent: boolean?)
	local previous = self.mode
	self.mode = Bind.mode(mode, "Keybind", previous)
	if self.mode == previous then
		-- _downKey deliberately untouched on a no-op: clearing it mid-hold would
		-- strand a Hold bind on. Config load calls this unconditionally whenever the
		-- saved record carries a Mode, so the no-op path is the common one.
		return
	end
	self._downKey = nil
	self.manager:_changed()
	if self.mode == "Always" then
		self:_set(true)
	elseif (self.mode == "Hold" or self.mode == "Press" or self.mode == "None") and not silent then
		-- ENTERING a mode that can't hold a value on its own. Hold's value exists
		-- only while the key is down, Press carries no value at all, and None never
		-- activates — so anything the previous mode left ON is now on with nothing
		-- holding it there and no key that can turn it off (worse for None, which
		-- also drops out of the HUD while the feature is still running). Drop it the
		-- moment the mode changes rather than making the user tap the key once just
		-- to clear it. `_downKey` was cleared just above, so there's no hold in
		-- progress to fight.
		--
		-- `silent` (only ever set by the config-restore path in BindChip:SetFlag) opts
		-- out: a saved Hold bind that was on is a value the caller chose to persist,
		-- and the load pass isn't a user flipping the mode.
		if self:_value() then
			self:_set(false)
		end
	elseif previous == "Hold" and self:_value() then
		-- Leaving Hold with the key down would strand the feature on.
		self:_set(false)
	end
	-- Leaving Always deliberately keeps whatever value it left behind — dropping
	-- straight to off would kill a feature the user only meant to re-key.
	if not silent and self.onChanged then
		self.onChanged(self.key, self.mode)
	end
end

function Binding:GetModes(): { string }
	return self.modes
end

function Binding:GetState(): boolean
	return self.state
end

function Binding:GetLabel(): string?
	return self.label
end

function Binding:SetLabel(label: string?)
	self.label = (type(label) == "string" and label ~= "") and label or nil
	self._normLabel = self.label and normalize(self.label) or nil
	-- Structural: a child pointing at this bind by name resolves differently now.
	self.manager:_restructured()
end

-- ── the tree ────────────────────────────────────────────────────────────────
-- Does `key` (already normalized) name this binding? `key` is never nil here —
-- `refKey` rejects the empty string and `GetParent` returns early on nil — so a
-- binding with neither an id nor a label can't match by both being absent.
function Binding:_named(key: string): boolean
	return self._normId == key or self._normLabel == key
end

-- The feature this bind is a sub-option of, or nil. Resolved lazily and cached
-- against the manager's STRUCTURAL revision: the parent may not have been
-- registered yet when the child was, and it can be destroyed and rebuilt under
-- it — but nothing a keypress does can change the answer, which is why this
-- memo deliberately doesn't key off `revision` (see Bind.new).
--
-- An unresolvable name is nil, deliberately — a typo, or a parent the host
-- didn't build in this game, degrades to "top-level feature" rather than
-- silently hiding the control from the HUD forever.
function Binding:GetParent(): any?
	local ref = self.parentKey
	if ref == nil then
		return nil
	end
	if type(ref) == "table" then
		return (not ref.destroyed) and ref or nil
	end
	local manager = self.manager
	if self._parentRev == manager.structure then
		return self._parentCache
	end
	local found: any = nil
	for _, entry in manager.entries do
		if entry ~= self and entry:_named(ref) then
			found = entry
			break
		end
	end
	self._parentRev = manager.structure
	self._parentCache = found
	return found
end

function Binding:SetParent(parent: any)
	self.parentKey = refKey(parent)
	self._parentRev = nil
	self.manager:_restructured()
end

-- The live children list, memoized against the manager's structural revision.
-- Only the membership is cached — every caller reads the children's *state*
-- fresh — so an activation never has to invalidate it.
function Binding:_children(): { any }
	local manager = self.manager
	if self._childRev == manager.structure and self._childCache then
		return self._childCache
	end
	local out = {}
	for _, entry in manager.entries do
		if entry ~= self and entry:GetParent() == self then
			table.insert(out, entry)
		end
	end
	self._childRev = manager.structure
	self._childCache = out
	return out
end

-- Sub-options of this bind, in registration order. A copy: the cache above is
-- the library's, and a caller sorting or appending to it would corrupt every
-- later read.
function Binding:GetChildren(): { any }
	return table.clone(self:_children())
end

-- Does this bind belong in a bind list / HUD? Four rules:
--   * it needs a name — an unlabeled binding is internal plumbing, and a row
--     reading "None" tells nobody anything;
--   * it needs a mode that can actually go live — "None" is a pure key picker
--     (the Settings tab's Toggle-UI bind), which never activates;
--   * a KEY on it lists it outright — putting a key on something is the user
--     saying they want to be able to find it;
--   * with no key, it lists only while it's ON **and** it isn't a sub-option of
--     something else.
--
-- The key clause is what keeps the panel from being an inventory of the whole
-- menu: since components/Toggle.lua gives *every* toggle a chip, listing the
-- unbound ones would be a wall of "— · toggle" rows burying the handful the user
-- actually bound.
--
-- The "on right now" clause is the other half of the HUD's job. The panel
-- answers "what's running?", and a feature the user enabled by clicking it is
-- running whether or not they ever put a key on it — an "Always" bind ignores
-- its key by definition, and a keyless Toggle switched on from the menu is no
-- different from the outside.
--
-- The PARENT clause is what stops that second half from being its own flood.
-- Turning Aimbot on means turning on the eight sub-options that make it work,
-- and every one of those is a toggle that is now "running" — so the panel filled
-- with Sticky Aim / Wall Check / Auto Fire rows saying nothing the "Aimbot" row
-- above them didn't. A sub-option is spoken for by its parent, so a keyless one
-- stays out and the parent row carries the count instead (components/Hud.lua).
-- Put a key on it and it's back — that's the user asking for it by name.
--
-- Note this makes an ON sub-option of an OFF parent invisible, which is correct:
-- a sub-option of a feature that isn't running isn't running either.
--
-- `Hud = true/false` at registration overrides all four.
function Binding:IsListed(): boolean
	if self.hud ~= nil then
		return self.hud == true
	end
	if self.label == nil or self.mode == "None" then
		return false
	end
	if Bind.isKey(self.key) and self.key ~= Enum.KeyCode.Unknown then
		return true
	end
	return self:_value() and self:GetParent() == nil
end

-- Sub-options that are ON but rolled up into this row (the "+2" the HUD draws).
-- Counted, not listed: the point of the roll-up is that the detail lives in the
-- menu, and the panel only has to say the feature is running with more than its
-- bare minimum switched on.
function Binding:CountActive(): number
	local n = 0
	for _, child in self:_children() do
		if child:_value() and not child:IsListed() then
			n += 1
		end
	end
	return n
end

-- Sync the binding's idea of the value without firing the callback — used when
-- something else (a click on the toggle, a config load) moved it.
function Binding:SetState(active: boolean, fire: boolean?)
	if fire then
		self:_set(active == true)
		return
	end
	self.state = active == true
	if self.onState then
		self.onState(self.state)
	end
	self.manager:_changed()
end

function Binding:SetEnabled(enabled: boolean)
	self.enabled = enabled ~= false
	self.manager:_changed()
end

function Binding:Destroy()
	local list = self.manager.entries
	for i = #list, 1, -1 do
		if list[i] == self then
			table.remove(list, i)
			break
		end
	end
	-- Marked as well as removed: a child holding a direct reference to this
	-- binding (`Parent = someHandle`) has no other way to tell it's gone, and
	-- would keep hiding itself behind a parent that isn't on screen any more.
	self.destroyed = true
	self.callback = nil
	self.onChanged = nil
	self.onState = nil
	self.manager:_restructured()
end

return Bind

end

__modules['util.Collapse'] = function(...)
--!strict
-- util/Collapse.lua — animate a frame collapsing/expanding by height.
--
-- Wraps an AutomaticSize.Y `content` frame in a ClipsDescendants holder whose
-- height is what actually animates. While open the holder tracks the content via
-- AutomaticSize.Y (so dynamically-added controls still grow it); during the
-- collapse/expand it switches to a manual offset height that we tween to/from 0.
-- The content keeps its natural size the whole time (clipping only hides it), so
-- the target height can be read straight off it even while collapsed.

local Tween = __require("util.Tween")
local Create = __require("util.Create")

local Collapse = {}

-- `content` must be (1, 0) wide with AutomaticSize.Y. Returns the holder to drop
-- into the surrounding layout, plus `set(collapsed, animate)`.
function Collapse.wrap(content: GuiObject, startCollapsed: boolean): (Frame, (boolean, boolean?) -> ())
	local holder = Create("Frame", {
		Name = "Collapse",
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 0),
		ClipsDescendants = true,
		AutomaticSize = startCollapsed and Enum.AutomaticSize.None or Enum.AutomaticSize.Y,
	})
	content.Parent = holder

	local collapsed = startCollapsed
	local activeTween: Tween? = nil
	local watcher: RBXScriptConnection? = nil
	-- Bumped by every `set`, so a tween/watcher left over from the previous state
	-- can't finalise on top of the current one.
	local generation = 0

	local function stop()
		generation += 1
		if activeTween then
			activeTween:Cancel()
			activeTween = nil
		end
		if watcher then
			watcher:Disconnect()
			watcher = nil
		end
	end

	-- Expanding measures a target the content can't honestly report yet: while
	-- collapsed the holder is 0px and clipping, so the subtree isn't rendered and
	-- anything sized from a render pass (wrapped text, auto-sized rows still
	-- settling) measures short or not at all. Tweening to that snapshot and then
	-- handing height back to AutomaticSize made the panel slide part of the way
	-- and snap the remainder in. So the expand watches the content and re-aims
	-- while it's in flight: a re-aim starts from the height the holder is at right
	-- now, so the motion stays continuous and simply carries on to the real one.
	local function expand()
		local gen = generation
		local target = -1

		local function slideTo(height: number)
			if activeTween then
				activeTween:Cancel()
			end
			local t = Tween.play(holder, Tween.Slide, { Size = UDim2.new(1, 0, 0, height) })
			activeTween = t
			t.Completed:Once(function(state)
				if gen ~= generation or state ~= Enum.PlaybackState.Completed then
					return
				end
				-- Landed on the content's own height: hand tracking back so later
				-- content changes keep growing the holder.
				if watcher then
					watcher:Disconnect()
					watcher = nil
				end
				activeTween = nil
				holder.AutomaticSize = Enum.AutomaticSize.Y
			end)
		end

		watcher = content:GetPropertyChangedSignal("AbsoluteSize"):Connect(function()
			if gen ~= generation then
				return
			end
			local height = content.AbsoluteSize.Y
			-- Sub-pixel churn isn't worth restarting the tween over.
			if math.abs(height - target) < 0.5 then
				return
			end
			target = height
			slideTo(height)
		end)

		target = content.AbsoluteSize.Y
		if target > 0 then
			slideTo(target)
		end
		-- target == 0 means the content has never been laid out (a group built
		-- collapsed and opened before its first render). Nothing to slide to yet —
		-- the watcher above starts the slide the frame it measures.
	end

	local function set(value: boolean, animate: boolean?)
		if value == collapsed then
			return
		end
		collapsed = value
		stop()

		-- `animate == false`, not `not animate`. Every other `animate: boolean?` in
		-- the library reads nil as "yes, animate" (Group:SetCollapsed,
		-- Window:SetMaximized, Hud:SetVisible all spell it `animate ~= false`), and
		-- this one alone read nil as "snap". Both call sites happen to pass an
		-- explicit boolean, so nothing moves today — but the next one to omit it
		-- would have got the opposite of what the rest of the codebase taught them.
		if animate == false then
			holder.AutomaticSize = value and Enum.AutomaticSize.None or Enum.AutomaticSize.Y
			holder.Size = UDim2.new(1, 0, 0, value and 0 or content.AbsoluteSize.Y)
			return
		end

		-- Hand height control to a manual offset for the duration of the tween.
		holder.AutomaticSize = Enum.AutomaticSize.None
		if value then
			-- collapse: freeze at the current rendered height, slide to 0
			holder.Size = UDim2.new(1, 0, 0, holder.AbsoluteSize.Y)
			activeTween = Tween.play(holder, Tween.Slide, { Size = UDim2.new(1, 0, 0, 0) })
		else
			expand()
		end
	end

	return holder, set
end

return Collapse

end

__modules['util.Config'] = function(...)
--!strict
-- util/Config.lua — executor filesystem layer for saving / loading configs.
--
-- Exploit executors expose global file functions (writefile / readfile / …) that
-- don't exist in Studio or live game clients. Everything here is feature-detected
-- and pcall-guarded so the library degrades gracefully (Config.supported = false)
-- instead of erroring where those globals are absent.
--
-- Layout on disk:  <folder>/configs/<name>.json   (one JSON blob per config)
--                  <folder>/autoload.txt          (name of the config to auto-load)

local Services = __require("util.Services")

local HttpService = Services.HttpService

local Config = {}

-- Resolve executor file globals. Executors put these on the SHARED global env
-- (getgenv) — not the chunk env — so prefer that, then fall back to the ambient
-- global / _G. Everything is pcall-guarded: some sandboxes throw merely on
-- touching getgenv/getfenv, and a raw error here would kill the whole library at
-- require time (this module is required by Window).
local genv: any = nil
pcall(function()
	if type(getgenv) == "function" then
		genv = getgenv()
	end
end)

local function g(name: string): any
	-- 1) shared global env (getgenv)
	if type(genv) == "table" then
		local ok, v = pcall(function()
			return genv[name]
		end)
		if ok and v ~= nil then
			return v
		end
	end
	-- 2) ambient global identifier (works when funcs are plain globals)
	local ok2, v2 = pcall(function()
		return (_G :: any)[name]
	end)
	if ok2 and v2 ~= nil then
		return v2
	end
	return nil
end

local g_writefile = g("writefile")
local g_readfile = g("readfile")
local g_isfile = g("isfile")
local g_delfile = g("delfile")
local g_isfolder = g("isfolder")
local g_makefolder = g("makefolder")
local g_listfiles = g("listfiles")

Config.supported = type(g_writefile) == "function"
	and type(g_readfile) == "function"
	and type(g_isfile) == "function"

-- What was detected, so executor file-API gaps are diagnosable. Built as a
-- string rather than printed: this module is required at load time, long before
-- `CreateWindow{ Verbose = ... }` can be read, and an unconditional branded line
-- on every load is a free fingerprint for a game scraping LogService. Window
-- logs it through `Log.info` once it knows whether the host wants output.
Config.report = ("config: supported=%s  writefile=%s readfile=%s isfile=%s listfiles=%s delfile=%s")
	:format(
		tostring(Config.supported),
		type(g_writefile), type(g_readfile), type(g_isfile),
		type(g_listfiles), type(g_delfile)
	)

-- The reserved key a config file carries its metadata under. It sits alongside
-- the flags in the same JSON object, and nothing registers a flag by that name,
-- so `Context:LoadConfig` skips it (see the note there — the skip is a promise,
-- not an accident). `Window:SaveConfig(name, meta)` writes it and
-- `Window:ConfigInfo(name)` reads it back without applying anything.
Config.MetaKey = "__uranium"

-- Strip path separators so a config name can't escape its folder. Wrapped in
-- parens: gsub returns (string, count), and letting that second value escape made
-- `sanitize(name)` in an argument list expand to two arguments.
--
-- Spelled out in ASCII rather than `%w` on purpose. `%w` is whatever the host
-- Lua's isalnum() says, which on some builds counts high bytes as alphanumeric —
-- there, half the bytes of a multi-byte glyph survive the strip and the name no
-- longer round-trips (save writes one filename, the list reads back another).
--
-- This is a CONTRACT, not an implementation detail: every name a caller shows in
-- a config list has to survive it unchanged, because the filename and the
-- autoload pointer are matched by string equality later. It's exported as
-- `Uranium.Config.sanitize` so a host can check a name it builds
-- (`Config.sanitize(n) == n`) instead of reverse-engineering the pattern.
local function sanitize(name: string): string
	local cleaned = (tostring(name):gsub("[^A-Za-z0-9%-_ ]", ""))
	return (cleaned:gsub("^%s*(.-)%s*$", "%1"))
end
Config.sanitize = sanitize

local function configsDir(folder: string): string
	return folder .. "/configs"
end

local function pathFor(folder: string, name: string): string
	return configsDir(folder) .. "/" .. sanitize(name) .. ".json"
end

-- Create `path` and every folder above it. ConfigFolder is documented as
-- free-form, so a host that scopes its configs ("uranium/games/12345" — one
-- folder per place) hands us a path several levels deep. This used to be two
-- flat makefolder calls, which is fine only on executors whose makefolder is
-- itself recursive; on the others the folder was never created and every save
-- silently failed.
local function makeFolders(path: string)
	local parts = {}
	for segment in tostring(path):gmatch("[^/\\]+") do
		table.insert(parts, segment)
	end
	local walked = ""
	for _, segment in parts do
		walked = walked == "" and segment or (walked .. "/" .. segment)
		if not g_isfolder(walked) then
			g_makefolder(walked)
		end
	end
end

local function ensureFolders(folder: string)
	if type(g_isfolder) ~= "function" or type(g_makefolder) ~= "function" then
		return
	end
	pcall(function()
		makeFolders(configsDir(folder)) -- walks `folder` on the way down
	end)
end

-- List saved config names (no path, no extension), sorted.
function Config.list(folder: string): { string }
	local names = {}
	if not Config.supported or type(g_listfiles) ~= "function" then
		return names
	end
	ensureFolders(folder)
	local ok, files = pcall(g_listfiles, configsDir(folder))
	if ok and type(files) == "table" then
		for _, path in files do
			local name = tostring(path):match("([^/\\]+)%.json$")
			if name then
				table.insert(names, name)
			end
		end
	end
	table.sort(names)
	return names
end

-- Every entry point below returns `(result, reason)`. The library already knew
-- which of "no file access" / "no such config" / "corrupt JSON" happened — it
-- just threw the answer away and handed back a bare `false`, which is the
-- difference between a useful toast and "Couldn't load". Reasons are short
-- lowercase phrases meant to be pasted straight into a message.

-- Serialize `data` to JSON and write it. Returns true on success.
function Config.save(folder: string, name: string, data: any): (boolean, string?)
	if not Config.supported then
		return false, "no file access"
	end
	name = sanitize(name)
	if name == "" then
		return false, "invalid name"
	end
	ensureFolders(folder)
	local ok, json = pcall(function()
		return HttpService:JSONEncode(data)
	end)
	if not ok then
		return false, "couldn't encode"
	end
	local wrote = pcall(g_writefile, pathFor(folder, name), json)
	return wrote, wrote and nil or "write failed"
end

-- Read + decode a config. Returns the table, or nil + why not.
function Config.load(folder: string, name: string): (any?, string?)
	if not Config.supported then
		return nil, "no file access"
	end
	local path = pathFor(folder, name)
	local okExists, exists = pcall(g_isfile, path)
	if not okExists or not exists then
		return nil, "no such config"
	end
	local okRead, raw = pcall(g_readfile, path)
	if not okRead then
		return nil, "unreadable"
	end
	local okDecode, data = pcall(function()
		return HttpService:JSONDecode(raw)
	end)
	if not okDecode or type(data) ~= "table" then
		return nil, "corrupt JSON"
	end
	return data
end

-- The metadata a config was stamped with (Config.MetaKey), without touching a
-- single control. This is what "which game does this config belong to?" actually
-- wants to ask — decoding the whole file to read four fields, then discarding it,
-- is the shape every host would otherwise write.
function Config.info(folder: string, name: string): (any?, string?)
	local data, reason = Config.load(folder, name)
	if not data then
		return nil, reason
	end
	local meta = (data :: any)[Config.MetaKey]
	if type(meta) ~= "table" then
		return nil, "no metadata"
	end
	return meta
end

function Config.delete(folder: string, name: string): (boolean, string?)
	if not Config.supported then
		return false, "no file access"
	end
	if type(g_delfile) ~= "function" then
		return false, "executor can't delete files"
	end
	local path = pathFor(folder, name)
	local okExists, exists = pcall(g_isfile, path)
	if not okExists or not exists then
		return false, "no such config"
	end
	local removed = pcall(g_delfile, path)
	return removed, removed and nil or "delete failed"
end

-- Auto-load pointer: which config (if any) to apply on launch.
function Config.setAutoload(folder: string, name: string?)
	if not Config.supported then
		return
	end
	ensureFolders(folder)
	local path = folder .. "/autoload.txt"
	if name and sanitize(name) ~= "" then
		pcall(g_writefile, path, sanitize(name))
	elseif type(g_delfile) == "function" then
		local okExists, exists = pcall(g_isfile, path)
		if okExists and exists then
			pcall(g_delfile, path)
		end
	end
end

function Config.getAutoload(folder: string): string?
	if not Config.supported then
		return nil
	end
	local path = folder .. "/autoload.txt"
	local okExists, exists = pcall(g_isfile, path)
	if not okExists or not exists then
		return nil
	end
	local okRead, raw = pcall(g_readfile, path)
	if okRead and type(raw) == "string" and raw ~= "" then
		-- Trim ONLY. A stray newline from an editor (or another tool writing the
		-- file) would never match a name in the saved-config dropdown — but running
		-- the full sanitize on the way out was worse: the pointer is already written
		-- sanitized, so a second pass could only ever mangle a name that had round-
		-- tripped fine, and did exactly that wherever `%w` disagreed between the
		-- writing session and the reading one. Store verbatim, read verbatim.
		local name = (raw:gsub("^%s*(.-)%s*$", "%1"))
		return name ~= "" and name or nil
	end
	return nil
end

return Config

end

__modules['util.Context'] = function(...)
--!strict
-- util/Context.lua — the object threaded through every component.
--
-- Carries the live accent color (themeable via Window:SetAccent), an accent
-- subscription registry, the single-popover manager used by dropdowns and
-- color pickers (menus mount into a high-ZIndex overlay so they escape the
-- scrolling content's clipping), and the flag registry that backs config
-- save / load (any control given a `Flag` is captured by GetConfig/LoadConfig).

local Create = __require("util.Create")
local Tween = __require("util.Tween")
local Fade = __require("util.Fade")
local Log = __require("util.Log")
local Bind = __require("util.Bind")
local Signal = __require("util.Signal")

local Context = {}
Context.__index = Context

export type Context = typeof(setmetatable(
	{} :: {
		Theme: any,
		Accent: Color3,
		AccentHover: Color3,
		AccentFill: Color3,
		AccentSoft: Color3,
		Keybinds: boolean,
		overlay: Frame,
		Flags: { [string]: { handle: any, kind: string } },
		Groups: { { key: string, handle: any } },
		_groupKeys: { [string]: boolean },
		-- Four watcher registries, all util/Signal.lua. Each one's contract (does
		-- it replay? is it guarded? is it synchronous?) is on its Register/On
		-- method below; the shared mechanics — unsubscribe, and firing over a
		-- snapshot so a listener may unsubscribe itself mid-broadcast — are the
		-- Signal's.
		_consumers: Signal.Signal<Color3, Color3>,
		_flagWatchers: Signal.Signal<string, string>,
		_valueWatchers: Signal.Signal<string, any, string, string>,
		_lastEncoded: { [string]: any },
		_source: string,
		_windowState: Signal.Signal<>,
		_popover: {
			menu: Instance,
			catcher: Instance,
			conns: { RBXScriptConnection },
			onClose: (() -> ())?,
			fade: any,
		}?,
		_capturing: number,
	},
	Context
))

-- The hover shade of an accent. Lerping toward white washed the color out (the
-- Uranium accent went pastel-mint); brightening in HSV instead keeps the hue and
-- most of the saturation, so #00C46A hovers to ~#1FE087 like the palette says.
local function hover(accent: Color3): Color3
	local h, s, v = accent:ToHSV()
	return Color3.fromHSV(h, math.max(0, s - 0.12), math.min(1, v + 0.12))
end

-- The accent, deepened, for LARGE solid fills (primary buttons). The accent is
-- sized for small marks — a 6px slider fill, a 23px toggle track. The same
-- colour across a 36px full-width button is a searing slab that drowns
-- everything around it, so big fills sit ~18% darker and *hover up* to the full
-- accent, which also gives the press somewhere to go.
local function fill(accent: Color3): Color3
	local h, s, v = accent:ToHSV()
	return Color3.fromHSV(h, math.min(1, s + 0.06), v * 0.82)
end

-- The accent laid *into* a surface — a tinted tile rather than a painted one.
-- Used where something needs to read as accent-coloured across an area too big
-- for the real accent (active nav tile, avatar placeholders, badges): the icon
-- or text on top carries the actual colour, the tile just tints under it.
local function soft(theme: any, accent: Color3): Color3
	return theme.Colors.card:Lerp(accent, 0.13)
end

function Context.new(theme: any, overlay: Frame, accent: Color3): Context
	return setmetatable({
		Theme = theme,
		Accent = accent,
		AccentHover = hover(accent),
		AccentFill = fill(accent),
		AccentSoft = soft(theme, accent),
		-- Are controls bindable unless they say otherwise? Window flips this from
		-- `CreateWindow{ Keybinds = false }`; a control built without a Window (a
		-- test harness) gets the default. Read it as `ctx.Keybinds ~= false` so a
		-- context predating the field still means "yes".
		Keybinds = true,
		overlay = overlay,
		Flags = {},
		-- Every collapsible group in the window, in build order, each under a
		-- stable key — see RegisterGroup. Window snapshots this for the
		-- `uranium_window` flag; nothing else reads it.
		Groups = {},
		_groupKeys = {},
		_consumers = Signal.new(),
		_flagWatchers = Signal.new(),
		_valueWatchers = Signal.new(),
		_lastEncoded = {},
		-- Where the change currently being applied came from. "code" is the
		-- resting state (a programmatic :Set); the two interesting cases push
		-- their own over it — see WithSource.
		_source = "code",
		_windowState = Signal.new(),
		_popover = nil,
		_capturing = 0,
	}, Context)
end

-- ── Key capture ─────────────────────────────────────────────────────────────
-- A control that's listening for a raw keypress (Keybind) claims capture for the
-- duration. The window's toggle-key listener sits on UserInputService, which
-- doesn't know a control is mid-bind, so without this, binding a key also
-- toggled the window on the very keystroke being bound.
function Context:BeginCapture()
	self._capturing += 1
end

function Context:EndCapture()
	self._capturing = math.max(0, self._capturing - 1)
end

function Context:IsCapturing(): boolean
	return self._capturing > 0
end

-- Register a function recolored whenever the accent changes. Called once now
-- with the current accent so callers don't duplicate the initial paint. The
-- derived shades (`ctx.AccentFill` / `ctx.AccentSoft`) are refreshed *before*
-- consumers run, so a callback can read them straight off ctx. Returns
-- an unsubscribe function — transient consumers (e.g. toasts) must call it on
-- teardown or their dead closures pile up in the registry and fire on every
-- SetAccent forever.
function Context:RegisterAccent(fn: (Color3, Color3) -> ()): () -> ()
	local unsubscribe = self._consumers:Connect(fn)
	fn(self.Accent, self.AccentHover) -- the initial paint; Signal never replays
	return unsubscribe
end

-- The three derived weights for an ARBITRARY colour, in the same order the live
-- ones sit on ctx: hover / large-fill / tinted-tile. For anything that paints a
-- colour the window accent doesn't own — a per-tab accent (components/Tab.lua) —
-- so it ramps exactly like SetAccent ramps the global one instead of growing a
-- second, hand-rolled set of shades. Keep reading ctx.AccentFill / ctx.AccentSoft
-- for the live accent; this is only for the exceptions.
function Context:Shades(color: Color3): (Color3, Color3, Color3)
	return hover(color), fill(color), soft(self.Theme, color)
end

function Context:SetAccent(color: Color3)
	self.Accent = color
	self.AccentHover = hover(color)
	self.AccentFill = fill(color)
	self.AccentSoft = soft(self.Theme, color)
	-- Unguarded on purpose: these are the library's own re-theme callbacks, not a
	-- host's, so one throwing is our bug and should surface rather than be logged
	-- and stepped over. (Firing over a snapshot — so a consumer may unsubscribe
	-- itself mid-broadcast without skipping the next control — is Signal's job.)
	self._consumers:Fire(self.Accent, self.AccentHover)
end

-- ── Flags / config ──────────────────────────────────────────────────────────
-- Each control kind serializes its value to a JSON-safe form and back. Color3 /
-- Enum.KeyCode aren't JSON-encodable, so they round-trip through hex / name.
local Codec: { [string]: { encode: (any) -> any, decode: (any) -> any } } = {
	toggle = {
		encode = function(v) return v == true end,
		decode = function(v) return v == true end,
	},
	slider = {
		encode = function(v) return v end,
		decode = function(v) return tonumber(v) or 0 end,
	},
	input = {
		encode = function(v) return tostring(v) end,
		decode = function(v) return tostring(v) end,
	},
	code = { -- raw editor text; stored verbatim like input
		encode = function(v) return tostring(v) end,
		decode = function(v) return tostring(v) end,
	},
	dropdown = {
		-- string | { string } — both JSON-safe. "Nothing selected" is `nil`, and a
		-- nil assignment leaves the key out of the table entirely, so the flag never
		-- reached the file: saving with no selection and loading it back left
		-- whatever had been picked since. `false` is the stand-in that survives the
		-- JSON round trip; decode hands nil back.
		encode = function(v) if v == nil then return false end return v end,
		decode = function(v) if v == false then return nil end return v end,
	},
	keybind = {
		encode = function(v) return (typeof(v) == "EnumItem" and v.Name) or "Unknown" end,
		decode = function(v)
			local ok, key = pcall(function()
				return (Enum.KeyCode :: any)[v]
			end)
			return (ok and key) or Enum.KeyCode.Unknown
		end,
	},
	-- A bind is a key AND a mode (Toggle / Hold / Press / Always / None), so it
	-- persists as a pair via the handle's GetFlag/SetFlag. Configs written before
	-- modes existed hold a bare key name, so decode still accepts a plain string.
	bind = {
		encode = function(v)
			if typeof(v) == "EnumItem" then
				return { key = Bind.name(v), mode = "None" }
			elseif type(v) == "table" then
				return { key = Bind.name(v.Key), mode = v.Mode or "None" }
			end
			return { key = "None", mode = "None" }
		end,
		decode = function(v)
			if type(v) == "string" then
				return { Key = Bind.parse(v) }
			elseif type(v) == "table" then
				return { Key = Bind.parse(v.key), Mode = v.mode }
			end
			return { Key = Bind.parse(v) } -- anything unrecognized parses to Unknown
		end,
	},
	-- The bind HUD (components/Hud.lua) isn't a control and has no single value —
	-- it persists as where you put it and whether it was up, through the same
	-- GetFlag/SetFlag pair the bind codec uses.
	hud = {
		encode = function(v)
			if type(v) ~= "table" then
				return { visible = false }
			end
			local record: any = {
				visible = v.Visible == true,
				collapsed = v.Collapsed == true,
			}
			-- Coordinates only when there actually are some. A window whose HUD was
			-- never built reports `{ Visible = false }` and nothing else, and
			-- `floor(nil or 0)` wrote that down as a real position of (0, 0) — loading
			-- the config in a session where the HUD *is* up teleported it into the
			-- corner instead of leaving it where the user put it.
			local x, y = tonumber(v.X), tonumber(v.Y)
			if x and y then
				record.x = math.floor(x)
				record.y = math.floor(y)
			end
			return record
		end,
		decode = function(v)
			if type(v) ~= "table" then
				return { Visible = v == true }
			end
			return {
				Visible = v.visible == true,
				Collapsed = v.collapsed == true,
				X = tonumber(v.x),
				Y = tonumber(v.y),
			}
		end,
	},
	-- The window's own UI state — where it sits, whether it's maximized, which tab
	-- is open and which groups are folded. Like `hud` it isn't a control and has no
	-- single value, so it goes through the same GetFlag/SetFlag pair;
	-- components/Window.lua registers it itself unless
	-- `CreateWindow{ PersistWindow = false }`.
	--
	-- Every field is optional on the way back in: a config written by a build with
	-- different tabs (or on a machine with a different viewport) has to restore the
	-- parts that still make sense and drop the rest, which is Window's job in
	-- `applyWindowState` — the codec only gets it there and back.
	window = {
		encode = function(v)
			if type(v) ~= "table" then
				return {}
			end
			local record: any = { maximized = v.Maximized == true }
			-- Paired, and only when both are real numbers: half a coordinate is not
			-- a position, and `floor(nil or 0)` would write the corner of the screen
			-- down as if the user had put the window there (the bug the `hud` codec
			-- above already had once).
			local x, y = tonumber(v.X), tonumber(v.Y)
			if x and y then
				record.x = math.floor(x)
				record.y = math.floor(y)
			end
			local w, h = tonumber(v.Width), tonumber(v.Height)
			if w and h then
				record.w = math.floor(w)
				record.h = math.floor(h)
			end
			local tab = tonumber(v.Tab)
			if tab then
				record.tab = math.floor(tab)
			end
			if type(v.Groups) == "table" then
				local groups: any = {}
				local any = false
				for key, collapsed in v.Groups :: any do
					groups[key] = collapsed == true
					any = true
				end
				-- Omitted rather than written empty: HttpService encodes an empty
				-- table as `[]`, which reads as a corrupt record rather than "no
				-- groups" when a human opens the file.
				if any then
					record.groups = groups
				end
			end
			return record
		end,
		decode = function(v)
			if type(v) ~= "table" then
				return {}
			end
			return {
				X = tonumber(v.x),
				Y = tonumber(v.y),
				Width = tonumber(v.w),
				Height = tonumber(v.h),
				Maximized = v.maximized == true,
				Tab = tonumber(v.tab),
				Groups = type(v.groups) == "table" and v.groups or nil,
			}
		end,
	},
	colorpicker = {
		encode = function(v) return typeof(v) == "Color3" and v:ToHex() or tostring(v) end,
		decode = function(v)
			local ok, color = pcall(Color3.fromHex, v)
			return (ok and color) or Color3.new(1, 1, 1)
		end,
	},
	playerselect = { -- handle:Get() returns Player(s); persist as UserId(s), :Set resolves back
		encode = function(v)
			if type(v) == "table" then
				local ids = {}
				for _, p in v do
					if typeof(p) == "Instance" and p:IsA("Player") then
						table.insert(ids, p.UserId)
					end
				end
				return ids
			elseif typeof(v) == "Instance" and v:IsA("Player") then
				return v.UserId
			end
			return false -- nobody picked — see the dropdown codec for why not nil
		end,
		-- number | { number } — handle:Set resolves ids live
		decode = function(v) if v == false then return nil end return v end,
	},
}

-- Read a flag's *persisted* value and encode it, exactly as GetConfig would.
-- Shared so a single flag's notification and a whole-config snapshot can never
-- disagree about what a control's value is; `where` names the caller in the
-- warnings, since a failure means something different in each ("save skipped it"
-- vs "the change notification was dropped").
local function encodeFlag(name: string, entry: { handle: any, kind: string }, where: string): (boolean, any)
	local codec = Codec[entry.kind]
	if not codec then
		return false, nil
	end
	local okRead, value = pcall(function()
		if entry.handle.GetFlag then
			return entry.handle:GetFlag()
		end
		return entry.handle:Get()
	end)
	if not okRead then
		-- Silence here is what makes "save did nothing" impossible to debug: the
		-- flag just goes missing from the file. Name it and carry on with the rest.
		Log.warn(where, ('flag "%s" (%s) failed to read — skipped: %s')
			:format(name, entry.kind, tostring(value)))
		return false, nil
	end
	local okEncode, encoded = pcall(codec.encode, value)
	if not okEncode then
		Log.warn(where, ('flag "%s" (%s) failed to encode — skipped: %s')
			:format(name, entry.kind, tostring(encoded)))
		return false, nil
	end
	return true, encoded
end

-- Value equality over encoded (JSON-safe) values, which is what "did this flag
-- actually change?" means. Tables here are small and acyclic by construction —
-- a bind is `{ key, mode }`, the window record is a handful of numbers plus a
-- map of booleans — so a plain recursive walk is both correct and cheap.
local function sameValue(a: any, b: any): boolean
	if a == b then
		return true
	end
	if type(a) ~= "table" or type(b) ~= "table" then
		return false
	end
	for key, value in a do
		if not sameValue(value, b[key]) then
			return false
		end
	end
	for key in b do
		if a[key] == nil then
			return false
		end
	end
	return true
end

-- The dedupe baseline has to be OURS. Codecs build fresh tables today, but a
-- codec (or a host's `GetFlag`) that ever handed back the live table it reads
-- from would mutate the baseline along with the value, and every subsequent
-- change would compare equal and go unreported — a silent, near-undebuggable
-- failure of the whole feature. A copy costs nothing at this size.
local function freeze(value: any): any
	if type(value) ~= "table" then
		return value
	end
	local out = {}
	for key, v in value do
		out[key] = freeze(v)
	end
	return out
end

-- ── Flag change notifications ───────────────────────────────────────────────
-- `OnFlag` above answers "which flags exist"; this answers "which one just
-- moved", which is what a host that persists continuously needs. Without it the
-- only way to notice a change is to poll `GetConfig()` and diff, so everything
-- since the last poll is lost whenever the client dies without a clean unload.
--
-- `fn(name, value, kind, source)`:
--   name    the flag
--   value   the ENCODED value — byte-for-byte what `GetConfig()` would put in
--           the file for it, so a host can patch its snapshot in place instead
--           of re-reading every flag to find the one that moved
--   kind    the codec kind, as `GetFlags()` reports it
--   source  "user" (a control the user operated) · "code" (a programmatic
--           `:Set`) · "config" (inside ApplyConfig / LoadConfig)
--
-- `source` is the load-bearing one: a config landing 40 flags must not look like
-- 40 edits worth writing back, and the alternative — the host guessing with a
-- re-entrancy flag around its own ApplyConfig call — can't see an autoload the
-- library ran itself.
--
-- Fires SYNCHRONOUSLY, like OnFlag. Note that most controls hand their callback
-- to `task.spawn`, so a watcher usually runs on that spawned thread rather than
-- on the one that caused the change — fine to yield in, never a reason to
-- assume you're still inside the click handler.
function Context:OnFlagChanged(fn: (string, any, string, string) -> ()): () -> ()
	return self._valueWatchers:Connect(fn)
end

-- Run `fn` with changes attributed to `source`. The tag is dynamically scoped
-- rather than passed down because the notification is raised several frames of
-- call stack below the thing that knows the answer — a click handler calls
-- `handle:Set`, which spawns the control's callback, which is where the notify
-- lands. `task.spawn` resumes immediately, so that spawned thread is still
-- inside this scope.
--
-- pcall'd so a throwing handler can't strand the tag and mislabel every change
-- after it; the error is re-raised untouched.
function Context:WithSource(source: string, fn: (...any) -> ...any, ...): ...any
	local previous = self._source
	self._source = source
	local results = table.pack(pcall(fn, ...))
	self._source = previous
	if not results[1] then
		error(results[2], 0)
	end
	return table.unpack(results, 2, results.n)
end

-- Sugar for the common one: a control's own input handler. Every place a
-- control turns a click / drag / keystroke into a value change wraps it, so
-- "the user did this" is a fact rather than an inference.
function Context:User(fn: (...any) -> ...any, ...): ...any
	return self:WithSource("user", fn, ...)
end

-- Announce that `name`'s value may have moved. Cheap to over-call: it re-reads
-- and re-encodes the flag and stays silent unless the result actually differs
-- from the last value it reported, which is what keeps a `:Set` that lands on
-- the value already held — a config restoring what's already on screen, a
-- toggle re-asserted every frame — from looking like an edit.
--
-- `source` overrides the ambient tag for this one notification; almost nothing
-- needs it, since WithSource already covers the paths that know better.
function Context:NotifyFlag(name: string, source: string?)
	local entry = self.Flags[name]
	if not entry then
		return
	end
	-- Nobody listening: skip the read + encode entirely. The baseline going stale
	-- is harmless — it holds the last value we *reported*, so the first
	-- notification after a watcher appears compares against that and fires iff
	-- something really did change in between, which is the honest answer.
	if self._valueWatchers:Count() == 0 then
		return
	end
	local ok, encoded = encodeFlag(name, entry, "OnFlagChanged")
	if not ok then
		return
	end
	if sameValue(self._lastEncoded[name], encoded) then
		return
	end
	self._lastEncoded[name] = freeze(encoded)
	local from = source or self._source
	-- Guarded: same rule as OnFlag — a host's bookkeeping blowing up must not take
	-- the control that moved down with it, nor stop the remaining watchers hearing
	-- about it.
	self._valueWatchers:FireGuarded(function(err)
		Log.warn("OnFlagChanged", ('watcher errored for flag "%s" (%s): %s')
			:format(name, entry.kind, tostring(err)))
	end, name, encoded, entry.kind, from)
end

-- ── Group registry ──────────────────────────────────────────────────────────
-- Collapsible groups register themselves so the window can persist which ones
-- are folded. The key is `"<tab>::<group>"` — the tab's name at creation and the
-- group's `Id` (or its Title), which is the most stable identity available
-- without making every caller invent one. Same key twice gets a `#n` suffix, so
-- two identically-titled groups in one tab still round-trip as long as the menu
-- builds in the same order.
function Context:RegisterGroup(scope: string, id: string, handle: any): string
	local base = ("%s::%s"):format(scope, id)
	local key = base
	local n = 1
	while self._groupKeys[key] do
		n += 1
		key = ("%s#%d"):format(base, n)
	end
	self._groupKeys[key] = true
	table.insert(self.Groups, { key = key, handle = handle })
	return key
end

-- Window subscribes; groups and tabs raise it. The window's own geometry is
-- Window's business, but "a group was folded" and "a tab was selected" happen
-- in components that have no idea the flag exists.
function Context:OnWindowState(fn: () -> ()): () -> ()
	return self._windowState:Connect(fn)
end

function Context:WindowStateChanged()
	self._windowState:Fire()
end

-- Watch flag registration. `fn(name, kind)` fires SYNCHRONOUSLY from inside
-- RegisterFlag, which is the whole point: a loader that wants to know which
-- module (or which boot phase) a flag came from tags it against whatever it is
-- currently building, and that only works if the notification lands before the
-- next line of the builder runs. A BindableEvent would not do — Roblox's
-- deferred signal behaviour hands the callback back at the end of the
-- resumption cycle, by which time "what are we building right now?" has moved
-- on. Same shape as RegisterAccent: returns an unsubscribe.
--
-- Unlike RegisterAccent this does NOT replay the flags already registered —
-- Context:GetFlags() is there for that, and a watcher installed at CreateWindow
-- time (the `OnFlag` option) has missed nothing.
function Context:OnFlag(fn: (string, string) -> ()): () -> ()
	return self._flagWatchers:Connect(fn)
end

-- Every registered flag as `{ [name] = kind }` — a copy, so a caller can't edit
-- the live registry through it. Enumerating at two points in time is what lets a
-- host split flags into groups it registered before and after some milestone
-- (a per-place module, a profile), which is the difference between a config that
-- scopes and one that has to be all-or-nothing.
function Context:GetFlags(): { [string]: string }
	local out = {}
	for name, entry in self.Flags do
		out[name] = entry.kind
	end
	return out
end

-- Register a stateful control's handle under `name` so config save/load can
-- read (:Get) and write (:Set) it. `kind` selects the codec. No-op without both.
function Context:RegisterFlag(name: string?, handle: any, kind: string?)
	if not name or not kind or not Codec[kind] or not handle then
		return
	end
	-- Two controls sharing a Flag silently overwrite each other in config
	-- save/load — the second wins and the first never persists. That's almost
	-- always a copy-paste slip, so surface it rather than let configs go stale.
	if self.Flags[name] then
		Log.warn("Flag", ('"%s" is registered twice — both controls share one config '
			.. "slot, so only the last will save/load. Give each a unique Flag."):format(name))
	end
	local entry = { handle = handle, kind = kind }
	self.Flags[name] = entry
	-- Seed the change-notification baseline with the value the control was BUILT
	-- with, so a control taking its `Default` is never reported as a change (see
	-- OnFlagChanged). A handle that can't be read at all is a malformed handle and
	-- encodeFlag says so; the flag still registers, and saving it will fail the
	-- same way later.
	-- Explicit branch, not `ok and freeze(...) or nil`: a legitimately falsy
	-- baseline (the `dropdown` and `playerselect` codecs both encode "nothing
	-- selected" as `false`) would fall through to nil, and the first real
	-- notification would then report a change that never happened.
	local ok, encoded = encodeFlag(name, entry, "OnFlagChanged")
	if ok then
		self._lastEncoded[name] = freeze(encoded)
	else
		self._lastEncoded[name] = nil
	end
	-- Guarded: a host's bookkeeping blowing up must not take the control down with
	-- it — the flag is registered either way.
	self._flagWatchers:FireGuarded(function(err)
		Log.warn("OnFlag", ('watcher errored for flag "%s" (%s): %s')
			:format(name, kind, tostring(err)))
	end, name, kind)
end

-- Snapshot every flagged control into a JSON-safe table.
--
-- A control whose persisted value isn't its primary value — a keybind, which is
-- a key *and* a mode, while `:Get()` is just the key — exposes `:GetFlag()` /
-- `:SetFlag()` and those win. Everything else round-trips through `:Get()`/`:Set()`.
function Context:GetConfig(): { [string]: any }
	local data = {}
	for name, entry in self.Flags do
		local ok, encoded = encodeFlag(name, entry, "SaveConfig")
		if ok then
			data[name] = encoded
		end
	end
	return data
end

-- Apply a saved table back onto the flagged controls (fires their callbacks).
-- Returns how many flags were applied and how many keys were skipped.
--
-- **A key with no registered flag is skipped, quietly and on purpose** — that's
-- a promised part of the format, not an accident of the loop. It's what lets a
-- config carry data that isn't a control value: `Config.MetaKey` ("__uranium")
-- is the library's own reserved slot for the metadata `Window:SaveConfig(name,
-- meta)` stamps, and a host is free to keep its own bookkeeping keys alongside
-- it. It also means a config written by a build with more controls than this one
-- still loads the flags this build does have.
--
-- `opts.Filter = function(name, kind) -> boolean` decides, per flag, whether it
-- is applied at all — for a host that scopes its registry (a portable half and a
-- per-place half) and wants to land only one of them. It's a *predicate*, not a
-- list of names, because that classification is computed rather than enumerable.
-- Three things it promises:
--   • It only ever sees keys that resolved to a registered flag, so `kind` is
--     always a real codec kind and `Config.MetaKey` (and any other bookkeeping
--     key) never reaches it — those are skipped before the filter is consulted.
--   • A filtered-out key counts as **skipped**, never applied, so LoadConfig's
--     "applied nothing" still means nothing matched.
--   • It's called inside a pcall; a filter that errors skips its flag rather
--     than half-applying a config the host couldn't classify.
export type LoadOpts = { Filter: ((string, string) -> boolean)? }

function Context:LoadConfig(data: { [string]: any }, opts: LoadOpts?): (number, number)
	if type(data) ~= "table" then
		return 0, 0
	end
	local filter: ((string, string) -> boolean)? = nil
	if opts ~= nil then
		if type(opts) ~= "table" then
			Log.warn("LoadConfig", ("options must be a table, got %s — ignoring.")
				:format(typeof(opts)))
		elseif opts.Filter ~= nil then
			if type(opts.Filter) ~= "function" then
				Log.warn("LoadConfig", ("Filter must be a function, got %s — ignoring.")
					:format(typeof(opts.Filter)))
			else
				filter = opts.Filter
			end
		end
	end
	local applied, skipped = 0, 0
	for name, raw in data do
		local entry = self.Flags[name]
		local codec = entry and Codec[entry.kind]
		local wanted = true
		if codec and filter then
			local okFilter, verdict = pcall(filter, name, entry.kind)
			if not okFilter then
				Log.warn("LoadConfig", ('filter errored for flag "%s" (%s) — skipped: %s')
					:format(name, entry.kind, tostring(verdict)))
				wanted = false
			else
				wanted = verdict and true or false
			end
		end
		if not codec or not wanted then
			skipped += 1
		else
			-- Every failure below used to be swallowed by a bare pcall, so one broken
			-- control read as "the whole config didn't load". Skip the bad flag, say
			-- which one, and keep applying the rest.
			local okDecode, value = pcall(codec.decode, raw)
			if not okDecode then
				Log.warn("LoadConfig", ('flag "%s" (%s) failed to decode — skipped: %s')
					:format(name, entry.kind, tostring(value)))
				skipped += 1
			else
				-- Tagged for the whole apply, so a host persisting on change can tell
				-- 40 flags landing from a config apart from 40 edits worth writing
				-- back (see OnFlagChanged). The control's own callback fires from
				-- inside here, which is where most of the notifications come from.
				local okSet, err = pcall(function()
					self:WithSource("config", function()
						if entry.handle.SetFlag then
							entry.handle:SetFlag(value)
						else
							entry.handle:Set(value)
						end
					end)
				end)
				if okSet then
					applied += 1
					-- Backstop for handles with no callback of their own — the HUD, the
					-- window record, a host's own registered state. Deduped against
					-- whatever the control already reported, so the common case is a
					-- comparison and nothing else.
					self:NotifyFlag(name, "config")
				else
					Log.warn("LoadConfig", ('flag "%s" (%s) failed to apply — skipped: %s')
						:format(name, entry.kind, tostring(err)))
					skipped += 1
				end
			end
		end
	end
	return applied, skipped
end

-- ── Popovers ───────────────────────────────────────────────────────────────
function Context:ClosePopover()
	local p = self._popover
	if not p then
		return
	end
	self._popover = nil
	for _, conn in p.conns do
		conn:Disconnect()
	end
	p.catcher:Destroy()
	-- Land the open-fade back on its resting values before hiding. Closing
	-- mid-fade and immediately reopening would otherwise snapshot the half-faded
	-- tree as the new baseline and leave the menu permanently washed out.
	p.fade:Set(0)
	p.menu.Visible = false
	if p.onClose then
		p.onClose()
	end
end

-- Open `menu` directly under `anchor`, closing any other open popover first.
-- A full-overlay catcher button dismisses it on any outside click.
function Context:OpenPopover(menu: GuiObject, anchor: GuiObject, onClose: (() -> ())?)
	self:ClosePopover()

	local catcher = Create("TextButton", {
		Name = "Catcher",
		Size = UDim2.fromScale(1, 1),
		BackgroundTransparency = 1,
		Text = "",
		AutoButtonColor = false,
		ZIndex = 50,
		Parent = self.overlay,
	})
	menu.ZIndex = 60
	menu.Parent = self.overlay

	-- Place the menu under the anchor, but keep it inside the overlay (= window)
	-- bounds: clamp horizontally, and flip above the anchor when there isn't
	-- enough room below. The window clips descendants, so a menu that spilled
	-- off the edge would be cut off — this keeps it fully visible.
	local MARGIN = 8
	local GAP = 6
	local function place()
		local o = self.overlay.AbsolutePosition
		local os = self.overlay.AbsoluteSize
		local a = anchor.AbsolutePosition
		local asz = anchor.AbsoluteSize
		local msz = menu.AbsoluteSize

		local x = a.X - o.X
		x = math.clamp(x, MARGIN, math.max(MARGIN, os.X - msz.X - MARGIN))

		local below = (a.Y - o.Y) + asz.Y + GAP
		local above = (a.Y - o.Y) - msz.Y - GAP
		local y = below
		if below + msz.Y > os.Y - MARGIN and above >= MARGIN then
			y = above -- not enough room below → open upward
		end
		y = math.clamp(y, MARGIN, math.max(MARGIN, os.Y - msz.Y - MARGIN))

		menu.Position = UDim2.fromOffset(x, y)
	end
	place()
	menu.Visible = true

	-- Fade the menu in as a unit. This used to be a CanvasGroup + one
	-- GroupTransparency tween, which rasterized every option label into a buffer
	-- and blurred it — util/Fade.lua does the same job on the real properties.
	-- Snapshotting here (not at build time) is deliberate: menus rebuild their
	-- rows, so each open re-reads the tree it's actually about to show.
	local fade = Fade.new(menu)
	fade:Set(1)
	fade:To(Tween.Pop, 0)

	-- Re-place when the anchor moves, when the menu's auto-size settles, or when
	-- the window resizes.
	local conns = {
		anchor:GetPropertyChangedSignal("AbsolutePosition"):Connect(place),
		menu:GetPropertyChangedSignal("AbsoluteSize"):Connect(place),
		self.overlay:GetPropertyChangedSignal("AbsoluteSize"):Connect(place),
	}
	self._popover = { menu = menu, catcher = catcher, conns = conns, onClose = onClose, fade = fade }
	catcher.Activated:Connect(function()
		self:ClosePopover()
	end)
end

function Context:IsOpen(menu: GuiObject): boolean
	return self._popover ~= nil and self._popover.menu == menu
end

return Context

end

__modules['util.Create'] = function(...)
--!strict
-- util/Create.lua — tiny instance factory + common UI helpers.
--
--   Create("Frame", { Size = ..., Parent = ... }, { childA, childB })
--
-- `Parent` is always applied LAST, so children exist before the instance enters
-- the tree. Everything else is assigned in whatever order the table iterates —
-- which is a hash order, i.e. arbitrary and not the source order, whatever the
-- literal looks like. (This used to be documented as "props are assigned in
-- order", which is not true and is exactly the sort of thing someone eventually
-- writes an order-dependent pair against.) Nothing in the library depends on
-- one property landing before another; if you ever need that, set it explicitly
-- after the call rather than relying on the literal's layout.
--
-- Helper constructors (corner, stroke, padding, listLayout) cover the
-- boilerplate instances used everywhere.

-- util/Tween.lua only requires util/Services.lua, so there's no cycle back here.
local Tween = __require("util.Tween")

local Create = setmetatable({}, {
	__call = function(_, className: string, props: { [string]: any }?, children: { Instance }?): any
		local inst = Instance.new(className)
		local parent
		if props then
			for key, value in props do
				if key == "Parent" then
					parent = value
				else
					(inst :: any)[key] = value
				end
			end
		end
		if children then
			for _, child in children do
				child.Parent = inst
			end
		end
		inst.Parent = parent
		return inst
	end,
})

function Create.corner(radius: number): UICorner
	return Create("UICorner", { CornerRadius = UDim.new(0, radius) })
end

function Create.stroke(color: Color3, thickness: number?): UIStroke
	return Create("UIStroke", {
		Color = color,
		Thickness = thickness or 1,
		ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
		-- Round joins trace the UICorner arc smoothly instead of cutting it with
		-- mitred corners, which is what made bordered cards/controls look jagged.
		LineJoinMode = Enum.LineJoinMode.Round,
	})
end

function Create.padding(top: number, right: number?, bottom: number?, left: number?): UIPadding
	right = right or top
	bottom = bottom or top
	left = left or right
	return Create("UIPadding", {
		PaddingTop = UDim.new(0, top),
		PaddingRight = UDim.new(0, right),
		PaddingBottom = UDim.new(0, bottom),
		PaddingLeft = UDim.new(0, left),
	})
end

-- The hover pair: tween `prop` to `over` on MouseEnter, back to `base` on
-- MouseLeave, at Tween.Fast.
--
--   Create.hover(button, "BackgroundColor3", colors.control, colors.control_hi)
--
-- This was the same six lines at eight call sites — and at two of them
-- (components/Dropdown.lua, components/PlayerSelect.lua) it was already the same
-- private `hover` helper, copied verbatim into both files. It isn't a deep
-- abstraction; it's the shape a hover has in this library, written once so a new
-- control doesn't re-derive it and so `Tween.Fast` stays the single answer to
-- "how fast is a hover" rather than whatever got pasted alongside it.
--
-- Returns the instance (so it can be chained) and `set(base, over)`, which
-- re-points both ends AND repaints immediately if the pointer is currently
-- inside. That second part is what an accent-coloured control needs:
-- `Window:SetAccent` can move the colour out from under a button the cursor is
-- already sitting on, and every call site that handled this before had to track
-- its own `hovering` boolean to do it.
--
-- Deliberately not for every MouseEnter in the library — a hover that runs a
-- state machine (components/BindChip.lua), tints an icon (components/Hud.lua) or
-- animates a different instance than the one under the pointer
-- (components/Colorpicker.lua) is a different shape and stays hand-written.
function Create.hover<T>(inst: GuiObject, prop: string, base: T, over: T): (GuiObject, (T, T) -> ())
	local restingValue, hoverValue = base, over
	local inside = false
	inst.MouseEnter:Connect(function()
		inside = true
		Tween.play(inst, Tween.Fast, { [prop] = hoverValue })
	end)
	inst.MouseLeave:Connect(function()
		inside = false
		Tween.play(inst, Tween.Fast, { [prop] = restingValue })
	end)
	return inst, function(newBase: T, newOver: T)
		restingValue, hoverValue = newBase, newOver;
		-- Snapped, not tweened: this is a re-theme landing, not an interaction.
		-- (The `;` above is load-bearing — without it Lua reads the `(` as a call
		-- on the previous line's last value.)
		(inst :: any)[prop] = inside and hoverValue or restingValue
	end
end

function Create.listLayout(props: { [string]: any }?): UIListLayout
	local layout = Create("UIListLayout", {
		SortOrder = Enum.SortOrder.LayoutOrder,
		FillDirection = Enum.FillDirection.Vertical,
	})
	if props then
		for key, value in props do
			(layout :: any)[key] = value
		end
	end
	return layout
end

return Create

end

__modules['util.Fade'] = function(...)
--!strict
-- util/Fade.lua — fade a whole subtree in or out WITHOUT a CanvasGroup.
--
-- Why this exists, because it's the single most important rendering rule in this
-- library after "use FontFace, not Font":
--
--   **A CanvasGroup makes text blurry.** It rasterizes its entire subtree into
--   an offscreen buffer at the group's own size and then draws that buffer to
--   the screen. Text inside it is no longer drawn by the SDF renderer at the
--   display's real resolution — it's baked into a bitmap and resampled, so every
--   label comes out soft and smeared. Nothing the user can do fixes it: raising
--   graphics quality doesn't help, resizing the Roblox window doesn't help,
--   because the blur happens before the pixels ever reach the screen.
--
-- CanvasGroup is still the *obvious* way to fade a panel — one GroupTransparency
-- tween and everything inside goes with it — and that's exactly what this
-- library used to do for the window, the popovers, the toasts and the splash.
-- Which meant essentially every character of text in the UI was being rendered
-- through a buffer.
--
-- This is the replacement: snapshot every transparency property in the subtree
-- once, then drive them all from a single tweened NumberValue. Identical result
-- (same easing, everything moves together), no buffer, real text.
--
--   local fade = Fade.new(panel)
--   fade:Set(1)                        -- instantly invisible
--   fade:To(Tween.Normal, 0)           -- fade in
--   fade:To(Tween.MenuOut, 1, done)    -- fade out, then `done`
--
-- Alpha is 0 = "as built" (each instance back at its own resting transparency,
-- which is NOT necessarily 0) and 1 = fully invisible.

local Tween = __require("util.Tween")

local Fade = {}
Fade.__index = Fade

type Target = { inst: Instance, prop: string, base: number }

export type Fade = typeof(setmetatable(
	{} :: {
		root: GuiObject,
		alpha: number,
		_targets: { Target }?,
		_driver: NumberValue?,
		_conn: RBXScriptConnection?,
	},
	Fade
))

-- Every transparency property that actually hides something. A GuiObject can
-- carry several at once (a TextButton has a background AND text), so this is a
-- list of checks, not a lookup.
local function collect(inst: Instance, out: { Target })
	local any: any = inst
	if inst:IsA("GuiObject") then
		table.insert(out, { inst = inst, prop = "BackgroundTransparency", base = any.BackgroundTransparency })
	end
	if inst:IsA("TextLabel") or inst:IsA("TextButton") or inst:IsA("TextBox") then
		table.insert(out, { inst = inst, prop = "TextTransparency", base = any.TextTransparency })
		table.insert(out, { inst = inst, prop = "TextStrokeTransparency", base = any.TextStrokeTransparency })
	end
	if inst:IsA("ImageLabel") or inst:IsA("ImageButton") then
		table.insert(out, { inst = inst, prop = "ImageTransparency", base = any.ImageTransparency })
	end
	if inst:IsA("ScrollingFrame") then
		table.insert(out, { inst = inst, prop = "ScrollBarImageTransparency", base = any.ScrollBarImageTransparency })
	end
	if inst:IsA("UIStroke") then
		table.insert(out, { inst = inst, prop = "Transparency", base = any.Transparency })
	end
	-- Belt and braces: if a CanvasGroup ever shows up inside a faded subtree
	-- again, fade it as a unit rather than walking into it.
	if inst:IsA("CanvasGroup") then
		table.insert(out, { inst = inst, prop = "GroupTransparency", base = any.GroupTransparency })
	end
end

-- Hidden subtrees are skipped whole — an inactive tab page is a few hundred
-- instances that aren't on screen and don't need touching 60 times a second.
local function walk(inst: Instance, out: { Target })
	collect(inst, out)
	if inst:IsA("CanvasGroup") then
		return -- faded as a unit above
	end
	for _, child in inst:GetChildren() do
		if child:IsA("GuiObject") and not child.Visible then
			continue
		end
		walk(child, out)
	end
end

function Fade.new(root: GuiObject): Fade
	return setmetatable({
		root = root,
		alpha = 0,
		_targets = nil,
		_driver = nil,
		_conn = nil,
	}, Fade) :: any
end

-- Snapshot on demand. The cache is dropped again whenever the subtree comes
-- fully back to rest (alpha 0), so the next fade re-reads a tree that may have
-- grown controls in the meantime — and so a snapshot is never taken of a subtree
-- that's currently mid-fade, which would bake the faded values in as the bases.
function Fade:_snapshot()
	if self._targets then
		return
	end
	local targets: { Target } = {}
	walk(self.root, targets)
	self._targets = targets
end

function Fade:_apply(alpha: number)
	self.alpha = alpha
	local targets = self._targets
	if not targets then
		return
	end
	for _, t in targets do
		-- lerp each instance from its own resting value toward fully invisible
		local inst: any = t.inst
		inst[t.prop] = t.base + (1 - t.base) * alpha
	end
end

function Fade:_stop()
	if self._conn then
		self._conn:Disconnect()
		self._conn = nil
	end
	if self._driver then
		self._driver:Destroy()
		self._driver = nil
	end
end

function Fade:Set(alpha: number)
	self:_stop()
	self:_snapshot()
	self:_apply(alpha)
	if alpha <= 0 then
		self._targets = nil -- back at rest
	end
end

-- One NumberValue is tweened and its Changed pushes the alpha out to the whole
-- subtree, so the easing is exactly the same TweenInfo everything else uses.
-- Returns the driver tween (`.Completed` is safe to connect to).
function Fade:To(info: TweenInfo, alpha: number, onDone: (() -> ())?): Tween
	self:_stop()
	self:_snapshot()

	local driver = Instance.new("NumberValue")
	driver.Value = self.alpha
	self._driver = driver
	self._conn = driver.Changed:Connect(function(v: number)
		self:_apply(v)
	end)

	local tween = Tween.play(driver, info, { Value = alpha })
	tween.Completed:Once(function()
		if self._driver ~= driver then
			return -- superseded by a later fade; it owns the state now
		end
		self:_stop()
		self:_apply(alpha) -- land exactly on the goal
		if alpha <= 0 then
			self._targets = nil
		end
		if onDone then
			onDone()
		end
	end)
	return tween
end

function Fade:Destroy()
	self:_stop()
	self._targets = nil
end

return Fade

end

__modules['util.Gui'] = function(...)
--!strict
-- util/Gui.lua — where the ScreenGui goes, what it's called, and how we find it
-- again. Everything in here exists because a LocalScript in the place can walk
-- `PlayerGui` and read `Name`.
--
-- **Parenting order** (`Gui.mount`), most hidden first:
--   1. `opts.Parent` — the host already resolved a container; trust it.
--   2. `gethui()`     — the executor's hidden container. Invisible to the place.
--   3. `CoreGui`      — not enumerable by a normal LocalScript.
--   4. `PlayerGui`    — last resort (Studio, and executors with neither global).
--
-- `protect_gui` / `syn.protect_gui` runs FIRST where the global exists, because
-- some executors want to do the reparent themselves. We then set `Parent` ONCE,
-- at the resolved target: the old code parented to PlayerGui and nothing else,
-- and even a "parent here, move it after" would leave a frame where the place
-- can see the instance.
--
-- **Identity is an attribute, not the name.** The ScreenGui used to be called
-- `Theme.Brand.name` ("Uranium") — a fixed, brand-shaped string is the single
-- cheapest thing to detect, and `util/Singleton.lua`'s leftover sweep matched on
-- it, so the name couldn't just be dropped. Instead each load gets a fresh
-- neutral name (`Gui.rname`) and carries `Gui.Attribute` as an attribute;
-- attributes don't show up in an Explorer-style name walk, and the sweep matches
-- on that instead. `Window{ GuiName = "..." }` pins the name if a host wants one.

local Services = __require("util.Services")

local Players = Services.Players

local Gui = {}

-- The identity marker. Set on every ScreenGui we create; the singleton sweep
-- looks for it across all three possible roots.
Gui.Attribute = "__urn"

-- ── neutral names ───────────────────────────────────────────────────────────
-- Fresh every load, so a place can't learn the name from a previous session
-- either. Letters first (instance names starting with a digit are legal but
-- unusual enough to stand out), then letters + digits.
local HEAD = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ"
local TAIL = HEAD .. "0123456789"
local rng = Random.new()

function Gui.rname(minLen: number?, maxLen: number?): string
	local lo = minLen or 10
	local hi = maxLen or 16
	local n = rng:NextInteger(lo, math.max(lo, hi))
	local out = table.create(n)
	local h = rng:NextInteger(1, #HEAD)
	out[1] = HEAD:sub(h, h)
	for i = 2, n do
		local t = rng:NextInteger(1, #TAIL)
		out[i] = TAIL:sub(t, t)
	end
	return table.concat(out)
end

-- ── executor globals ────────────────────────────────────────────────────────
-- Resolved the same way util/Config.lua resolves the file API: the shared env
-- (getgenv) first, then the ambient global. Both reads are pcall-guarded —
-- some sandboxes throw merely on touching getgenv, and this module is required
-- at load time.
local genv: any = nil
pcall(function()
	if type(getgenv) == "function" then
		genv = getgenv()
	end
end)

local function g(name: string): any
	if type(genv) == "table" then
		local ok, v = pcall(function()
			return genv[name]
		end)
		if ok and v ~= nil then
			return v
		end
	end
	local ok2, v2 = pcall(function()
		return (_G :: any)[name]
	end)
	if ok2 and v2 ~= nil then
		return v2
	end
	return nil
end

-- ── containers ──────────────────────────────────────────────────────────────
-- Each returns the container or nil; all of them are pcall-guarded, because
-- `gethui` is executor-only and `CoreGui` throws for an unprivileged script.

function Gui.hidden(): Instance?
	local ok, h = pcall(function()
		local fn = g("gethui")
		-- ...and the ambient global, for executors that inject it into the chunk
		-- env rather than onto getgenv/_G.
		if type(fn) ~= "function" and type(gethui) == "function" then
			fn = gethui
		end
		if type(fn) == "function" then
			return fn()
		end
		return nil
	end)
	if ok and typeof(h) == "Instance" then
		return h
	end
	return nil
end

function Gui.coreGui(): Instance?
	local ok, c = pcall(function()
		return Services.CoreGui
	end)
	if ok and typeof(c) == "Instance" then
		return c
	end
	return nil
end

-- `timeout` is opt-in and only the mount uses it: the sweep runs before the
-- window is built and must not stall the load waiting on a container it's merely
-- checking for leftovers.
function Gui.playerGui(timeout: number?): Instance?
	local ok, pg = pcall(function()
		local lp = Players.LocalPlayer
		if not lp then
			return nil
		end
		local found = lp:FindFirstChildOfClass("PlayerGui")
		if found then
			return found
		end
		if timeout then
			-- Only ever waits when the library loads before PlayerGui replicates,
			-- which is the one case the old `WaitForChild("PlayerGui")` covered.
			return lp:WaitForChild("PlayerGui", timeout)
		end
		return nil
	end)
	if ok and typeof(pg) == "Instance" then
		return pg
	end
	return nil
end

-- Every root a leftover window of ours could be sitting in — the hidden
-- container included, or a window parented there leaks on reload (its record is
-- gone with the old chunk, the sweep never looks in gethui, and the user ends up
-- with two windows stacked).
function Gui.roots(): { Instance }
	local roots: { Instance } = {}
	local seen: { [Instance]: boolean } = {}
	for _, get in { Gui.hidden, Gui.coreGui, Gui.playerGui } do
		local root = get()
		if root and not seen[root] then
			seen[root] = true
			table.insert(roots, root)
		end
	end
	return roots
end

-- ── protection + mounting ───────────────────────────────────────────────────

-- `protect_gui(gui)` / `syn.protect_gui(gui)` where they exist. Some executors
-- implement it as "I'll hide and reparent this for you", which is why it runs
-- before we set Parent, not after.
function Gui.protect(inst: Instance): boolean
	local done = false
	pcall(function()
		local fn = g("protect_gui")
		if type(fn) ~= "function" and type(protect_gui) == "function" then
			fn = protect_gui
		end
		if type(fn) == "function" then
			fn(inst)
			done = true
		end
	end)
	if not done then
		pcall(function()
			local s: any = g("syn")
			if type(s) ~= "table" then
				s = syn
			end
			if type(s) == "table" and type(s.protect_gui) == "function" then
				s.protect_gui(inst)
				done = true
			end
		end)
	end
	return done
end

-- Tag + parent, once. Returns `(target, label)` — the label names which branch
-- won, for the verbose log line.
function Gui.mount(inst: Instance, preferred: Instance?): (Instance?, string)
	pcall(function()
		inst:SetAttribute(Gui.Attribute, true)
	end)

	Gui.protect(inst)

	local target: Instance? = nil
	local label = "nowhere"

	if typeof(preferred) == "Instance" then
		target, label = preferred, "opts.Parent"
	end
	if not target then
		target = Gui.hidden()
		if target then
			label = "gethui()"
		end
	end
	if not target then
		target = Gui.coreGui()
		if target then
			label = "CoreGui"
		end
	end
	if not target then
		target = Gui.playerGui(5)
		if target then
			label = "PlayerGui"
		end
	end

	if target then
		local ok = pcall(function()
			inst.Parent = target
		end)
		-- CoreGui can resolve and still refuse the write on a client with no
		-- elevated identity; PlayerGui always accepts it.
		if not ok then
			local fallback = Gui.playerGui(5)
			if fallback and fallback ~= target then
				pcall(function()
					inst.Parent = fallback
				end)
				target, label = fallback, "PlayerGui (fallback)"
			else
				target, label = nil, "nowhere"
			end
		end
	end

	return target, label
end

-- True for a ScreenGui this library created (any run of it, including one whose
-- record was lost). Attribute first; a build older than the neutral-name change
-- is matched by name via the caller's legacy list.
function Gui.isOurs(inst: Instance): boolean
	local ok, v = pcall(function()
		return inst:GetAttribute(Gui.Attribute)
	end)
	return ok and v == true
end

return Gui

end

__modules['util.Log'] = function(...)
--!strict
-- util/Log.lua — one place every Uranium diagnostic flows through, so the format
-- stays uniform and the library explains a mistake instead of throwing a bare
-- "attempt to index nil value" three frames deep in a bundled chunk.
--
-- Policy:
--   * fail  — the call genuinely can't proceed (wrong TYPE for a required arg).
--             Raised with level 0 so the executor console shows our clean
--             "[Uranium] Slider "Speed": ..." text, not a bundle file:line prefix.
--   * warn  — a recoverable mistake (bad enum value, out-of-range index, a
--             missing option we can default). We say what happened + what we did
--             and keep building, so one typo never blanks the whole menu.
--
--   * info  — chatty progress/diagnostic output ("loaded", "SaveConfig -> ok",
--             the detected file-API capabilities). **Silent by default.** A game
--             scraping LogService reads everything the client prints, and six
--             branded lines on a normal load is a free fingerprint. Turn it on
--             with `CreateWindow{ Verbose = true }`, `Uranium.setVerbose(true)`,
--             or — for the lines that fire before any of that runs, at require
--             time — `getgenv().URANIUM_VERBOSE = true` before the loadstring.
--
-- `where` is a short human label for the call site, e.g. `Log.where("Slider",
-- opts.Name)` → `Slider "Speed"`. Keep messages actionable: name the field, the
-- value we got, and the fix.

local Log = {}

-- Every line the library prints is stamped with this, and it's writable from one
-- place so a host can rename it (or empty it) without patching call sites.
Log.Prefix = "[Uranium]"

-- Chatty output gate. warn/fail ignore it — a real failure that prints nothing
-- is worse than a fingerprint.
Log.Verbose = false

-- Build stamp, injected by bundle.py into the bundled build (nil in the plain
-- ModuleScript tree). Logged by Window under Verbose instead of unconditionally
-- at the top of the chunk.
Log.Build = nil :: string?

-- Pre-set opt-in, read once at require time: the banner and the config
-- capability line happen before CreateWindow can be reached.
do
	local on = false
	pcall(function()
		local env: any = if type(getgenv) == "function" then getgenv() else _G
		if type(env) == "table" and env.URANIUM_VERBOSE == true then
			on = true
		end
	end)
	Log.Verbose = on
end

function Log.setPrefix(prefix: string)
	if type(prefix) == "string" then
		Log.Prefix = prefix
	end
end

function Log.setVerbose(on: boolean?)
	Log.Verbose = on == true
end

-- Chatty line — dropped entirely unless Verbose.
function Log.info(msg: string)
	if not Log.Verbose then
		return
	end
	print(("%s %s"):format(Log.Prefix, msg))
end

-- Same, formatted. The format runs only when we're actually going to print.
function Log.infof(fmt: string, ...: any)
	if not Log.Verbose then
		return
	end
	print(("%s %s"):format(Log.Prefix, fmt:format(...)))
end

-- The build stamp, at most once per load. Two callers race for it: the bundled
-- chunk (which can only honour the pre-set env global) and CreateWindow (which
-- knows about `Verbose = true`, but runs later). Whichever gets there with
-- Verbose on prints; the other is a no-op. A run with output off never marks it,
-- so a second window built after `setVerbose(true)` still stamps.
local bannered = false

function Log.banner()
	if bannered or not Log.Verbose then
		return
	end
	bannered = true
	print(("%s build %s loaded"):format(Log.Prefix, Log.Build or "dev (module tree)"))
end

-- Build a "Control \"Name\"" label for messages. Falls back to just the control
-- name when the field is anonymous.
function Log.where(control: string, name: any?): string
	if type(name) == "string" and name ~= "" then
		return ('%s "%s"'):format(control, name)
	end
	return control
end

-- Hard stop. Never returns.
function Log.fail(where: string, msg: string): never
	return error(("%s %s: %s"):format(Log.Prefix, where, msg), 0)
end

-- Soft warning — lands in the executor console (warn channel), build continues.
function Log.warn(where: string, msg: string)
	warn(("%s %s: %s"):format(Log.Prefix, where, msg))
end

-- fail(where, msg) unless `cond` is truthy. Returns cond so it can be inlined.
function Log.assert(cond: any, where: string, msg: string): any
	if not cond then
		Log.fail(where, msg)
	end
	return cond
end

-- Type guard for a single option field. `accepts` is one type name or a list of
-- them (as returned by `typeof`, so "table"/"number"/"function"/"Color3"/
-- "EnumItem"/…). `nil`/absent always passes — callers validate required-ness
-- separately. Fails with a message naming the field, the accepted type(s), and
-- what we actually got.
function Log.field(where: string, field: string, value: any, accepts: string | { string })
	if value == nil then
		return value
	end
	local got = typeof(value)
	local list = type(accepts) == "table" and accepts or { accepts :: string }
	for _, want in list do
		if got == want then
			return value
		end
	end
	Log.fail(where, ("%s must be a %s, got %s"):format(field, table.concat(list, " or "), got))
	return value
end

-- A whole options table against a declared shape, in one call:
--
--   local SCHEMA: Log.Schema = {
--       { "Name", "string" },
--       { "Keybind", { "EnumItem", "boolean" } },
--   }
--   ...
--   Log.check(where, opts, SCHEMA)
--
-- Same rules as `Log.field` per entry (nil passes; a wrong type is a hard fail
-- naming the field). What this buys is not brevity — it's that the shape becomes
-- a value the component OWNS, next to the code that reads it, instead of a run
-- of imperative calls at whichever call site happened to validate first.
--
-- That mattered most for tabs: `CreateTab` validated fifteen fields inside
-- components/Window.lua while components/Tab.lua separately normalized `Pin` and
-- `Style`, so one option's contract was split across two files and adding one
-- meant editing both. Tab now declares its own and Window just forwards.
--
-- An ARRAY of pairs rather than a `{ [field] = type }` map, deliberately: Luau
-- table iteration order is a hash order, so a map would report an arbitrary one
-- of several bad fields and a different one on the next run. This reports the
-- first bad field in declaration order, every time.
export type Schema = { { any } }

function Log.check(where: string, opts: any, schema: Schema): any
	if opts == nil then
		return opts
	end
	for _, entry in schema do
		Log.field(where, entry[1] :: string, opts[entry[1]], entry[2] :: any)
	end
	return opts
end

return Log

end

__modules['util.Services'] = function(...)
--!strict
-- util/Services.lua — the single place the library touches `game:GetService`.
--
-- Two reasons this exists, and only one of them is tidiness:
--
--  1. **cloneref.** Executors expose `cloneref(service)`, which hands back a
--     reference that is NOT the one the place gets from its own
--     `game:GetService("UserInputService")`. A game that hooks a service's
--     methods, or compares identities (`svc == game:GetService(...)`), sees the
--     library's calls as coming from somewhere else entirely. Fifteen scattered
--     `game:GetService` calls can't be wrapped after the fact; one funnel can.
--  2. **The host's own cache.** A hub that already built its cloned services
--     passes the table in as the chunk vararg (`loadstring(src)(Services)`), and
--     the library adopts it instead of making a second set of clones — so the
--     hub and the UI hold the *same* references. The library must still work
--     standalone, so a missing/!table vararg falls through to building its own.
--
-- Access is lazy and memoized: `Services.UserInputService` resolves on first
-- touch, `rawset`s itself, and every later read is a plain table index.
--
-- In the bundled build, bundle.py wraps each module as `function(...)` and
-- threads the chunk's varargs through `__require`, so `...` here is whatever the
-- loader passed. In the plain ModuleScript tree `...` is simply empty, and the
-- fallback branch runs.

local passed: any = ...

local Services: any = if type(passed) == "table" then passed else nil

if Services == nil then
	Services = setmetatable({}, {
		__index = function(self: any, name: string): any
			local ok, svc = pcall(function()
				local s = game:GetService(name :: any)
				-- Feature-detected exactly like the file globals in util/Config.lua:
				-- absent in Studio and on some executors, and never required.
				return (type(cloneref) == "function") and cloneref(s) or s
			end)
			if not ok then
				error("Invalid Service: " .. tostring(name), 2)
			end
			rawset(self, name, svc)
			return svc
		end,
	})
end

return Services

end

__modules['util.Signal'] = function(...)
--!strict
-- util/Signal.lua — the subscribe/notify registry every watcher list in the
-- library is built on.
--
--   local changed = Signal.new()
--   local unsub = changed:Connect(function(value) ... end)
--   changed:Fire(42)
--   unsub()
--
-- This existed eight times before it existed once: util/Context.lua kept four
-- (accent consumers, flag registration, flag values, window state),
-- components/Window.lua three (HUD visibility, HUD state, config folder),
-- components/Settings.lua one (config selection) and util/Bind.lua one (registry
-- observers). Every copy was the same fifteen lines — `table.insert`, a reverse
-- loop to unsubscribe, `table.clone` before notifying — and each one had to
-- independently get the third of those right.
--
-- **That third one is the whole reason this is a module.** A listener is allowed
-- to unsubscribe itself (or add another) from inside its own callback, and
-- mutating the array mid-walk shifts it out from under the loop and silently
-- skips the next listener — a control that doesn't re-theme, a HUD row that
-- doesn't repaint, with nothing to show for it. Firing a snapshot is the fix,
-- and it belongs somewhere it can't be forgotten rather than in a comment
-- repeated at eight call sites.
--
-- Deliberately no dependencies — not even util/Log.lua. Errors are reported
-- through the caller's own handler (see FireGuarded), because what a broken
-- listener *means* differs per signal and the message should say so. It also
-- keeps this requirable from util/Bind.lua and util/Context.lua without a cycle.
--
-- Not a BindableEvent: those are deferred, so a listener is resumed at the end
-- of the resumption cycle rather than inside the call that raised it. Several
-- signals here depend on landing synchronously — Context:OnFlag exists so a
-- loader can attribute a flag to whatever it is building *at that instant*.

local Signal = {}
Signal.__index = Signal

export type Signal<T...> = typeof(setmetatable(
	{} :: { _fns: { (T...) -> () } },
	Signal
))

function Signal.new<T...>(): Signal<T...>
	return (setmetatable({ _fns = {} }, Signal) :: any) :: Signal<T...>
end

-- Subscribe. Returns the unsubscribe; calling it twice is harmless.
--
-- Note that this does NOT replay anything to a late subscriber. Several callers
-- want that (`RegisterAccent` paints immediately, `OnConfigFolder` reports the
-- current folder), but what the "current value" *is* differs every time, so they
-- call `fn` themselves right after connecting rather than handing a value here.
function Signal:Connect<T...>(fn: (T...) -> ()): () -> ()
	table.insert(self._fns, fn)
	return function()
		local list = self._fns
		for i = #list, 1, -1 do
			if list[i] == fn then
				table.remove(list, i)
				break
			end
		end
	end
end

-- Notify every listener, synchronously, over a SNAPSHOT of the list — see the
-- header. A listener that throws takes the rest of the broadcast down with it;
-- use FireGuarded where a listener is a host's code rather than ours.
function Signal:Fire<T...>(...: T...)
	for _, fn in table.clone(self._fns) do
		fn(...)
	end
end

-- Fire, but a throwing listener is reported to `onError` and the remaining
-- listeners still run. This is the shape for anything a *host* subscribes to:
-- someone else's bookkeeping blowing up must never take down the control that
-- moved. `onError` gets the error; the caller words the message, because "a
-- flag watcher errored" and "a HUD observer errored" want different text.
function Signal:FireGuarded<T...>(onError: (any) -> (), ...: T...)
	for _, fn in table.clone(self._fns) do
		local ok, err = pcall(fn, ...)
		if not ok then
			onError(err)
		end
	end
end

-- How many listeners. `Context:NotifyFlag` reads this to skip an expensive
-- read-and-encode when nobody is listening at all.
function Signal:Count(): number
	return #self._fns
end

-- Drop every listener. Teardown only.
function Signal:Clear()
	table.clear(self._fns)
end

return Signal

end

__modules['util.Singleton'] = function(...)
--!strict
-- util/Singleton.lua — the "only one Uranium at a time" guard.
--
-- Every loadstring run is a brand new chunk with brand new module state, so the
-- ONLY place a previous run can leave a note for the next one is the shared
-- executor env (getgenv). We stash a small record there:
--
--   getgenv()._URANIUM_LOADED = { Name = "Uranium", Window = <handle>, Unload = fn }
--
-- Re-running the loader finds that record, unloads the old window, then builds a
-- fresh one — so the loadstring refreshes the UI in place instead of stacking a
-- second copy on top of the first. Consumers can also test the key themselves
-- (`if getgenv()._URANIUM_LOADED then ... end`) since a table is truthy.
--
-- Everything is feature-detected + pcall-guarded exactly like util/Config.lua:
-- Studio has no getgenv, and some sandboxes throw merely on touching it.

local Gui = __require("util.Gui")

local Singleton = {}

Singleton.Key = "_URANIUM_LOADED"

-- Pre-rebrand slots. A build older than the Uranium rename is still a live
-- window on screen, but it parked its record (and named its ScreenGui) under the
-- old brand — so unloadExisting has to look there too, or re-running the loader
-- stacks a Uranium window on top of a Krypton one instead of replacing it.
--
-- `LegacyNames` is also where the *brand* name now lives as far as the sweep is
-- concerned: current builds give the ScreenGui a neutral, per-load random name
-- and mark it with `Gui.Attribute` instead (see util/Gui.lua), so a name match is
-- purely the fallback for builds that predate that.
Singleton.LegacyKeys = { "_KRYPTON_LOADED" }
Singleton.LegacyNames = { "Krypton", "Uranium" }

-- Shared env, with a fallback chain: getgenv() (executors) → _G (Studio and
-- anywhere getgenv is missing — same cross-run persistence, different table).
local env: any = nil
pcall(function()
	if type(getgenv) == "function" then
		env = getgenv()
	end
end)
if type(env) ~= "table" then
	pcall(function()
		env = _G
	end)
end

Singleton.supported = type(env) == "table"

-- The record left by whichever run is currently live, or nil.
function Singleton.get(): any
	if type(env) ~= "table" then
		return nil
	end
	local ok, v = pcall(function()
		return env[Singleton.Key]
	end)
	if ok and type(v) == "table" then
		return v
	end
	return nil
end

local function setKey(value: any)
	if type(env) ~= "table" then
		return
	end
	pcall(function()
		env[Singleton.Key] = value
	end)
end

-- Publish `record` as the live instance. Returns it so the caller can hold on to
-- it for the matching release().
function Singleton.claim(record: any): any
	setKey(record)
	return record
end

-- Clear the key, but only if it still points at OUR record — a window torn down
-- late (after a newer run already claimed the slot) must not evict the new one.
function Singleton.release(record: any)
	-- A nil record is a window that never claimed the slot (AllowMultiple), not a
	-- wildcard: letting it fall through to setKey(nil) had a secondary window's
	-- close wipe the *primary* window's record, after which IsLoaded read false and
	-- a loader re-run couldn't find the live window to unload it.
	if record == nil or Singleton.get() ~= record then
		return
	end
	setKey(nil)
end

-- Last-resort sweep: destroy any leftover ScreenGui of ours. Covers the cases
-- the record can't — the flag was cleared by hand, the previous chunk's Unload
-- closure errored, or an older build that predates this guard is still on
-- screen. Destroying the ScreenGui is always safe; a live window that survives
-- this would be an orphan nobody can see anyway.
--
-- Two things changed with the neutral-name work (util/Gui.lua):
--   * matching is by ATTRIBUTE, since the name is random per load now. `name`
--     stays supported for pre-attribute builds and is passed through
--     `LegacyNames`.
--   * the root list includes `gethui()`. A window parented into the hidden
--     container is exactly the one whose record is most likely to be the only
--     handle on it, and missing that root meant a leaked window nothing could
--     find — the user reloads and gets two stacked.
local function sweep(guiName: string?): number
	local removed = 0
	for _, root in Gui.roots() do
		pcall(function()
			for _, child in root:GetChildren() do
				if not child:IsA("ScreenGui") then
					continue
				end
				if Gui.isOurs(child) or (guiName ~= nil and child.Name == guiName) then
					child:Destroy()
					removed += 1
				end
			end
		end)
	end
	return removed
end

-- Tear down whatever Uranium is already on screen. Returns true if something was
-- actually unloaded, so the caller can log a refresh instead of a fresh load.
function Singleton.unloadExisting(guiName: string?): boolean
	local record = Singleton.get()
	local unloaded = false
	if record then
		if type(record.Unload) == "function" then
			-- pcall: the old chunk may be half-dead (executor unloaded, error
			-- mid-teardown). Either way we still clear the key + sweep below.
			pcall(record.Unload)
		end
		setKey(nil)
		unloaded = true
	end
	-- Same treatment for anything a pre-rebrand build left behind.
	if type(env) == "table" then
		for _, key in Singleton.LegacyKeys do
			local ok, old = pcall(function()
				return env[key]
			end)
			if ok and type(old) == "table" then
				if type(old.Unload) == "function" then
					pcall(old.Unload)
				end
				pcall(function()
					env[key] = nil
				end)
				unloaded = true
			end
		end
	end
	if sweep(guiName) > 0 then
		unloaded = true
	end
	for _, name in Singleton.LegacyNames do
		if name ~= guiName and sweep(name) > 0 then
			unloaded = true
		end
	end
	return unloaded
end

return Singleton

end

__modules['util.Tween'] = function(...)
--!strict
-- util/Tween.lua — shared tween presets. All UI motion is ease-out ~0.12–0.18s.

local Services = __require("util.Services")

local TweenService = Services.TweenService

local Tween = {}

local OUT = Enum.EasingStyle.Quad
local DIR = Enum.EasingDirection.Out

Tween.Fast   = TweenInfo.new(0.12, OUT, DIR) -- hovers, borders
Tween.Normal = TweenInfo.new(0.18, OUT, DIR) -- toggle, chevron
Tween.Spin   = TweenInfo.new(0.26, Enum.EasingStyle.Back, DIR) -- collapse chevrons (slight overshoot)
Tween.Spring = TweenInfo.new(0.28, Enum.EasingStyle.Back, DIR) -- knobs / pops that should overshoot
Tween.Press  = TweenInfo.new(0.09, Enum.EasingStyle.Quad, DIR) -- button tap squash
Tween.Pop    = TweenInfo.new(0.16, Enum.EasingStyle.Back, DIR) -- popovers / window in
Tween.Slide  = TweenInfo.new(0.22, Enum.EasingStyle.Quint, DIR) -- panel collapse/expand, search reveal (smooth, no overshoot)
Tween.MenuOut = TweenInfo.new(0.2, Enum.EasingStyle.Quad, Enum.EasingDirection.In) -- window leaving (accelerate + fade away)
Tween.Toast  = TweenInfo.new(0.22, Enum.EasingStyle.Quint, DIR)
Tween.ToastOut = TweenInfo.new(0.25, Enum.EasingStyle.Quad, Enum.EasingDirection.In)

function Tween.play(instance: Instance, info: TweenInfo, goals: { [string]: any }): Tween
	local tween = TweenService:Create(instance, info, goals)
	tween:Play()
	return tween
end

return Tween

end

